def _binance_futures_settings_summary(
    observation: dict[str, object],
) -> dict[str, object]:
    account = (
        observation.get("account")
        if isinstance(observation.get("account"), dict)
        else {}
    )
    symbol_config = (
        observation.get("symbol_config")
        if isinstance(observation.get("symbol_config"), dict)
        else {}
    )
    return {
        "can_trade": account.get("can_trade"),
        "available_usdt": account.get("available_usdt"),
        "symbol": str(symbol_config.get("symbol") or ""),
        "margin_type": str(symbol_config.get("margin_type") or "").upper(),
        "leverage": safe_float(symbol_config.get("leverage"), 0.0),
        "position_count": int(
            safe_float(observation.get("position_count"), 0.0)
        ),
        "open_order_count": int(
            safe_float(observation.get("open_order_count"), 0.0)
        ),
    }


def _binance_futures_settings_blockers(
    observation: dict[str, object],
) -> list[str]:
    blockers: list[str] = []
    if observation.get("can_trade") is not True:
        blockers.append("account-cannot-trade")
    if int(observation.get("position_count") or 0) > 0:
        blockers.append("positions-present")
    if int(observation.get("open_order_count") or 0) > 0:
        blockers.append("open-orders-present")
    if not str(observation.get("margin_type") or ""):
        blockers.append("margin-type-unknown")
    if safe_float(observation.get("leverage"), 0.0) <= 0:
        blockers.append("leverage-unknown")
    return blockers


def binance_futures_settings_status() -> dict[str, Any]:
    with BINANCE_FUTURES_SETTINGS_LOCK:
        current = dict(BINANCE_FUTURES_SETTINGS_INTERNAL)
    current.pop("confirmation_token_hash", None)
    current.pop("confirmation_expires_epoch", None)
    return redact_sensitive_payload(current)  # type: ignore[return-value]


def preview_binance_futures_order_risk(
    payload: dict[str, Any] | None,
) -> dict[str, Any]:
    request = dict(payload or {})
    normalized_symbol = normalize_usdm_symbol(
        request.get("symbol") or "ETHUSDT"
    )
    strategy_id = str(request.get("strategy_id") or "").strip()
    selected_strategy = next(
        (
            row
            for row in strategy_rows()
            if str(row.get("strategy_id") or "") == strategy_id
        ),
        None,
    )
    policy = (
        dict(selected_strategy.get("futures_execution_policy") or {})
        if isinstance(selected_strategy, dict)
        else futures_execution_policy_from_artifact({})
    )
    route_blockers: list[str] = []
    if not normalized_symbol:
        route_blockers.append("symbol-invalid")
    if strategy_id and selected_strategy is None:
        route_blockers.append("strategy-artifact-missing")
    if selected_strategy is not None:
        strategy_symbol = normalize_usdm_symbol(
            selected_strategy.get("symbol")
        )
        if strategy_symbol and strategy_symbol != normalized_symbol:
            route_blockers.append("strategy-symbol-mismatch")
        if strategy_broker_id(selected_strategy) != "binance-futures":
            route_blockers.append("strategy-route-not-binance-futures")

    if route_blockers:
        return {
            "ok": False,
            "reason": "선물 위험 계산 입력 차단: " + ", ".join(route_blockers),
            "risk": {
                "status": "BLOCKED",
                "blockers": route_blockers,
                "warnings": [],
                "policy": policy,
            },
        }

    router = BINANCE_FUTURES_SETTINGS_ROUTER_FACTORY()
    try:
        raw_observation = router.get_binance_futures_canary_observation(
            normalized_symbol
        )
        observation = _binance_futures_settings_summary(raw_observation)
        market = router.get_binance_futures_risk_inputs(
            normalized_symbol,
            notional_usdt=request.get("notional_usdt"),
        )
        account_snapshot = router.get_account_snapshot("binance-futures")
        account_rows = (
            account_snapshot.get("accounts")
            if isinstance(account_snapshot.get("accounts"), list)
            else []
        )
        account = (
            account_rows[0]
            if account_rows and isinstance(account_rows[0], dict)
            else {}
        )
    except (
        BrokerNotReadyError,
        OSError,
        RuntimeError,
        TimeoutError,
        ValueError,
    ) as exc:
        reason = (
            "Binance Futures 읽기 전용 위험 입력 조회 실패: "
            + str(exc)[:240]
        )
        append_audit(
            "warn",
            "Binance Futures 주문 위험 계산",
            reason,
        )
        return {
            "ok": False,
            "reason": reason,
            "risk": {
                "status": "BLOCKED",
                "blockers": ["broker-risk-inputs-unavailable"],
                "warnings": [],
                "policy": policy,
            },
        }

    current_leverage = safe_float(observation.get("leverage"), 0.0)
    requested_leverage = safe_float(
        request.get("leverage"),
        current_leverage,
    )
    account_equity = safe_float(
        account.get("broker_equity"),
        safe_float(account.get("margin_balance"), 0.0),
    )
    available_usdt = safe_float(
        observation.get("available_usdt"),
        safe_float(account.get("broker_cash"), 0.0),
    )
    risk = simulate_futures_order_risk(
        {
            **request,
            "symbol": normalized_symbol,
            "margin_type": observation.get("margin_type"),
            "account_equity_usdt": account_equity,
            "available_usdt": available_usdt,
            "entry_price": market.get("mark_price"),
            "leverage": requested_leverage,
            "maintenance_margin_rate": market.get(
                "maintenance_margin_rate"
            ),
            "taker_fee_rate": market.get("taker_fee_rate"),
            "funding_rate": market.get("funding_rate"),
        },
        policy=policy,
    )
    drift = compare_futures_policy_to_broker(
        policy,
        {
            "marginType": observation.get("margin_type"),
            "leverage": observation.get("leverage"),
        },
    )
    extra_blockers = [
        str(item)
        for item in drift.get("blockers") or []
        if str(item)
    ]
    if (
        requested_leverage <= 0
        or abs(requested_leverage - current_leverage) > 1e-12
    ):
        extra_blockers.append("requested-leverage-broker-mismatch")
    risk["blockers"] = list(
        dict.fromkeys([*risk.get("blockers", []), *extra_blockers])
    )
    risk["status"] = (
        "BLOCKED"
        if risk["blockers"]
        else "WARNING"
        if risk.get("warnings")
        else "READY"
    )
    risk["broker"] = {
        "margin_type": observation.get("margin_type"),
        "leverage": current_leverage,
        "position_count": observation.get("position_count"),
        "open_order_count": observation.get("open_order_count"),
        "policy_drift": drift,
    }
    risk["market"] = {
        "mark_price": market.get("mark_price"),
        "index_price": market.get("index_price"),
        "funding_rate": market.get("funding_rate"),
        "next_funding_time": market.get("next_funding_time"),
        "maintenance_margin_rate": market.get(
            "maintenance_margin_rate"
        ),
        "notional_floor": market.get("notional_floor"),
        "notional_cap": market.get("notional_cap"),
        "initial_leverage_limit": market.get(
            "initial_leverage_limit"
        ),
        "maker_fee_rate": market.get("maker_fee_rate"),
        "taker_fee_rate": market.get("taker_fee_rate"),
        "source": "Binance USD-M read-only endpoints",
    }
    risk["strategy"] = {
        "strategy_id": strategy_id,
        "name": (
            str(selected_strategy.get("name") or "")
            if isinstance(selected_strategy, dict)
            else ""
        ),
    }
    append_audit(
        "info" if risk["status"] == "READY" else "warn",
        "Binance Futures 주문 위험 계산",
        (
            f"{normalized_symbol} · {request.get('direction') or 'LONG'} · "
            f"{safe_float(request.get('notional_usdt'), 0.0):g} USDT · "
            f"{requested_leverage:g}x · {risk['status']} · 주문 전송 없음"
        ),
    )
    return {
        "ok": True,
        "reason": (
            "주문 전송 없이 현재 브로커 설정과 Artifact 정책으로 계산했습니다."
        ),
        "risk": redact_sensitive_payload(risk),
    }


def _binance_futures_settings_mutation_hold_reason() -> str:
    """Keep ordinary Futures settings outside every functional lifecycle."""

    if not real_orders_enabled():
        return "binance-futures-settings-real-orders-disabled"
    if _binance_functional_durable_authority_open():
        return "binance-functional-authority-blocks-futures-settings"
    try:
        coordinator = crypto_first_live_coordinator_state_status()
    except Exception:
        return "crypto-first-live-coordinator-status-unreadable"
    phase = str(
        (coordinator.get("coordinator") or {}).get("phase")
        if isinstance(coordinator.get("coordinator"), dict)
        else coordinator.get("phase")
        or ""
    ).strip().upper()
    if phase not in {"IDLE", "FINALIZED"}:
        return (
            "crypto-first-live-coordinator-blocks-futures-settings:"
            + (phase or "UNREADABLE")
        )
    return ""


@_serialized_binance_order_authority
def preview_binance_futures_settings(
    symbol: object = "ETHUSDT",
    margin_type: object = "ISOLATED",
    leverage: object = 1,
) -> dict[str, Any]:
    mutation_hold = _binance_futures_settings_mutation_hold_reason()
    if mutation_hold:
        return {
            "ok": False,
            "reason": mutation_hold,
            "settings": binance_futures_settings_status(),
            "authorization": {},
        }
    normalized_symbol = normalize_usdm_symbol(symbol)
    normalized_margin_type = str(margin_type or "").strip().upper()
    try:
        normalized_leverage = int(str(leverage).strip())
    except (TypeError, ValueError):
        normalized_leverage = 0
    validation_errors: list[str] = []
    if not normalized_symbol:
        validation_errors.append("symbol-invalid")
    if normalized_margin_type != "ISOLATED":
        validation_errors.append("only-isolated-supported")
    if normalized_leverage not in BINANCE_FUTURES_SAFE_LEVERAGE_PRESETS:
        validation_errors.append("leverage-outside-safe-presets")

    with BINANCE_FUTURES_SETTINGS_LOCK:
        BINANCE_FUTURES_SETTINGS_INTERNAL.update(
            {
                "status": "CHECKING",
                "symbol": normalized_symbol or "ETHUSDT",
                "target_margin_type": normalized_margin_type or "ISOLATED",
                "target_leverage": normalized_leverage or 1,
                "confirmation_token_hash": "",
                "confirmation_expires_epoch": 0.0,
                "confirmation_used": False,
                "preview": {},
                "result": {},
                "detail": "현재 Binance Futures 종목 설정과 계정 상태를 조회 중입니다.",
            }
        )

    if validation_errors:
        observation: dict[str, object] = {}
        blockers = validation_errors
    else:
        try:
            observation = _binance_futures_settings_summary(
                BINANCE_FUTURES_SETTINGS_ROUTER_FACTORY()
                .get_binance_futures_canary_observation(normalized_symbol)
            )
            blockers = _binance_futures_settings_blockers(observation)
        except (BrokerNotReadyError, RuntimeError, ValueError) as exc:
            observation = {"error": str(exc)[:240]}
            blockers = ["observation-failed"]

    needs_change = (
        not blockers
        and (
            observation.get("margin_type") != normalized_margin_type
            or int(safe_float(observation.get("leverage"), 0.0))
            != normalized_leverage
        )
    )
    already_configured = not blockers and not needs_change
    token = secrets.token_urlsafe(32) if needs_change else ""
    token_hash = (
        hashlib.sha256(token.encode("utf-8")).hexdigest()
        if token
        else ""
    )
    expires_epoch = (
        time.time() + BINANCE_FUTURES_SETTINGS_TTL_SECONDS
        if token
        else 0.0
    )
    preview = {
        **observation,
        "target_margin_type": normalized_margin_type,
        "target_leverage": normalized_leverage,
        "blockers": blockers,
        "needs_change": needs_change,
        "already_configured": already_configured,
    }
    status = (
        "READY"
        if needs_change
        else "CONFIGURED"
        if already_configured
        else "BLOCKED"
    )
    detail = (
        "변경 직전 계정 상태를 다시 검사하는 1회 확인 토큰을 발급했습니다."
        if needs_change
        else "이미 목표 마진 방식과 레버리지로 설정되어 있습니다."
        if already_configured
        else "설정 변경 차단: " + ", ".join(blockers)
    )
    with BINANCE_FUTURES_SETTINGS_LOCK:
        BINANCE_FUTURES_SETTINGS_INTERNAL.update(
            {
                "status": status,
                "confirmation_token_hash": token_hash,
                "confirmation_expires_epoch": expires_epoch,
                "confirmation_used": False,
                "preview": preview,
                "detail": detail,
            }
        )
    append_audit(
        "info" if not blockers else "warn",
        "Binance Futures 종목 설정 사전점검",
        (
            f"{normalized_symbol or '-'} · "
            f"{normalized_margin_type or '-'} · {normalized_leverage}x · "
            f"status {status} · 주문 전송 없음"
        ),
    )
    return {
        "ok": not blockers,
        "reason": detail,
        "settings": binance_futures_settings_status(),
        "authorization": (
            {
                "confirmation_token": token,
                "expires_at": datetime.fromtimestamp(
                    expires_epoch,
                    tz=timezone.utc,
                ).isoformat().replace("+00:00", "Z"),
            }
            if token
            else {}
        ),
    }


@_serialized_binance_order_authority
def apply_binance_futures_settings(
    confirmation_token: object,
    *,
    confirmed: bool,
) -> dict[str, Any]:
    mutation_hold = _binance_futures_settings_mutation_hold_reason()
    if mutation_hold:
        return {
            "ok": False,
            "reason": mutation_hold,
            "settings": binance_futures_settings_status(),
        }
    token = str(confirmation_token or "")
    token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    with BINANCE_FUTURES_SETTINGS_LOCK:
        current = BINANCE_FUTURES_SETTINGS_INTERNAL
        if (
            confirmed is not True
            or not token
            or not current.get("confirmation_token_hash")
            or not secrets.compare_digest(
                token_hash,
                str(current.get("confirmation_token_hash") or ""),
            )
        ):
            return {
                "ok": False,
                "reason": "정확한 1회 확인 토큰과 명시 확인이 필요합니다.",
                "settings": binance_futures_settings_status(),
            }
        if (
            current.get("status") != "READY"
            or current.get("confirmation_used") is True
            or safe_float(current.get("confirmation_expires_epoch"), 0.0)
            <= time.time()
        ):
            current.update(
                {
                    "status": "EXPIRED",
                    "confirmation_token_hash": "",
                    "confirmation_used": True,
                    "detail": "사전점검이 만료되었거나 적용 가능한 상태가 아닙니다.",
                }
            )
            return {
                "ok": False,
                "reason": current["detail"],
                "settings": binance_futures_settings_status(),
            }
        symbol = str(current.get("symbol") or "")
        target_margin_type = str(
            current.get("target_margin_type") or ""
        )
        target_leverage = int(current.get("target_leverage") or 0)
        current.update(
            {
                "status": "APPLYING",
                "confirmation_token_hash": "",
                "confirmation_used": True,
                "detail": "적용 직전 포지션·미체결 주문·현재 설정을 다시 검사합니다.",
            }
        )

    router = BINANCE_FUTURES_SETTINGS_ROUTER_FACTORY()
    try:
        before = _binance_futures_settings_summary(
            router.get_binance_futures_canary_observation(symbol)
        )
        blockers = _binance_futures_settings_blockers(before)
        if blockers:
            raise BrokerNotReadyError(
                "적용 직전 안전검사 차단: " + ", ".join(blockers)
            )
        mutation_hold = _binance_futures_settings_mutation_hold_reason()
        if mutation_hold:
            raise BrokerNotReadyError(mutation_hold)
        change_margin_type = (
            before.get("margin_type") != target_margin_type
        )
        change_leverage = (
            int(safe_float(before.get("leverage"), 0.0))
            != target_leverage
        )
        mutation = router.configure_binance_futures_symbol(
            symbol,
            margin_type=target_margin_type,
            leverage=target_leverage,
            change_margin_type=change_margin_type,
            change_leverage=change_leverage,
        )
        after = _binance_futures_settings_summary(
            router.get_binance_futures_canary_observation(symbol)
        )
        verified = (
            after.get("margin_type") == target_margin_type
            and int(safe_float(after.get("leverage"), 0.0))
            == target_leverage
            and int(after.get("position_count") or 0) == 0
            and int(after.get("open_order_count") or 0) == 0
        )
        if not verified:
            raise BrokerNotReadyError(
                "변경 응답 후 재조회한 설정이 목표값과 일치하지 않습니다."
            )
        result = {
            "before": before,
            "after": after,
            "applied": list(mutation.get("applied") or []),
            "verified": True,
        }
        with BINANCE_FUTURES_SETTINGS_LOCK:
            BINANCE_FUTURES_SETTINGS_INTERNAL.update(
                {
                    "status": "APPLIED",
                    "preview": after,
                    "result": result,
                    "detail": (
                        f"{symbol}을 {target_margin_type} · "
                        f"{target_leverage}x로 적용하고 재검증했습니다."
                    ),
                }
            )
        append_audit(
            "warn",
            "Binance Futures 종목 설정 변경",
            (
                f"{symbol} · {before.get('margin_type')} "
                f"{int(safe_float(before.get('leverage'), 0.0))}x → "
                f"{target_margin_type} {target_leverage}x · "
                f"변경 {','.join(result['applied']) or '없음'} · 재검증 완료"
            ),
        )
        return {
            "ok": True,
            "reason": BINANCE_FUTURES_SETTINGS_INTERNAL["detail"],
            "settings": binance_futures_settings_status(),
        }
    except (BrokerNotReadyError, RuntimeError, ValueError) as exc:
        after: dict[str, object] = {}
        try:
            after = _binance_futures_settings_summary(
                router.get_binance_futures_canary_observation(symbol)
            )
        except (BrokerNotReadyError, RuntimeError, ValueError):
            pass
        with BINANCE_FUTURES_SETTINGS_LOCK:
            BINANCE_FUTURES_SETTINGS_INTERNAL.update(
                {
                    "status": "FAILED",
                    "result": {"after": after, "verified": False},
                    "detail": (
                        str(exc)[:240]
                        + " 자동 재시도하지 않았습니다. 현재값을 다시 점검하세요."
                    ),
                }
            )
        append_audit(
            "danger",
            "Binance Futures 종목 설정 변경 실패",
            f"{symbol} · 자동 재시도 없음 · {str(exc)[:160]}",
        )
        return {
            "ok": False,
            "reason": BINANCE_FUTURES_SETTINGS_INTERNAL["detail"],
            "settings": binance_futures_settings_status(),
        }


def _binance_futures_fill_soak_report_summary(
    report: dict[str, Any] | None,
) -> dict[str, Any]:
    if not isinstance(report, dict) or not report:
        return {}
    progress = (
        report.get("progress")
        if isinstance(report.get("progress"), dict)
        else {}
    )
    final_checks = (
        report.get("final_checks")
        if isinstance(report.get("final_checks"), dict)
        else {}
    )
    risk = (
        report.get("risk")
        if isinstance(report.get("risk"), dict)
        else {}
    )
    return {
        "schema_version": report.get("schema_version"),
        "session_id": report.get("session_id"),
        "status": report.get("status"),
        "started_at": report.get("started_at"),
        "finished_at": report.get("finished_at"),
        "reason_ids": list(report.get("reason_ids") or []),
        "round_trips_completed": progress.get("round_trips_completed"),
        "fill_count": progress.get("fill_count"),
        "max_drawdown_pct": risk.get("max_drawdown_pct"),
        "flat": final_checks.get("flat"),
        "open_orders_clear": final_checks.get("open_orders_clear"),
        "duration_complete": final_checks.get("duration_complete"),
        "report_path": report.get("report_path"),
        "strategy_promotion_authorized": False,
    }


def _latest_binance_futures_fill_soak_report() -> dict[str, Any]:
    directory = futures_fill_soak_report_directory()
    try:
        candidates = sorted(
            directory.glob("bfsoak-*.json"),
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
    except OSError:
        return {}
    for path in candidates:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(payload, dict):
            payload.setdefault("report_path", str(path))
            return _binance_futures_fill_soak_report_summary(payload)
    return {}


def binance_futures_fill_soak_status() -> dict[str, Any]:
    with BINANCE_FUTURES_FILL_SOAK_LOCK:
        current = dict(BINANCE_FUTURES_FILL_SOAK_INTERNAL)
        session = BINANCE_FUTURES_FILL_SOAK_SESSION
        thread = BINANCE_FUTURES_FILL_SOAK_THREAD
    current.pop("confirmation_token_hash", None)
    current.pop("confirmation_issued_epoch", None)
    current.pop("confirmation_expires_epoch", None)
    current["active"] = bool(thread and thread.is_alive())
    current["session"] = session.status() if session is not None else {}
    current["final_report"] = _binance_futures_fill_soak_report_summary(
        current.get("final_report")
        if isinstance(current.get("final_report"), dict)
        else {}
    )
    if not current["final_report"]:
        current["latest_durable_report"] = (
            _latest_binance_futures_fill_soak_report()
        )
    else:
        current["latest_durable_report"] = current["final_report"]
    return redact_sensitive_payload(current)  # type: ignore[return-value]


def _authorize_binance_futures_fill_soak_dispatch(
    payload: dict[str, object],
) -> tuple[bool, str, dict[str, object]]:
    """Authorize fill-soak entries and reduce-only exits on separate paths."""

    strategy_id = str(payload.get("strategy_id") or "").strip()
    symbol = normalize_usdm_symbol(payload.get("symbol"))
    strategy = next(
        (
            item
            for item in strategy_rows()
            if str(item.get("strategy_id") or "") == strategy_id
            and normalize_usdm_symbol(item.get("symbol")) == symbol
            and strategy_broker_id(item) == "binance-futures"
        ),
        None,
    )
    portfolio_gate = (
        strategy.get("portfolio_gate")
        if isinstance(strategy, dict)
        and isinstance(strategy.get("portfolio_gate"), dict)
        else {}
    )
    now = datetime.now(timezone.utc)
    soak_leg = str(payload.get("soak_leg") or "").strip().lower()
    risk_reducing = payload.get("risk_reducing") is True
    reduce_only = payload.get("reduce_only") is True
    intent = OrderIntent(
        strategy_id=strategy_id,
        asset="CRYPTO",
        symbol=symbol,
        side=str(payload.get("side") or "BUY").upper(),
        quantity=max(0.0, safe_float(payload.get("quantity"), 0.0)),
        reference_price=max(0.0, safe_float(payload.get("price"), 0.0)),
        mode=current_mode(),
        reason="Binance Futures fill-soak operational dispatch revalidation",
        metadata={
            "broker_id": "binance-futures",
            "profile_id": "crypto",
            "strategy_instance_id": str(
                strategy.get("strategy_instance_id")
                if isinstance(strategy, dict)
                else ""
            ),
            "portfolio_id": str(portfolio_gate.get("portfolioId") or ""),
            "order_purpose": "FUTURES_FILL_SOAK",
            "order_type": str(payload.get("order_type") or "MARKET"),
            "market_type": "futures",
            "position_direction": str(
                payload.get("position_direction") or "short"
            ),
            "risk_reducing": payload.get("risk_reducing") is True,
            "reduce_only": reduce_only,
            "soak_leg": soak_leg,
            "market_event_time": now.isoformat().replace("+00:00", "Z"),
            "market_data_verified": True,
        },
    )
    if strategy is None:
        return False, "fill-soak-current-strategy-missing", {}

    # Every risk-increasing entry gets all mutable safety controls and its
    # preview-bound canary scope re-read immediately before broker dispatch.
    if soak_leg == "entry" and not risk_reducing and not reduce_only:
        if intent.mode != "SMALL_LIVE":
            return False, "fill-soak-entry-small-live-required", {}
        invariant_allowed, invariant_reason = live_broker_dispatch_allowed(
            intent,
            dry_run=False,
        )
        if not invariant_allowed:
            return False, invariant_reason, {}
        scope_allowed, scope_reason, current_scope = (
            exact_live_canary_scope_dispatch_allowed(
                intent,
                payload.get("canary_scope")
                if isinstance(payload.get("canary_scope"), dict)
                else {},
            )
        )
        if not scope_allowed:
            return False, scope_reason, {"canaryScope": current_scope}
        allowed, reason, authorization = operational_runtime_dispatch_allowed(
            intent
        )
        result = dict(authorization)
        result.update(
            {
                "dispatchPath": "new-entry",
                "brokerInvariantRevalidated": True,
                "canaryScope": current_scope,
            }
        )
        return allowed, reason, result

    # A cover is never allowed to masquerade as a new entry.  It has a
    # deliberately separate recovery path so a safety stop can flatten an
    # already-open short, but current broker truth must prove it is reducing.
    if (
        soak_leg in {"cover", "recovery-cover"}
        and risk_reducing
        and reduce_only
    ):
        if not futures_risk_reducing_verified({}, intent):
            return False, "fill-soak-reduce-only-position-unverified", {}
        allowed, reason, authorization = operational_runtime_dispatch_allowed(
            intent
        )
        result = dict(authorization)
        result.update(
            {
                "dispatchPath": "recovery-reduce-only",
                "recoveryReduceOnly": True,
            }
        )
        return allowed, reason, result

    return False, "fill-soak-dispatch-shape-invalid", {}


@contextmanager
def _binance_futures_fill_soak_dispatch_boundary():
    """Linearize fill-soak authorization/POST with API mutations and Kill."""

    with SAFETY_CONFIRMATION_MUTATION_LOCK:
        # Canonical Binance order is route authority -> emergency.  The
        # LiveBrokerRouter's nested final edge reuses this thread-local lease,
        # so there is one fresh durable authority read and no emergency/route
        # inversion with normal sends or Kill.
        with ordinary_binance_final_mutation_boundary(
            operation="FUTURES_FILL_SOAK"
        ) as authority:
            yield authority


def preview_binance_futures_fill_soak(
    symbol: object = "ETHUSDT",
) -> dict[str, Any]:
    global BINANCE_FUTURES_FILL_SOAK_SESSION

    normalized_symbol = normalize_usdm_symbol(symbol or "ETHUSDT")
    selected_strategy_id = str(STATE.get("selected_strategy_id") or "").strip()
    selected_deployment_id = str(
        STATE.get("selected_deployment_id") or ""
    ).strip()
    selected_strategy = next(
        (
            item
            for item in strategy_rows()
            if (
                (selected_strategy_id and str(item.get("strategy_id") or "") == selected_strategy_id)
                or (
                    selected_deployment_id
                    and str(item.get("deployment_id") or "")
                    == selected_deployment_id
                )
            )
            and normalize_usdm_symbol(item.get("symbol")) == normalized_symbol
            and strategy_broker_id(item) == "binance-futures"
        ),
        None,
    )
    session_id = (
        "bfsoak-"
        + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S")
        + "-"
        + secrets.token_hex(4)
    )
    with BINANCE_FUTURES_FILL_SOAK_LOCK:
        running = BINANCE_FUTURES_FILL_SOAK_THREAD
        if running is not None and running.is_alive():
            return {
                "ok": False,
                "reason": "이미 Binance Futures 실체결 soak가 실행 중입니다.",
                "fill_soak": binance_futures_fill_soak_status(),
            }
        BINANCE_FUTURES_FILL_SOAK_INTERNAL.update(
            {
                "phase": "previewing",
                "status": "PREVIEWING",
                "session_id": session_id,
                "symbol": normalized_symbol,
                "confirmation_token_hash": "",
                "confirmation_issued_epoch": 0.0,
                "confirmation_expires_epoch": 0.0,
                "confirmation_used": False,
                "preview": {},
                "final_report": {},
                "report_path": "",
                "detail": "실계좌·포지션·미체결 주문·최소 주문을 읽기 전용으로 확인 중입니다.",
            }
        )

    try:
        selected_canary_scope = (
            current_live_canary_scope(
                str(selected_strategy.get("strategy_id") or ""),
                materialize=True,
            )
            if isinstance(selected_strategy, dict)
            else {}
        )
        config = FillSoakConfig(
            session_id=session_id,
            symbol=normalized_symbol,
            duration_seconds=BINANCE_FUTURES_FILL_SOAK_DURATION_SECONDS,
            target_round_trips=3,
            target_notional_usdt=BINANCE_FUTURES_FILL_SOAK_NOTIONAL_USDT,
            daily_drawdown_limit_pct=10,
            strategy_id=str(
                selected_strategy.get("strategy_id")
                if isinstance(selected_strategy, dict)
                else "binance-futures-fill-soak-unbound"
            ),
            canary_scope=selected_canary_scope,
        )
        session = BINANCE_FUTURES_FILL_SOAK_SESSION_FACTORY(config)
        session.dispatch_authorizer = (
            _authorize_binance_futures_fill_soak_dispatch
        )
        session.dispatch_boundary = (
            _binance_futures_fill_soak_dispatch_boundary
        )
        preview = session.preview()
    except (BrokerNotReadyError, RuntimeError, ValueError) as exc:
        preview = {
            "schema_version": "binance-usdm-fill-soak-v1",
            "session_id": session_id,
            "symbol": normalized_symbol,
            "ready": False,
            "blockers": ["preview-observation-failed"],
            "detail": str(exc)[:240],
        }
        session = None

    ready = preview.get("ready") is True
    token = secrets.token_urlsafe(32) if ready else ""
    token_hash = (
        hashlib.sha256(token.encode("utf-8")).hexdigest()
        if token
        else ""
    )
    now_epoch = time.time()
    expires_epoch = (
        now_epoch + BINANCE_FUTURES_FILL_SOAK_TTL_SECONDS
        if token
        else 0.0
    )
    with BINANCE_FUTURES_FILL_SOAK_LOCK:
        if BINANCE_FUTURES_FILL_SOAK_INTERNAL.get("session_id") != session_id:
            return {
                "ok": False,
                "reason": "더 최근 사전점검이 시작되어 현재 결과를 폐기했습니다.",
                "fill_soak": binance_futures_fill_soak_status(),
            }
        BINANCE_FUTURES_FILL_SOAK_SESSION = session
        BINANCE_FUTURES_FILL_SOAK_INTERNAL.update(
            {
                "phase": "ready" if ready else "blocked",
                "status": "READY" if ready else "BLOCKED",
                "confirmation_token_hash": token_hash,
                "confirmation_issued_epoch": now_epoch if token else 0.0,
                "confirmation_expires_epoch": expires_epoch,
                "confirmation_used": False,
                "preview": preview,
                "detail": (
                    "실행 직전 동일 조건을 다시 확인하는 1회 확인 토큰을 발급했습니다."
                    if ready
                    else "사전점검 차단: "
                    + ", ".join(
                        str(item)
                        for item in preview.get("blockers", [])
                    )
                ),
            }
        )
    append_audit(
        "info" if ready else "warn",
        "Binance Futures 실체결 soak 사전점검",
        (
            f"{normalized_symbol} · ready {ready} · "
            f"blockers {len(preview.get('blockers', []))}개 · "
            "주문 전송 없음"
        ),
    )
    return {
        "ok": ready,
        "reason": BINANCE_FUTURES_FILL_SOAK_INTERNAL["detail"],
        "fill_soak": binance_futures_fill_soak_status(),
        "authorization": (
            {
                "confirmation_token": token,
                "expires_at": datetime.fromtimestamp(
                    expires_epoch,
                    tz=timezone.utc,
                ).isoformat().replace("+00:00", "Z"),
            }
            if token
            else {}
        ),
    }


def _run_binance_futures_fill_soak(
    session: BinanceFuturesFillSoakSession,
    authorization: LiveOrderAuthorization,
) -> None:
    try:
        report = session.run(authorization)
    except Exception as exc:
        report = {
            "schema_version": "binance-usdm-fill-soak-v1",
            "session_id": session.config.session_id,
            "status": "FAIL",
            "reason_ids": ["session-unhandled-error"],
            "detail": str(exc)[:240],
            "strategy_promotion_authorized": False,
        }
    summary = _binance_futures_fill_soak_report_summary(report)
    with BINANCE_FUTURES_FILL_SOAK_LOCK:
        BINANCE_FUTURES_FILL_SOAK_INTERNAL.update(
            {
                "phase": "finished",
                "status": str(report.get("status") or "FAIL"),
                "final_report": report,
                "report_path": str(report.get("report_path") or ""),
                "detail": (
                    "실체결 soak를 통과했습니다. 이 결과는 전략 승급 증거로 자동 사용하지 않습니다."
                    if report.get("status") == "PASS"
                    else "실체결 soak가 실패 또는 안전 중단되었습니다."
                ),
            }
        )
    append_audit(
        "info" if report.get("status") == "PASS" else "danger",
        "Binance Futures 실체결 soak 종료",
        (
            f"{summary.get('session_id') or '-'} · "
            f"{summary.get('status') or 'FAIL'} · "
            f"fills {summary.get('fill_count') or 0} · "
            f"flat {summary.get('flat') is True}"
        ),
    )


@_serialized_safety_mutation
def start_binance_futures_fill_soak(
    confirmation_token: object,
    *,
    confirmed: bool,
    safety_confirmation: dict[str, Any] | None = None,
) -> dict[str, Any]:
    global BINANCE_FUTURES_FILL_SOAK_THREAD

    token = str(confirmation_token or "")
    token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    with BINANCE_FUTURES_FILL_SOAK_LOCK:
        session = BINANCE_FUTURES_FILL_SOAK_SESSION
        current = BINANCE_FUTURES_FILL_SOAK_INTERNAL
        running = BINANCE_FUTURES_FILL_SOAK_THREAD
        if running is not None and running.is_alive():
            return {
                "ok": False,
                "reason": "이미 실체결 soak가 실행 중입니다.",
                "fill_soak": binance_futures_fill_soak_status(),
            }
        if (
            confirmed is not True
            or not token
            or not current.get("confirmation_token_hash")
            or not secrets.compare_digest(
                token_hash,
                str(current.get("confirmation_token_hash") or ""),
            )
        ):
            return {
                "ok": False,
                "reason": "정확한 1회 확인 토큰과 명시 확인이 필요합니다.",
                "fill_soak": binance_futures_fill_soak_status(),
            }
        if (
            session is None
            or current.get("phase") != "ready"
            or current.get("confirmation_used") is True
            or safe_float(
                current.get("confirmation_expires_epoch"),
                0.0,
            )
            <= time.time()
        ):
            current.update(
                {
                    "phase": "expired",
                    "status": "EXPIRED",
                    "confirmation_token_hash": "",
                    "confirmation_used": True,
                    "detail": "사전점검이 만료되었거나 실행 가능한 상태가 아닙니다.",
                }
            )
            return {
                "ok": False,
                "reason": current["detail"],
                "fill_soak": binance_futures_fill_soak_status(),
            }

        challenge = consume_safety_confirmation(
            "BINANCE_FUTURES_FILL_SOAK_START",
            safety_confirmation,
            {"symbol": str(current.get("symbol") or "")},
        )
        if challenge.get("ok") is not True:
            return {
                "ok": False,
                "reason": str(
                    challenge.get("reason")
                    or "safety-confirmation-required"
                ),
                "fill_soak": binance_futures_fill_soak_status(),
            }

        issued_epoch = safe_float(
            current.get("confirmation_issued_epoch"),
            0.0,
        )
        expires_epoch = safe_float(
            current.get("confirmation_expires_epoch"),
            0.0,
        )
        # Consume before starting the worker. A timeout, crash, or broker
        # ambiguity must never make the authorization reusable.
        current.update(
            {
                "phase": "starting",
                "status": "STARTING",
                "confirmation_token_hash": "",
                "confirmation_used": True,
                "detail": "실행 직전 사전점검 재검증을 시작합니다.",
            }
        )
        authorization = LiveOrderAuthorization(
            confirmed=True,
            token_fingerprint=token_hash,
            issued_at_epoch=issued_epoch,
            expires_at_epoch=expires_epoch,
        )
        thread = threading.Thread(
            target=_run_binance_futures_fill_soak,
            args=(session, authorization),
            daemon=True,
            name=f"binance-futures-fill-soak-{session.config.session_id}",
        )
        BINANCE_FUTURES_FILL_SOAK_THREAD = thread
        thread.start()
    append_audit(
        "warn",
        "Binance Futures 실체결 soak 시작",
        (
            f"{session.config.session_id} · 최소 주문 SHORT 왕복 3회 · "
            "5시간 · 초기 사용 가능 USDT 100% 상한 · 일일 손실 10%"
        ),
    )
    return {
        "ok": True,
        "reason": "실체결 soak를 시작했습니다.",
        "fill_soak": binance_futures_fill_soak_status(),
    }


def stop_binance_futures_fill_soak() -> dict[str, Any]:
    with BINANCE_FUTURES_FILL_SOAK_LOCK:
        session = BINANCE_FUTURES_FILL_SOAK_SESSION
        running = BINANCE_FUTURES_FILL_SOAK_THREAD
        if session is None or running is None or not running.is_alive():
            return {
                "ok": False,
                "reason": "실행 중인 실체결 soak가 없습니다.",
                "fill_soak": binance_futures_fill_soak_status(),
            }
        session.request_stop()
        BINANCE_FUTURES_FILL_SOAK_INTERNAL.update(
            {
                "phase": "stopping",
                "status": "STOPPING",
                "detail": "중단 요청을 보냈습니다. 활성 주문을 정리하고 평탄 상태를 확인합니다.",
            }
        )
    append_audit(
        "warn",
        "Binance Futures 실체결 soak 중단 요청",
        str(session.config.session_id),
    )
    return {
        "ok": True,
        "reason": "안전 중단을 요청했습니다.",
        "fill_soak": binance_futures_fill_soak_status(),
    }


def binance_futures_canary_status() -> dict[str, Any]:
    with BINANCE_FUTURES_CANARY_LOCK:
        current = dict(STATE.get("binance_futures_canary", {}))
    current.pop("confirmation_token", None)
    current.pop("test_context", None)
    current.pop("test_requests", None)
    return current


def _binance_futures_ticker_price(symbol: str) -> float:
    normalized_symbol = normalize_usdm_symbol(symbol)
    base_url = (
        env_value("BINANCE_FUTURES_BASE_URL")
        or BINANCE_FUTURES_BASE_URL
    )
    response = http_json(
        "GET",
        (
            f"{base_url.rstrip('/')}/fapi/v1/ticker/price?"
            f"symbol={normalized_symbol}"
        ),
        body=None,
        headers={},
        timeout_seconds=10.0,
    )
    payload = (
        response.get("json")
        if isinstance(response.get("json"), dict)
        else {}
    )
    price = safe_float(payload.get("price"), 0.0)
    if response.get("ok") is not True or price <= 0:
        raise RuntimeError(
            "Binance Futures 현재가를 확인하지 못했습니다."
        )
    return price


def _artifact_custom_definition(strategy: dict[str, Any]) -> dict[str, Any]:
    parameters = (
        strategy.get("parameters")
        if isinstance(strategy.get("parameters"), dict)
        else {}
    )
    contract = (
        strategy.get("strategyContract")
        if isinstance(strategy.get("strategyContract"), dict)
        else strategy.get("strategy_contract")
        if isinstance(strategy.get("strategy_contract"), dict)
        else {}
    )
    for candidate in (
        parameters.get("customStrategyDefinition"),
        parameters.get("custom_strategy_definition"),
        strategy.get("customStrategyDefinition"),
        strategy.get("custom_strategy_definition"),
        contract.get("customStrategyDefinition"),
    ):
        if isinstance(candidate, dict):
            return candidate
    return {}


def _evaluate_binance_futures_canary(
    strategy_id: object,
    notional_usdt: object = 6.0,
) -> tuple[dict[str, Any], dict[str, str]]:
    selected_id = str(strategy_id or "").strip()
    strategies = strategy_rows()
    strategy = next(
        (
            item
            for item in strategies
            if str(item.get("strategy_id") or item.get("id") or "")
            == selected_id
        ),
        None,
    )
    symbol = normalize_usdm_symbol(
        (strategy or {}).get("symbol") or "BTCUSDT"
    )
    definition = _artifact_custom_definition(strategy or {})
    direction = str(
        definition.get("positionDirection")
        or (strategy or {}).get("position_direction")
        or (strategy or {}).get("positionDirection")
        or "long"
    ).strip().lower()
    lifecycle = normalize_lifecycle_status(
        (strategy or {}).get("lifecycleStatus")
        or (strategy or {}).get("status")
        or (
            (strategy or {}).get("lifecycle", {}).get("status")
            if isinstance((strategy or {}).get("lifecycle"), dict)
            else ""
        )
    )
    scope = (
        current_live_canary_scope(selected_id, materialize=False)
        if strategy is not None
        else {}
    )
    broker_id = strategy_broker_id(strategy) if strategy is not None else ""
    market_type = str(
        (strategy or {}).get("market_type")
        or (strategy or {}).get("marketType")
        or ""
    ).strip().lower()
    strategy_gate = {
        "found": strategy is not None,
        "broker_id": broker_id,
        "symbol": symbol,
        "symbol_matches": bool(symbol),
        "market_type": market_type,
        "position_direction": direction,
        "short_authorized": (
            strategy is not None
            and direction == "short"
            and broker_id == "binance-futures"
            and market_type
            in {"future", "futures", "perpetual", "swap"}
        ),
        "lifecycle_status": lifecycle,
        "live_small_eligible": (
            (strategy or {}).get("live_small_eligible") is True
        ),
        "deployment_provenance_ok": bool(
            scope.get("deploymentId")
            and scope.get("strategyArtifactHash")
            and scope.get("strategyId")
        ),
        "canary_scope_ok": scope.get("eligible") is True,
    }
    observation: dict[str, Any] = {
        "account": {},
        "position_mode": {},
        "symbol_config": {},
        "position_count": None,
        "open_order_count": None,
    }
    observation_errors: list[str] = []
    price: float | None = None
    rules: dict[str, Any] = {}
    try:
        observation = (
            LiveBrokerRouter()
            .get_binance_futures_canary_observation(symbol)
        )
    except (BrokerNotReadyError, RuntimeError):
        observation_errors.extend(
            (
                "account-observation-failed",
                "position-mode-observation-failed",
                "symbol-config-observation-failed",
                "positions-observation-failed",
                "open-orders-observation-failed",
            )
        )
    try:
        price = _binance_futures_ticker_price(symbol)
    except RuntimeError:
        observation_errors.append("ticker-observation-failed")
    try:
        rules = binance_symbol_rules(symbol, futures=True)
    except RuntimeError:
        observation_errors.append("exchange-rules-observation-failed")
    quantity_result = derive_canary_quantity(
        target_notional_usdt=notional_usdt,
        price=price,
        min_qty=rules.get("minQty"),
        max_qty=rules.get("maxQty"),
        step_size=rules.get("stepSize"),
        exchange_min_notional=rules.get("minNotional"),
    )
    report = evaluate_futures_canary_preflight(
        strategy_gate=strategy_gate,
        account=(
            observation.get("account")
            if isinstance(observation.get("account"), dict)
            else {}
        ),
        position_mode=(
            observation.get("position_mode")
            if isinstance(observation.get("position_mode"), dict)
            else {}
        ),
        symbol_config=(
            observation.get("symbol_config")
            if isinstance(observation.get("symbol_config"), dict)
            else {}
        ),
        position_count=(
            int(observation["position_count"])
            if isinstance(observation.get("position_count"), int)
            else None
        ),
        open_order_count=(
            int(observation["open_order_count"])
            if isinstance(observation.get("open_order_count"), int)
            else None
        ),
        requested_notional_usdt=notional_usdt,
        quantity_result=quantity_result,
        real_orders_enabled=real_orders_enabled(),
        observation_errors=tuple(dict.fromkeys(observation_errors)),
    )
    report["strategy"] = {
        "strategy_id": selected_id,
        "symbol": symbol,
        "broker_id": broker_id,
        "market_type": market_type,
        "position_direction": direction,
        "lifecycle_status": lifecycle,
        "short_authorized": strategy_gate["short_authorized"],
    }
    report["detail"] = (
        "test order 사전점검 통과"
        if report["ready_for_test"]
        else "차단: " + ", ".join(report["test_blockers"])
    )
    context = {
        "strategy_id": selected_id,
        "symbol": symbol,
        "requested_notional_usdt": str(notional_usdt),
        "quantity": str(
            report.get("order_plan", {}).get("quantity") or ""
        ),
        "estimated_notional_usdt": str(
            report.get("order_plan", {}).get(
                "estimated_notional_usdt"
            )
            or ""
        ),
        "scope_id": str(scope.get("scopeId") or ""),
    }
    return report, context


def preview_binance_futures_canary(
    strategy_id: object,
    notional_usdt: object = 6.0,
) -> dict[str, Any]:
    with BINANCE_FUTURES_CANARY_LOCK:
        report, context = _evaluate_binance_futures_canary(
            strategy_id,
            notional_usdt,
        )
        now = datetime.now(timezone.utc)
        expires = now + timedelta(
            seconds=BINANCE_FUTURES_CANARY_TEST_TTL_SECONDS
        )
        token = (
            secrets.token_urlsafe(32)
            if report["ready_for_test"]
            else ""
        )
        stored = {
            **report,
            "confirmation_token": token,
            "expires_at": (
                expires.isoformat().replace("+00:00", "Z")
                if token
                else ""
            ),
            "expires_epoch": expires.timestamp() if token else 0.0,
            "used": False,
            "test_context": context if token else {},
            "test_result": {},
        }
        STATE["binance_futures_canary"] = stored
    append_audit(
        "info" if report["ready_for_test"] else "warn",
        "Binance Futures canary 사전점검",
        (
            f"{context.get('strategy_id') or '-'} "
            f"{context.get('symbol') or '-'} · "
            f"test blockers {len(report['test_blockers'])}개 · "
            f"start blockers {len(report['start_blockers'])}개"
        ),
    )
    return {
        "ok": report["ready_for_test"],
        "reason": report["detail"],
        "canary": binance_futures_canary_status(),
        "test_authorization": (
            {
                "confirmation_token": token,
                "expires_at": stored["expires_at"],
            }
            if token
            else {}
        ),
    }


def _sanitize_binance_futures_test_leg(
    leg: str,
    intent: dict[str, object],
    response: dict[str, object],
) -> dict[str, object]:
    payload = (
        response.get("json")
        if isinstance(response.get("json"), dict)
        else {}
    )
    exchange_code = payload.get("code")
    message = str(payload.get("msg") or "")[:160]
    return {
        "leg": leg,
        "side": str(intent.get("side") or ""),
        "position_side": "SHORT",
        "risk_reducing": intent.get("risk_reducing") is True,
        "ok": response.get("ok") is True,
        "status_code": int(
            safe_float(response.get("statusCode"), 0.0)
        ),
        "exchange_code": (
            str(exchange_code)[:40]
            if exchange_code not in (None, "")
            else None
        ),
        "message": message,
    }


def _binance_futures_test_result(
    *,
    status: str,
    context: dict[str, str],
    legs: list[dict[str, object]] | None = None,
    reason_id: str = "",
) -> dict[str, object]:
    return {
        "status": status,
        "endpoint": BINANCE_FUTURES_TEST_ORDER_ENDPOINT,
        "submitted_to_matching_engine": False,
        "strategy_id": context.get("strategy_id", ""),
        "symbol": context.get("symbol", ""),
        "quantity": context.get("quantity", ""),
        "estimated_notional_usdt": context.get(
            "estimated_notional_usdt",
            "",
        ),
        "reason_id": reason_id,
        "legs": list(legs or []),
        "validated_at": (
            datetime.now(timezone.utc)
            .isoformat()
            .replace("+00:00", "Z")
        ),
    }


def test_binance_futures_canary_order(
    confirmation_token: object,
    *,
    confirmed: bool,
) -> dict[str, Any]:
    token = str(confirmation_token or "")
    with BINANCE_FUTURES_CANARY_LOCK:
        current = dict(STATE.get("binance_futures_canary", {}))
        stored_token = str(current.get("confirmation_token") or "")
        if (
            not confirmed
            or not token
            or not stored_token
            or not secrets.compare_digest(token, stored_token)
        ):
            return {
                "ok": False,
                "reason": (
                    "정확한 Binance Futures test order 미리보기의 "
                    "1회 확인 토큰이 필요합니다."
                ),
                "canary": binance_futures_canary_status(),
            }
        if (
            current.get("ready_for_test") is not True
            or current.get("status") != "test_ready"
            or current.get("used") is True
        ):
            return {
                "ok": False,
                "reason": "이미 사용되었거나 test order 가능한 미리보기가 아닙니다.",
                "canary": binance_futures_canary_status(),
            }
        if (
            safe_float(current.get("expires_epoch"), 0.0)
            <= datetime.now(timezone.utc).timestamp()
        ):
            current.update(
                {
                    "status": "expired",
                    "used": True,
                    "confirmation_token": "",
                    "detail": (
                        "test order 미리보기가 만료되었습니다. "
                        "다시 사전점검하세요."
                    ),
                }
            )
            STATE["binance_futures_canary"] = current
            return {
                "ok": False,
                "reason": current["detail"],
                "canary": binance_futures_canary_status(),
            }
        context = (
            dict(current.get("test_context", {}))
            if isinstance(current.get("test_context"), dict)
            else {}
        )
        if not all(
            context.get(key)
            for key in (
                "strategy_id",
                "symbol",
                "requested_notional_usdt",
                "quantity",
                "scope_id",
            )
        ):
            current.update(
                {
                    "status": "blocked",
                    "used": True,
                    "confirmation_token": "",
                    "detail": "test order 미리보기 문맥이 완전하지 않습니다.",
                }
            )
            STATE["binance_futures_canary"] = current
            return {
                "ok": False,
                "reason": current["detail"],
                "canary": binance_futures_canary_status(),
            }

        # Consume before any action-time broker observation or signed POST.
        # A timeout or partial validation must never make the token reusable.
        current.update(
            {
                "status": "test_validating",
                "used": True,
                "confirmation_token": "",
                "detail": "action-time 사전점검 재검증 중",
            }
        )
        STATE["binance_futures_canary"] = current

        fresh_report, fresh_context = _evaluate_binance_futures_canary(
            context["strategy_id"],
            context["requested_notional_usdt"],
        )
        bound_fields = (
            "strategy_id",
            "symbol",
            "requested_notional_usdt",
            "quantity",
            "scope_id",
        )
        context_matches = all(
            fresh_context.get(key) == context.get(key)
            for key in bound_fields
        )
        if fresh_report.get("ready_for_test") is not True or not context_matches:
            reason_id = (
                "preview-context-changed"
                if fresh_report.get("ready_for_test") is True
                else "action-time-preflight-blocked"
            )
            if reason_id not in fresh_report["test_blockers"]:
                fresh_report["test_blockers"].append(reason_id)
            if reason_id not in fresh_report["start_blockers"]:
                fresh_report["start_blockers"].append(reason_id)
            test_result = _binance_futures_test_result(
                status="blocked",
                context=context,
                reason_id=reason_id,
            )
            fresh_report.update(
                {
                    "status": "blocked",
                    "ready_for_test": False,
                    "used": True,
                    "confirmation_token": "",
                    "expires_at": current.get("expires_at", ""),
                    "expires_epoch": current.get("expires_epoch", 0.0),
                    "test_context": context,
                    "test_result": test_result,
                    "detail": (
                        "action-time 사전점검이 변경되어 test order를 "
                        "전송하지 않았습니다."
                    ),
                }
            )
            STATE["binance_futures_canary"] = fresh_report
            append_audit(
                "warn",
                "Binance Futures test order",
                (
                    f"{context['strategy_id']} {context['symbol']} · "
                    f"{reason_id} · matching engine 전송 없음"
                ),
            )
            return {
                "ok": False,
                "reason": fresh_report["detail"],
                "test": test_result,
                "canary": binance_futures_canary_status(),
            }

        fingerprint = hashlib.sha256(token.encode("utf-8")).hexdigest()
        entry, cover = build_futures_canary_test_intents(
            strategy_id=context["strategy_id"],
            symbol=context["symbol"],
            quantity=context["quantity"],
            token_fingerprint=fingerprint,
        )
        router = LiveBrokerRouter()
        legs: list[dict[str, object]] = []
        for leg_name, intent in (("entry", entry), ("cover", cover)):
            try:
                response = router.test_binance_futures_order(intent)
                leg_result = _sanitize_binance_futures_test_leg(
                    leg_name,
                    intent,
                    response,
                )
            except (BrokerNotReadyError, RuntimeError):
                leg_result = {
                    "leg": leg_name,
                    "side": str(intent.get("side") or ""),
                    "position_side": "SHORT",
                    "risk_reducing": (
                        intent.get("risk_reducing") is True
                    ),
                    "ok": False,
                    "status_code": 0,
                    "exchange_code": None,
                    "message": "Binance Futures test order 사전검사 실패",
                }
            legs.append(leg_result)
            if leg_result["ok"] is not True:
                break

        succeeded = len(legs) == 2 and all(
            leg.get("ok") is True for leg in legs
        )
        test_result = _binance_futures_test_result(
            status="validated" if succeeded else "failed",
            context=context,
            legs=legs,
            reason_id="" if succeeded else "broker-test-rejected",
        )
        fresh_report.update(
            {
                "status": (
                    "test_validated" if succeeded else "test_failed"
                ),
                "used": True,
                "confirmation_token": "",
                "expires_at": current.get("expires_at", ""),
                "expires_epoch": current.get("expires_epoch", 0.0),
                "test_context": context,
                "test_result": test_result,
                "detail": (
                    "SELL/BUY SHORT test order 검증 통과 · "
                    "matching engine 전송 없음"
                    if succeeded
                    else "Binance Futures test order 검증 실패"
                ),
            }
        )
        STATE["binance_futures_canary"] = fresh_report
        append_audit(
            "info" if succeeded else "warn",
            "Binance Futures test order",
            (
                f"{context['strategy_id']} {context['symbol']} · "
                f"{len(legs)}/2 legs · "
                "matching engine 전송 없음"
            ),
        )
        return {
            "ok": succeeded,
            "reason": fresh_report["detail"],
            "test": test_result,
            "canary": binance_futures_canary_status(),
        }


def _binance_smoke_order_view(**updates: Any) -> dict[str, Any]:
    current = dict(STATE.get("binance_smoke_order", {}))
    current.update(updates)
    STATE["binance_smoke_order"] = current
    return current


def _binance_ticker_price() -> float:
    base_url = env_value("BINANCE_BASE_URL") or BINANCE_BASE_URL
    response = http_json(
        "GET",
        f"{base_url.rstrip('/')}/api/v3/ticker/price?symbol={BINANCE_SMOKE_SYMBOL}",
        body=None,
        headers={},
        timeout_seconds=10.0,
    )
    payload = response.get("json") if isinstance(response.get("json"), dict) else {}
    price = safe_float(payload.get("price"), 0.0)
    if response.get("ok") is not True or price <= 0:
        raise RuntimeError(str(response.get("text") or "Binance BTCUSDT 현재가 조회 실패"))
    return price


def approved_binance_smoke_strategy(strategy_id: object) -> dict[str, Any] | None:
    selected_id = str(strategy_id or "").strip()
    if not selected_id:
        return None
    return next(
        (
            item
            for item in strategy_rows()
            if str(item.get("strategy_id") or "") == selected_id
            and item.get("live_small_eligible") is True
            and strategy_broker_id(item) == "binance"
            and str(item.get("symbol") or "").upper()
            == BINANCE_SMOKE_SYMBOL
            and str(item.get("strategy_instance_id") or "").strip()
        ),
        None,
    )


def preview_binance_smoke_order(strategy_id: str) -> dict[str, Any]:
    strategy = approved_binance_smoke_strategy(strategy_id)
    if strategy is None:
        reason = "선택한 Binance Strategy Instance가 before-live-small 및 검증 evidence를 통과하지 못했습니다."
        _binance_smoke_order_view(status="blocked", status_label="차단", detail=reason, confirmation_token="")
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    router = LiveBrokerRouter()
    try:
        account_snapshot = router.get_account_snapshot("binance")
        price = _binance_ticker_price()
    except (BrokerNotReadyError, RuntimeError) as exc:
        reason = str(exc)
        _binance_smoke_order_view(status="blocked", status_label="조회 실패", detail=reason, confirmation_token="")
        append_audit("danger", "Binance 소액 주문 미리보기", reason)
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    accounts = account_snapshot.get("accounts", []) if isinstance(account_snapshot, dict) else []
    usdt_row = next(
        (
            item
            for item in accounts
            if isinstance(item, dict) and str(item.get("currency") or "").upper() == "USDT"
        ),
        {},
    )
    available_usdt = safe_float(usdt_row.get("broker_cash"), 0.0)
    notional_usdt = BINANCE_SMOKE_QUANTITY * price
    blocked_reasons: list[str] = []
    if notional_usdt < BINANCE_SMOKE_MIN_USDT:
        blocked_reasons.append(f"거래소 최소 주문 {BINANCE_SMOKE_MIN_USDT:g} USDT 미만")
    if notional_usdt > BINANCE_SMOKE_MAX_USDT:
        blocked_reasons.append(f"점검 주문 하드 한도 {BINANCE_SMOKE_MAX_USDT:g} USDT 초과")
    if available_usdt + 1e-9 < notional_usdt * 1.01:
        blocked_reasons.append("수수료 여유분을 포함한 USDT 잔고 부족")

    prepared = build_binance_spot_order_request(
        {
            "broker_id": "binance",
            "symbol": BINANCE_SMOKE_SYMBOL,
            "side": "BUY",
            "quantity": BINANCE_SMOKE_QUANTITY,
            "order_type": "MARKET",
        }
    )
    if not prepared.can_send:
        blocked_reasons.append("주문 요청 설정 누락: " + ", ".join(prepared.blocked_reasons))
    ready = not blocked_reasons
    now = datetime.now(timezone.utc)
    expires = now + timedelta(seconds=BINANCE_SMOKE_PREVIEW_TTL_SECONDS)
    token = secrets.token_urlsafe(24) if ready else ""
    detail = (
        f"{BINANCE_SMOKE_SYMBOL} 시장가 매수 {BINANCE_SMOKE_QUANTITY:g} BTC · "
        f"현재가 {price:,.2f} USDT · 예상 {notional_usdt:.2f} USDT · 가용 {available_usdt:.2f} USDT"
        if ready
        else " · ".join(blocked_reasons)
    )
    preview = _binance_smoke_order_view(
        status="ready" if ready else "blocked",
        status_label="확인 대기" if ready else "차단",
        strategy_id=str(strategy.get("strategy_id") or ""),
        strategy_instance_id=str(strategy.get("strategy_instance_id") or ""),
        portfolio_id=str(
            (strategy.get("portfolio_gate") or {}).get("portfolioId")
            if isinstance(strategy.get("portfolio_gate"), dict)
            else ""
        ),
        symbol=BINANCE_SMOKE_SYMBOL,
        side="BUY",
        order_type="MARKET",
        quantity=BINANCE_SMOKE_QUANTITY,
        price=price,
        notional_usdt=notional_usdt,
        available_usdt=available_usdt,
        confirmation_token=token,
        expires_at=expires.isoformat().replace("+00:00", "Z"),
        expires_epoch=expires.timestamp(),
        used=False,
        broker_order_id="",
        detail=detail,
        request_preview=prepared.preview(),
        blocked_reasons=blocked_reasons,
    )
    append_audit("info" if ready else "danger", "Binance 소액 주문 미리보기", detail + (" · 실제 주문 전송 없음" if ready else ""))
    return {"ok": ready, "reason": detail, "preview": preview, "snapshot": snapshot()}


def submit_binance_smoke_order(confirmation_token: object, *, confirmed: bool) -> dict[str, Any]:
    preview = dict(STATE.get("binance_smoke_order", {}))
    token = str(confirmation_token or "")
    if not confirmed or not token or not secrets.compare_digest(token, str(preview.get("confirmation_token") or "")):
        return {"ok": False, "reason": "정확한 Binance 주문 미리보기의 1회 확인 토큰이 필요합니다.", "snapshot": snapshot()}
    if preview.get("status") != "ready" or bool(preview.get("used")):
        return {"ok": False, "reason": "이미 사용되었거나 전송 가능한 미리보기가 아닙니다.", "snapshot": snapshot()}
    if safe_float(preview.get("expires_epoch"), 0.0) <= datetime.now(timezone.utc).timestamp():
        _binance_smoke_order_view(status="expired", status_label="만료", confirmation_token="", detail="미리보기가 만료되었습니다.")
        return {"ok": False, "reason": "미리보기가 만료되었습니다. 다시 조회하세요.", "snapshot": snapshot()}
    strategy = approved_binance_smoke_strategy(preview.get("strategy_id"))
    current_portfolio_id = str(
        (strategy.get("portfolio_gate") or {}).get("portfolioId")
        if isinstance(strategy, dict)
        and isinstance(strategy.get("portfolio_gate"), dict)
        else ""
    )
    if (
        strategy is None
        or str(preview.get("strategy_instance_id") or "").strip()
        != str(strategy.get("strategy_instance_id") or "").strip()
        or str(preview.get("portfolio_id") or "").strip()
        != current_portfolio_id
    ):
        reason = (
            "미리보기의 Binance Strategy/Portfolio Instance가 현재 Live "
            "Deployment와 달라졌습니다. 다시 조회하세요."
        )
        _binance_smoke_order_view(
            status="blocked",
            status_label="전송 직전 차단",
            detail=reason,
            confirmation_token="",
        )
        return {"ok": False, "reason": reason, "snapshot": snapshot()}
    if STATE.get("kill_switch") or STATE.get("new_entries_blocked"):
        return {"ok": False, "reason": "긴급/신규 진입 차단이 켜져 있어 실제 주문을 전송할 수 없습니다.", "snapshot": snapshot()}
    if STATE.get("dry_run") or current_mode() != "SMALL_LIVE":
        return {"ok": False, "reason": "Dry Run을 해제하고 SMALL_LIVE에서만 점검 주문을 보낼 수 있습니다.", "snapshot": snapshot()}
    if not real_orders_enabled():
        return {"ok": False, "reason": "LIVE_TRADER_ENABLE_REAL_ORDERS=true가 필요합니다.", "snapshot": snapshot()}

    try:
        fresh_price = _binance_ticker_price()
        fresh_account = LiveBrokerRouter().get_account_snapshot("binance")
        accounts = fresh_account.get("accounts", []) if isinstance(fresh_account, dict) else []
        usdt_row = next(
            (
                item
                for item in accounts
                if isinstance(item, dict) and str(item.get("currency") or "").upper() == "USDT"
            ),
            {},
        )
        fresh_cash = safe_float(usdt_row.get("broker_cash"), 0.0)
        fresh_notional = BINANCE_SMOKE_QUANTITY * fresh_price
        if fresh_notional < BINANCE_SMOKE_MIN_USDT or fresh_notional > BINANCE_SMOKE_MAX_USDT:
            raise BrokerNotReadyError(f"전송 직전 주문 금액 {fresh_notional:.2f} USDT가 5~10 USDT 하드 한도를 벗어났습니다.")
        if fresh_cash + 1e-9 < fresh_notional * 1.01:
            raise BrokerNotReadyError("전송 직전 수수료 여유분을 포함한 USDT 잔고가 부족합니다.")
    except (BrokerNotReadyError, RuntimeError) as exc:
        reason = str(exc)
        _binance_smoke_order_view(status="blocked", status_label="전송 직전 차단", detail=reason, confirmation_token="")
        append_audit("danger", "Binance 실제 소액 주문", reason)
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    _binance_smoke_order_view(status="submitting", status_label="전송 중", used=True, confirmation_token="")
    strategy_id = str(strategy.get("strategy_id") or "")
    intent = OrderIntent(
        strategy_id=strategy_id,
        asset="CRYPTO",
        symbol=BINANCE_SMOKE_SYMBOL,
        side="BUY",
        quantity=BINANCE_SMOKE_QUANTITY,
        reference_price=fresh_price,
        mode="SMALL_LIVE",
        reason="승급 전략 기반 Binance 브로커 제출 경로 소액 검증(전략 신호 아님)",
        metadata={
            "broker_id": "binance",
            "profile_id": "crypto",
            "strategy_instance_id": str(
                strategy.get("strategy_instance_id") or ""
            ),
            "portfolio_id": current_portfolio_id,
            "instrument_id": BINANCE_SMOKE_SYMBOL,
            "target_revision": int(datetime.now(timezone.utc).timestamp()),
            "order_purpose": "BROKER_SMOKE",
            "order_type": "MARKET",
            "market_event_time": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
            "market_data_verified": True,
        },
    )
    result = submit_order_intent(snapshot(), intent, dry_run=False, audit_event="Binance Broker Smoke")
    order = result.get("order") if isinstance(result.get("order"), dict) else {}
    _binance_smoke_order_view(
        status="acknowledged" if result.get("ok") else "rejected",
        status_label="접수" if result.get("ok") else "거절/차단",
        broker_order_id=str(order.get("broker_order_id") or ""),
        detail=str(result.get("reason") or ""),
        order_id=str(order.get("order_id") or ""),
        order_state=str(order.get("state") or ""),
    )
    return {**result, "smoke_order": dict(STATE["binance_smoke_order"])}


UPBIT_SMOKE_MARKET = "KRW-BTC"
UPBIT_SMOKE_MIN_KRW = 5_000
UPBIT_SMOKE_MAX_KRW = 10_000
UPBIT_SMOKE_PREVIEW_TTL_SECONDS = 600


def _upbit_smoke_order_view(**updates: Any) -> dict[str, Any]:
    current = dict(STATE.get("upbit_smoke_order", {}))
    current.update(updates)
    STATE["upbit_smoke_order"] = current
    return current


def approved_upbit_smoke_strategy(strategy_id: object) -> dict[str, Any] | None:
    selected_id = str(strategy_id or "").strip()
    if not selected_id:
        return None
    minimum_stage = lifecycle_rank("before-live-small")
    return next(
        (
            item
            for item in strategy_rows()
            if str(item.get("strategy_id") or "") == selected_id
            and str(item.get("symbol") or "").strip().upper() == UPBIT_SMOKE_MARKET
            and strategy_broker_id(item) == "upbit"
            and item.get("live_small_eligible") is True
            and lifecycle_rank(normalize_lifecycle_status(item.get("lifecycle_status"))) >= minimum_stage
            and normalize_lifecycle_status(item.get("lifecycle_status")) not in {"paused", "retired"}
        ),
        None,
    )


@_serialized_safety_mutation
@_serialized_upbit_order_authority
def preview_upbit_smoke_order(
    strategy_id: object,
    notional_krw: object = UPBIT_SMOKE_MIN_KRW,
) -> dict[str, Any]:
    if _upbit_functional_durable_authority_open():
        reason = "Upbit 연속 기능시험 권한이 활성 상태라 smoke 주문 경로가 닫혀 있습니다."
        _upbit_smoke_order_view(
            status="blocked",
            status_label="기능시험 격리",
            detail=reason,
            confirmation_token="",
        )
        return {"ok": False, "reason": reason, "snapshot": snapshot()}
    strategy = approved_upbit_smoke_strategy(strategy_id)
    if strategy is None:
        reason = "선택한 Upbit KRW-BTC Strategy Instance가 before-live-small 및 검증 evidence를 통과하지 못했습니다."
        _upbit_smoke_order_view(
            status="blocked",
            status_label="차단",
            strategy_id=str(strategy_id or ""),
            detail=reason,
            confirmation_token="",
        )
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    amount = int(safe_float(notional_krw, 0.0))
    if amount < UPBIT_SMOKE_MIN_KRW or amount > UPBIT_SMOKE_MAX_KRW:
        reason = f"Upbit 점검 주문은 {UPBIT_SMOKE_MIN_KRW:,}~{UPBIT_SMOKE_MAX_KRW:,}원만 허용합니다."
        _upbit_smoke_order_view(
            status="blocked",
            status_label="차단",
            strategy_id=str(strategy.get("strategy_id") or ""),
            detail=reason,
            confirmation_token="",
        )
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    router = LiveBrokerRouter()
    try:
        account_snapshot = router.get_account_snapshot("upbit")
        chance = router.get_upbit_order_chance(UPBIT_SMOKE_MARKET)
    except (BrokerNotReadyError, RuntimeError) as exc:
        reason = str(exc)
        _upbit_smoke_order_view(status="blocked", status_label="조회 실패", detail=reason, confirmation_token="")
        append_audit("danger", "Upbit 소액 주문 미리보기", reason)
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    accounts = account_snapshot.get("accounts", []) if isinstance(account_snapshot, dict) else []
    krw_account = accounts[0] if isinstance(accounts, list) and accounts and isinstance(accounts[0], dict) else {}
    available_krw = safe_float(krw_account.get("broker_cash"), 0.0)
    market_info = chance.get("market") if isinstance(chance.get("market"), dict) else {}
    bid_rules = market_info.get("bid") if isinstance(market_info.get("bid"), dict) else {}
    bid_account = chance.get("bid_account") if isinstance(chance.get("bid_account"), dict) else {}
    chance_balance = safe_float(bid_account.get("balance"), available_krw)
    if chance_balance > 0:
        available_krw = min(available_krw, chance_balance) if available_krw > 0 else chance_balance
    min_total = safe_float(bid_rules.get("min_total"), float(UPBIT_SMOKE_MIN_KRW))
    max_total = safe_float(bid_rules.get("max_total"), 0.0)
    bid_fee_rate = safe_float(chance.get("bid_fee"), 0.0)
    required_krw = amount * (1.0 + max(0.0, bid_fee_rate))
    blocked_reasons: list[str] = []
    if min_total > 0 and amount < min_total:
        blocked_reasons.append(f"거래소 최소 주문 {min_total:,.0f}원 미만")
    if max_total > 0 and amount > max_total:
        blocked_reasons.append(f"거래소 최대 주문 {max_total:,.0f}원 초과")
    if available_krw + 1e-9 < required_krw:
        blocked_reasons.append(f"수수료 포함 필요 금액 {required_krw:,.0f}원 대비 잔고 부족")

    now = datetime.now(timezone.utc)
    identifier = f"lt-smoke-{now.strftime('%Y%m%dT%H%M%S')}-{secrets.token_hex(4)}"
    order_intent = {
        "broker_id": "upbit",
        "strategy_id": str(strategy.get("strategy_id") or ""),
        "market": UPBIT_SMOKE_MARKET,
        "symbol": UPBIT_SMOKE_MARKET,
        "side": "BUY",
        "order_type": "price",
        "notional": amount,
        "identifier": identifier,
    }
    prepared = build_upbit_order_request(order_intent)
    if not prepared.can_send:
        blocked_reasons.append("주문 요청 설정 누락: " + ", ".join(prepared.blocked_reasons))
    ready = not blocked_reasons
    confirmation_token = secrets.token_urlsafe(24) if ready else ""
    expires = now + timedelta(seconds=UPBIT_SMOKE_PREVIEW_TTL_SECONDS)
    preview = prepared.preview()
    detail = (
        f"{UPBIT_SMOKE_MARKET} 시장가 매수 {amount:,}원 · 예상 수수료율 {bid_fee_rate:.4%} · "
        f"주문 가능 KRW {available_krw:,.0f}원"
    )
    if blocked_reasons:
        detail = " · ".join(blocked_reasons)
    state_row = _upbit_smoke_order_view(
        status="ready" if ready else "blocked",
        status_label="확인 대기" if ready else "차단",
        strategy_id=str(strategy.get("strategy_id") or ""),
        strategy_instance_id=str(strategy.get("strategy_instance_id") or ""),
        portfolio_id=str(
            (strategy.get("portfolio_gate") or {}).get("portfolioId")
            if isinstance(strategy.get("portfolio_gate"), dict)
            else ""
        ),
        market=UPBIT_SMOKE_MARKET,
        side="BUY",
        order_type="시장가 매수",
        notional_krw=amount,
        available_krw=available_krw,
        required_krw=required_krw,
        minimum_krw=min_total,
        maximum_krw=max_total,
        fee_rate=bid_fee_rate,
        identifier=identifier,
        confirmation_token=confirmation_token,
        expires_at=expires.isoformat().replace("+00:00", "Z"),
        expires_epoch=expires.timestamp(),
        used=False,
        broker_order_id="",
        broker_state="",
        detail=detail,
        request_preview=preview,
        blocked_reasons=blocked_reasons,
    )
    append_audit(
        "info" if ready else "danger",
        "Upbit 소액 주문 미리보기",
        detail + (" · 실제 주문 전송 없음" if ready else ""),
    )
    return {"ok": ready, "reason": detail, "preview": state_row, "snapshot": snapshot()}


@_serialized_safety_mutation
@_serialized_upbit_order_authority
def submit_upbit_smoke_order(confirmation_token: object, *, confirmed: bool) -> dict[str, Any]:
    if _upbit_functional_durable_authority_open():
        return {
            "ok": False,
            "reason": "upbit-functional-session-closes-smoke-order-route",
            "snapshot": snapshot(),
        }
    preview = dict(STATE.get("upbit_smoke_order", {}))
    token = str(confirmation_token or "")
    if not confirmed or not token or not secrets.compare_digest(token, str(preview.get("confirmation_token") or "")):
        return {"ok": False, "reason": "정확한 주문 미리보기의 1회 확인 토큰이 필요합니다.", "snapshot": snapshot()}
    if preview.get("status") != "ready" or bool(preview.get("used")):
        return {"ok": False, "reason": "이미 사용되었거나 전송 가능한 미리보기가 아닙니다.", "snapshot": snapshot()}
    if safe_float(preview.get("expires_epoch"), 0.0) <= datetime.now(timezone.utc).timestamp():
        _upbit_smoke_order_view(status="expired", status_label="만료", confirmation_token="", detail="미리보기가 만료되었습니다. 다시 조회하세요.")
        return {"ok": False, "reason": "미리보기가 만료되었습니다. 다시 조회하세요.", "snapshot": snapshot()}
    strategy = approved_upbit_smoke_strategy(preview.get("strategy_id"))
    if strategy is None:
        return {
            "ok": False,
            "reason": "미리보기 전략의 Upbit before-live-small/live_small_eligible 승인이 더 이상 유효하지 않습니다.",
            "snapshot": snapshot(),
        }
    current_portfolio_id = str(
        (strategy.get("portfolio_gate") or {}).get("portfolioId")
        if isinstance(strategy.get("portfolio_gate"), dict)
        else ""
    )
    if (
        str(preview.get("strategy_instance_id") or "").strip()
        != str(strategy.get("strategy_instance_id") or "").strip()
        or str(preview.get("portfolio_id") or "").strip()
        != current_portfolio_id
    ):
        reason = (
            "미리보기의 Upbit Strategy/Portfolio Instance가 현재 Live "
            "Deployment와 달라졌습니다. 다시 조회하세요."
        )
        _upbit_smoke_order_view(
            status="blocked",
            status_label="전송 직전 차단",
            detail=reason,
            confirmation_token="",
        )
        return {"ok": False, "reason": reason, "snapshot": snapshot()}
    if STATE.get("kill_switch") or STATE.get("new_entries_blocked"):
        return {"ok": False, "reason": "긴급/신규 진입 차단이 켜져 있어 실제 주문을 전송할 수 없습니다.", "snapshot": snapshot()}
    if STATE.get("dry_run") or current_mode() != "SMALL_LIVE":
        return {"ok": False, "reason": "Dry Run을 해제하고 SMALL_LIVE에서만 점검 주문을 보낼 수 있습니다.", "snapshot": snapshot()}
    if not real_orders_enabled():
        return {"ok": False, "reason": "LIVE_TRADER_ENABLE_REAL_ORDERS=true가 필요합니다.", "snapshot": snapshot()}
    if STATE.get("operator_confirmed") is not True:
        return {
            "ok": False,
            "reason": "실제 주문 전 운용자 수동 확인이 필요합니다.",
            "snapshot": snapshot(),
        }

    amount = int(safe_float(preview.get("notional_krw"), 0.0))
    if amount < UPBIT_SMOKE_MIN_KRW or amount > UPBIT_SMOKE_MAX_KRW:
        return {"ok": False, "reason": "서버의 소액 주문 하드 한도를 벗어났습니다.", "snapshot": snapshot()}

    router = LiveBrokerRouter()
    try:
        fresh_account = router.get_account_snapshot("upbit")
        accounts = fresh_account.get("accounts", []) if isinstance(fresh_account, dict) else []
        row = accounts[0] if isinstance(accounts, list) and accounts and isinstance(accounts[0], dict) else {}
        fresh_cash = safe_float(row.get("broker_cash"), 0.0)
        required_krw = safe_float(preview.get("required_krw"), float(amount))
        if fresh_cash + 1e-9 < required_krw:
            raise BrokerNotReadyError(f"전송 직전 잔고 {fresh_cash:,.0f}원이 필요 금액 {required_krw:,.0f}원보다 적습니다.")
    except (BrokerNotReadyError, RuntimeError) as exc:
        reason = str(exc)
        _upbit_smoke_order_view(status="blocked", status_label="전송 직전 차단", detail=reason, confirmation_token="")
        append_audit("danger", "Upbit 실제 소액 주문", reason)
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    # 네트워크 결과가 불명확해도 같은 identifier로 재전송하지 않도록 전송 직전에 소진 처리합니다.
    _upbit_smoke_order_view(status="submitting", status_label="전송 중", used=True, confirmation_token="")
    now = datetime.now(timezone.utc)
    dispatch_intent = OrderIntent(
        strategy_id=str(strategy.get("strategy_id") or ""),
        asset="CRYPTO",
        symbol=str(preview.get("market") or UPBIT_SMOKE_MARKET),
        side="BUY",
        quantity=1.0,
        reference_price=float(amount),
        mode="SMALL_LIVE",
        reason="Upbit broker smoke operational dispatch revalidation",
        metadata={
            "broker_id": "upbit",
            "profile_id": "crypto",
            "strategy_instance_id": str(
                strategy.get("strategy_instance_id") or ""
            ),
            "portfolio_id": current_portfolio_id,
            "instrument_id": str(
                preview.get("market") or UPBIT_SMOKE_MARKET
            ),
            "target_revision": int(now.timestamp()),
            "order_purpose": "BROKER_SMOKE",
            "order_type": "price",
            "market_event_time": now.isoformat().replace("+00:00", "Z"),
            "market_data_verified": True,
        },
    )
    result = submit_order_intent(
        snapshot(),
        dispatch_intent,
        dry_run=False,
        audit_event="Upbit Broker Smoke",
    )
    dispatch_order = (
        dict(result.get("order"))
        if isinstance(result.get("order"), dict)
        else {}
    )
    if result.get("ok") is not True:
        reason = str(result.get("reason") or "Upbit 주문 경로가 차단되었습니다.")
        dispatch_state = str(dispatch_order.get("state") or "").strip().lower()
        smoke_status = (
            "unknown"
            if dispatch_state == "unknown"
            else "blocked"
            if dispatch_state == "risk_blocked"
            else "rejected"
        )
        smoke_label = (
            "결과 불명·조정 필요"
            if smoke_status == "unknown"
            else "전송 직전 차단"
            if smoke_status == "blocked"
            else "거절"
        )
        _upbit_smoke_order_view(
            status=smoke_status,
            status_label=smoke_label,
            detail=reason,
            order_id=str(dispatch_order.get("order_id") or ""),
            order_state=str(dispatch_order.get("state") or ""),
            runtime_authorization=(
                dispatch_order.get("runtime_authorization")
                if isinstance(
                    dispatch_order.get("runtime_authorization"), dict
                )
                else {}
            ),
        )
        return {
            **result,
            "dispatch_order": dispatch_order,
            "order": dict(STATE["upbit_smoke_order"]),
        }

    broker_response = (
        dispatch_order.get("broker_response")
        if isinstance(dispatch_order.get("broker_response"), dict)
        else {}
    )
    payload = (
        broker_response.get("json")
        if isinstance(broker_response.get("json"), dict)
        else {}
    )
    order_uuid = str(
        dispatch_order.get("broker_order_id") or payload.get("uuid") or ""
    ).strip()
    broker_state = str(payload.get("state") or "wait").strip().lower()
    order_detail = payload
    if order_uuid:
        try:
            order_detail = router.get_upbit_order(order_uuid)
            broker_state = str(order_detail.get("state") or broker_state).strip().lower()
        except (BrokerNotReadyError, RuntimeError):
            pass
    trades = order_detail.get("trades") if isinstance(order_detail.get("trades"), list) else []
    executed_volume = sum(safe_float(item.get("volume"), 0.0) for item in trades if isinstance(item, dict))
    executed_funds = sum(safe_float(item.get("funds"), 0.0) for item in trades if isinstance(item, dict))
    paid_fee = safe_float(order_detail.get("paid_fee"), 0.0)
    filled_after_cancel = broker_state == "cancel" and executed_funds > 0
    final_status = "filled" if broker_state == "done" or filled_after_cancel else "acknowledged"
    detail = (
        f"Upbit 주문 접수 {order_uuid or '-'} · 상태 {broker_state or '-'} · "
        f"체결금액 {executed_funds:,.0f}원 · 수수료 {paid_fee:,.2f}원"
    )
    _upbit_smoke_order_view(
        status=final_status,
        status_label="체결·잔여취소" if filled_after_cancel else "체결" if final_status == "filled" else "접수",
        broker_order_id=order_uuid,
        broker_state=broker_state,
        executed_volume=executed_volume,
        executed_funds=executed_funds,
        paid_fee=paid_fee,
        detail=detail,
        broker_response=order_detail,
        order_id=str(dispatch_order.get("order_id") or ""),
        order_state=str(dispatch_order.get("state") or ""),
        runtime_authorization=(
            dispatch_order.get("runtime_authorization")
            if isinstance(dispatch_order.get("runtime_authorization"), dict)
            else {}
        ),
    )
    append_audit("info", "Upbit 실제 소액 주문", detail)
    poll_execution_events("upbit")
    run_reconciliation()
    return {
        "ok": True,
        "reason": detail,
        "order": dict(STATE["upbit_smoke_order"]),
        "dispatch_order": dispatch_order,
        "snapshot": snapshot(),
    }


def refresh_upbit_smoke_order() -> dict[str, Any]:
    current = dict(STATE.get("upbit_smoke_order", {}))
    order_uuid = str(current.get("broker_order_id") or "").strip()
    if not order_uuid:
        return {"ok": False, "reason": "조회할 Upbit 주문 UUID가 없습니다.", "snapshot": snapshot()}
    try:
        detail = LiveBrokerRouter().get_upbit_order(order_uuid)
    except (BrokerNotReadyError, RuntimeError) as exc:
        return {"ok": False, "reason": str(exc), "snapshot": snapshot()}
    broker_state = str(detail.get("state") or "").strip().lower()
    trades = detail.get("trades") if isinstance(detail.get("trades"), list) else []
    executed_volume = sum(safe_float(item.get("volume"), 0.0) for item in trades if isinstance(item, dict))
    executed_funds = sum(safe_float(item.get("funds"), 0.0) for item in trades if isinstance(item, dict))
    paid_fee = safe_float(detail.get("paid_fee"), 0.0)
    filled_after_cancel = broker_state == "cancel" and executed_funds > 0
    final_status = "filled" if broker_state == "done" or filled_after_cancel else "acknowledged"
    detail_text = f"Upbit 주문 {order_uuid} · 상태 {broker_state or '-'} · 체결금액 {executed_funds:,.0f}원 · 수수료 {paid_fee:,.2f}원"
    _upbit_smoke_order_view(
        status=final_status,
        status_label="체결·잔여취소" if filled_after_cancel else "체결" if final_status == "filled" else "접수",
        broker_state=broker_state,
        executed_volume=executed_volume,
        executed_funds=executed_funds,
        paid_fee=paid_fee,
        detail=detail_text,
        broker_response=detail,
    )
    poll_execution_events("upbit")
    run_reconciliation()
    return {"ok": True, "reason": detail_text, "order": dict(STATE["upbit_smoke_order"]), "snapshot": snapshot()}


def _run_reconciliation_without_public_fence(
    *,
    refresh_brokers: bool = True,
    include_snapshot: bool = True,
) -> dict[str, Any]:
    STATE["reconciliation_last_run"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    broker_data = (
        refresh_broker_reconciliation()
        if refresh_brokers
        else STATE.get("broker_reconciliation", {})
    )
    if not isinstance(broker_data, dict):
        broker_data = refresh_broker_reconciliation()
    reconciliation = reconciliation_snapshot()
    summary = reconciliation["summary"]
    broker_truth = broker_position_truth_snapshot(reconciliation)
    was_broker_blocked = bool(STATE.get("broker_truth_blocked"))
    STATE["broker_truth_blocked"] = bool(broker_truth.get("newEntriesBlocked"))
    if STATE["broker_truth_blocked"]:
        STATE["new_entries_blocked"] = True
    elif (
        was_broker_blocked
        and not STATE.get("kill_switch")
        and not STATE.get("kill_switch_rearm_required")
        and not STATE.get("manual_new_entries_blocked")
    ):
        STATE["new_entries_blocked"] = False
    append_audit(
        "danger" if int(summary["mismatch_count"]) or broker_data["errors"] else "warn" if int(summary["api_required_count"]) or int(summary.get("capability_gap_count") or 0) else "info",
        "포지션/계좌 대조",
        (
            f"{summary['status_label']}: API/원장 필요 {summary['api_required_count']}개, "
            f"미지원 capability {summary.get('capability_gap_count', 0)}개, "
            f"불일치 {summary['mismatch_count']}개, 조회 오류 {len(broker_data['errors'])}개"
        ),
    )
    reconciliation_blocked = bool(
        broker_truth.get("newEntriesBlocked")
        or int(summary.get("mismatch_count") or 0)
        or int(summary.get("api_required_count") or 0)
        or int(summary.get("capability_gap_count") or 0)
        or broker_data.get("errors")
    )
    sync_operational_incident(
        code="RECONCILIATION_BLOCKED",
        active=reconciliation_blocked,
        severity=(
            "CRITICAL"
            if int(summary.get("mismatch_count") or 0) or broker_data.get("errors")
            else "ERROR"
        ),
        title="포지션·계좌 3자 대조 차단",
        detail=(
            f"API/원장 필요 {summary.get('api_required_count', 0)}개 · "
            f"capability gap {summary.get('capability_gap_count', 0)}개 · "
            f"불일치 {summary.get('mismatch_count', 0)}개 · "
            f"조회 오류 {len(broker_data.get('errors') or [])}개"
            if reconciliation_blocked
            else "Broker Snapshot·실시간 Event·내부 Ledger 대조가 복구되었습니다."
        ),
        impact=(
            "신규 위험 주문 차단"
            if reconciliation_blocked
            else "대조 기반 차단 원인 해소"
        ),
    )
    automatic_results = automatic_live_promotion_sweep()
    return {
        "ok": True,
        "reason": f"대조 완료: {summary['status_label']} 상태",
        "reconciliation": reconciliation,
        "broker_position_truth": broker_truth,
        "automatic_promotion": automatic_results,
        **({"snapshot": snapshot()} if include_snapshot else {}),
    }


@_serialized_safety_mutation
@_two_phase_kis_route_control("SETTINGS")
def run_reconciliation(
    *,
    refresh_brokers: bool = True,
    include_snapshot: bool = True,
) -> dict[str, Any]:
    """Publish a KIS control reservation around broker-truth mutation.

    Durable Kill recovery calls the private body only after the Kill latch has
    already closed ordinary entry.  That path can hold the runtime manager
    lock, so it must never reacquire the KIS route in reverse order.
    """

    return _run_reconciliation_without_public_fence(
        refresh_brokers=refresh_brokers,
        include_snapshot=include_snapshot,
    )


PREFLIGHT_RECONCILIATION_MAX_AGE_SECONDS = 60


def refresh_preflight_reconciliation(
    strategy: dict[str, Any],
    *,
    maximum_age_seconds: int = PREFLIGHT_RECONCILIATION_MAX_AGE_SECONDS,
) -> dict[str, Any]:
    """Build broker-scoped, fresh REST/Event/Ledger evidence for Preflight.

    The broker poll only reads broker state. It drains private execution events
    into the local event ledger and forces a new REST account/position snapshot
    for the selected Deployment route. A previous cached PASS is never enough.
    """

    broker_id = strategy_broker_id(strategy)
    maximum_age = max(1, int(maximum_age_seconds))
    try:
        poll_result = poll_execution_events(
            broker_id,
            force_snapshot=True,
            include_snapshot=False,
        )
    except Exception as exc:  # Broker read boundary must become evidence, not a crash.
        poll_result = {
            "ok": False,
            "errors": [
                {
                    "broker_id": broker_id,
                    "detail": f"{type(exc).__name__}: {str(exc)[:240]}",
                }
            ],
        }

    poll_errors = (
        poll_result.get("errors", [])
        if isinstance(poll_result, dict)
        and isinstance(poll_result.get("errors"), list)
        else []
    )
    poll_ok = bool(
        isinstance(poll_result, dict)
        and poll_result.get("ok") is True
        and poll_result.get("coalesced") is not True
        and not poll_errors
    )
    if poll_ok:
        STATE["reconciliation_last_run"] = datetime.now().strftime(
            "%Y-%m-%d %H:%M:%S"
        )

    reconciliation = reconciliation_snapshot()
    scoped_summary = _reconciliation_summary_for_broker_snapshot(
        reconciliation,
        broker_id,
    )
    positions_data = [
        item
        for item in reconciliation.get("positions", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == broker_id
    ]
    accounts_data = [
        item
        for item in reconciliation.get("accounts", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == broker_id
    ]
    scoped_errors = [
        item
        for item in reconciliation.get("errors", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == broker_id
    ]

    broker_cache = (
        STATE.get("broker_reconciliation")
        if isinstance(STATE.get("broker_reconciliation"), dict)
        else {}
    )
    execution_state = (
        STATE.get("execution_events")
        if isinstance(STATE.get("execution_events"), dict)
        else {}
    )
    program_state = (
        STATE.get("program_ledger")
        if isinstance(STATE.get("program_ledger"), dict)
        else {}
    )
    position_observations = (
        broker_cache.get("position_observations")
        if isinstance(broker_cache.get("position_observations"), dict)
        else {}
    )
    broker_observation = (
        position_observations.get(broker_id)
        if isinstance(position_observations.get(broker_id), dict)
        else {}
    )
    evidence_times = {
        "broker_snapshot": broker_observation.get("observedAt")
        or broker_observation.get("observed_at"),
        "execution_event": execution_state.get("last_poll"),
        "local_ledger": program_state.get("last_event_sync"),
    }
    evidence_ages = {
        label: seconds_since(value)
        for label, value in evidence_times.items()
    }
    successful_accounts = {
        str(item).strip().lower()
        for item in broker_cache.get("successful_account_brokers", [])
    }
    successful_positions = {
        str(item).strip().lower()
        for item in broker_cache.get("successful_position_brokers", [])
    }
    execution_errors = [
        item
        for item in execution_state.get("errors", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == broker_id
    ]
    evidence_issues: list[str] = []
    if not broker_id:
        evidence_issues.append("deployment-broker-route-missing")
    if not poll_ok:
        evidence_issues.append(
            "broker-poll-coalesced"
            if isinstance(poll_result, dict)
            and poll_result.get("coalesced") is True
            else "broker-poll-failed"
        )
    if broker_id not in successful_accounts:
        evidence_issues.append("broker-account-snapshot-unverified")
    if broker_id not in successful_positions:
        evidence_issues.append("broker-position-snapshot-unverified")
    if scoped_errors or execution_errors:
        evidence_issues.append("broker-or-execution-poll-error")
    for label, age in evidence_ages.items():
        if age is None:
            evidence_issues.append(f"{label}-timestamp-missing")
        elif age > maximum_age:
            evidence_issues.append(f"{label}-stale:{age}s")

    fresh = not evidence_issues
    three_way_verified = bool(
        fresh
        and scoped_summary.get("status") == "pass"
        and int(scoped_summary.get("row_count") or 0) > 0
    )
    if not three_way_verified and scoped_summary.get("status") != "pass":
        evidence_issues.append("broker-event-ledger-mismatch-or-unverified")
    if not three_way_verified and int(scoped_summary.get("row_count") or 0) == 0:
        evidence_issues.append("broker-scoped-reconciliation-rows-missing")
    evidence_issues = list(dict.fromkeys(evidence_issues))
    freshness_detail = (
        "Fresh Broker REST Snapshot·Execution Event·Local Ledger 3자 대조를 "
        f"{max(evidence_ages.values() or [0])}초 이내 증거로 확인했습니다."
        if fresh and three_way_verified
        else "Fresh 3자 대조 차단: " + ", ".join(evidence_issues)
    )
    scoped_summary.update(
        {
            "last_run": STATE.get("reconciliation_last_run") or "미실행",
            "fresh": fresh,
            "three_way_verified": three_way_verified,
            "freshness_detail": freshness_detail,
            "freshness_max_age_seconds": maximum_age,
            "evidence_ages_seconds": evidence_ages,
            "error_count": len(scoped_errors) + len(execution_errors),
        }
    )
    if not three_way_verified:
        STATE["broker_truth_blocked"] = True
        STATE["new_entries_blocked"] = True
    return {
        "summary": scoped_summary,
        "positions": positions_data,
        "accounts": accounts_data,
        "errors": scoped_errors,
        "poll": {
            "ok": poll_ok,
            "coalesced": bool(
                isinstance(poll_result, dict)
                and poll_result.get("coalesced") is True
            ),
            "error_count": len(poll_errors),
        },
    }


@_serialized_safety_mutation
@_two_phase_kis_route_control("SETTINGS")
def run_final_preflight(
    deployment_id: str = "",
    strategy_id: str = "",
) -> dict[str, Any]:
    STATE["preflight_last_run"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    data = snapshot()
    strategies = data.get("strategies") if isinstance(data.get("strategies"), list) else []
    selected = _operational_strategy(
        strategies,
        deployment_id=deployment_id,
        strategy_id=strategy_id,
    )
    requested_deployment = str(deployment_id or "").strip()
    requested_strategy = str(strategy_id or "").strip()
    explicit_context = bool(requested_deployment or requested_strategy)
    if selected is not None and (
        (requested_deployment and str(selected.get("deployment_id") or "") != requested_deployment)
        or (requested_strategy and str(selected.get("strategy_id") or "") != requested_strategy)
    ):
        selected = None
    if explicit_context and selected is None:
        scoped_checks = [
            {
                "label": "Deployment 실행 컨텍스트",
                "status": "fail",
                "detail": "요청한 deployment_id/strategy_id와 정확히 일치하는 Artifact를 찾지 못했습니다.",
            }
        ]
        scoped_launch = launch_report(scoped_checks)
        doctor_data = {
            **data,
            "final_preflight": scoped_checks,
            "launch_report": scoped_launch,
        }
        doctor_diagnostics = persist_doctor_diagnostic_snapshot(doctor_data)
        append_audit(
            "danger",
            "최종 Preflight",
            "명시한 Deployment 실행 컨텍스트가 없어 fail-closed로 차단했습니다.",
        )
        return {
            "ok": False,
            "reason": "요청한 Deployment 실행 컨텍스트를 찾지 못했습니다.",
            "preflight_snapshot": {
                "status": "BLOCKED",
                "error": "deployment-context-not-found",
            },
            "doctor_diagnostics": doctor_diagnostics,
            "snapshot": snapshot(),
        }
    if selected is not None:
        data = {
            **data,
            "reconciliation": refresh_preflight_reconciliation(selected),
        }
    scoped_checks = (
        final_preflight_checks(
            [selected],
            data.get("brokers") if isinstance(data.get("brokers"), list) else [],
            data.get("reconciliation") if isinstance(data.get("reconciliation"), dict) else reconciliation_snapshot(),
            current_strategy=selected,
        )
        if selected is not None
        else data.get("final_preflight", [])
    )
    scoped_launch = launch_report(scoped_checks)
    hard_stop_count = int(scoped_launch["hard_stop_count"])
    warning_count = int(scoped_launch["warning_count"])
    governance_preflight: dict[str, Any] | None = None
    if selected is not None:
        try:
            manifest = ensure_operational_deployment_manifest(selected)
            reconciliation = data.get("reconciliation") if isinstance(data.get("reconciliation"), dict) else {}
            checks = [
                {
                    "checkId": f"preflight-{governance_sha256(str(check.get('label') or index))[:16]}",
                    "status": str(check.get("status") or "fail").upper(),
                    "detail": str(check.get("detail") or ""),
                    "evidenceHash": governance_sha256(
                        {
                            "label": str(check.get("label") or ""),
                            "status": str(check.get("status") or ""),
                            "detail": str(check.get("detail") or ""),
                        }
                    ),
                }
                for index, check in enumerate(scoped_checks)
                if isinstance(check, dict)
            ]
            preflight_snapshot = OPERATIONAL_GOVERNANCE.create_preflight_snapshot(
                deployment_id=manifest.deployment_id,
                deployment_manifest_hash=manifest.manifest_hash,
                checks=checks,
                reconciliation_hash=governance_sha256(
                    {
                        "summary": reconciliation.get("summary", {}),
                        "positions": reconciliation.get("positions", []),
                        "accounts": reconciliation.get("accounts", []),
                    }
                ),
                broker_snapshot_hash=governance_sha256(
                    {
                        "brokers": data.get("brokers", []),
                        "executionStreams": data.get("execution_streams", {}),
                        "generatedAt": data.get("generated_at", ""),
                    }
                ),
                metadata={
                    "mode": str(data.get("mode") or "MONITOR"),
                    "strategyId": str(selected.get("strategy_id") or ""),
                    "portfolioId": str((selected.get("portfolio_gate") or {}).get("portfolioId") or ""),
                },
            )
            STATE["selected_deployment_id"] = manifest.deployment_id
            STATE["selected_strategy_id"] = str(selected.get("strategy_id") or "")
            STATE["latest_preflight_snapshot_id"] = preflight_snapshot.snapshot_id
            governance_preflight = preflight_snapshot.to_dict()
            if hard_stop_count == 0 and warning_count == 0:
                STATE["kill_switch_rearm_required"] = False
        except (OSError, sqlite3.Error, ValueError) as exc:
            scoped_checks = [
                *scoped_checks,
                {
                    "label": "운영 거버넌스 저장소",
                    "status": "fail",
                    "detail": f"Preflight Snapshot 저장 실패: {type(exc).__name__}",
                },
            ]
            scoped_launch = launch_report(scoped_checks)
            hard_stop_count = int(scoped_launch["hard_stop_count"])
            warning_count = int(scoped_launch["warning_count"])
            governance_preflight = {
                "status": "BLOCKED",
                "error": f"{type(exc).__name__}: {str(exc)[:240]}",
            }
    doctor_data = {
        **data,
        "final_preflight": scoped_checks,
        "launch_report": scoped_launch,
    }
    doctor_diagnostics = persist_doctor_diagnostic_snapshot(doctor_data)
    append_audit(
        "danger" if hard_stop_count else "warn" if warning_count else "info",
        "최종 Preflight",
        (
            f"hard stop {hard_stop_count}개, warning {warning_count}개. "
            f"{scoped_launch['lock_reason']} · snapshot "
            f"{(governance_preflight or {}).get('snapshotId', '저장 실패/미적용')}"
        ),
    )
    return {
        "ok": True,
        "reason": f"최종 점검 완료: hard stop {hard_stop_count}개, warning {warning_count}개",
        "preflight_snapshot": governance_preflight,
        "doctor_diagnostics": doctor_diagnostics,
        "snapshot": snapshot(),
    }


def export_audit(format_name: str) -> dict[str, Any]:
    normalized = format_name.lower().strip()
    if normalized not in {"csv", "html"}:
        return {"ok": False, "reason": "unsupported export format", "snapshot": snapshot()}

    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    append_audit("info", "감사 로그 내보내기", f"{normalized.upper()} 감사 로그를 생성했습니다.")
    rows = STATE["audit"]

    if normalized == "csv":
        stream = StringIO()
        writer = csv.writer(stream)
        writer.writerow(["time", "level", "event", "detail"])
        for row in rows:
            writer.writerow([row["time"], row["level"], row["event"], row["detail"]])
        return {
            "ok": True,
            "format": "csv",
            "filename": f"live-trader-audit-{timestamp}.csv",
            "mime": "text/csv;charset=utf-8",
            "content": stream.getvalue(),
            "snapshot": snapshot(),
        }

    body_rows = "\n".join(
        "<tr>"
        f"<td>{html.escape(str(row['time']))}</td>"
        f"<td>{html.escape(str(row['level']))}</td>"
        f"<td>{html.escape(str(row['event']))}</td>"
        f"<td>{html.escape(str(row['detail']))}</td>"
        "</tr>"
        for row in rows
    )
    content = (
        "<!doctype html><meta charset='utf-8'>"
        "<title>Live Trader Audit</title>"
        "<style>body{font-family:Segoe UI,sans-serif;padding:24px;color:#111827}"
        "table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:8px;text-align:left}"
        "th{background:#eff6ff}</style>"
        "<h1>Live Trader Audit</h1>"
        f"<p>Generated at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}</p>"
        "<table><thead><tr><th>Time</th><th>Level</th><th>Event</th><th>Detail</th></tr></thead>"
        f"<tbody>{body_rows}</tbody></table>"
    )
    return {
        "ok": True,
        "format": "html",
        "filename": f"live-trader-audit-{timestamp}.html",
        "mime": "text/html;charset=utf-8",
        "content": content,
        "snapshot": snapshot(),
    }


def evaluate_order_gate(checks: dict[str, Any], side: str, dry_run: bool) -> tuple[bool, str, str, str]:
    ok, state_name, queue_state, reason, _report = evaluate_order_gate_with_report(checks, side, dry_run)
    return ok, state_name, queue_state, reason


def strategy_for_order_intent(checks: dict[str, Any], intent: OrderIntent) -> dict[str, Any]:
    strategies = checks.get("strategies") if isinstance(checks.get("strategies"), list) else []
    return next((strategy for strategy in strategies if str(strategy.get("strategy_id")) == intent.strategy_id), {})


def futures_risk_reducing_verified(
    checks: dict[str, Any],
    intent: OrderIntent,
) -> bool:
    """Verify a reduce-only claim against fresh broker position truth.

    ``risk_reducing`` is an untrusted intent claim.  A missing position row is
    deliberately different from a confirmed flat position: neither can prove
    that a new order reduces risk.  The check therefore requires a recent,
    successful snapshot for the exact broker and instrument and rejects orders
    that cross through zero.

    The historical function name is kept because futures rollout code imports
    it, but the invariant applies to every live broker.
    """

    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    if metadata.get("risk_reducing") is not True:
        return False
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    if broker_id not in {"kis", "binance", "binance-futures", "upbit"}:
        return False

    reconciliation = (
        STATE.get("broker_reconciliation")
        if isinstance(STATE.get("broker_reconciliation"), dict)
        else {}
    )
    successful = {
        str(item).strip().lower()
        for item in reconciliation.get("successful_position_brokers", [])
        if str(item).strip()
    }
    if broker_id not in successful:
        return False
    failed = {
        str(item.get("broker_id") or "").strip().lower()
        for item in reconciliation.get("errors", [])
        if isinstance(item, dict)
    }
    if broker_id in failed:
        return False
    fetched_age = seconds_since(reconciliation.get("fetched_at"))
    if (
        fetched_age is None
        or fetched_age > REDUCE_ONLY_POSITION_MAX_AGE_SECONDS
    ):
        return False

    # A merged multi-broker cache may receive a new global fetched_at when a
    # different broker is refreshed.  If broker-scoped observation evidence is
    # available, it must independently be fresh as well.
    observations = reconciliation.get("position_observations")
    broker_observation = (
        observations.get(broker_id)
        if isinstance(observations, dict)
        and isinstance(observations.get(broker_id), dict)
        else {}
    )
    if broker_observation:
        observed_age = seconds_since(
            broker_observation.get("observedAt")
            or broker_observation.get("observed_at")
        )
        if (
            observed_age is None
            or observed_age > REDUCE_ONLY_POSITION_MAX_AGE_SECONDS
        ):
            return False
    canonical_symbol = _canonical_restore_instrument(
        broker_id,
        str(intent.symbol or "").upper().removesuffix(".PERP"),
    )
    matching_positions = [
        item
        for item in reconciliation.get("positions", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == broker_id
        and _canonical_restore_instrument(
            broker_id,
            str(item.get("symbol") or "").upper().removesuffix(".PERP"),
        )
        == canonical_symbol
    ]
    if not matching_positions:
        return False

    if broker_id == "binance-futures":
        strategy = strategy_for_order_intent(checks, intent)
        if not strategy:
            try:
                strategy = next(
                    (
                        item
                        for item in strategy_rows(portfolio_rows())
                        if str(item.get("strategy_id") or "")
                        == intent.strategy_id
                    ),
                    {},
                )
            except (OSError, TypeError, ValueError, json.JSONDecodeError):
                return False
        if not strategy or strategy_broker_id(strategy) != "binance-futures":
            return False
        direction = str(
            strategy.get("position_direction") or ""
        ).strip().lower()
        if direction not in {"long", "short"}:
            return False
        requested_side = "SHORT" if direction == "short" else "LONG"
        exact_positions = [
            item
            for item in matching_positions
            if normalized_reconciliation_position_side(
                item,
                source="broker",
            )
            == requested_side
        ]
        one_way_positions = [
            item
            for item in matching_positions
            if normalized_reconciliation_position_side(
                item,
                source="broker",
            )
            == "BOTH"
        ]
        matching_positions = exact_positions or one_way_positions
        if not matching_positions:
            return False

    try:
        order_quantity = float(intent.quantity)
    except (TypeError, ValueError, OverflowError):
        return False
    position_quantity = sum(
        _restore_quantity(item)
        for item in matching_positions
    )
    if (
        not math.isfinite(order_quantity)
        or order_quantity <= 0
        or not math.isfinite(position_quantity)
    ):
        return False
    tolerance = max(1e-12, abs(position_quantity) * 1e-9)
    if position_quantity < -tolerance:
        return (
            intent.side == "BUY"
            and order_quantity <= abs(position_quantity) + tolerance
            and abs(position_quantity + order_quantity)
            < abs(position_quantity)
        )
    return (
        position_quantity > tolerance
        and intent.side == "SELL"
        and order_quantity <= position_quantity + tolerance
        and abs(position_quantity - order_quantity)
        < abs(position_quantity)
    )


def _intersect_futures_execution_policies(
    policies: list[dict[str, Any]],
) -> dict[str, Any]:
    normalized = [
        normalize_futures_execution_policy(policy)
        for policy in policies
        if isinstance(policy, dict)
    ]
    if not normalized:
        result = normalize_futures_execution_policy(None)
        result["valid"] = False
        result["blockers"] = ["futures-policy-missing"]
        return result
    margins = {
        str(item.get("marginMode") or "")
        for item in normalized
        if str(item.get("marginMode") or "")
    }
    blockers = [
        str(blocker)
        for item in normalized
        for blocker in item.get("blockers") or []
        if str(blocker)
    ]
    if len(margins) != 1:
        blockers.append("futures-policy-margin-conflict")
    strict = normalize_futures_execution_policy(
        {
            "marginMode": next(iter(margins), "ISOLATED"),
            "maxLeverageMultiplier": min(
                safe_float(item.get("maxLeverageMultiplier"), 1.0)
                for item in normalized
            ),
            "perTradeRiskPercent": min(
                safe_float(item.get("perTradeRiskPercent"), 0.5)
                for item in normalized
            ),
            "maxNotionalPercent": min(
                safe_float(item.get("maxNotionalPercent"), 10.0)
                for item in normalized
            ),
        }
    )
    blockers.extend(
        str(item) for item in strict.get("blockers") or [] if str(item)
    )
    strict["blockers"] = list(dict.fromkeys(blockers))
    strict["valid"] = not strict["blockers"]
    strict["source"] = "strict-policy-intersection"
    return strict


def _intent_futures_execution_policy(
    strategy: dict[str, Any],
    intent: OrderIntent,
) -> dict[str, Any]:
    artifact_policy = (
        strategy.get("futures_execution_policy")
        if isinstance(strategy.get("futures_execution_policy"), dict)
        else futures_execution_policy_from_artifact(strategy)
    )
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    intent_policy = (
        metadata.get("futures_execution_policy")
        if isinstance(metadata.get("futures_execution_policy"), dict)
        and metadata.get("futures_execution_policy")
        else None
    )
    return _intersect_futures_execution_policies(
        [
            dict(artifact_policy),
            *([dict(intent_policy)] if isinstance(intent_policy, dict) else []),
        ]
    )


def _strategy_stop_loss_percent(strategy: dict[str, Any]) -> float:
    parameters = (
        strategy.get("parameters")
        if isinstance(strategy.get("parameters"), dict)
        else {}
    )
    settings = (
        strategy.get("settings")
        if isinstance(strategy.get("settings"), dict)
        else {}
    )
    definitions = [
        strategy.get("customStrategyDefinition"),
        strategy.get("custom_strategy_definition"),
        parameters.get("customStrategyDefinition"),
        parameters.get("custom_strategy_definition"),
        settings.get("customStrategyDefinition"),
        settings.get("custom_strategy_definition"),
    ]
    candidates: list[object] = [
        strategy.get("stopLossPct"),
        strategy.get("stop_loss_pct"),
        parameters.get("stopLossPct"),
        parameters.get("stop_loss_pct"),
        settings.get("stopLossPct"),
        settings.get("stop_loss_pct"),
    ]
    for definition in definitions:
        if not isinstance(definition, dict):
            continue
        risk_rules = (
            definition.get("riskRules")
            if isinstance(definition.get("riskRules"), dict)
            else definition.get("risk_rules")
            if isinstance(definition.get("risk_rules"), dict)
            else {}
        )
        candidates.extend(
            [
                risk_rules.get("stopLossPct"),
                risk_rules.get("stop_loss_pct"),
            ]
        )
    for value in candidates:
        percent = safe_float(value, 0.0)
        if 0.0 < percent < 100.0:
            return percent
    return 0.0


def _binance_futures_live_order_risk(
    checks: dict[str, Any],
    intent: OrderIntent,
) -> dict[str, Any]:
    strategy = strategy_for_order_intent(checks, intent)
    if not strategy:
        return {
            "status": "BLOCKED",
            "blockers": ["strategy-artifact-missing"],
            "warnings": [],
        }
    integrity = (
        strategy.get("artifact_integrity")
        if isinstance(strategy.get("artifact_integrity"), dict)
        else {}
    )
    if integrity.get("valid") is not True:
        return {
            "status": "BLOCKED",
            "blockers": ["strategy-artifact-integrity-unverified"],
            "warnings": [],
            "artifactIntegrity": integrity,
        }
    symbol = normalize_usdm_symbol(intent.symbol)
    if (
        not symbol
        or normalize_usdm_symbol(strategy.get("symbol")) != symbol
        or strategy_broker_id(strategy) != "binance-futures"
    ):
        return {
            "status": "BLOCKED",
            "blockers": ["strategy-futures-route-mismatch"],
            "warnings": [],
        }
    policy = _intent_futures_execution_policy(strategy, intent)
    stop_loss_percent = _strategy_stop_loss_percent(strategy)
    if stop_loss_percent <= 0:
        return {
            "status": "BLOCKED",
            "blockers": ["protective-stop-policy-missing"],
            "warnings": [],
            "policy": policy,
        }
    router = BINANCE_FUTURES_SETTINGS_ROUTER_FACTORY()
    try:
        raw_observation = router.get_binance_futures_canary_observation(
            symbol
        )
        observation = _binance_futures_settings_summary(raw_observation)
        market = router.get_binance_futures_risk_inputs(
            symbol,
            notional_usdt=intent.notional,
        )
        account_snapshot = router.get_account_snapshot("binance-futures")
        account_rows = (
            account_snapshot.get("accounts")
            if isinstance(account_snapshot.get("accounts"), list)
            else []
        )
        account = (
            account_rows[0]
            if account_rows and isinstance(account_rows[0], dict)
            else {}
        )
    except (
        BrokerNotReadyError,
        OSError,
        RuntimeError,
        TimeoutError,
        ValueError,
    ) as exc:
        return {
            "status": "BLOCKED",
            "blockers": ["broker-risk-inputs-unavailable"],
            "warnings": [],
            "detail": str(exc)[:240],
            "policy": policy,
        }
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    direction = (
        "SHORT"
        if str(
            metadata.get("position_direction")
            or strategy.get("position_direction")
            or ""
        ).strip().lower()
        == "short"
        else "LONG"
    )
    mark_price = safe_float(market.get("mark_price"), 0.0)
    current_notional = max(0.0, intent.quantity * mark_price)
    stop_price = (
        mark_price * (1.0 + stop_loss_percent / 100.0)
        if direction == "SHORT"
        else mark_price * (1.0 - stop_loss_percent / 100.0)
    )
    account_equity = safe_float(
        account.get("broker_equity"),
        safe_float(account.get("margin_balance"), 0.0),
    )
    available_usdt = safe_float(
        observation.get("available_usdt"),
        safe_float(account.get("broker_cash"), 0.0),
    )
    risk = simulate_futures_order_risk(
        {
            "symbol": symbol,
            "direction": direction,
            "margin_type": observation.get("margin_type"),
            "account_equity_usdt": account_equity,
            "available_usdt": available_usdt,
            "entry_price": mark_price,
            "notional_usdt": current_notional,
            "leverage": observation.get("leverage"),
            "maintenance_margin_rate": market.get(
                "maintenance_margin_rate"
            ),
            "taker_fee_rate": market.get("taker_fee_rate"),
            "funding_rate": market.get("funding_rate"),
            "funding_intervals": 1,
            "stop_price": stop_price,
        },
        policy=policy,
    )
    drift = compare_futures_policy_to_broker(
        policy,
        {
            "marginType": observation.get("margin_type"),
            "leverage": observation.get("leverage"),
        },
    )
    risk["blockers"] = list(
        dict.fromkeys(
            [
                *risk.get("blockers", []),
                *[
                    str(item)
                    for item in drift.get("blockers") or []
                    if str(item)
                ],
                # The adapter does not yet create and acknowledge an
                # exchange-native reduce-only STOP_MARKET order atomically
                # with the entry. A strategy-side bar stop is not equivalent
                # protection, so risk-increasing live entry stays fail-closed.
                "protective-stop-order-not-implemented",
            ]
        )
    )
    risk["status"] = (
        "BLOCKED"
        if risk["blockers"]
        else "WARNING"
        if risk.get("warnings")
        else "READY"
    )
    risk["protective_stop"] = {
        "source": "immutable-strategy-riskRules.stopLossPct",
        "percent": stop_loss_percent,
        "price": stop_price,
    }
    risk["broker_policy_drift"] = drift
    return risk


def evaluate_order_gate_with_report(
    checks: dict[str, Any],
    side: str,
    dry_run: bool,
    intent: OrderIntent | None = None,
) -> tuple[bool, str, str, str, PreTradeRiskReport]:
    intent = intent or default_order_intent(checks, side)
    functional_execution = functional_test_execution_requested(intent)
    portfolio_gate = portfolio_gate_for_intent(checks, intent)
    context = apply_portfolio_gate_to_context(pre_trade_context(checks, intent, dry_run), portfolio_gate, intent)
    report = PreTradeRiskGate().evaluate(intent, context)
    if portfolio_gate.get("active"):
        portfolio_status: CheckStatus = "pass" if portfolio_gate.get("allowed") is True else "fail"
        report = PreTradeRiskReport(
            report.checked_at,
            (
                RiskCheck("Portfolio Artifact", portfolio_status, str(portfolio_gate.get("detail") or "")),
                *report.checks,
            ),
        )
    strategy = strategy_for_order_intent(checks, intent)
    paper_portfolio_evidence_gate = strategy.get("paper_portfolio_evidence_gate") if isinstance(strategy.get("paper_portfolio_evidence_gate"), dict) else {}
    if not functional_execution and paper_portfolio_evidence_gate.get("required"):
        evidence_status: CheckStatus = "pass" if paper_portfolio_evidence_gate.get("ready") is True else "fail"
        report = PreTradeRiskReport(
            report.checked_at,
            (
                RiskCheck("Portfolio Paper Evidence", evidence_status, str(paper_portfolio_evidence_gate.get("detail") or "")),
                *report.checks,
            ),
        )
    paper_live_qualification_gate = (
        strategy.get("paper_live_qualification_gate")
        if isinstance(strategy.get("paper_live_qualification_gate"), dict)
        else {}
    )
    if not functional_execution and paper_live_qualification_gate.get("required"):
        qualification_status: CheckStatus = (
            "pass"
            if paper_live_qualification_gate.get("ready") is True
            else "fail"
        )
        report = PreTradeRiskReport(
            report.checked_at,
            (
                RiskCheck(
                    "Exact Paper Final Binding",
                    qualification_status,
                    str(paper_live_qualification_gate.get("detail") or ""),
                ),
                *report.checks,
            ),
        )
    revalidation = strategy_revalidation_status(strategy, lifecycle_status=strategy.get("lifecycle_status")) if strategy else {}
    if (
        not functional_execution
        and intent.side == "BUY"
        and revalidation.get("expired") is True
    ):
        report = PreTradeRiskReport(
            report.checked_at,
            (*report.checks, RiskCheck("전략 재검증", "fail", str(revalidation.get("detail")))),
        )
    watchdog = checks.get("watchdog") if isinstance(checks.get("watchdog"), dict) else {}
    watchdog_critical = int(watchdog.get("critical_count", 0) or 0)
    if watchdog_critical:
        detail = f"Watchdog critical {watchdog_critical}개: {', '.join(watchdog.get('next_actions', [])[:4])}"
        report = PreTradeRiskReport(report.checked_at, (*report.checks, RiskCheck("Watchdog", "fail", detail)))
    quote_error = (
        kis_overseas_next_open_quote_error(intent)
        if not dry_run
        else ""
    )
    if quote_error:
        report = PreTradeRiskReport(
            report.checked_at,
            (
                *report.checks,
                RiskCheck("실행 가격 수명주기", "fail", quote_error),
            ),
        )
    # Dry-run is an offline safety simulation and remains usable outside market
    # hours.  Paper Trader enforces its own exchange-session clock; this gate is
    # for orders that could otherwise reach the live adapter.
    calendar_state = order_intent_market_session(intent) if not dry_run else None
    if calendar_state is not None:
        calendar_status: CheckStatus = "pass" if calendar_state.get("orderable") is True else "fail"
        report = PreTradeRiskReport(
            report.checked_at,
            (*report.checks, RiskCheck("거래소 세션", calendar_status, str(calendar_state.get("detail") or "시장 일정 확인 실패"))),
        )
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    verified_risk_reducing = futures_risk_reducing_verified(
        checks,
        intent,
    )
    if (
        not dry_run
        and intent.mode in {"SMALL_LIVE", "FULL_LIVE"}
        and broker_id == "binance-futures"
        and metadata.get("multi_strategy") is True
        and not verified_risk_reducing
    ):
        report = PreTradeRiskReport(
            report.checked_at,
            (
                *report.checks,
                RiskCheck(
                    "Multi-Strategy Futures 증거",
                    "fail",
                    (
                        "multi-strategy-futures-rollout-evidence-not-implemented: "
                        "모든 sleeve의 artifact lineage·배포 scope·soak·실체결 "
                        "증거를 함께 집계하기 전에는 신규 선물 진입을 차단합니다."
                    ),
                ),
            ),
        )
    if (
        report.can_submit
        and not dry_run
        and intent.mode in {"SMALL_LIVE", "FULL_LIVE"}
        and broker_id == "binance-futures"
        and not verified_risk_reducing
    ):
        futures_risk = _binance_futures_live_order_risk(checks, intent)
        futures_status: CheckStatus = (
            "fail"
            if futures_risk.get("blockers")
            else "warn"
            if futures_risk.get("warnings")
            else "pass"
        )
        risk_detail = (
            "차단: " + ", ".join(futures_risk.get("blockers") or [])
            if futures_risk.get("blockers")
            else "주의: " + ", ".join(futures_risk.get("warnings") or [])
            if futures_risk.get("warnings")
            else "immutable 정책·보호손절·현재 계좌/마진 위험 계산 통과"
        )
        report = PreTradeRiskReport(
            report.checked_at,
            (
                *report.checks,
                RiskCheck(
                    "Binance Futures 주문 위험",
                    futures_status,
                    risk_detail,
                ),
            ),
        )
    if report.can_submit:
        if dry_run:
            return True, "dry_run", "simulated", "Dry Run 보호가 켜져 있어 브로커 전송 없이 주문 의도를 감사 로그에만 기록했습니다.", report
        return True, "approved", "ready", "Pre-trade 위험 게이트와 실주문 어댑터 검증을 통과했습니다.", report

    adapter_labels = {"운용 모드", "실거래 환경 변수", "실주문 어댑터"}
    non_adapter_blockers = [check for check in report.blockers if check.label not in adapter_labels]
    adapter_blockers = [check for check in report.blockers if check.label in adapter_labels]
    # Until the live adapter itself is verified, retain that stronger/earlier
    # hold reason even when the exchange is also closed.  The failed session
    # check remains visible in the report and becomes the active blocker once
    # the adapter gates pass.
    if adapter_blockers and all(check.label == "거래소 세션" for check in non_adapter_blockers):
        adapter_blocker = next((check for check in adapter_blockers if check.label == "실주문 어댑터"), adapter_blockers[0])
        return False, "adapter_blocked", "held", adapter_blocker.detail, report
    if non_adapter_blockers:
        return False, "risk_blocked", "blocked", report.summary, report
    adapter_blocker = next((check for check in report.blockers if check.label == "실주문 어댑터"), report.blockers[0])
    return False, "adapter_blocked", "held", adapter_blocker.detail, report


def order_intent_market_session(intent: OrderIntent) -> dict[str, object] | None:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    asset = str(intent.asset or "").strip().lower()
    symbol = str(intent.symbol or "").strip().upper()
    if broker_id in {"binance", "binance-futures", "upbit"} or any(
        token in asset for token in ("crypto", "코인")
    ):
        return None
    local_code = symbol.removesuffix(".KS").removesuffix(".KQ")
    domestic = (
        (local_code.isdigit() and len(local_code) == 6)
        or symbol.endswith((".KS", ".KQ"))
        or any(
            token in asset
            for token in ("한국", "kr_stock", "stock_kr", "korean")
        )
    )
    if domestic:
        return market_session_state("XKRX", regular_open="09:00", regular_close="15:30")
    if broker_id == "kis" or any(
        token in f"{asset} {symbol}".lower()
        for token in ("미국", "us_stock", "stock_us", "nyse", "nasdaq", "amex")
    ):
        return market_session_state("XNYS", regular_open="09:30", regular_close="16:00")
    return None


def kis_overseas_next_open_quote_error(intent: OrderIntent) -> str:
    """Require a fresh priced quote before an automated KIS overseas order."""

    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    if broker_id != "kis":
        return ""
    symbol = str(intent.symbol or "").strip().upper()
    local_code = symbol.removesuffix(".KS").removesuffix(".KQ")
    domestic = (
        (local_code.isdigit() and len(local_code) == 6)
        or symbol.endswith((".KS", ".KQ"))
    )
    if domestic or str(metadata.get("execution_timing") or "") != "next-open-boundary":
        return ""
    if str(metadata.get("order_type") or "") != "00":
        return "KIS 미국주식 자동 주문은 신선한 지정가(ORD_DVSN=00)만 허용합니다."
    quote_price = safe_float(metadata.get("fresh_quote_price"), 0.0)
    quote_time_text = str(metadata.get("fresh_quote_observed_at") or "")
    try:
        quote_time = datetime.fromisoformat(
            quote_time_text.replace("Z", "+00:00")
        )
        if quote_time.tzinfo is None:
            quote_time = quote_time.replace(tzinfo=timezone.utc)
        quote_age = max(
            0.0,
            (
                datetime.now(timezone.utc)
                - quote_time.astimezone(timezone.utc)
            ).total_seconds(),
        )
    except (TypeError, ValueError):
        quote_age = float("inf")
    if (
        metadata.get("fresh_quote_verified") is not True
        or quote_price <= 0
        or quote_age > 5.0
    ):
        return (
            "KIS 미국주식 next-open 주문은 5초 이내 실시간 호가와 "
            "미체결 취소/부분체결 수명주기 확인 전까지 차단됩니다."
        )
    return ""


class LiveArtifactSignalProvider:
    plugin_id = "live_artifact_signal"
    label = "Live Artifact Signal"

    def signal_for_price(
        self,
        *,
        artifact: Any,
        price: float,
        context: Any,
    ) -> OrderSide | None:
        _ = price, context
        return explicit_artifact_signal(artifact)

    def signal_for_market(
        self,
        *,
        artifact: Any,
        market_data: StrategyMarketData,
        context: Any,
    ) -> OrderSide | None:
        _ = market_data, context
        return explicit_artifact_signal(artifact)


def explicit_artifact_signal(artifact: Any) -> OrderSide | None:
    values: list[Any] = []
    if isinstance(artifact, dict):
        values.extend(
            artifact.get(key)
            for key in ("signal", "last_signal", "test_signal", "manual_signal", "side", "order_side")
        )
        signals = artifact.get("signals")
        if isinstance(signals, dict):
            values.extend(signals.get(key) for key in ("current", "latest", "last", "signal"))
    for value in values:
        normalized = str(value or "").strip().upper()
        if normalized in {"BUY", "SELL"}:
            return normalized  # type: ignore[return-value]
    return None


def strategy_market_data(strategy: dict[str, Any]) -> StrategyMarketData:
    event = strategy_market_event(strategy)
    return StrategyMarketData(
        price=event.price,
        close_price=event.price,
        volume=event.quantity,
        occurred_at=event.event_time,
        instrument_id=event.instrument_id,
        provider=event.provider,
        received_at=event.received_time,
        latency_seconds=event.latency_seconds,
    )


def strategy_market_event(strategy: dict[str, Any]) -> MarketEvent:
    price = strategy_float(
        strategy,
        "reference_price",
        "last_price",
        "price",
        "close",
        "close_price",
        default=(
            1.0
            if strategy_broker_id(strategy)
            in {"binance", "binance-futures"}
            else 1000.0
        ),
    )
    symbol = str(strategy.get("symbol") or "UNKNOWN")
    provider = strategy_broker_id(strategy)
    now = datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    return MarketEvent(
        instrument_id=str(strategy.get("instrument_id") or f"symbol:{symbol}"),
        symbol=symbol,
        provider=provider,
        market=str(strategy.get("market") or provider).upper(),
        market_type=str(strategy.get("market_type") or strategy.get("asset") or "UNKNOWN").upper(),
        event_time=str(strategy.get("price_time") or strategy.get("occurred_at") or now),
        received_time=now,
        price=price,
        quantity=max(0.0, strategy_float(strategy, "volume", default=0.0)),
        event_id=str(strategy.get("market_event_id") or ""),
        metadata={"source": "strategy-artifact-reference-price"},
    )


def strategy_float(strategy: dict[str, Any], *keys: str, default: float = 0.0) -> float:
    for key in keys:
        value = strategy.get(key)
        if value in (None, ""):
            continue
        try:
            return float(value)
        except (TypeError, ValueError):
            continue
    return float(default)


def select_strategy_for_profile(checks: dict[str, Any], profile_id: str) -> dict[str, Any] | None:
    strategies = select_strategies_for_profile(checks, profile_id)
    return strategies[0] if strategies else None


def select_strategies_for_profile(checks: dict[str, Any], profile_id: str) -> list[dict[str, Any]]:
    normalized_profile = "stock" if profile_id == "stock" else "crypto"
    provider = str(STATE["automation"][normalized_profile].get("provider") or ("kis" if normalized_profile == "stock" else "binance"))
    eligibility_key = "live_eligible" if current_mode() == "FULL_LIVE" else "live_allowed"
    strategies = [strategy for strategy in checks.get("strategies", []) if strategy.get(eligibility_key)]
    if normalized_profile == "stock":
        matched = [strategy for strategy in strategies if strategy_broker_id(strategy) == "kis"]
    else:
        matched = [strategy for strategy in strategies if strategy_broker_id(strategy) == provider]
        if not matched:
            matched = [
                strategy
                for strategy in strategies
                if strategy_broker_id(strategy)
                in {"binance", "binance-futures", "upbit"}
            ]
    if len(matched) <= 1:
        return matched
    portfolio_ids = {
        str(instance.get("strategyId") or instance.get("strategy_id") or "")
        for portfolio in checks.get("portfolios", []) if isinstance(portfolio, dict)
        for instance in portfolio.get("strategy_instances", []) if isinstance(instance, dict)
    }
    portfolio_matched = [strategy for strategy in matched if str(strategy.get("strategy_id") or "") in portfolio_ids or str(strategy.get("plugin") or "") in portfolio_ids]
    return portfolio_matched or matched[:1]


def strategy_execution_for_profile(checks: dict[str, Any], profile_id: str) -> StrategyExecutionResult | None:
    executions = strategy_executions_for_profile(checks, profile_id)
    return executions[0][1] if executions else None


def _strategy_runtime_instance_context(
    strategy: dict[str, Any],
) -> tuple[str, str]:
    gate = (
        strategy.get("portfolio_gate")
        if isinstance(strategy.get("portfolio_gate"), dict)
        else {}
    )
    instance = (
        gate.get("instance")
        if isinstance(gate.get("instance"), dict)
        else {}
    )
    strategy_instance_id = str(
        strategy.get("strategy_instance_id")
        or instance.get("instanceId")
        or instance.get("strategyInstanceId")
        or ""
    ).strip()
    portfolio_id = (
        str(gate.get("portfolioId") or "").strip()
        if gate.get("active") is True
        else ""
    )
    return strategy_instance_id, portfolio_id


def strategy_executions_for_profile(checks: dict[str, Any], profile_id: str) -> list[tuple[dict[str, Any], StrategyExecutionResult]]:
    strategies = select_strategies_for_profile(checks, profile_id)
    if not strategies:
        return []
    normalized_profile = "stock" if profile_id == "stock" else "crypto"
    runner = StrategyExecutionRunner(lambda _plugin_id: LiveArtifactSignalProvider())
    executions: list[tuple[dict[str, Any], StrategyExecutionResult]] = []
    for strategy in strategies:
        broker_id = strategy_broker_id(strategy)
        market_data = strategy_market_data(strategy)
        strategy_instance_id, portfolio_id = (
            _strategy_runtime_instance_context(strategy)
        )
        futures_policy = (
            strategy.get("futures_execution_policy")
            if isinstance(strategy.get("futures_execution_policy"), dict)
            else futures_execution_policy_from_artifact(strategy)
        )
        metadata = {
            "broker_id": broker_id,
            "profile_id": normalized_profile,
            "strategy_instance_id": strategy_instance_id,
            "portfolio_id": portfolio_id,
            "runner": "StrategyExecutionRunner",
            "market_event_time": market_data.occurred_at,
            "market_received_time": market_data.received_at,
            "market_data_latency_seconds": market_data.latency_seconds,
            "market_data_verified": bool(
                strategy.get("price_time") or strategy.get("occurred_at")
            ),
            "market_type": str(
                strategy.get("market_type") or "spot"
            ).lower(),
            "position_direction": str(
                strategy.get("position_direction") or "long"
            ).lower(),
            "short_entries_requested": (
                strategy.get("allow_short_requested") is True
            ),
            "broker_short_adapter_verified": (
                broker_id == "binance-futures"
                and str(strategy.get("market_type") or "").lower()
                in {"future", "futures", "perpetual"}
            ),
        }
        if broker_id == "binance-futures":
            metadata.update(
                {
                    "futures_execution_policy": dict(futures_policy),
                    "futures_policy_valid": (
                        futures_policy.get("valid") is True
                    ),
                    "futures_policy_blockers": list(
                        futures_policy.get("blockers") or []
                    ),
                    "max_leverage": safe_float(
                        futures_policy.get("maxLeverageMultiplier"),
                        1.0,
                    ),
                    "required_margin_type": str(
                        futures_policy.get("marginMode") or "ISOLATED"
                    ),
                    "per_trade_risk_pct": safe_float(
                        futures_policy.get("perTradeRiskPercent"),
                        0.5,
                    ),
                    "max_notional_pct": safe_float(
                        futures_policy.get("maxNotionalPercent"),
                        10.0,
                    ),
                }
            )
        executions.append(
            (
                strategy,
                runner.run(
                    artifact=strategy,
                    market_data=market_data,
                    mode=current_mode(),
                    stream_id=(
                        f"live:{normalized_profile}:"
                        f"{strategy.get('strategy_id', 'unknown')}"
                    ),
                    quantity=strategy_float(
                        strategy,
                        "order_quantity",
                        "quantity",
                        default=1.0,
                    ),
                    metadata=metadata,
                    reason_prefix=(
                        f"{strategy.get('name') or strategy.get('strategy_id') or '전략'} "
                        "live runner signal"
                    ),
                ),
            )
        )
    return executions


def default_order_intent(checks: dict[str, Any], side: str) -> OrderIntent:
    strategies = checks.get("strategies", [])
    strategy = next((item for item in strategies if item.get("live_allowed")), strategies[0] if strategies else {})
    normalized_side: OrderSide = "SELL" if str(side).upper() == "SELL" else "BUY"
    symbol = str(strategy.get("symbol") or "TEST")
    asset = str(strategy.get("asset") or asset_from_symbol(symbol))
    strategy_instance_id, portfolio_id = _strategy_runtime_instance_context(
        strategy
    )
    return OrderIntent(
        strategy_id=str(strategy.get("strategy_id") or "manual-test"),
        asset=asset,
        symbol=symbol,
        side=normalized_side,
        quantity=1.0,
        reference_price=1000.0,
        mode=current_mode(),
        reason="live test intent",
        metadata={
            "broker_id": (
                strategy_broker_id(strategy)
                if strategy
                else broker_id_from_symbol(symbol, asset)
            ),
            "strategy_instance_id": strategy_instance_id,
            "portfolio_id": portfolio_id,
        },
    )


def intent_readiness_blocker_count(
    checks: dict[str, Any],
    intent: OrderIntent,
    reconciliation_summary: dict[str, Any] | None = None,
) -> int:
    if functional_test_execution_requested(intent):
        metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
        broker_id = str(
            metadata.get("broker_id")
            or broker_id_from_symbol(intent.symbol, intent.asset)
        ).strip().lower()
        scoped = reconciliation_summary or reconciliation_summary_for_broker(
            broker_id
        )
        checklist_missing = [
            item
            for item in checklist_rows()
            if item.get("required") and not item.get("checked")
        ]
        central_control = durable_control_snapshot()
        blockers = sum(
            (
                0 if real_orders_enabled() else 1,
                0 if not checklist_missing else 1,
                0 if broker_ready_for_intent(checks, intent) else 1,
                1 if STATE.get("kill_switch") else 0,
                1 if central_control.get("halted") else 0,
                0 if reconciliation_blocker_count(scoped) == 0 else 1,
            )
        )
        if intent_requires_unavailable_capability(intent, scoped):
            blockers += 1
        return blockers
    if not checks.get("strategies") or not checks.get("brokers"):
        return int(checks.get("summary", {}).get("blocker_count", 0))
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(metadata.get("broker_id") or broker_id_from_symbol(intent.symbol, intent.asset)).strip().lower()
    profile_id = str(
        metadata.get("profile_id")
        or (
            "crypto"
            if broker_id in {"binance", "binance-futures", "upbit"}
            else "stock"
        )
    )
    scoped = reconciliation_summary or reconciliation_summary_for_broker(broker_id)
    blockers = profile_readiness_blocker_count(
        checks,
        profile_id,
        broker_id,
        intent.mode,
        reconciliation_summary=scoped,
    )
    if intent_requires_unavailable_capability(intent, scoped):
        blockers += 1
    return blockers


def intent_requires_unavailable_capability(intent: OrderIntent, reconciliation_summary: dict[str, Any]) -> bool:
    if int(reconciliation_summary.get("capability_gap_count") or 0) == 0:
        return False
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(metadata.get("broker_id") or broker_id_from_symbol(intent.symbol, intent.asset)).strip().lower()
    if broker_id != "kis":
        return False
    symbol = str(intent.symbol or "").strip().upper()
    local_code = symbol.split(":")[-1].split(".")[0]
    asset = str(intent.asset or "").strip().lower()
    domestic_asset = any(token in asset for token in ("한국", "kr-stock", "kr_stock", "korean"))
    domestic_symbol = (len(local_code) == 6 and local_code.isdigit()) or symbol.endswith((".KS", ".KQ"))
    return not (domestic_asset or domestic_symbol)


def account_risk_for_intent(
    intent: OrderIntent,
    *,
    maximum_age_seconds: float = 120.0,
) -> dict[str, Any]:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    requested_currency = str(
        metadata.get("quote_currency")
        or metadata.get("currency")
        or (
            "USDT"
            if broker_id in {"binance", "binance-futures"}
            and str(intent.symbol).upper().replace("-", "").endswith("USDT")
            else "KRW"
            if broker_id in {"kis", "upbit"}
            else ""
        )
    ).strip().upper()
    snapshot_value = (
        STATE.get("account_risk")
        if isinstance(STATE.get("account_risk"), dict)
        else {}
    )
    return broker_account_risk(
        snapshot_value,
        broker_id,
        currency=requested_currency,
        maximum_age_seconds=maximum_age_seconds,
    )


FUTURES_ROLLOUT_MIN_SOAK_SECONDS = 5 * 60 * 60
FUTURES_ROLLOUT_SOAK_MAX_AGE_SECONDS = 24 * 60 * 60


def _accepted_futures_soak_report(
    report: dict[str, Any],
    scope: dict[str, Any],
) -> dict[str, Any]:
    blockers: list[str] = []
    metadata = (
        report.get("metadata")
        if isinstance(report.get("metadata"), dict)
        else {}
    )
    profiles = {
        str(item).strip().lower()
        for item in metadata.get("profiles") or []
        if str(item).strip()
    }
    if "crypto" not in profiles:
        blockers.append("soak-crypto-profile-missing")
    if str(report.get("status") or "").upper() != "STOPPED":
        blockers.append("soak-not-terminal")
    verdict = str(report.get("verdict") or "").upper()
    if verdict not in {"PASS", "PASS_WITH_WARNING"}:
        blockers.append("soak-verdict-not-accepted")
    duration = safe_float(report.get("durationSeconds"), float("nan"))
    target_duration = safe_float(
        report.get("targetDurationSeconds"),
        float("nan"),
    )
    if not math.isfinite(duration) or duration < 0:
        blockers.append("soak-duration-invalid")
        duration = 0.0
    if not math.isfinite(target_duration) or target_duration < 0:
        blockers.append("soak-target-duration-invalid")
        target_duration = FUTURES_ROLLOUT_MIN_SOAK_SECONDS
    if (
        duration < FUTURES_ROLLOUT_MIN_SOAK_SECONDS
        or duration < target_duration
    ):
        blockers.append("soak-minimum-duration-not-met")
    ended_at = _canary_datetime(
        report.get("endedAt") or report.get("updatedAt")
    )
    if ended_at is None:
        blockers.append("soak-ended-at-missing")
    elif (
        datetime.now(timezone.utc) - ended_at
    ).total_seconds() > FUTURES_ROLLOUT_SOAK_MAX_AGE_SECONDS:
        blockers.append("soak-report-stale")
    scopes = (
        metadata.get("strategyScopes")
        if isinstance(metadata.get("strategyScopes"), list)
        else []
    )
    if not any(
        isinstance(candidate, dict)
        and all(
            str(candidate.get(field) or "")
            == str(scope.get(field) or "")
            for field in CANARY_SCOPE_FIELDS
        )
        for candidate in scopes
    ):
        blockers.append("soak-strategy-deployment-scope-mismatch")
    accepted = not blockers
    clean_observation_hours = (
        duration / 3600.0
        if accepted and verdict == "PASS"
        else 0.0
    )
    return {
        "accepted": accepted,
        "verdict": verdict if accepted else "NOT_ACCEPTED",
        "blockers": list(dict.fromkeys(blockers)),
        "runId": str(report.get("runId") or ""),
        "durationSeconds": duration,
        "cleanObservationHours": clean_observation_hours,
        "endedAt": str(report.get("endedAt") or ""),
    }


def _strategy_rollout_context_key(strategy: dict[str, Any]) -> tuple[str, str]:
    source = Path(str(strategy.get("artifact_source_path") or ""))
    root = str(source.parent) if source.parent != source else ""
    return root, str(strategy.get("deployment_id") or "")


def _build_futures_rollout_evidence_context(
    strategies: list[dict[str, Any]],
    *,
    soak_report: dict[str, Any] | None = None,
    include_order_evidence: bool = True,
) -> dict[str, Any]:
    roots = {
        root
        for strategy in strategies
        if (root := _strategy_rollout_context_key(strategy)[0])
    }
    deployment_index: dict[tuple[str, str], dict[str, Any]] = {}
    deployment_events: dict[str, list[dict[str, Any]]] = {}
    for root in roots:
        root_path = Path(root)
        for deployment in DeploymentStore(root_path).list():
            deployment_index[
                (root, str(deployment.get("deploymentId") or ""))
            ] = deployment
        deployment_events[root] = _deployment_event_rows(root_path)
    if soak_report is None:
        try:
            from .soak_monitor import latest_live_soak_report

            soak_report = latest_live_soak_report()
        except (OSError, RuntimeError, ValueError):
            soak_report = {}
    context = {
        "deployment_index": deployment_index,
        "deployment_events": deployment_events,
        "soak_report": soak_report or {},
    }
    if include_order_evidence:
        context["execution_events"] = PROGRAM_LEDGER.execution_event_rows(5000)
        context["order_gate_events"] = PROGRAM_LEDGER.order_gate_event_rows(
            5000
        )
    return context


def live_soak_strategy_scopes(
    profiles: tuple[str, ...] | list[str],
) -> list[dict[str, Any]]:
    normalized_profiles = {
        str(item).strip().lower()
        for item in profiles
        if str(item).strip()
    }
    if "crypto" not in normalized_profiles:
        return []
    strategies = [
        row
        for row in strategy_rows()
        if strategy_broker_id(row) == "binance-futures"
    ]
    context = _build_futures_rollout_evidence_context(
        strategies,
        soak_report={},
        include_order_evidence=False,
    )
    deployment_index = context["deployment_index"]
    events_by_root = context["deployment_events"]
    scopes: list[dict[str, Any]] = []
    for strategy in strategies:
        context_key = _strategy_rollout_context_key(strategy)
        scope = current_live_canary_scope(
            str(strategy.get("strategy_id") or ""),
            normalized=strategy,
            deployment=deployment_index.get(context_key),
            deployment_events=events_by_root.get(context_key[0]),
        )
        if scope.get("eligible") is True:
            scopes.append(
                {
                    field: scope.get(field)
                    for field in CANARY_SCOPE_FIELDS
                }
            )
    return scopes


def _futures_capital_rollout_for_strategy(
    strategy: dict[str, Any],
    *,
    account_risk: dict[str, Any],
    reconciliation_fresh: bool,
    soak_report: dict[str, Any] | None = None,
    policy_override: dict[str, Any] | None = None,
    evidence_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    policy = (
        policy_override
        if isinstance(policy_override, dict)
        else strategy.get("futures_execution_policy")
        if isinstance(strategy.get("futures_execution_policy"), dict)
        else futures_execution_policy_from_artifact(strategy)
    )
    lineage = (
        strategy.get("lineage")
        if isinstance(strategy.get("lineage"), dict)
        else {}
    )
    lineage_valid = (
        not lineage.get("blockingIssues")
        and all(
            isinstance(lineage.get(stage), dict)
            and lineage.get(stage, {}).get("valid") is True
            for stage in ("dataset", "backtest", "paper")
        )
    )
    context = evidence_context or {}
    context_key = _strategy_rollout_context_key(strategy)
    deployment_index = (
        context.get("deployment_index")
        if isinstance(context.get("deployment_index"), dict)
        else {}
    )
    events_by_root = (
        context.get("deployment_events")
        if isinstance(context.get("deployment_events"), dict)
        else {}
    )
    execution = live_small_execution_summary(
        str(strategy.get("strategy_id") or ""),
        normalized=strategy,
        deployment=deployment_index.get(context_key),
        deployment_events=events_by_root.get(context_key[0]),
        execution_events=(
            context.get("execution_events")
            if isinstance(context.get("execution_events"), list)
            else None
        ),
        order_gate_events=(
            context.get("order_gate_events")
            if isinstance(context.get("order_gate_events"), list)
            else None
        ),
    )
    if isinstance(context.get("soak_report"), dict):
        soak = context["soak_report"]
    elif soak_report is None:
        try:
            from .soak_monitor import latest_live_soak_report

            soak = latest_live_soak_report()
        except (OSError, RuntimeError, ValueError):
            soak = {}
    else:
        soak = soak_report
    soak_assessment = _accepted_futures_soak_report(
        soak,
        execution.get("scope")
        if isinstance(execution.get("scope"), dict)
        else {},
    )
    rollout = build_capital_rollout(
        account_equity=account_risk.get("current_equity"),
        available_cash=account_risk.get("available_cash"),
        max_notional_percent=policy.get("maxNotionalPercent"),
        canary_fills=execution.get("fills"),
        blocked_orders=execution.get("blocked"),
        observation_hours=soak_assessment.get(
            "cleanObservationHours",
            0.0,
        ),
        reconciliation_fresh=reconciliation_fresh,
        lineage_valid=lineage_valid,
        policy_valid=policy.get("valid") is True,
        soak_status=soak_assessment.get("verdict"),
    )
    rollout.update(
        {
            "strategyId": str(strategy.get("strategy_id") or ""),
            "strategyName": str(
                strategy.get("name")
                or strategy.get("strategy_id")
                or ""
            ),
            "symbol": str(strategy.get("symbol") or ""),
            "timeframe": str(strategy.get("timeframe") or ""),
            "policy": policy,
            "lineageValid": lineage_valid,
            "accountRiskKnown": account_risk.get("known") is True,
            "accountRiskFresh": account_risk.get("fresh") is True,
            "soakRunId": str(soak.get("runId") or ""),
            "soakAssessment": soak_assessment,
        }
    )
    return rollout


def futures_capital_rollout_for_intent(
    checks: dict[str, Any],
    intent: OrderIntent,
    *,
    account_risk: dict[str, Any] | None = None,
) -> dict[str, Any]:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    if broker_id != "binance-futures":
        return {}
    strategy = strategy_for_order_intent(checks, intent)
    if not strategy:
        return {
            "schemaVersion": "capital-rollout-v1",
            "strategyId": intent.strategy_id,
            "decision": {
                "stage": "CANARY",
                "ready": False,
                "maxNotional": 0.0,
                "blockers": ["strategy-artifact-missing"],
            },
        }
    if (
        metadata.get("multi_strategy") is True
        and not futures_risk_reducing_verified(checks, intent)
    ):
        return {
            "schemaVersion": "capital-rollout-v1",
            "strategyId": intent.strategy_id,
            "decision": {
                "stage": "CANARY",
                "ready": False,
                "maxNotional": 0.0,
                "blockers": [
                    "multi-strategy-futures-rollout-evidence-not-implemented"
                ],
            },
        }
    scoped_reconciliation = reconciliation_summary_for_broker(
        "binance-futures"
    )
    account = account_risk or account_risk_for_intent(intent)
    rollout = _futures_capital_rollout_for_strategy(
        strategy,
        account_risk=account,
        reconciliation_fresh=(
            account.get("fresh") is True
            and reconciliation_blocker_count(scoped_reconciliation) == 0
        ),
        policy_override=_intent_futures_execution_policy(
            strategy,
            intent,
        ),
    )
    rollout["decision"] = capital_cap_for_mode(rollout, intent.mode)
    return rollout


def futures_capital_rollout_snapshot(
    strategies: list[dict[str, Any]] | None = None,
    *,
    reconciliation_summary: dict[str, Any] | None = None,
) -> dict[str, Any]:
    rows = strategies if strategies is not None else strategy_rows()
    account = broker_account_risk(
        STATE.get("account_risk", {}),
        "binance-futures",
        currency="USDT",
        maximum_age_seconds=120.0,
    )
    reconciliation = (
        reconciliation_summary
        if isinstance(reconciliation_summary, dict)
        else reconciliation_summary_for_broker("binance-futures")
    )
    fresh = (
        account.get("fresh") is True
        and reconciliation_blocker_count(reconciliation) == 0
    )
    candidates = [
        row
        for row in rows
        if strategy_broker_id(row) == "binance-futures"
        or str(row.get("market_type") or "").lower()
        in {"future", "futures", "perpetual"}
    ]
    try:
        from .soak_monitor import latest_live_soak_report

        soak = latest_live_soak_report()
    except (OSError, RuntimeError, ValueError):
        soak = {}
    evidence_context = _build_futures_rollout_evidence_context(
        candidates,
        soak_report=soak,
    )
    rollout_rows = [
        _futures_capital_rollout_for_strategy(
            row,
            account_risk=account,
            reconciliation_fresh=fresh,
            evidence_context=evidence_context,
        )
        for row in candidates
    ]
    return {
        "schemaVersion": "capital-rollout-dashboard-v1",
        "accountKnown": account.get("known") is True,
        "accountFresh": account.get("fresh") is True,
        "accountEquity": account.get("current_equity"),
        "availableCash": account.get("available_cash"),
        "reconciliationFresh": fresh,
        "strategyCount": len(rollout_rows),
        "strategies": rollout_rows,
    }


def broker_symbol_exposure(intent: OrderIntent) -> float:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    normalized_symbol = (
        str(intent.symbol or "")
        .strip()
        .upper()
        .removesuffix(".PERP")
        .replace("-", "")
    )
    total = 0.0
    rows = STATE.get("broker_reconciliation", {}).get("positions", [])
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        row_symbol = (
            str(row.get("symbol") or "")
            .strip()
            .upper()
            .removesuffix(".PERP")
            .replace("-", "")
        )
        if (
            str(row.get("broker_id") or "").strip().lower() == broker_id
            and row_symbol == normalized_symbol
        ):
            total += abs(safe_float(row.get("broker_value"), 0.0))
    return total


def intent_market_data_age_seconds(
    metadata: dict[str, Any],
    *,
    required: bool,
    maximum_age_seconds: int = 120,
) -> int:
    """Resolve live-order data age from a confirmed event, fail closed if absent."""

    event_time = str(
        metadata.get("confirmed_bar_end")
        or metadata.get("market_event_time")
        or metadata.get("price_time")
        or ""
    )
    verified = bool(
        metadata.get("confirmed_bar_end")
        or metadata.get("market_data_verified") is True
        or metadata.get("fresh_quote_verified") is True
    )
    age = seconds_since(event_time)
    if not required:
        return max(0, int(age or 0))
    if not verified or age is None:
        return maximum_age_seconds + 1
    declared_latency = max(
        0,
        int(safe_float(metadata.get("market_data_latency_seconds"), 0.0)),
    )
    return max(age, declared_latency)


def pre_trade_context(checks: dict[str, Any], intent: OrderIntent, dry_run: bool) -> PreTradeContext:
    settings = STATE["risk_settings"]
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    has_scoped_context = bool(checks.get("strategies")) and bool(checks.get("brokers"))
    if has_scoped_context:
        broker_id = str(metadata.get("broker_id") or broker_id_from_symbol(intent.symbol, intent.asset))
        reconciliation_summary = reconciliation_summary_for_broker(broker_id)
    else:
        reconciliation = checks.get("reconciliation") if isinstance(checks.get("reconciliation"), dict) else {}
        reconciliation_summary = reconciliation.get("summary") if isinstance(reconciliation.get("summary"), dict) else {}
    positions_matched = reconciliation_blocker_count(reconciliation_summary) == 0
    account_risk = account_risk_for_intent(intent)
    live_account_required = (
        not dry_run
        and intent.mode in {"SMALL_LIVE", "FULL_LIVE"}
    )
    maximum_market_data_age = 120
    account_known = account_risk.get("known") is True
    account_fresh = account_risk.get("fresh") is True
    available_cash = (
        safe_float(account_risk.get("available_cash"), 0.0)
        if account_known
        else None
    )
    account_equity = (
        safe_float(account_risk.get("current_equity"), 0.0)
        if account_known
        else None
    )
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    verified_risk_reducing = futures_risk_reducing_verified(
        checks,
        intent,
    )
    # Futures notionals are denominated in USDT, so a KRW setting must never
    # be compared to them. USD-M additionally receives a fail-closed staged
    # rollout cap from the immutable Artifact policy and current evidence.
    if broker_id == "binance-futures" and available_cash is not None:
        rollout = (
            metadata.get("capital_rollout")
            if isinstance(metadata.get("capital_rollout"), dict)
            else futures_capital_rollout_for_intent(
                checks,
                intent,
                account_risk=account_risk,
            )
        )
        decision = (
            rollout.get("decision")
            if isinstance(rollout.get("decision"), dict)
            else {}
        )
        rollout_cap = max(
            0.0,
            safe_float(decision.get("maxNotional"), 0.0),
        )
        if verified_risk_reducing:
            rollout_cap = max(0.0, available_cash)
        elif decision.get("ready") is not True:
            rollout_cap = 0.0
        maximum_order_value = min(
            max(0.0, available_cash),
            rollout_cap,
        )
        strategy_capital_limit = maximum_order_value
    else:
        maximum_order_value = float(settings["strategy_capital_limit_krw"])
        strategy_capital_limit = float(settings["strategy_capital_limit_krw"])
    symbol_exposure = broker_symbol_exposure(intent)
    broker_open_orders = metadata.get("broker_open_order_count")
    effective_open_order_count = (
        int(safe_float(broker_open_orders, 0.0))
        if broker_open_orders is not None
        else open_order_count()
    )
    return PreTradeContext(
        mode=intent.mode,
        dry_run=dry_run,
        halted=bool(STATE["kill_switch"]) or durable_control_halt_active(intent),
        new_entries_blocked=bool(STATE["new_entries_blocked"]),
        readiness_blockers=int(intent_readiness_blocker_count(checks, intent, reconciliation_summary)),
        readiness_warnings=int(checks.get("summary", {}).get("warning_count", 0)),
        real_orders_enabled=real_orders_enabled(),
        live_order_adapter_verified=broker_ready_for_intent(checks, intent),
        max_order_value=maximum_order_value,
        cooldown_seconds=int(float(settings["duplicate_order_cooldown_sec"])),
        max_symbol_weight_pct=float(settings["max_symbol_exposure_pct"]),
        daily_loss_limit_pct=float(settings["daily_loss_limit_pct"]),
        symbol_exposure=symbol_exposure,
        portfolio_equity=account_equity,
        daily_pnl_pct=safe_float(
            account_risk.get("minimum_daily_pnl_pct"),
            safe_float(account_risk.get("daily_pnl_pct"), 0.0),
        ),
        strategy_exposure=symbol_exposure,
        strategy_capital_limit=strategy_capital_limit,
        available_cash=available_cash,
        api_healthy=(
            account_known and account_fresh
            if live_account_required
            else True
        ),
        data_latency_seconds=intent_market_data_age_seconds(
            metadata,
            required=live_account_required,
            maximum_age_seconds=maximum_market_data_age,
        ),
        max_data_latency_seconds=maximum_market_data_age,
        max_slippage_bps=float(settings["max_slippage_bps"]),
        max_open_orders=int(float(settings["max_open_orders"])),
        open_order_count=effective_open_order_count,
        positions_matched=positions_matched,
        position_quantity=broker_position_quantity(
            intent.symbol,
            str(
                metadata.get("broker_id")
                or broker_id_from_symbol(intent.symbol, intent.asset)
            ),
            str(
                metadata.get("position_side")
                or metadata.get("positionSide")
                or (
                    "SHORT"
                    if str(metadata.get("position_direction") or "").lower()
                    == "short"
                    else "LONG"
                    if str(metadata.get("position_direction") or "").lower()
                    == "long"
                    else ""
                )
            ),
        ),
        risk_reducing_verified=verified_risk_reducing,
        market_type=str(metadata.get("market_type") or "spot").lower(),
        short_entries_allowed=(
            metadata.get("short_entries_requested") is True
            and metadata.get("broker_short_adapter_verified") is True
        ),
        recent_orders=recent_orders_for_risk(),
    )


def current_mode() -> Mode:
    value = str(STATE.get("mode", "MONITOR")).upper()
    if value in {"MONITOR", "SMALL_LIVE", "FULL_LIVE"}:
        return value  # type: ignore[return-value]
    return "MONITOR"


def durable_global_kill_active() -> bool:
    if emergency_stop_active():
        return True
    path = str(os.environ.get("TRADING_CONTROL_STATE_PATH") or "").strip()
    if not path:
        return False
    try:
        return bool(DurableControlState(path).read().get("globalKill"))
    except (OSError, ValueError, json.JSONDecodeError):
        return True


def durable_control_halt_active(intent: OrderIntent | None = None) -> bool:
    if emergency_stop_active():
        return True
    path = str(os.environ.get("TRADING_CONTROL_STATE_PATH") or "").strip()
    if not path:
        return False
    if intent is None:
        return durable_global_kill_active()
    broker_id = str(intent.metadata.get("broker_id") or broker_id_from_symbol(intent.symbol, intent.asset))
    assessment = DurableControlState(path).halt_assessment(
        app="live_trader",
        route=broker_id,
        strategy=intent.strategy_id,
        instrument=intent.symbol,
    )
    return bool(assessment.get("halted"))


def durable_control_snapshot() -> dict[str, Any]:
    emergency = emergency_stop_status()
    path = str(os.environ.get("TRADING_CONTROL_STATE_PATH") or "").strip()
    if not path:
        emergency_active = emergency.get("active") is True
        return {
            "configured": True,
            "halted": emergency_active,
            "globalKill": emergency_active,
            "scopedKills": {},
            "reasons": (
                [str(emergency.get("reason") or "local-emergency-stop-active")]
                if emergency_active
                else []
            ),
            "path": str(emergency.get("path") or ""),
            "emergencyStop": emergency,
            "hubControlConfigured": False,
        }
    try:
        state = DurableControlState(path).read()
        assessment = DurableControlState(path).halt_assessment(app="live_trader")
        hub_halted = bool(assessment.get("halted"))
        emergency_active = emergency.get("active") is True
        return {
            "configured": True,
            "halted": hub_halted or emergency_active,
            "globalKill": state.get("globalKill") is True or emergency_active,
            "scopedKills": state.get("scopedKills") or {},
            "reasons": [
                *(
                    [str(emergency.get("reason") or "local-emergency-stop-active")]
                    if emergency_active
                    else []
                ),
                *(assessment.get("reasons") or []),
            ],
            "path": path,
            "emergencyStop": emergency,
            "hubControlConfigured": True,
        }
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return {
            "configured": True,
            "halted": True,
            "globalKill": True,
            "scopedKills": {},
            "reasons": [f"control-state-unavailable:{type(exc).__name__}"],
            "path": path,
            "emergencyStop": emergency,
            "hubControlConfigured": True,
        }


def asset_from_symbol(symbol: str) -> str:
    text = symbol.upper()
    if any(token in text for token in ("BTC", "ETH", "USDT", "KRW-")):
        return "코인"
    if text.endswith(".KS") or text.isdigit():
        return "한국주식"
    return "미국주식"


def broker_id_from_symbol(symbol: str, asset: str) -> str:
    text = f"{symbol} {asset}".lower()
    if "krw-" in text or "upbit" in text:
        return "upbit"
    if any(token in text for token in ("btc", "eth", "usdt", "코인", "crypto")):
        return "binance"
    return "kis"


def broker_ready_for_intent(checks: dict[str, Any], intent: OrderIntent) -> bool:
    broker_id = str(intent.metadata.get("broker_id") or broker_id_from_symbol(intent.symbol, intent.asset))
    for broker in checks.get("brokers", []):
        if str(broker.get("broker_id")) == broker_id:
            return bool(broker.get("order_ready"))
    return False


def open_order_count() -> int:
    return sum(
        1
        for order in STATE["orders"]
        if _restore_order_is_pending_or_unknown(order)
    )


def recent_orders_for_risk() -> tuple[RecentOrder, ...]:
    rows: list[RecentOrder] = []
    for order in STATE["orders"][:50]:
        occurred_at = parse_order_time(str(order.get("created_at") or order.get("time") or ""))
        if occurred_at is None:
            continue
        side: OrderSide = "SELL" if str(order.get("side", "")).upper() == "SELL" else "BUY"
        rows.append(
            RecentOrder(
                strategy_id=str(order.get("strategy_id", "")),
                symbol=str(order.get("symbol", "")),
                side=side,
                occurred_at=occurred_at,
                state=str(order.get("state", "")),
            )
        )
    return tuple(rows)


def parse_order_time(value: str) -> datetime | None:
    for fmt in ("%Y-%m-%d %H:%M:%S", "%H:%M:%S"):
        try:
            parsed = datetime.strptime(value, fmt)
            if fmt == "%H:%M:%S":
                now = datetime.now()
                parsed = parsed.replace(year=now.year, month=now.month, day=now.day)
            return parsed
        except ValueError:
            continue
    return None


def next_order_id(state_name: str, dry_run: bool) -> str:
    if state_name == "dry_run" or dry_run:
        prefix = "LIVE-DRY"
    elif state_name == "approved":
        prefix = "LIVE-ORDER"
    elif state_name == "canceled":
        prefix = "LIVE-CXL"
    else:
        prefix = "LIVE-BLOCK"
    # Preserve the public prefix while replacing the process-local
    # len(orders)+1 counter with a restart-safe opaque identifier.
    return f"{prefix}-{secrets.token_hex(16).upper()}"


def stable_target_revision(
    metadata: dict[str, Any],
    *,
    trace_id: str,
    bar_time: str,
    intent: OrderIntent,
) -> int:
    raw_revision = metadata.get("target_revision")
    try:
        revision = int(raw_revision)
    except (TypeError, ValueError, OverflowError):
        revision = 0
    if revision > 0:
        return revision
    digest = hashlib.sha256(
        "|".join(
            (
                trace_id,
                bar_time,
                intent.strategy_id,
                intent.symbol,
                intent.side,
                f"{intent.quantity:.12g}",
            )
        ).encode("utf-8")
    ).hexdigest()
    return int(digest[:15], 16)


def functional_test_execution_requested(intent: OrderIntent) -> bool:
    """Return whether this order uses the isolated functional-test authority."""

    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    purpose = str(
        metadata.get("execution_purpose")
        or metadata.get("executionPurpose")
        or metadata.get("execution_profile")
        or metadata.get("executionProfile")
        or ""
    ).strip().upper()
    return purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE


def kis_functional_test_account_id() -> str:
    """Return the exact live KIS account binding used by shared permits."""

    cano, product_code = split_kis_account(
        env_value("KIS_ACCOUNT_NO"),
        env_value("KIS_ACCOUNT_PRODUCT_CODE"),
    )
    return kis_account_binding_id(cano, product_code)


def _functional_test_document_path(value: object) -> Path:
    root = FUNCTIONAL_TEST_DOCUMENT_ROOT.expanduser().resolve()
    text = str(value or "").strip()
    if not text:
        raise FunctionalTestContractError(
            "functional-test-document-path-missing"
        )
    requested = Path(text).expanduser()
    candidate = (
        requested if requested.is_absolute() else root / requested
    ).resolve()
    try:
        candidate.relative_to(root)
    except ValueError as exc:
        raise FunctionalTestContractError(
            "functional-test-document-path-outside-shared-root",
            str(candidate),
        ) from exc
    return candidate


def _read_functional_test_source(
    source: object,
    *,
    label: str,
) -> dict[str, Any]:
    try:
        return read_functional_test_document(
            _functional_test_document_path(source)
        )
    except FunctionalTestContractError:
        raise
    except (OSError, TypeError, ValueError) as exc:
        raise FunctionalTestContractError(
            f"functional-test-{label}-read-failed",
            type(exc).__name__,
        ) from exc


def functional_test_documents_for_intent(
    intent: OrderIntent,
) -> tuple[dict[str, Any] | str | None, dict[str, Any] | str | None, list[str]]:
    """Re-read only the workspace's active pointers at every safety edge.

    Permit material carried inside an order/runtime request is untrusted: its
    content hash is an integrity checksum, not an operator signature. Likewise,
    a reference to immutable history must not outlive the workspace's Stop
    action. Consequently live admission never accepts inline documents or
    caller-selected paths. Deleting either active pointer revokes the very next
    pre-trade/dispatch check.
    """

    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    errors: list[str] = []
    permit: dict[str, Any] | str | None = None
    activation: dict[str, Any] | str | None = None

    if any(
        key in metadata
        for key in (
            "functionalTestPermit",
            "functional_test_permit",
            "functionalTestPermitPath",
            "functional_test_permit_path",
            "functionalTestActivation",
            "functional_test_activation",
            "functionalTestActivationPath",
            "functional_test_activation_path",
            "functionalTestCurrentPath",
            "functional_test_current_path",
        )
    ):
        errors.append("functional-test-caller-document-override-forbidden")

    try:
        permit = _read_functional_test_source(
            FUNCTIONAL_TEST_CURRENT_PERMIT_DOCUMENT,
            label="permit",
        )
    except FunctionalTestContractError as exc:
        errors.append(str(getattr(exc, "code", "") or type(exc).__name__))
    try:
        activation = _read_functional_test_source(
            FUNCTIONAL_TEST_CURRENT_ACTIVATION_DOCUMENT,
            label="activation",
        )
    except FunctionalTestContractError as exc:
        errors.append(str(getattr(exc, "code", "") or type(exc).__name__))
    if permit is None:
        errors.append("functional-test-permit-required")
    if activation is None:
        errors.append("functional-test-live-activation-required")
    return permit, activation, list(dict.fromkeys(errors))


def functional_test_active_permit_binding() -> dict[str, Any]:
    """Return the strictly parsed binding from the one active Live permit."""

    permit = parse_functional_test_permit(
        _read_functional_test_source(
            FUNCTIONAL_TEST_CURRENT_PERMIT_DOCUMENT,
            label="permit",
        )
    )
    return permit.binding.snapshot()


def functional_test_account_fingerprint(account_id: object) -> str:
    return governance_sha256(
        {"functionalTestAccount": str(account_id or "")}
    )


def functional_test_durable_authority_status(permit: Any) -> dict[str, Any]:
    return PROGRAM_LEDGER.functional_test_authority_status(
        permit_id=str(permit.permit_id or ""),
        account_fingerprint=functional_test_account_fingerprint(
            permit.binding.account_id
        ),
    )


def functional_test_authority_mutation_assessment(
    *,
    require_kis_reconciliation: bool = False,
) -> dict[str, Any]:
    """Block permit/activation mutation while live authority is in use."""

    blockers: list[str] = []
    runtime_snapshot = LIVE_CONTINUOUS_CONTROLLER.snapshot()
    profiles = (
        runtime_snapshot.get("profiles")
        if isinstance(runtime_snapshot.get("profiles"), dict)
        else {}
    )
    stock_runtime = (
        profiles.get("stock")
        if isinstance(profiles.get("stock"), dict)
        else {}
    )
    runtime_phase = str(stock_runtime.get("phase") or "STOPPED").upper()
    runtime_active = bool(stock_runtime.get("running")) or runtime_phase in {
        "STARTING",
        "RUNNING",
        "DEGRADED",
        "DRAINING",
        "STOPPING",
    }
    if runtime_active:
        blockers.append("functional-test-authority-runtime-active")

    session_id = str(
        (STATE.get("active_runtime_session_ids") or {}).get("stock") or ""
    ).strip()
    session_lifecycle = ""
    session_execution_purpose = ""
    if session_id:
        try:
            session = OPERATIONAL_GOVERNANCE.get_runtime_session(session_id)
            session_lifecycle = str(
                session.lifecycle if session is not None else "UNKNOWN"
            ).upper()
            session_execution_purpose = str(
                (
                    session.metadata.get("executionPurpose")
                    if session is not None
                    and isinstance(session.metadata, dict)
                    else ""
                )
                or ""
            ).upper()
        except (OSError, sqlite3.Error, ValueError):
            session_lifecycle = "UNKNOWN"
        if session_lifecycle in {
            "STARTING",
            "RUNNING",
            "DEGRADED",
            "DRAINING",
            "STOPPING",
            "UNKNOWN",
        }:
            blockers.append("functional-test-authority-session-active")

    durable_truth_available = True
    try:
        durable_orders = PROGRAM_LEDGER.order_dispatch_rows(5000)
    except (OSError, sqlite3.Error, TypeError, ValueError):
        durable_orders = []
        durable_truth_available = False
        blockers.append("functional-test-durable-order-truth-unavailable")
    functional_orders = [
        item
        for item in [*STATE.get("orders", []), *durable_orders]
        if isinstance(item, dict)
        and str(item.get("execution_purpose") or "").upper()
        == FUNCTIONAL_TEST_EXECUTION_PURPOSE
    ]
    pending_orders = [
        item
        for item in functional_orders
        if _restore_order_is_pending_or_unknown(item)
    ]
    order_truth = kis_order_truth_snapshot()
    working_order_count = combined_kis_working_order_count(
        pending_orders,
        order_truth=order_truth,
    )
    if working_order_count:
        blockers.append("functional-test-working-orders-unresolved")
    if require_kis_reconciliation and (
        order_truth.get("complete") is not True
        or order_truth.get("fresh") is not True
        or order_truth.get("absenceIsAuthoritative") is not True
    ):
        blockers.append("functional-test-kis-order-truth-unavailable")

    reconciliation: dict[str, Any] = {}
    kis_reconciled = not require_kis_reconciliation
    if require_kis_reconciliation:
        try:
            reconciliation = reconciliation_summary_for_broker("kis")
            broker_cache = (
                STATE.get("broker_reconciliation")
                if isinstance(STATE.get("broker_reconciliation"), dict)
                else {}
            )
            broker_errors = [
                item
                for item in broker_cache.get("errors", [])
                if isinstance(item, dict)
                and str(item.get("broker_id") or "").strip().lower()
                in {"", "kis"}
            ]
            successful_accounts = {
                str(item).strip().lower()
                for item in broker_cache.get(
                    "successful_account_brokers", []
                )
            }
            successful_positions = {
                str(item).strip().lower()
                for item in broker_cache.get(
                    "successful_position_brokers", []
                )
            }
            kis_reconciled = bool(
                reconciliation_blocker_count(reconciliation) == 0
                and not broker_errors
                and "kis" in successful_accounts
                and "kis" in successful_positions
                and order_truth.get("complete") is True
                and order_truth.get("fresh") is True
                and order_truth.get("absenceIsAuthoritative") is True
            )
        except (OSError, sqlite3.Error, TypeError, ValueError):
            kis_reconciled = False
        if not kis_reconciled:
            blockers.append("functional-test-kis-reconciliation-unresolved")

    return {
        "allowed": not blockers,
        "blockers": list(dict.fromkeys(blockers)),
        "runtime": {
            "active": runtime_active,
            "phase": runtime_phase,
            "executionPurpose": str(
                stock_runtime.get("executionPurpose") or ""
            ),
        },
        "session": {
            "sessionId": session_id,
            "lifecycle": session_lifecycle,
            "executionPurpose": session_execution_purpose,
        },
        "workingOrderCount": working_order_count,
        "kisOrderTruth": order_truth,
        "durableOrderTruthAvailable": durable_truth_available,
        "kisReconciled": kis_reconciled,
        "reconciliation": reconciliation,
    }


def functional_test_runtime_authority_scope() -> dict[str, str]:
    """Recover the sealed stop scope even when workspace pointers are lost."""

    session_id = str(
        (STATE.get("active_runtime_session_ids") or {}).get("stock") or ""
    ).strip()
    if session_id:
        try:
            session = OPERATIONAL_GOVERNANCE.get_runtime_session(session_id)
            metadata = (
                session.metadata
                if session is not None and isinstance(session.metadata, dict)
                else {}
            )
            permit_id = str(metadata.get("permitId") or "").strip()
            fingerprint = str(
                metadata.get("accountFingerprint") or ""
            ).strip().lower()
            if permit_id and fingerprint:
                return {
                    "permitId": permit_id,
                    "accountFingerprint": fingerprint,
                    "source": "governance-session",
                }
        except (OSError, sqlite3.Error, ValueError):
            pass
    context = getattr(
        LIVE_CONTINUOUS_CONTROLLER,
        "functional_test_context",
        {},
    )
    if isinstance(context, dict):
        permit_id = str(
            context.get("functional_test_permit_id") or ""
        ).strip()
        fingerprint = str(
            context.get("functional_test_account_fingerprint") or ""
        ).strip().lower()
        if permit_id and fingerprint:
            return {
                "permitId": permit_id,
                "accountFingerprint": fingerprint,
                "source": "controller-context",
            }
    return {}


def functional_test_active_authority(
    *,
    now: datetime | None = None,
) -> tuple[Any, Any]:
    """Return the current, active permit and daily activation.

    Only the two revocable workspace pointers are accepted.  This helper is
    shared by runtime sealing and final dispatch authorization so a stopped,
    expired, replaced, or malformed document invalidates the next boundary.
    """

    current = now or datetime.now(timezone.utc)
    permit_payload = _read_functional_test_source(
        FUNCTIONAL_TEST_CURRENT_PERMIT_DOCUMENT,
        label="permit",
    )
    permit = assert_functional_test_permit_active(
        permit_payload,
        now=current,
    )
    if str(getattr(permit.environment, "value", permit.environment)) != (
        FUNCTIONAL_TEST_ENVIRONMENT
    ):
        raise FunctionalTestContractError(
            "functional-test-kis-live-environment-required"
        )
    activation_payload = _read_functional_test_source(
        FUNCTIONAL_TEST_CURRENT_ACTIVATION_DOCUMENT,
        label="activation",
    )
    activation = parse_live_activation_token(
        activation_payload,
        permit=permit,
        now=current,
    )
    return permit, activation


def _functional_test_strategy_for_intent(
    checks: dict[str, Any],
    intent: OrderIntent,
) -> dict[str, Any]:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    portfolio_id = str(
        metadata.get("portfolio_id") or metadata.get("portfolioId") or ""
    ).strip()
    candidates = [
        item
        for item in checks.get("strategies", [])
        if isinstance(item, dict)
    ]
    try:
        candidates.extend(strategy_rows(portfolio_rows()))
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        pass
    for strategy in candidates:
        if str(strategy.get("strategy_id") or "") != str(intent.strategy_id):
            continue
        if str(strategy.get("symbol") or "").strip().upper() != str(
            intent.symbol or ""
        ).strip().upper():
            continue
        gate = (
            strategy.get("portfolio_gate")
            if isinstance(strategy.get("portfolio_gate"), dict)
            else {}
        )
        if portfolio_id and str(gate.get("portfolioId") or "") != portfolio_id:
            continue
        return strategy
    return {}


def _functional_test_portfolio_for_intent(
    checks: dict[str, Any],
    intent: OrderIntent,
) -> dict[str, Any]:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    portfolio_id = str(
        metadata.get("portfolio_id") or metadata.get("portfolioId") or ""
    ).strip()
    if not portfolio_id:
        return {}
    candidates = [
        item
        for item in checks.get("portfolios", [])
        if isinstance(item, dict)
    ]
    try:
        candidates.extend(portfolio_rows())
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        pass
    return next(
        (
            item
            for item in candidates
            if str(
                item.get("id")
                or item.get("portfolio_id")
                or item.get("portfolioId")
                or ""
            ).strip()
            == portfolio_id
        ),
        {},
    )


def _functional_test_us_strategy_route(
    strategy: dict[str, Any],
) -> dict[str, Any]:
    """Derive the released US live route from current artifact truth.

    The signed permit is deliberately not an input.  This prevents a valid
    permit from teaching the runtime which exchange to use after the selected
    Strategy artifact has changed or lost its exact route metadata.
    """

    parameters = (
        strategy.get("parameters")
        if isinstance(strategy.get("parameters"), dict)
        else {}
    )
    trader_contract = (
        strategy.get("traderContract")
        if isinstance(strategy.get("traderContract"), dict)
        else strategy.get("trader_contract")
        if isinstance(strategy.get("trader_contract"), dict)
        else {}
    )
    symbol = canonical_kis_us_symbol(
        strategy.get("execution_instrument")
        or strategy.get("instrument_id")
        or strategy.get("symbol")
        or ""
    )
    raw_exchange = str(
        strategy.get("exchange")
        or strategy.get("exchangeCode")
        or trader_contract.get("exchange")
        or parameters.get("exchange")
        or ""
    ).strip().upper()
    exchange = {
        "NYS": "NYSE",
        "NAS": "NASD",
        "AMS": "AMEX",
    }.get(raw_exchange, raw_exchange)
    timeframe = str(strategy.get("timeframe") or "").strip().lower()
    blockers: list[str] = []
    if strategy_broker_id(strategy) != "kis":
        blockers.append("kis-broker-route-required")
    if symbol != "F":
        blockers.append("functional-test-us-symbol-must-be-F")
    if exchange != "NYSE":
        blockers.append("functional-test-us-exchange-must-be-NYSE")
    if timeframe != "5m":
        blockers.append("functional-test-us-timeframe-must-be-5m")
    if blockers:
        raise ValueError("functional-test-us-current-artifact-route:" + ",".join(blockers))
    return {
        "marketGroup": "US_STOCK",
        "executionRoute": "KIS_US_LIVE_CONTINUOUS",
        "settlementCurrency": "USD",
        "exchanges": ("NYSE",),
        "symbolRoutes": (("F", "NYSE"),),
        "symbol": "F",
        "timeframe": "5m",
    }


def functional_test_current_binding(
    checks: dict[str, Any],
    intent: OrderIntent,
    *,
    portfolio_only: bool = False,
) -> dict[str, Any]:
    """Derive current target/account scope without trusting intent hashes."""

    permit_binding: dict[str, Any] = {}
    try:
        permit_binding = functional_test_active_permit_binding()
    except (FunctionalTestContractError, OSError, ValueError):
        permit_binding = {}
    market_group = str(permit_binding.get("marketGroup") or "").upper()
    us_live = market_group == "US_STOCK"
    strategy = _functional_test_strategy_for_intent(checks, intent)
    portfolio = _functional_test_portfolio_for_intent(checks, intent)
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    portfolio_id = str(
        portfolio.get("id")
        or portfolio.get("portfolio_id")
        or portfolio.get("portfolioId")
        or ""
    ).strip()
    portfolio_reference = (
        verified_portfolio_artifact_reference(portfolio)
        if portfolio
        else {}
    )
    strategy_reference = (
        strategy.get("artifact_reference")
        if isinstance(strategy.get("artifact_reference"), dict)
        else {}
    )
    strategy_id = str(strategy.get("strategy_id") or "").strip()
    strategy_hash = str(
        strategy_reference.get("artifactHash")
        or strategy.get("artifact_hash")
        or ""
    ).strip().lower()
    instances = (
        portfolio.get("strategy_instances")
        if isinstance(portfolio.get("strategy_instances"), list)
        else portfolio.get("strategyInstances")
        if isinstance(portfolio.get("strategyInstances"), list)
        else []
    )
    canonical_symbol = (
        canonical_kis_us_symbol if us_live else canonical_kis_domestic_symbol
    )
    symbols = {
        canonical_symbol(
            item.get("executionInstrument")
            or item.get("instrumentId")
            or item.get("symbol")
            or item.get("qualifiedSymbol")
            or ""
        )
        for item in instances
        if isinstance(item, dict)
    }
    symbols.discard("")
    if not symbols and strategy:
        symbol = canonical_symbol(
            strategy.get("execution_instrument")
            or strategy.get("instrument_id")
            or strategy.get("symbol")
            or intent.symbol
        )
        if symbol:
            symbols.add(symbol)

    requested_instance_id = str(
        metadata.get("strategy_instance_id")
        or metadata.get("strategyInstanceId")
        or ""
    ).strip()
    matching_instance = next(
        (
            item
            for item in instances
            if isinstance(item, dict)
            and str(
                item.get("sourceStrategyId")
                or item.get("strategyId")
                or item.get("strategy_id")
                or ""
            ).strip()
            == strategy_id
            and str(
                item.get("symbol")
                or item.get("qualifiedSymbol")
                or intent.symbol
            ).strip().upper()
            == str(intent.symbol or "").strip().upper()
            and (
                not requested_instance_id
                or str(
                    item.get("instanceId")
                    or item.get("strategyInstanceId")
                    or ""
                ).strip()
                == requested_instance_id
            )
        ),
        {},
    )
    strategy_instance_id = str(
        matching_instance.get("instanceId")
        or matching_instance.get("strategyInstanceId")
        or strategy.get("strategy_instance_id")
        or (f"standalone:{strategy_id}" if strategy_id and not portfolio_id else "")
    ).strip()
    result = {
        "strategy_artifact_id": (
            ""
            if portfolio_only
            else str(
                strategy_reference.get("artifactId") or strategy_id
            ).strip()
        ),
        "strategy_artifact_hash": "" if portfolio_only else strategy_hash,
        "strategy_instance_id": "" if portfolio_only else strategy_instance_id,
        "portfolio_required": bool(portfolio_id),
        "portfolio_artifact_id": str(
            portfolio_reference.get("artifactId") or portfolio_id
        ).strip(),
        "portfolio_artifact_hash": str(
            portfolio_reference.get("artifactHash")
            or portfolio.get("artifact_hash")
            or portfolio.get("artifactHash")
            or ""
        ).strip().lower(),
        "portfolio_instance_id": (
            f"functional-portfolio:{str(portfolio_reference.get('artifactId') or portfolio_id).strip()}:"
            f"{str(portfolio_reference.get('artifactHash') or '').strip().lower()[:12]}"
            if portfolio_id
            else ""
        ),
        "account_id": kis_functional_test_account_id(),
        "symbols": tuple(sorted(symbols)),
    }
    if us_live:
        if portfolio_id or portfolio_only:
            raise ValueError("functional-test-us-live-strategy-only")
        route = _functional_test_us_strategy_route(strategy)
        if tuple(sorted(symbols)) != (route["symbol"],):
            raise ValueError("functional-test-us-current-artifact-symbol-mismatch")
        sealed_route = FunctionalTestBinding(
            strategy_artifact_id=str(result["strategy_artifact_id"]),
            strategy_artifact_hash=str(result["strategy_artifact_hash"]),
            strategy_instance_id=str(result["strategy_instance_id"]),
            portfolio_required=False,
            portfolio_artifact_id="",
            portfolio_artifact_hash="",
            portfolio_instance_id="",
            account_id=str(result["account_id"]),
            symbols=("F",),
            market_group=str(route["marketGroup"]),
            execution_route=str(route["executionRoute"]),
            settlement_currency=str(route["settlementCurrency"]),
            exchanges=tuple(route["exchanges"]),
            symbol_routes=tuple(route["symbolRoutes"]),
        ).snapshot()
        result.update(
            {
                "market_group": sealed_route["marketGroup"],
                "execution_route": sealed_route["executionRoute"],
                "settlement_currency": sealed_route["settlementCurrency"],
                "exchanges": tuple(sealed_route["exchanges"]),
                "symbol_routes": tuple(
                    (str(item["symbol"]), str(item["exchange"]))
                    for item in sealed_route["symbolRoutes"]
                ),
                "route_scope_hash": sealed_route["routeScopeHash"],
            }
        )
    return result


def functional_test_global_caps(intent: OrderIntent) -> dict[str, float | int]:
    """Intersect configured risk with the deliberately tiny SMALL_LIVE profile."""

    account = account_risk_for_intent(
        intent,
        maximum_age_seconds=FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS,
    )
    equity = (
        safe_float(account.get("current_equity"), 0.0)
        if account.get("known") is True and account.get("fresh") is True
        else 0.0
    )
    settings = STATE.get("risk_settings", {})
    profile = ENVIRONMENT_PROFILES["SMALL_LIVE"]
    configured_capital = max(
        0.0,
        safe_float(settings.get("strategy_capital_limit_krw"), 0.0),
    )
    gross_cap = min(
        configured_capital,
        equity * profile.maximum_strategy_capital_pct / 100.0,
    )
    order_cap = min(
        configured_capital,
        equity * profile.maximum_order_pct / 100.0,
    )
    configured_loss_pct = abs(
        safe_float(settings.get("daily_loss_limit_pct"), 0.0)
    )
    loss_pct = min(
        configured_loss_pct,
        profile.daily_loss_limit_pct,
    )
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    us_live = str(metadata.get("marketGroup") or "").upper() == "US_STOCK"
    if us_live:
        return {
            "max_order_quantity": 1,
            "max_order_notional": US_LIVE_FUNCTIONAL_TEST_CAPS.max_order_notional,
            "max_gross_exposure": US_LIVE_FUNCTIONAL_TEST_CAPS.max_gross_exposure,
            "max_orders": US_LIVE_FUNCTIONAL_TEST_CAPS.max_orders,
            "max_open_positions": US_LIVE_FUNCTIONAL_TEST_CAPS.max_open_positions,
            "max_loss": US_LIVE_FUNCTIONAL_TEST_CAPS.max_loss,
        }
    return {
        "max_order_quantity": 1,
        "max_order_notional": order_cap,
        "max_gross_exposure": gross_cap,
        "max_orders": max(
            1,
            min(
                3,
                int(safe_float(settings.get("max_open_orders"), 0.0)),
            ),
        ),
        "max_open_positions": 1,
        "max_loss": equity * loss_pct / 100.0,
    }


def functional_test_effective_caps_snapshot() -> dict[str, Any]:
    """Expose the exact safer permit/global intersection used at order time."""

    intent = OrderIntent(
        strategy_id="functional-test-cap-preview",
        asset="KR_STOCK",
        symbol="005930",
        side="BUY",
        quantity=1.0,
        reference_price=1.0,
        mode="SMALL_LIVE",
        reason="functional-test-cap-preview",
        metadata={"broker_id": "kis"},
    )
    global_caps = functional_test_global_caps(intent)
    permit_caps = LIVE_FUNCTIONAL_TEST_CAPS.snapshot()
    field_map = {
        "maxOrderQuantity": "max_order_quantity",
        "maxOrderNotional": "max_order_notional",
        "maxGrossExposure": "max_gross_exposure",
        "maxOrders": "max_orders",
        "maxOpenPositions": "max_open_positions",
        "maxLoss": "max_loss",
    }
    effective = {
        public: min(
            safe_float(permit_caps.get(public), 0.0),
            safe_float(global_caps.get(internal), 0.0),
        )
        for public, internal in field_map.items()
    }
    account = account_risk_for_intent(
        intent,
        maximum_age_seconds=FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS,
    )
    available = bool(
        account.get("known") is True and account.get("fresh") is True
    )
    return {
        "available": available,
        "values": effective,
        "permitCaps": permit_caps,
        "reason": (
            "permit-and-current-account-risk-intersection"
            if available
            else "fresh-kis-account-risk-required"
        ),
        "observedAt": str(account.get("observed_at") or ""),
    }


def functional_test_risk_snapshot(
    intent: OrderIntent,
    *,
    permit_id: str = "",
) -> FunctionalTestRiskSnapshot:
    """Build fresh broker-derived account/position risk for one KIS order."""

    reconciliation = (
        STATE.get("broker_reconciliation")
        if isinstance(STATE.get("broker_reconciliation"), dict)
        else {}
    )
    errors = {
        str(item.get("broker_id") or "").strip().lower()
        for item in reconciliation.get("errors", [])
        if isinstance(item, dict)
    }
    successful = {
        str(item).strip().lower()
        for item in reconciliation.get("successful_position_brokers", [])
        if str(item).strip()
    }
    fetched_age = seconds_since(reconciliation.get("fetched_at"))
    account = account_risk_for_intent(
        intent,
        maximum_age_seconds=FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS,
    )
    rows = [
        item
        for item in reconciliation.get("positions", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == "kis"
    ]
    gross_exposure = 0.0
    value_complete = True
    normalized_symbol = _canonical_restore_instrument("kis", intent.symbol)
    symbol_quantity = 0.0
    symbol_value = 0.0
    open_position_count = 0
    for row in rows:
        quantity = _restore_quantity(row)
        if abs(quantity) <= 1e-12:
            continue
        open_position_count += 1
        raw_value = row.get("broker_value")
        if raw_value is None:
            value_complete = False
            value = 0.0
        else:
            value = abs(safe_float(raw_value, 0.0))
        gross_exposure += value
        if _canonical_restore_instrument(
            "kis", str(row.get("symbol") or "")
        ) == normalized_symbol:
            symbol_quantity += quantity
            symbol_value += value

    signed_quantity = intent.quantity if intent.side == "BUY" else -intent.quantity
    projected_quantity = symbol_quantity + signed_quantity
    projected_symbol_value = abs(projected_quantity * intent.reference_price)
    projected_gross = max(
        0.0,
        gross_exposure - symbol_value + projected_symbol_value,
    )
    opens_new_position = (
        abs(symbol_quantity) <= 1e-12
        and abs(projected_quantity) > 1e-12
    )
    projected_positions = max(
        0,
        open_position_count
        + (1 if opens_new_position else 0)
        - (
            1
            if abs(symbol_quantity) > 1e-12
            and abs(projected_quantity) <= 1e-12
            else 0
        ),
    )
    functional_orders = [
        item
        for item in STATE.get("orders", [])
        if isinstance(item, dict)
        and str(item.get("execution_purpose") or "").upper()
        == FUNCTIONAL_TEST_EXECUTION_PURPOSE
        and (
            not permit_id
            or str(
                (
                    item.get("functional_test")
                    if isinstance(item.get("functional_test"), dict)
                    else {}
                ).get("permitId")
                or ""
            )
            == permit_id
        )
        and str(item.get("state") or "").lower()
        not in {
            "risk_blocked",
            "adapter_blocked",
            "broker_rejected",
            "canceled",
            "retry_exhausted",
        }
    ]
    local_kis_pending_orders = [
        item
        for item in STATE.get("orders", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower() == "kis"
        and _restore_order_is_pending_or_unknown(item)
    ]
    order_truth = kis_order_truth_snapshot()
    working_order_count = combined_kis_working_order_count(
        local_kis_pending_orders,
        order_truth=order_truth,
    )
    reservation_truth_available = True
    try:
        durable_order_count = PROGRAM_LEDGER.functional_test_reservation_count(
            permit_id,
            exclude_idempotency_key=str(
                (
                    intent.metadata
                    if isinstance(intent.metadata, dict)
                    else {}
                ).get("functional_test_reservation_id")
                or ""
            ),
        )
    except (OSError, sqlite3.Error, TypeError, ValueError):
        durable_order_count = 0
        reservation_truth_available = False
    durable_equity_truth = False
    permit_drawdown = 0.0
    try:
        active_permit, _active_activation = functional_test_active_authority()
        if (
            not permit_id
            or str(active_permit.permit_id or "") != str(permit_id)
        ):
            raise ValueError("functional-test-equity-permit-mismatch")
        account_fingerprint = governance_sha256(
            {
                "functionalTestAccount": str(
                    active_permit.binding.account_id or ""
                )
            }
        )
        current_equity = safe_float(account.get("current_equity"), -1.0)
        observed_at = str(account.get("observed_at") or "").strip()
        if (
            account.get("known") is not True
            or account.get("fresh") is not True
            or current_equity < 0
            or not observed_at
        ):
            raise ValueError("functional-test-equity-observation-unavailable")
        equity_scope = PROGRAM_LEDGER.observe_functional_test_equity(
            permit_id=str(active_permit.permit_id),
            account_fingerprint=account_fingerprint,
            current_equity=current_equity,
            observed_at=observed_at,
            allow_create=False,
        )
        permit_drawdown = max(
            0.0,
            safe_float(equity_scope.get("worst_drawdown"), 0.0),
        )
        durable_equity_truth = True
    except (
        FunctionalTestContractError,
        OSError,
        sqlite3.Error,
        TypeError,
        ValueError,
    ):
        durable_equity_truth = False
    daily_pnl = safe_float(account.get("daily_pnl"), 0.0)
    starting_equity = safe_float(account.get("starting_equity"), 0.0)
    minimum_pct = safe_float(account.get("minimum_daily_pnl_pct"), 0.0)
    peak_loss = max(0.0, -(starting_equity * minimum_pct / 100.0))
    reconciled = bool(
        "kis" in successful
        and "kis" not in errors
        and fetched_age is not None
        and fetched_age <= FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS
        and account.get("known") is True
        and account.get("fresh") is True
        and value_complete
        and order_truth.get("complete") is True
        and order_truth.get("fresh") is True
        and order_truth.get("absenceIsAuthoritative") is True
    )
    return FunctionalTestRiskSnapshot(
        gross_exposure=gross_exposure,
        open_position_count=open_position_count,
        loss=max(0.0, -daily_pnl, peak_loss, permit_drawdown),
        opens_new_position=opens_new_position,
        working_order_count=working_order_count,
        submitted_order_count=max(
            len(functional_orders),
            durable_order_count,
            int(order_truth.get("orderCount") or 0),
        ),
        reconciled=(
            reconciled
            and reservation_truth_available
            and durable_equity_truth
        ),
        observed_at=str(
            account.get("observed_at")
            or reconciliation.get("fetched_at")
            or ""
        ),
        gross_exposure_after=projected_gross,
        open_position_count_after=projected_positions,
    )


def functional_test_safety_report_for_intent(
    checks: dict[str, Any],
    intent: OrderIntent,
    *,
    phase: Literal["PRETRADE", "DISPATCH"],
) -> tuple[FunctionalTestSafetyReport, list[str]]:
    permit, activation, document_errors = functional_test_documents_for_intent(
        intent
    )
    permit_id = ""
    portfolio_only = False
    if isinstance(permit, dict):
        permit_id = str(permit.get("permitId") or "")
        binding_payload = (
            permit.get("binding")
            if isinstance(permit.get("binding"), dict)
            else {}
        )
        portfolio_only = bool(
            binding_payload.get("portfolioRequired") is True
            and not any(
                str(binding_payload.get(key) or "").strip()
                for key in (
                    "strategyArtifactId",
                    "strategyArtifactHash",
                    "strategyInstanceId",
                )
            )
        )
        try:
            authority_status = PROGRAM_LEDGER.functional_test_authority_status(
                permit_id=permit_id,
                account_fingerprint=functional_test_account_fingerprint(
                    binding_payload.get("accountId")
                ),
            )
            if authority_status.get("closed") is True:
                document_errors.append("functional-test-authority-closed")
        except (OSError, sqlite3.Error, TypeError, ValueError):
            document_errors.append(
                "functional-test-durable-authority-unavailable"
            )
    report = evaluate_functional_test_order(
        permit,
        current_binding=functional_test_current_binding(
            checks,
            intent,
            portfolio_only=portfolio_only,
        ),
        environment=FUNCTIONAL_TEST_ENVIRONMENT,
        intent=intent,
        global_caps=functional_test_global_caps(intent),
        risk=functional_test_risk_snapshot(intent, permit_id=permit_id),
        operator_confirmed=STATE.get("operator_confirmed") is True,
        live_activation_payload=activation,
        phase=phase,
    )
    return report, document_errors


def _functional_test_report_reason(
    report: FunctionalTestSafetyReport,
    document_errors: list[str],
) -> str:
    blockers = [*document_errors, *report.blocker_codes]
    return (
        "functional-test-authorized"
        if not blockers
        else "functional-test-blocked:" + ",".join(dict.fromkeys(blockers))
    )


def functional_test_dispatch_assessment(
    intent: OrderIntent,
    *,
    broker_payload: dict[str, Any] | None = None,
) -> tuple[bool, str, dict[str, Any]]:
    """Re-read exact functional-test authority and broker truth for dispatch."""

    if not functional_test_execution_requested(intent):
        return True, "", {}
    try:
        evaluated_intent = intent
        if isinstance(broker_payload, dict):
            broker_quantity = safe_float(
                broker_payload.get("quantity")
                or broker_payload.get("qty"),
                0.0,
            )
            broker_price = safe_float(broker_payload.get("price"), 0.0)
            if broker_quantity > 0 and broker_price > 0:
                evaluated_intent = replace(
                    intent,
                    quantity=broker_quantity,
                    reference_price=broker_price,
                )
        portfolios = portfolio_rows()
        checks = {
            "portfolios": portfolios,
            "strategies": strategy_rows(portfolios),
        }
        report, document_errors = functional_test_safety_report_for_intent(
            checks,
            evaluated_intent,
            phase="DISPATCH",
        )
        reason = _functional_test_report_reason(report, document_errors)
        payload = report.to_dict()
        payload["documentErrors"] = list(document_errors)
        payload["promotionEligible"] = False
        return report.allowed and not document_errors, reason, payload
    except Exception as exc:
        # This edge is immediately upstream of a broker side effect. Unknown
        # filesystem, parsing, account, or state failures are always blocking.
        reason = f"functional-test-dispatch-error:{type(exc).__name__}"
        return False, reason, {
            "schemaVersion": "live-functional-test-safety-report-v1",
            "phase": "DISPATCH",
            "allowed": False,
            "blockerCodes": [reason],
            "promotionEligible": False,
            "fullLiveAllowed": False,
        }


def _block_managed_order_before_dispatch(
    order: dict[str, Any],
    managed_order: Any,
    reason: str,
) -> tuple[bool, str]:
    LIVE_OMS.transition(managed_order.order_id, "REJECTED", reason)
    order.update(
        {
            "state": "risk_blocked",
            "queue_state": "blocked",
            "reason": reason,
            "next_retry_at": "-",
            "updated_at": now_text(),
        }
    )
    return False, reason


def live_broker_dispatch_allowed(
    intent: OrderIntent,
    *,
    dry_run: bool,
) -> tuple[bool, str]:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    if broker_id == "kis" and _KIS_CONTROL_RESERVATION:
        return False, "kis-route-control-reservation-active"
    if dry_run:
        return False, "dry-run-broker-dispatch-forbidden"
    if STATE.get("dry_run"):
        return False, "dry-run-control-active"
    normalized_mode = str(intent.mode or "").strip().upper()
    if normalized_mode not in LIVE_BROKER_DISPATCH_MODES:
        return False, "non-live-intent-broker-dispatch-forbidden"
    runtime_mode = current_mode()
    if runtime_mode not in LIVE_BROKER_DISPATCH_MODES:
        return False, "non-live-runtime-broker-dispatch-forbidden"
    if runtime_mode != normalized_mode:
        return False, "live-runtime-intent-mode-mismatch"
    if functional_test_execution_requested(intent):
        if normalized_mode != "SMALL_LIVE":
            return False, "functional-test-small-live-mode-required"
        if broker_id != "kis":
            return False, "functional-test-kis-live-route-required"
        environment = str(
            metadata.get("functional_test_environment")
            or metadata.get("functionalTestEnvironment")
            or metadata.get("environment")
            or ""
        ).strip().upper()
        if environment != FUNCTIONAL_TEST_ENVIRONMENT:
            return False, "functional-test-kis-live-environment-required"
        if any(
            metadata.get(key) is True
            for key in (
                "promotion_eligible",
                "promotionEligible",
                "use_as_promotion_evidence",
                "useAsPromotionEvidence",
                "full_live_requested",
                "fullLiveRequested",
            )
        ):
            return False, "functional-test-promotion-evidence-forbidden"
        order_type = str(
            metadata.get("order_type") or "LIMIT"
        ).strip().upper()
        if (
            ENVIRONMENT_PROFILES["SMALL_LIVE"].market_orders_allowed
            is not True
            and order_type in {"01", "MARKET", "MKT"}
        ):
            return False, "functional-test-market-order-forbidden"
    if not real_orders_enabled():
        return False, "real-order-route-disabled"
    if not STATE.get("operator_confirmed"):
        return False, "operator-confirmation-required"
    if STATE.get("kill_switch") or durable_control_halt_active(intent):
        return False, "kill-switch-broker-dispatch-forbidden"
    if intent_market_data_age_seconds(metadata, required=True) > 120:
        return False, "market-data-event-stale-or-unverified"
    verified_risk_reducing = False
    if metadata.get("risk_reducing") is True or STATE.get(
        "new_entries_blocked"
    ):
        verified_risk_reducing = futures_risk_reducing_verified({}, intent)
    if STATE.get("new_entries_blocked"):
        # Recompute from current broker truth at the final side-effect edge.
        # The metadata flag may originate in strategy code and is never enough
        # on its own to bypass a new-entry block.
        if not verified_risk_reducing:
            return False, "risk-increasing-order-blocked"
    elif (
        metadata.get("risk_reducing") is True
        and not verified_risk_reducing
    ):
        return False, "reduce-only-position-verification-failed"
    return True, ""


def kis_cross_process_dispatch_lease(
    intent: OrderIntent,
) -> dict[str, object]:
    """Retain exclusive ownership of the exact KIS account/authority.

    The lease is acquired only at the final broker boundary and then held for
    this process lifetime. This makes a second server fail closed instead of
    merely queueing the same account's POST behind the first process.
    """

    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    if broker_id != "kis":
        return {"acquired": True, "kind": "not-kis"}
    account_id = kis_functional_test_account_id()
    account_fingerprint = functional_test_account_fingerprint(account_id)
    authority_id = ""
    if functional_test_execution_requested(intent):
        authority_id = governance_sha256(
            {
                "permitId": str(
                    metadata.get("functional_test_permit_id") or ""
                ),
                "permitHash": str(
                    metadata.get("functional_test_permit_hash") or ""
                ),
                "activationTokenId": str(
                    metadata.get("functional_test_activation_token_id") or ""
                ),
            }
        )
    return hold_kis_dispatch_lease(
        account_fingerprint,
        authority_id=authority_id,
    )


def exact_live_canary_scope_dispatch_allowed(
    intent: OrderIntent,
    stored_scope: dict[str, Any] | None,
) -> tuple[bool, str, dict[str, Any]]:
    """Require the SMALL_LIVE order scope to equal current persisted truth."""

    if intent.mode != "SMALL_LIVE":
        return True, "", {}
    expected = dict(stored_scope) if isinstance(stored_scope, dict) else {}
    if expected.get("eligible") is not True or not str(
        expected.get("scopeId") or ""
    ):
        return False, "live-canary-order-scope-missing", {}
    try:
        current = current_live_canary_scope(
            intent.strategy_id,
            materialize=False,
        )
    except Exception as exc:
        return (
            False,
            f"live-canary-current-scope-error:{type(exc).__name__}",
            {},
        )
    if current.get("eligible") is not True:
        issues = ",".join(
            str(item) for item in current.get("issues") or []
        )
        return (
            False,
            "live-canary-current-scope-invalid:" + (issues or "eligible=false"),
            current,
        )
    compared_fields = (*CANARY_SCOPE_FIELDS, "scopeId")
    mismatches = [
        field
        for field in compared_fields
        if str(expected.get(field) or "") != str(current.get(field) or "")
    ]
    if mismatches:
        return (
            False,
            "live-canary-order-scope-changed:" + ",".join(mismatches),
            current,
        )
    return True, "", current


def order_gate_audit_record(
    *,
    source: str,
    intent: OrderIntent,
    order: dict[str, Any],
    risk_report: PreTradeRiskReport,
    runner_report: StrategyExecutionResult | None = None,
    retry: bool = False,
) -> AuditEvent:
    payload: dict[str, Any] = {
        "order": dict(order),
        "queue_state": str(order.get("queue_state", "")),
        "dry_run": bool(order.get("dry_run", False)),
        "retry": retry,
    }
    if runner_report is not None:
        payload["runner_report"] = runner_report.to_dict()
    return audit_event_from_order_gate(
        app="live_trader",
        intent=intent,
        report=risk_report,
        order_id=str(order.get("order_id", "")),
        state=str(order.get("state", "")),
        source=source,
        payload=payload,
    )


def live_broker_payload(
    intent: OrderIntent,
    *,
    idempotency_key: str,
) -> dict[str, Any]:
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).lower()
    order_type = str(metadata.get("order_type") or "LIMIT")
    broker_price = intent.reference_price
    if broker_id == "upbit":
        if order_type.lower() == "price":
            broker_price = intent.notional
        elif order_type.lower() == "market":
            broker_price = 0.0
    elif broker_id == "kis":
        if order_type == "01":
            broker_price = 0.0
        elif (
            order_type == "00"
            and metadata.get("fresh_quote_verified") is True
        ):
            broker_price = safe_float(
                metadata.get("fresh_quote_price"),
                intent.reference_price,
            )
    return {
        "broker_id": broker_id,
        "symbol": intent.symbol,
        "asset": intent.asset,
        "side": intent.side,
        "quantity": intent.quantity,
        "qty": intent.quantity,
        "price": broker_price,
        "notional": intent.notional,
        "order_type": order_type,
        "identifier": idempotency_key,
        "exchange": str(metadata.get("exchange") or ""),
        "position_direction": str(
            metadata.get("position_direction") or "long"
        ),
        "market_type": str(metadata.get("market_type") or "spot"),
        "risk_reducing": metadata.get("risk_reducing") is True,
        "max_leverage": safe_float(
            metadata.get("max_leverage"),
            1.0,
        ),
        "required_margin_type": str(
            metadata.get("required_margin_type") or "ISOLATED"
        ),
        "per_trade_risk_pct": safe_float(
            metadata.get("per_trade_risk_pct"),
            0.5,
        ),
        "max_notional_pct": safe_float(
            metadata.get("max_notional_pct"),
            10.0,
        ),
        "futures_execution_policy": (
            dict(metadata.get("futures_execution_policy"))
            if isinstance(metadata.get("futures_execution_policy"), dict)
            else {}
        ),
    }


def functional_test_runtime_dispatch_allowed(
    intent: OrderIntent,
) -> tuple[bool, str, dict[str, Any]]:
    """Authorize a FUNCTIONAL_TEST order only from its sealed test session."""

    if not functional_test_execution_requested(intent):
        return False, "functional-test-execution-purpose-required", {}
    if intent.mode != "SMALL_LIVE" or current_mode() != "SMALL_LIVE":
        return False, "functional-test-runtime-small-live-required", {}
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    if str(metadata.get("broker_id") or "").strip().lower() != "kis":
        return False, "functional-test-runtime-kis-route-required", {}
    session_id = str(
        (STATE.get("active_runtime_session_ids") or {}).get("stock") or ""
    ).strip()
    claimed_session_id = str(
        metadata.get("functional_test_session_id")
        or metadata.get("functionalTestSessionId")
        or ""
    ).strip()
    if not session_id or not claimed_session_id:
        return False, "functional-test-runtime-session-missing", {}
    if not secrets.compare_digest(session_id, claimed_session_id):
        return False, "functional-test-runtime-session-mismatch", {}
    try:
        refreshed, refresh_reason, refresh_details = (
            refresh_functional_test_runtime_preflight(intent)
        )
        if not refreshed:
            return False, refresh_reason, refresh_details
        authorization = OPERATIONAL_GOVERNANCE.runtime_authorization(
            session_id,
            require_fresh_preflight=True,
        )
        if authorization.get("allowed") is not True:
            return (
                False,
                "functional-test-runtime-authorization-blocked:"
                + ",".join(
                    str(item) for item in authorization.get("reasons", [])
                ),
                authorization,
            )
        session = (
            authorization.get("session")
            if isinstance(authorization.get("session"), dict)
            else {}
        )
        if (
            str(session.get("profile") or "") != "stock"
            or str(session.get("mode") or "") != "SMALL_LIVE"
        ):
            return False, "functional-test-runtime-profile-mode-mismatch", authorization
        session_metadata = (
            session.get("metadata")
            if isinstance(session.get("metadata"), dict)
            else {}
        )
        if (
            str(session_metadata.get("executionPurpose") or "")
            != FUNCTIONAL_TEST_EXECUTION_PURPOSE
            or session_metadata.get("promotionEligible") is not False
            or str(session_metadata.get("evidenceClass") or "")
            != "FUNCTIONAL_TEST_NON_PROMOTION"
        ):
            return False, "functional-test-session-purpose-invalid", authorization
        manifest = OPERATIONAL_GOVERNANCE.get_deployment_manifest_by_hash(
            str(session.get("deploymentManifestHash") or "")
        )
        if manifest is None:
            return False, "functional-test-manifest-missing", authorization
        manifest_metadata = dict(manifest.metadata)
        if (
            str(manifest_metadata.get("executionPurpose") or "")
            != FUNCTIONAL_TEST_EXECUTION_PURPOSE
            or manifest_metadata.get("promotionEligible") is not False
            or manifest_metadata.get("fullLiveAllowed") is not False
        ):
            return False, "functional-test-manifest-purpose-invalid", authorization

        permit, activation = functional_test_active_authority()
        try:
            authority_status = PROGRAM_LEDGER.functional_test_authority_status(
                permit_id=str(permit.permit_id or ""),
                account_fingerprint=functional_test_account_fingerprint(
                    permit.binding.account_id
                ),
            )
        except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
            return (
                False,
                "functional-test-durable-authority-unavailable:"
                + type(exc).__name__,
                authorization,
            )
        if authority_status.get("closed") is True:
            return (
                False,
                "functional-test-authority-closed",
                {**authorization, "authorityStatus": authority_status},
            )
        authority_pairs = (
            ("permitId", permit.permit_id),
            ("permitHash", permit.content_hash),
            ("activationTokenId", activation.token_id),
            ("activationHash", activation.content_hash),
        )
        for key, current_value in authority_pairs:
            if (
                str(manifest_metadata.get(key) or "") != str(current_value)
                or str(session_metadata.get(key) or "") != str(current_value)
            ):
                return (
                    False,
                    "functional-test-session-authority-changed:" + key,
                    authorization,
                )

        portfolio_id = str(
            metadata.get("portfolio_id")
            or metadata.get("portfolioId")
            or ""
        ).strip()
        scope = _functional_test_runtime_scope(
            portfolio_id=portfolio_id,
            strategy_id=str(intent.strategy_id or ""),
            permit=permit,
        )
        if (
            str(scope.get("bindingHash") or "")
            != str(manifest_metadata.get("bindingHash") or "")
            or str(scope.get("bindingHash") or "")
            != str(session_metadata.get("bindingHash") or "")
        ):
            return False, "functional-test-runtime-binding-changed", authorization
        if (
            str(scope.get("accountFingerprint") or "")
            != str(manifest.account_fingerprint or "")
            or str(scope.get("accountFingerprint") or "")
            != str(session_metadata.get("accountFingerprint") or "")
        ):
            return False, "functional-test-runtime-account-changed", authorization
        if (
            str(scope.get("strategyMemberHash") or "")
            != str(manifest_metadata.get("strategyMemberHash") or "")
            or str(scope.get("strategyMemberHash") or "")
            != str(session_metadata.get("strategyMemberHash") or "")
        ):
            return False, "functional-test-runtime-members-changed", authorization
        if sorted(scope.get("allowedSymbols") or []) != sorted(
            manifest_metadata.get("allowedSymbols") or []
        ):
            return False, "functional-test-runtime-symbol-scope-changed", authorization

        current_values = _functional_test_manifest_values(
            scope,
            permit,
            activation,
            preflight_ttl_seconds=manifest.preflight_ttl_seconds,
        )
        immutable_mismatches = [
            label
            for label, current_value, sealed_value in (
                (
                    "strategy-artifact",
                    current_values["strategy_artifact_hash"],
                    manifest.strategy_artifact_hash,
                ),
                (
                    "portfolio-artifact",
                    current_values["portfolio_artifact_hash"],
                    manifest.portfolio_artifact_hash,
                ),
                ("build", current_values["build_hash"], manifest.build_hash),
                (
                    "risk-policy",
                    current_values["risk_policy_hash"],
                    manifest.risk_policy_hash,
                ),
                ("config", current_values["config_hash"], manifest.config_hash),
            )
            if str(current_value or "") != str(sealed_value or "")
        ]
        if immutable_mismatches:
            return (
                False,
                "functional-test-runtime-seal-changed:"
                + ",".join(immutable_mismatches),
                authorization,
            )

        requested_instance = str(
            metadata.get("strategy_instance_id")
            or metadata.get("strategyInstanceId")
            or ""
        ).strip()
        normalized_symbol = canonical_kis_domestic_symbol(intent.symbol)
        matching_member = next(
            (
                item
                for item in scope.get("strategyMembers", [])
                if isinstance(item, dict)
                and str(item.get("strategyId") or "")
                == str(intent.strategy_id or "")
                and str(item.get("strategyInstanceId") or "")
                == requested_instance
                and str(item.get("symbol") or "") == normalized_symbol
                and str(item.get("brokerId") or "") == "kis"
            ),
            None,
        )
        if matching_member is None:
            return False, "functional-test-runtime-sleeve-context-mismatch", authorization
        authorization["functionalTest"] = {
            "permitId": permit.permit_id,
            "permitHash": permit.content_hash,
            "activationTokenId": activation.token_id,
            "activationHash": activation.content_hash,
            "bindingHash": scope.get("bindingHash"),
            "strategyMemberHash": scope.get("strategyMemberHash"),
            "promotionEligible": False,
        }
        return True, "functional-test-runtime-authorized", authorization
    except (FunctionalTestContractError, OSError, sqlite3.Error, ValueError) as exc:
        code = (
            exc.code
            if isinstance(exc, FunctionalTestContractError)
            else type(exc).__name__
        )
        return (
            False,
            f"functional-test-runtime-authorization-error:{code}",
            {},
        )


def operational_runtime_dispatch_allowed(intent: OrderIntent) -> tuple[bool, str, dict[str, Any]]:
    """Revalidate immutable live session identity at the final side-effect edge."""

    if intent.mode not in {"SMALL_LIVE", "FULL_LIVE"}:
        return False, "operational-session-live-mode-required", {}
    if current_mode() != intent.mode:
        return False, "operational-runtime-intent-mode-mismatch", {}
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    profile_id = "stock" if broker_id == "kis" else "crypto"
    session_id = str(
        (STATE.get("active_runtime_session_ids") or {}).get(profile_id) or ""
    )
    if not session_id:
        return False, "operational-runtime-session-missing", {}
    try:
        authorization = OPERATIONAL_GOVERNANCE.runtime_authorization(
            session_id,
            # A runtime may stay alive longer than its launch preflight TTL.
            # Revalidate freshness again at every broker side-effect edge so
            # an expired launch approval cannot authorize a later order.
            require_fresh_preflight=True,
        )
        if authorization.get("allowed") is not True:
            return (
                False,
                "operational-runtime-authorization-blocked:"
                + ",".join(str(item) for item in authorization.get("reasons", [])),
                authorization,
            )
        session = authorization.get("session") if isinstance(authorization.get("session"), dict) else {}
        if str(session.get("mode") or "").upper() != str(intent.mode).upper():
            return False, "operational-runtime-mode-mismatch", authorization
        manifest = OPERATIONAL_GOVERNANCE.get_deployment_manifest_by_hash(
            str(session.get("deploymentManifestHash") or "")
        )
        if manifest is None:
            return False, "operational-deployment-manifest-missing", authorization
        manifest_metadata = dict(manifest.metadata)
        manifest_deployment_binding = (
            dict(manifest_metadata.get("deploymentBinding"))
            if isinstance(manifest_metadata.get("deploymentBinding"), dict)
            else {}
        )
        if not _live_deployment_binding_is_executable(
            manifest_deployment_binding,
            mode=intent.mode,
        ):
            return False, "operational-deployment-binding-invalid", authorization
        if str(manifest_deployment_binding.get("deploymentId") or "") != str(
            manifest.deployment_id or ""
        ):
            return False, "operational-deployment-binding-id-mismatch", authorization
        if str(manifest_metadata.get("deploymentBindingHash") or "") != str(
            manifest_deployment_binding.get("bindingHash") or ""
        ):
            return False, "operational-deployment-binding-hash-invalid", authorization
        session_metadata = (
            session.get("metadata")
            if isinstance(session.get("metadata"), dict)
            else {}
        )
        if (
            session_metadata.get("deploymentBinding")
            != manifest_deployment_binding
            or str(session_metadata.get("deploymentBindingHash") or "")
            != str(manifest_deployment_binding.get("bindingHash") or "")
        ):
            return False, "operational-session-deployment-binding-mismatch", authorization
        manifest_paper_bindings = [
            dict(item)
            for item in manifest_metadata.get("paperFinalBindings", [])
            if isinstance(item, dict)
        ]
        if (
            not manifest_paper_bindings
            or any(item.get("ready") is not True for item in manifest_paper_bindings)
        ):
            return False, "operational-paper-final-binding-missing", authorization
        required_binding_keys = (
            "strategyId",
            "strategyInstanceId",
            "paperEvidenceId",
            "paperEvidenceHash",
            "paperEvidenceBundleHash",
            "paperFinalBindingHash",
            "paperGovernanceDeploymentId",
        )
        if any(
            any(not str(item.get(key) or "").strip() for key in required_binding_keys)
            for item in manifest_paper_bindings
        ):
            return False, "operational-paper-final-binding-incomplete", authorization
        if any(
            str(item.get("paperGovernanceDeploymentId") or "").strip()
            == str(manifest.deployment_id or "").strip()
            for item in manifest_paper_bindings
        ):
            return False, "operational-paper-live-deployment-not-distinct", authorization
        hash_keys = (
            "paperEvidenceHash",
            "paperEvidenceBundleHash",
            "paperFinalBindingHash",
        )
        if any(
            any(
                len(str(item.get(key) or "").strip()) != 64
                or any(
                    character not in "0123456789abcdef"
                    for character in str(item.get(key) or "").strip().lower()
                )
                for key in hash_keys
            )
            for item in manifest_paper_bindings
        ):
            return False, "operational-paper-final-binding-hash-invalid", authorization
        portfolio_binding_required = bool(manifest.portfolio_artifact_hash)
        if any(
            (
                not str(item.get("paperPortfolioArtifactId") or "").strip()
                or not str(item.get("paperPortfolioArtifactHash") or "").strip()
                or not str(item.get("paperPortfolioInstanceId") or "").strip()
            )
            if portfolio_binding_required
            else any(
                str(item.get(key) or "").strip()
                for key in (
                    "paperPortfolioArtifactId",
                    "paperPortfolioArtifactHash",
                    "paperPortfolioInstanceId",
                )
            )
            for item in manifest_paper_bindings
        ):
            return False, "operational-paper-portfolio-binding-invalid", authorization
        manifest_portfolio_reference = (
            manifest_metadata.get("portfolioArtifact")
            if isinstance(manifest_metadata.get("portfolioArtifact"), dict)
            else {}
        )
        if portfolio_binding_required and (
            str(manifest_portfolio_reference.get("artifactHash") or "").lower()
            != str(manifest.portfolio_artifact_hash or "").lower()
            or any(
                str(item.get("paperPortfolioArtifactId") or "")
                != str(manifest_portfolio_reference.get("artifactId") or "")
                or str(item.get("paperPortfolioArtifactHash") or "").lower()
                != str(manifest.portfolio_artifact_hash or "").lower()
                for item in manifest_paper_bindings
            )
        ):
            return False, "operational-paper-portfolio-hash-mismatch", authorization
        if str(manifest_metadata.get("paperFinalBindingsHash") or "") != governance_sha256(
            manifest_paper_bindings
        ):
            return False, "operational-paper-final-binding-hash-invalid", authorization
        manifest_broker_routes = sorted(
            {
                str(item).strip().lower()
                for item in manifest_metadata.get("brokerRoutes", [])
                if str(item).strip()
            }
        )
        if not manifest_broker_routes:
            manifest_broker_routes = [str(manifest.broker_route or "").lower()]
        if (
            len(manifest_broker_routes) != 1
            or manifest_broker_routes[0] != str(manifest.broker_route or "").lower()
        ):
            return False, "operational-cross-broker-portfolio-blocked", authorization
        members = [
            dict(item)
            for item in manifest_metadata.get("strategyMembers", [])
            if isinstance(item, dict)
        ]
        if not members:
            members = [
                {
                    "strategyId": str(manifest_metadata.get("strategyId") or ""),
                    "strategyInstanceId": str(
                        manifest_metadata.get("strategyInstanceId") or ""
                    ),
                    "symbol": str(manifest_metadata.get("symbol") or "").upper(),
                    "brokerId": str(manifest_metadata.get("brokerId") or "").lower(),
                    "artifactHash": manifest.strategy_artifact_hash,
                }
            ]
        requested_instance_ids: list[str] = []
        if metadata.get("multi_strategy") is True:
            raw_instance_ids = metadata.get("strategy_instance_ids")
            if not isinstance(raw_instance_ids, (list, tuple)):
                return (
                    False,
                    "operational-multi-strategy-instance-context-invalid",
                    authorization,
                )
            requested_instance_ids = [
                str(item or "").strip() for item in raw_instance_ids
            ]
            if (
                not requested_instance_ids
                or any(not item for item in requested_instance_ids)
                or len(set(requested_instance_ids)) != len(requested_instance_ids)
            ):
                return (
                    False,
                    "operational-multi-strategy-instance-context-invalid",
                    authorization,
                )
            manifest_symbol_instances = {
                str(item.get("strategyInstanceId") or "").strip()
                for item in members
                if str(item.get("symbol") or "").upper()
                == str(intent.symbol).upper()
                and str(item.get("strategyInstanceId") or "").strip()
            }
            if not set(requested_instance_ids).issubset(
                manifest_symbol_instances
            ):
                return (
                    False,
                    "operational-multi-strategy-instance-context-mismatch",
                    authorization,
                )
        requested_strategy_instance = str(
            metadata.get("strategy_instance_id")
            or metadata.get("strategyInstanceId")
            or ""
        ).strip()
        if not requested_strategy_instance:
            return False, "operational-strategy-instance-context-missing", authorization
        if (
            metadata.get("multi_strategy") is True
            and requested_strategy_instance not in requested_instance_ids
        ):
            return (
                False,
                "operational-multi-strategy-lead-instance-mismatch",
                authorization,
            )
        matching_identity_members = [
            item
            for item in members
            if str(item.get("strategyId") or "") == str(intent.strategy_id)
            and str(item.get("symbol") or "").upper()
            == str(intent.symbol).upper()
        ]
        member = next(
            (
                item
                for item in matching_identity_members
                if str(item.get("strategyInstanceId") or "").strip()
                == requested_strategy_instance
            ),
            None,
        )
        if member is None:
            if matching_identity_members:
                return (
                    False,
                    "operational-strategy-instance-context-mismatch",
                    authorization,
                )
            return False, "operational-strategy-context-mismatch", authorization
        if str(member.get("brokerId") or "").lower() != broker_id:
            return False, "operational-broker-context-mismatch", authorization
        requested_portfolio = str(
            metadata.get("portfolio_id") or metadata.get("portfolioId") or ""
        )
        manifest_portfolio = str(manifest_metadata.get("portfolioId") or "")
        if manifest.portfolio_artifact_hash:
            if requested_portfolio != manifest_portfolio:
                return False, "operational-portfolio-context-mismatch", authorization
        elif requested_portfolio:
            return (
                False,
                "operational-standalone-portfolio-context-not-empty",
                authorization,
            )
        strategies = strategy_rows(portfolio_rows())
        strategy = next(
            (
                item
                for item in strategies
                if str(item.get("strategy_id") or "") == str(intent.strategy_id)
                and (
                    not manifest_portfolio
                    or str(
                        (item.get("portfolio_gate") or {}).get("portfolioId")
                        if isinstance(item.get("portfolio_gate"), dict)
                        else ""
                    )
                    == manifest_portfolio
                )
            ),
            None,
        )
        if strategy is None:
            return False, "operational-current-strategy-missing", authorization
        required_permission = (
            "live_eligible" if intent.mode == "FULL_LIVE" else "live_small_eligible"
        )
        if strategy.get(required_permission) is not True:
            return False, "operational-current-deployment-permission-revoked", authorization
        current_member_hash = _operational_artifact_hash(strategy)
        if str(member.get("artifactHash") or "") != current_member_hash:
            return False, "operational-strategy-hash-changed", authorization
        current_inputs = _operational_manifest_inputs(strategy)
        if str(current_inputs.get("deployment_id") or "").strip() != str(
            manifest.deployment_id or ""
        ).strip():
            return False, "operational-deployment-context-changed", authorization
        current_metadata = (
            current_inputs.get("metadata")
            if isinstance(current_inputs.get("metadata"), dict)
            else {}
        )
        if (
            current_metadata.get("paperFinalBindings")
            != manifest_metadata.get("paperFinalBindings")
            or current_metadata.get("paperFinalBindingsHash")
            != manifest_metadata.get("paperFinalBindingsHash")
        ):
            return False, "operational-paper-final-binding-changed", authorization
        if (
            current_metadata.get("deploymentBinding")
            != manifest_deployment_binding
            or current_metadata.get("deploymentBindingHash")
            != manifest_metadata.get("deploymentBindingHash")
        ):
            return False, "operational-deployment-binding-changed", authorization
        if current_metadata.get("portfolioArtifact") != manifest_portfolio_reference:
            return False, "operational-portfolio-reference-changed", authorization
        if current_inputs["strategy_artifact_hash"] != manifest.strategy_artifact_hash:
            return False, "operational-strategy-hash-changed", authorization
        if current_inputs["portfolio_artifact_hash"] != manifest.portfolio_artifact_hash:
            return False, "operational-portfolio-hash-changed", authorization
        if current_inputs["risk_policy_hash"] != manifest.risk_policy_hash:
            return False, "operational-risk-policy-changed", authorization
        if current_inputs["config_revision"] != manifest.config_revision:
            return False, "operational-config-revision-changed", authorization
        if current_inputs["config_hash"] != manifest.config_hash:
            return False, "operational-config-changed", authorization
        return True, "operational-runtime-authorized", authorization
    except (OSError, sqlite3.Error, ValueError) as exc:
        return False, f"operational-runtime-authorization-error:{type(exc).__name__}", {}


def dispatch_live_order_with_checkpoint(
    order: dict[str, Any],
    intent: OrderIntent,
    managed_order: Any,
    *,
    trace_id: str,
) -> tuple[bool, str]:
    """Checkpoint an intent before dispatch and durably close its outcome."""

    initial_metadata = (
        intent.metadata if isinstance(intent.metadata, dict) else {}
    )
    initial_broker_id = str(
        initial_metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    if not bool(order.get("dry_run")) and _runtime_mode_lock_owned():
        # ContinuousRuntimeSupervisor retains RUNTIME_MODE_LOCK for the whole
        # evaluated cycle.  Until controls are migrated to a durable A/B/C
        # protocol, entering SAFETY here would invert against mode/STOP/Kill.
        # Block before a functional slot, ProgramLedger checkpoint, broker
        # read, token request, or trading socket is possible.
        return _block_managed_order_before_dispatch(
            order,
            managed_order,
            "CONTINUOUS_FINAL_DISPATCH_LOCK_ORDER_UNAVAILABLE:"
            + initial_broker_id,
        )

    dispatch_allowed, invariant_reason = live_broker_dispatch_allowed(
        intent,
        dry_run=bool(order.get("dry_run")),
    )
    if not dispatch_allowed:
        LIVE_OMS.transition(
            managed_order.order_id,
            "REJECTED",
            invariant_reason,
        )
        order.update(
            {
                "state": "risk_blocked",
                "queue_state": "blocked",
                "reason": invariant_reason,
                "next_retry_at": "-",
                "updated_at": now_text(),
            }
        )
        return False, invariant_reason
    functional_allowed, functional_reason, functional_report = (
        functional_test_dispatch_assessment(intent)
    )
    if functional_test_execution_requested(intent):
        order["functional_test_dispatch"] = functional_report
    if not functional_allowed:
        return _block_managed_order_before_dispatch(
            order,
            managed_order,
            functional_reason,
        )
    functional_execution = functional_test_execution_requested(intent)
    scope_allowed, scope_reason, current_scope = (
        (True, "", {})
        if functional_execution
        else exact_live_canary_scope_dispatch_allowed(
            intent,
            order.get("canary_scope")
            if isinstance(order.get("canary_scope"), dict)
            else {},
        )
    )
    order["current_canary_scope"] = current_scope
    if not scope_allowed:
        LIVE_OMS.transition(
            managed_order.order_id,
            "REJECTED",
            scope_reason,
        )
        order.update(
            {
                "state": "risk_blocked",
                "queue_state": "blocked",
                "reason": scope_reason,
                "next_retry_at": "-",
                "updated_at": now_text(),
            }
        )
        return False, scope_reason
    governance_allowed, governance_reason, governance_authorization = (
        functional_test_runtime_dispatch_allowed(intent)
        if functional_execution
        else operational_runtime_dispatch_allowed(intent)
    )
    order["runtime_authorization"] = governance_authorization
    if not governance_allowed:
        LIVE_OMS.transition(
            managed_order.order_id,
            "REJECTED",
            governance_reason,
        )
        order.update(
            {
                "state": "risk_blocked",
                "queue_state": "blocked",
                "reason": governance_reason,
                "next_retry_at": "-",
                "updated_at": now_text(),
            }
        )
        return False, governance_reason

    if functional_test_execution_requested(intent):
        effective_caps = (
            functional_report.get("effectiveCaps")
            if isinstance(functional_report.get("effectiveCaps"), dict)
            else {}
        )
        permit_id = str(functional_report.get("permitId") or "").strip()
        raw_maximum_orders = effective_caps.get("max_orders")
        try:
            maximum_orders = int(raw_maximum_orders)
            if (
                isinstance(raw_maximum_orders, bool)
                or float(raw_maximum_orders) != float(maximum_orders)
                or maximum_orders <= 0
            ):
                raise ValueError("invalid maximum orders")
            reservation = PROGRAM_LEDGER.reserve_functional_test_order(
                permit_id=permit_id,
                idempotency_key=str(order.get("idempotency_key") or ""),
                order_id=str(order.get("order_id") or ""),
                maximum_orders=maximum_orders,
                reserved_at=now_text(),
            )
        except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
            reservation = {
                "allowed": False,
                "created": False,
                "count": -1,
                "reservation": {},
                "reason": (
                    "functional-test-order-reservation-error:"
                    f"{type(exc).__name__}"
                ),
            }
        order["functional_test_reservation"] = reservation
        if reservation.get("allowed") is not True:
            return _block_managed_order_before_dispatch(
                order,
                managed_order,
                str(
                    reservation.get("reason")
                    or "functional-test-order-reservation-blocked"
                ),
            )
        intent = replace(
            intent,
            metadata={
                **(
                    intent.metadata
                    if isinstance(intent.metadata, dict)
                    else {}
                ),
                "functional_test_reservation_id": str(
                    order.get("idempotency_key") or ""
                ),
            },
        )

    broker_payload = live_broker_payload(
        intent,
        idempotency_key=str(order.get("idempotency_key") or ""),
    )
    broker_id = str(broker_payload["broker_id"])
    order.update(
        {
            "broker_id": broker_id,
            "broker_request": dict(broker_payload),
            "state": "dispatch_pending",
            "queue_state": "reconcile_required",
            "reason": "broker-dispatch-pending",
            "next_retry_at": "-",
            "updated_at": now_text(),
        }
    )
    try:
        checkpoint = PROGRAM_LEDGER.checkpoint_order_dispatch(order)
    except (OSError, sqlite3.Error, ValueError) as exc:
        reason = "durable-dispatch-checkpoint-failed"
        LIVE_OMS.transition(managed_order.order_id, "REJECTED", reason)
        order.update(
            {
                "state": "adapter_blocked",
                "queue_state": "held",
                "reason": reason,
                "dispatch_checkpoint_error": (
                    f"{type(exc).__name__}:{str(exc)[:200]}"
                ),
                "updated_at": now_text(),
            }
        )
        return False, reason
    if checkpoint.get("created") is not True:
        existing = (
            checkpoint.get("order")
            if isinstance(checkpoint.get("order"), dict)
            else {}
        )
        reason = "durable-dispatch-idempotency-key-exists"
        LIVE_OMS.mark_unknown(
            managed_order.order_id,
            "durable pending/terminal dispatch already exists",
        )
        order.update(
            {
                "state": "unknown",
                "queue_state": "reconcile_required",
                "reason": reason,
                "duplicate_dispatch_order_id": str(
                    existing.get("order_id") or ""
                ),
                "updated_at": now_text(),
            }
        )
        return False, reason

    # The SQLite dispatch journal is the primary pre-side-effect checkpoint.
    # Mirror it to the recovery journal so older recovery readers also retain
    # the pending intent and idempotency key.
    try:
        recovery_payload = recovery_state_payload()
        recovery_payload["orders"] = [
            dict(order),
            *[
                dict(item)
                for item in STATE.get("orders", [])
                if str(item.get("order_id") or "")
                != str(order.get("order_id") or "")
            ],
        ][:50]
        recovery_keys = [
            str(item.get("idempotency_key") or "")
            for item in recovery_payload["orders"]
            if str(item.get("idempotency_key") or "")
        ]
        RECOVERY_JOURNAL.save(
            recovery_payload,
            reason="dispatch-pending",
            idempotency_keys=recovery_keys,
        )
    except (OSError, ValueError, TypeError) as exc:
        append_audit(
            "warn",
            "Dispatch Journal",
            (
                "보조 recovery checkpoint 저장 실패; SQLite pending "
                f"journal은 유지됨: {type(exc).__name__}"
            ),
        )

    try:
        # Re-check at the final side-effect boundary.  A PAPER/SHADOW/MONITOR
        # intent can never reach place_order even if an earlier gate is mocked
        # or a mode changes between evaluation and dispatch preparation.
        dispatch_allowed, invariant_reason = live_broker_dispatch_allowed(
            intent,
            dry_run=bool(order.get("dry_run")),
        )
        if not dispatch_allowed:
            LIVE_OMS.transition(
                managed_order.order_id,
                "REJECTED",
                invariant_reason,
            )
            order.update(
                {
                    "state": "risk_blocked",
                    "queue_state": "blocked",
                    "reason": invariant_reason,
                    "next_retry_at": "-",
                }
            )
            return False, invariant_reason
        scope_allowed, scope_reason, current_scope = (
            (True, "", {})
            if functional_execution
            else exact_live_canary_scope_dispatch_allowed(
                intent,
                order.get("canary_scope")
                if isinstance(order.get("canary_scope"), dict)
                else {},
            )
        )
        order["current_canary_scope"] = current_scope
        if not scope_allowed:
            LIVE_OMS.transition(
                managed_order.order_id,
                "REJECTED",
                scope_reason,
            )
            order.update(
                {
                    "state": "risk_blocked",
                    "queue_state": "blocked",
                    "reason": scope_reason,
                    "next_retry_at": "-",
                }
            )
            return False, scope_reason
        governance_allowed, governance_reason, governance_authorization = (
            functional_test_runtime_dispatch_allowed(intent)
            if functional_execution
            else operational_runtime_dispatch_allowed(intent)
        )
        order["runtime_authorization"] = governance_authorization
        if not governance_allowed:
            LIVE_OMS.transition(
                managed_order.order_id,
                "REJECTED",
                governance_reason,
            )
            order.update(
                {
                    "state": "risk_blocked",
                    "queue_state": "blocked",
                    "reason": governance_reason,
                    "next_retry_at": "-",
                }
            )
            return False, governance_reason

        # Re-read the shared permit, today's live activation, the current
        # Artifact/account binding, and broker-derived exposure immediately
        # before the KIS POST. The earlier PRETRADE/DISPATCH reports are
        # diagnostics only and never become reusable authorization tokens.
        functional_allowed, functional_reason, functional_report = (
            functional_test_dispatch_assessment(
                intent,
                broker_payload=broker_payload,
            )
        )
        if functional_test_execution_requested(intent):
            order["functional_test_dispatch_final"] = functional_report
        if not functional_allowed:
            return _block_managed_order_before_dispatch(
                order,
                managed_order,
                functional_reason,
            )

        # A portfolio intent carries a sealed sleeve-allocation/netting plan.
        # Reconcile that plan against the latest complete KIS holdings at the
        # final side-effect boundary; an earlier strategy-cycle validation is
        # never reusable authority for this POST.
        portfolio_execution = (
            intent.metadata.get("portfolio_execution")
            if isinstance(intent.metadata, dict)
            and isinstance(intent.metadata.get("portfolio_execution"), dict)
            else None
        )
        if portfolio_execution is not None:
            try:
                from .continuous_live import (
                    validate_portfolio_execution_dispatch,
                )

                (
                    portfolio_allowed,
                    portfolio_reason,
                    portfolio_report,
                ) = validate_portfolio_execution_dispatch(intent)
                order["portfolio_execution_dispatch_final"] = (
                    dict(portfolio_report)
                    if isinstance(portfolio_report, dict)
                    else {}
                )
            except Exception as exc:
                portfolio_allowed = False
                portfolio_reason = (
                    "portfolio-execution-dispatch-validation-error:"
                    + type(exc).__name__
                )
                order["portfolio_execution_dispatch_final"] = {
                    "ok": False,
                    "errorType": type(exc).__name__,
                }
            if not portfolio_allowed:
                return _block_managed_order_before_dispatch(
                    order,
                    managed_order,
                    str(
                        portfolio_reason
                        or "portfolio-execution-dispatch-validation-blocked"
                    ),
                )

        with FUNCTIONAL_TEST_AUTHORITY_DISPATCH_LOCK:
            cross_process_lease = kis_cross_process_dispatch_lease(intent)
            order["cross_process_dispatch_lease"] = cross_process_lease
            if cross_process_lease.get("acquired") is not True:
                return _block_managed_order_before_dispatch(
                    order,
                    managed_order,
                    str(
                        cross_process_lease.get("reason")
                        or "kis-cross-process-dispatch-lease-unavailable"
                    ),
                )
            if functional_execution:
                try:
                    final_permit, final_activation = (
                        functional_test_active_authority()
                    )
                    final_account_fingerprint = (
                        functional_test_account_fingerprint(
                            final_permit.binding.account_id
                        )
                    )
                    final_authority = (
                        PROGRAM_LEDGER.functional_test_authority_status(
                            permit_id=str(final_permit.permit_id or ""),
                            account_fingerprint=final_account_fingerprint,
                        )
                    )
                except (
                    FunctionalTestContractError,
                    OSError,
                    sqlite3.Error,
                    TypeError,
                    ValueError,
                ) as exc:
                    return _block_managed_order_before_dispatch(
                        order,
                        managed_order,
                        "functional-test-final-authority-unavailable:"
                        + type(exc).__name__,
                    )
                order["functional_test_authority_final"] = final_authority
                if final_authority.get("closed") is True:
                    return _block_managed_order_before_dispatch(
                        order,
                        managed_order,
                        "functional-test-authority-closed",
                    )
                metadata = (
                    intent.metadata
                    if isinstance(intent.metadata, dict)
                    else {}
                )
                sealed_authority = {
                    "permitId": str(
                        metadata.get("functional_test_permit_id") or ""
                    ),
                    "permitHash": str(
                        metadata.get("functional_test_permit_hash") or ""
                    ),
                    "activationTokenId": str(
                        metadata.get("functional_test_activation_token_id")
                        or ""
                    ),
                    "activationHash": str(
                        metadata.get("functional_test_activation_hash") or ""
                    ),
                    "accountFingerprint": str(
                        metadata.get("functional_test_account_fingerprint")
                        or ""
                    ).lower(),
                }
                current_authority = {
                    "permitId": str(final_permit.permit_id or ""),
                    "permitHash": str(final_permit.content_hash or ""),
                    "activationTokenId": str(
                        final_activation.token_id or ""
                    ),
                    "activationHash": str(
                        final_activation.content_hash or ""
                    ),
                    "accountFingerprint": final_account_fingerprint.lower(),
                }
                missing_seals = [
                    key
                    for key, value in sealed_authority.items()
                    if not value
                ]
                mismatched_seals = [
                    key
                    for key, value in sealed_authority.items()
                    if value
                    and not secrets.compare_digest(
                        value,
                        current_authority[key],
                    )
                ]
                order["functional_test_authority_final"][
                    "sealedAuthority"
                ] = sealed_authority
                order["functional_test_authority_final"][
                    "currentAuthority"
                ] = current_authority
                if missing_seals:
                    return _block_managed_order_before_dispatch(
                        order,
                        managed_order,
                        "functional-test-final-authority-seal-missing:"
                        + ",".join(missing_seals),
                    )
                if mismatched_seals:
                    return _block_managed_order_before_dispatch(
                        order,
                        managed_order,
                        "functional-test-final-authority-changed:"
                        + ",".join(mismatched_seals),
                    )
            # Serialize the final mutable-control check and broker call with
            # both API risk mutations and the native Kill latch. Native Kill
            # writes ON first and returns only after any already-in-flight
            # boundary exits; every later boundary observes ON and POSTs 0.
            with SAFETY_CONFIRMATION_MUTATION_LOCK:
                with _ordinary_upbit_final_mutation_boundary(
                    broker_id
                ) as emergency:
                    if emergency.get("active") is True:
                        return _block_managed_order_before_dispatch(
                            order,
                            managed_order,
                            "emergency-stop-latch-broker-dispatch-forbidden",
                        )
                    final_allowed, final_reason = live_broker_dispatch_allowed(
                        intent,
                        dry_run=bool(order.get("dry_run")),
                    )
                    if not final_allowed:
                        return _block_managed_order_before_dispatch(
                            order,
                            managed_order,
                            final_reason,
                        )
                    LIVE_OMS.transition(
                        managed_order.order_id,
                        "SUBMITTING",
                        "broker request dispatch",
                    )
                    broker_response = LiveBrokerRouter().place_order(
                        broker_payload
                    )
                    if broker_id == "kis":
                        response_dict = (
                            dict(broker_response)
                            if isinstance(broker_response, dict)
                            else {}
                        )
                        response_account_binding = (
                            response_dict.get("kisOrderAccountBinding")
                        )
                        current_account_binding = (
                            _normalize_kis_order_account_binding(
                                _kis_environment_order_account_binding()
                            )
                        )
                        normalized_account_binding = (
                            _normalize_kis_order_account_binding(
                                {
                                    **(
                                        response_account_binding
                                        if isinstance(
                                            response_account_binding, dict
                                        )
                                        else {}
                                    ),
                                    "environmentRevision": str(
                                        current_account_binding.get(
                                            "environmentRevision"
                                        )
                                        or ""
                                    ),
                                }
                            )
                        )
                        if (
                            not normalized_account_binding
                            or not current_account_binding
                            or not _kis_order_account_binding_matches(
                                normalized_account_binding,
                                current_account_binding,
                            )
                        ):
                            # A socket may already have crossed, so the only
                            # safe outcome is UNKNOWN.  Never synthesize an
                            # account binding after leaving this final lock.
                            broker_response = {
                                **(
                                    response_dict
                                ),
                                "ok": False,
                                "outcomeAmbiguous": True,
                                "physicalAttemptCount": max(
                                    1,
                                    int(
                                        safe_float(
                                            (
                                                response_dict
                                            ).get("physicalAttemptCount"),
                                            0.0,
                                        )
                                    ),
                                ),
                                "retryAllowed": False,
                                "accountBindingError": (
                                    "kis-order-ack-account-binding-missing-"
                                    "or-changed"
                                ),
                            }
                        else:
                            order["kis_order_account_binding"] = dict(
                                normalized_account_binding
                            )
        if not isinstance(broker_response, dict):
            broker_response = {}
        order["broker_response"] = broker_response
        response_ok = broker_response.get("ok") is True
        response_payload = (
            broker_response.get("json")
            if isinstance(broker_response.get("json"), dict)
            else {}
        )
        broker_order_id = str(
            response_payload.get("uuid")
            or response_payload.get("orderId")
            or response_payload.get("clientOrderId")
            or (response_payload.get("output") or {}).get("ODNO")
            or ""
        )
        if response_ok and broker_order_id:
            kis_ack_identity: dict[str, str] = {}
            if broker_id == "kis":
                output = (
                    response_payload.get("output")
                    if isinstance(response_payload.get("output"), dict)
                    else {}
                )
                order_date = str(
                    output.get("ORD_DT")
                    or output.get("ORD_DATE")
                    or datetime.now(timezone(timedelta(hours=9))).strftime(
                        "%Y%m%d"
                    )
                ).strip()
                organization_no = str(
                    output.get("KRX_FWDG_ORD_ORGNO")
                    or output.get("KRX_FWDG_ORD_ORG_NO")
                    or ""
                ).strip().upper()
                broker_order_key = (
                    f"{order_date}:{organization_no}:{broker_order_id}"
                    if len(order_date) == 8
                    and order_date.isdigit()
                    and organization_no
                    else ""
                )
                kis_ack_identity = {
                    "order_date": order_date,
                    "organization_no": organization_no,
                    "broker_order_key": broker_order_key,
                }
            LIVE_OMS.acknowledge(
                managed_order.order_id,
                broker_order_id,
            )
            order.update(
                {
                    "state": "acknowledged",
                    "queue_state": "submitted",
                    "broker_order_id": broker_order_id,
                    **kis_ack_identity,
                    "reason": "broker-acknowledged",
                    "next_retry_at": "-",
                }
            )
            reason = "broker-acknowledged"
            ok = True
            DECISION_TRACE_STORE.append(
                trace_id=trace_id,
                stage="BROKER_ACKNOWLEDGED",
                decision="ACKNOWLEDGED",
                output_payload={
                    "brokerId": broker_id,
                    "brokerOrderId": broker_order_id,
                    **(
                        {"brokerOrderKey": kis_ack_identity.get("broker_order_key")}
                        if kis_ack_identity
                        else {}
                    ),
                },
            )
        elif response_ok:
            reason = "broker-response-missing-order-id"
            LIVE_OMS.mark_unknown(
                managed_order.order_id,
                "broker response missing order id",
            )
            order.update(
                {
                    "state": "unknown",
                    "queue_state": "reconcile_required",
                    "reason": reason,
                    "next_retry_at": "-",
                }
            )
            ok = False
            DECISION_TRACE_STORE.append(
                trace_id=trace_id,
                stage="BLOCKED",
                decision="UNKNOWN",
                reasons=(reason,),
                output_payload={"brokerId": broker_id},
            )
        elif (
            broker_response.get("outcomeAmbiguous") is True
            or int(
                safe_float(
                    broker_response.get("physicalAttemptCount"), 0.0
                )
            )
            > 0
        ):
            reason = "broker-dispatch-outcome-ambiguous"
            LIVE_OMS.mark_unknown(
                managed_order.order_id,
                "broker dispatch may have crossed; reconcile before retry",
            )
            order.update(
                {
                    "state": "unknown",
                    "queue_state": "reconcile_required",
                    "reason": reason,
                    "broker_outcome_ambiguous": True,
                    "physical_attempt_count": int(
                        safe_float(
                            broker_response.get("physicalAttemptCount"),
                            0.0,
                        )
                    ),
                    "next_retry_at": "-",
                }
            )
            ok = False
            DECISION_TRACE_STORE.append(
                trace_id=trace_id,
                stage="BLOCKED",
                decision="UNKNOWN",
                reasons=(reason,),
                output_payload={
                    "brokerId": broker_id,
                    "outcomeAmbiguous": True,
                    "physicalAttemptCount": order[
                        "physical_attempt_count"
                    ],
                },
            )
        elif int(
            safe_float(broker_response.get("statusCode"), 0.0)
        ) == 0:
            reason = "network-outcome-unknown"
            LIVE_OMS.mark_unknown(
                managed_order.order_id,
                "network outcome unknown; reconcile before retry",
            )
            order.update(
                {
                    "state": "unknown",
                    "queue_state": "reconcile_required",
                    "reason": reason,
                    "next_retry_at": "-",
                }
            )
            ok = False
            DECISION_TRACE_STORE.append(
                trace_id=trace_id,
                stage="BLOCKED",
                decision="UNKNOWN",
                reasons=(reason,),
                output_payload={"brokerId": broker_id},
            )
        else:
            reason = str(
                broker_response.get("text") or "broker-rejected"
            )[:500]
            LIVE_OMS.transition(
                managed_order.order_id,
                "REJECTED",
                "broker rejected request",
                {"response": broker_response},
            )
            order.update(
                {
                    "state": "broker_rejected",
                    "queue_state": "failed",
                    "reason": reason,
                    "next_retry_at": "-",
                }
            )
            ok = False
            DECISION_TRACE_STORE.append(
                trace_id=trace_id,
                stage="BLOCKED",
                decision="BROKER_REJECTED",
                reasons=(reason,),
                output_payload={"brokerId": broker_id},
            )
    except BrokerNotReadyError as exc:
        reason = str(exc)
        LIVE_OMS.transition(managed_order.order_id, "REJECTED", reason)
        order.update(
            {
                "state": "adapter_blocked",
                "queue_state": "failed",
                "reason": reason,
                "next_retry_at": "-",
            }
        )
        ok = False
        DECISION_TRACE_STORE.append(
            trace_id=trace_id,
            stage="BLOCKED",
            decision="ADAPTER_BLOCKED",
            reasons=(reason,),
            output_payload={"brokerId": broker_id},
        )
    except Exception as exc:
        # The broker may have accepted the request before the local exception.
        # Never retry this idempotency key until broker reconciliation resolves
        # the durable pending record.
        reason = "broker-dispatch-outcome-unknown"
        LIVE_OMS.mark_unknown(managed_order.order_id, reason)
        order.update(
            {
                "state": "unknown",
                "queue_state": "reconcile_required",
                "reason": reason,
                "dispatch_error_type": type(exc).__name__,
                "next_retry_at": "-",
            }
        )
        ok = False
        DECISION_TRACE_STORE.append(
            trace_id=trace_id,
            stage="BLOCKED",
            decision="UNKNOWN",
            reasons=(reason,),
            output_payload={"brokerId": broker_id},
        )
    finally:
        order["updated_at"] = now_text()
        try:
            terminal_saved = PROGRAM_LEDGER.update_order_dispatch(order)
        except (OSError, sqlite3.Error, ValueError):
            terminal_saved = False
        if not terminal_saved:
            STATE["new_entries_blocked"] = True
            order.update(
                {
                    "state": "unknown",
                    "queue_state": "reconcile_required",
                    "reason": "dispatch-terminal-checkpoint-failed",
                }
            )
            ok = False
            reason = "dispatch-terminal-checkpoint-failed"
        if functional_test_execution_requested(intent) and isinstance(
            order.get("functional_test_reservation"),
            dict,
        ):
            try:
                PROGRAM_LEDGER.update_functional_test_reservation(
                    str(order.get("idempotency_key") or ""),
                    str(order.get("state") or "UNKNOWN"),
                )
            except (OSError, sqlite3.Error, TypeError, ValueError):
                # The slot was consumed by the atomic INSERT and is never
                # deleted; an outcome-label failure cannot restore capacity.
                pass
        order["oms_status"] = LIVE_OMS.orders[
            managed_order.order_id
        ].status
    return ok, reason


def submit_order_intent(
    checks: dict[str, Any],
    intent: OrderIntent,
    *,
    dry_run: bool,
    audit_event: str,
    runner_report: StrategyExecutionResult | None = None,
) -> dict[str, Any]:
    if not dry_run and _runtime_mode_lock_owned():
        metadata = (
            dict(intent.metadata)
            if isinstance(intent.metadata, dict)
            else {}
        )
        broker_id = str(
            metadata.get("broker_id")
            or broker_id_from_symbol(intent.symbol, intent.asset)
        ).strip().lower()
        return {
            "ok": False,
            "reason": (
                "CONTINUOUS_FINAL_DISPATCH_LOCK_ORDER_UNAVAILABLE:"
                + broker_id
            ),
            "order": {},
            "runtimeDispatchDisabled": True,
        }
    metadata = dict(intent.metadata) if isinstance(intent.metadata, dict) else {}
    bar_time = str(metadata.get("confirmed_bar_end") or datetime.now(timezone.utc).isoformat())
    try:
        trace_revision = int(metadata.get("target_revision") or 0)
    except (TypeError, ValueError, OverflowError):
        trace_revision = 0
    trace_id = str(metadata.get("trace_id") or metadata.get("traceId") or build_trace_id(
        strategy_instance_id=str(metadata.get("strategy_instance_id") or intent.strategy_id),
        instrument_id=str(metadata.get("instrument_id") or intent.symbol),
        bar_time=bar_time,
        deployment_id=str(metadata.get("portfolio_id") or "live-trader"),
        revision=trace_revision,
    ))
    metadata.update({"trace_id": trace_id, "traceId": trace_id})
    broker_id = str(
        metadata.get("broker_id")
        or broker_id_from_symbol(intent.symbol, intent.asset)
    ).strip().lower()
    claimed_risk_reducing = metadata.get("risk_reducing") is True
    candidate_intent = replace(intent, metadata=dict(metadata))
    verified_risk_reducing = futures_risk_reducing_verified(
        checks,
        candidate_intent,
    )
    metadata["risk_reducing"] = verified_risk_reducing
    if claimed_risk_reducing and not verified_risk_reducing:
        metadata["risk_reducing_claim_rejected"] = True
    else:
        metadata.pop("risk_reducing_claim_rejected", None)
    intent = replace(intent, metadata=metadata)
    canary_scope_required = (
        not dry_run
        and intent.mode == "SMALL_LIVE"
        and not functional_test_execution_requested(intent)
    )
    canary_scope: dict[str, Any] = {}
    if canary_scope_required:
        try:
            resolved_canary_scope = current_live_canary_scope(
                intent.strategy_id,
                materialize=True,
            )
            canary_scope = (
                dict(resolved_canary_scope)
                if isinstance(resolved_canary_scope, dict)
                else {
                    "schemaVersion": CANARY_SCOPE_SCHEMA_VERSION,
                    "eligible": False,
                    "issues": ["scope-response-type-invalid"],
                }
            )
        except Exception as exc:
            # The broker edge must fail closed while still leaving a durable,
            # redacted reason in the order/audit trail.  The observed failure
            # remains attached to this order; successful observations are
            # deliberately re-read at both dispatch boundaries and must match
            # this exact scope.
            canary_scope = {
                "schemaVersion": CANARY_SCOPE_SCHEMA_VERSION,
                "eligible": False,
                "issues": [f"scope-load-error:{type(exc).__name__}"],
            }
    canary_scope_failure_reason = ""
    if canary_scope_required and canary_scope.get("eligible") is not True:
        scope_issues = [
            str(item).strip()
            for item in canary_scope.get("issues") or []
            if str(item).strip()
        ]
        if not canary_scope:
            canary_scope_failure_reason = "live-canary-scope-missing"
        else:
            canary_scope_failure_reason = (
                "live-canary-scope-invalid:"
                + ",".join(scope_issues[:5] or ["eligible=false"])
            )
    if broker_id == "binance-futures":
        metadata["capital_rollout"] = futures_capital_rollout_for_intent(
            checks,
            intent,
        )
    intent = replace(intent, metadata=metadata)
    functional_preflight_refresh_allowed = True
    functional_preflight_refresh_reason = (
        "functional-test-preflight-not-required"
    )
    functional_preflight_refresh_report: dict[str, Any] = {}
    claimed_functional_session = str(
        metadata.get("functional_test_session_id")
        or metadata.get("functionalTestSessionId")
        or ""
    ).strip()
    if (
        functional_test_execution_requested(intent)
        and not dry_run
        and claimed_functional_session
    ):
        (
            functional_preflight_refresh_allowed,
            functional_preflight_refresh_reason,
            functional_preflight_refresh_report,
        ) = refresh_functional_test_runtime_preflight(intent)
    RECOVERY_JOURNAL.save(recovery_state_payload(), reason="before-order", idempotency_keys=[str(item.get("idempotency_key") or "") for item in STATE.get("orders", [])])
    ok, order_state, queue_state, reason, risk_report = evaluate_order_gate_with_report(checks, intent.side, dry_run, intent)
    functional_test_report: dict[str, Any] = {}
    if functional_test_execution_requested(intent):
        try:
            functional_report, document_errors = (
                functional_test_safety_report_for_intent(
                    checks,
                    intent,
                    phase="PRETRADE",
                )
            )
            functional_reason = _functional_test_report_reason(
                functional_report,
                document_errors,
            )
            functional_allowed = (
                functional_report.allowed and not document_errors
            )
            functional_test_report = functional_report.to_dict()
            functional_test_report["documentErrors"] = list(document_errors)
        except Exception as exc:
            functional_allowed = False
            functional_reason = (
                f"functional-test-pretrade-error:{type(exc).__name__}"
            )
            functional_test_report = {
                "schemaVersion": "live-functional-test-safety-report-v1",
                "phase": "PRETRADE",
                "allowed": False,
                "blockerCodes": [functional_reason],
                "promotionEligible": False,
                "fullLiveAllowed": False,
            }
        risk_report = PreTradeRiskReport(
            risk_report.checked_at,
            (
                *risk_report.checks,
                RiskCheck(
                    "Functional Test Permit",
                    "pass" if functional_allowed else "fail",
                    functional_reason,
                ),
            ),
        )
        if not functional_allowed:
            ok = False
            order_state = "risk_blocked"
            queue_state = "blocked"
            reason = functional_reason
        if claimed_functional_session:
            risk_report = PreTradeRiskReport(
                risk_report.checked_at,
                (
                    *risk_report.checks,
                    RiskCheck(
                        "Functional Test Runtime Preflight",
                        (
                            "pass"
                            if functional_preflight_refresh_allowed
                            else "fail"
                        ),
                        functional_preflight_refresh_reason,
                    ),
                ),
            )
            if not functional_preflight_refresh_allowed:
                ok = False
                order_state = "risk_blocked"
                queue_state = "blocked"
                reason = functional_preflight_refresh_reason
    if canary_scope_failure_reason:
        risk_report = PreTradeRiskReport(
            risk_report.checked_at,
            (
                *risk_report.checks,
                RiskCheck(
                    "Live Canary Scope",
                    "fail",
                    canary_scope_failure_reason,
                ),
            ),
        )
        if ok:
            ok = False
            order_state = "risk_blocked"
            queue_state = "blocked"
            reason = canary_scope_failure_reason
    portfolio_gate = portfolio_gate_for_intent(checks, intent)
    retry_backoff = float(STATE["retry_policy"]["backoff_sec"])
    target_revision = stable_target_revision(
        metadata,
        trace_id=trace_id,
        bar_time=bar_time,
        intent=intent,
    )
    idempotency_key = build_idempotency_key(
        portfolio_id=str(metadata.get("portfolio_id") or portfolio_gate.get("portfolio_id") or "default-portfolio"),
        strategy_instance_id=str(metadata.get("strategy_instance_id") or intent.strategy_id),
        instrument_id=str(metadata.get("instrument_id") or intent.symbol),
        target_revision=target_revision,
        purpose=str(metadata.get("order_purpose") or "REBALANCE"),
    )
    if idempotency_key in set(STATE.get("persisted_idempotency_keys", [])):
        existing = next((item for item in STATE.get("orders", []) if item.get("idempotency_key") == idempotency_key), None)
        DECISION_TRACE_STORE.append(
            trace_id=trace_id,
            stage="BLOCKED",
            decision="DUPLICATE",
            reasons=("persistent-duplicate-idempotency-key",),
            output_payload={"idempotencyKey": idempotency_key},
        )
        append_audit("warn", audit_event, f"재시작 이후 중복 주문 차단: idempotency_key={idempotency_key}")
        return {"ok": False, "reason": "persistent-duplicate-idempotency-key", "order": existing or {}, "duplicate": True, "snapshot": snapshot()}
    dispatch_journal_error = ""
    try:
        durable_existing = PROGRAM_LEDGER.order_dispatch_for_idempotency_key(
            idempotency_key
        )
    except (OSError, sqlite3.Error, ValueError) as exc:
        durable_existing = None
        dispatch_journal_error = f"{type(exc).__name__}:{str(exc)[:200]}"
    if durable_existing is not None:
        DECISION_TRACE_STORE.append(
            trace_id=trace_id,
            stage="BLOCKED",
            decision="DUPLICATE",
            reasons=("durable-dispatch-idempotency-key-exists",),
            output_payload={"idempotencyKey": idempotency_key},
        )
        append_audit(
            "warn",
            audit_event,
            (
                "영속 dispatch journal 중복 주문 차단: "
                f"idempotency_key={idempotency_key}"
            ),
        )
        return {
            "ok": False,
            "reason": "durable-dispatch-idempotency-key-exists",
            "order": durable_existing,
            "duplicate": True,
            "snapshot": snapshot(),
        }
    dispatch_allowed, dispatch_invariant_reason = live_broker_dispatch_allowed(
        intent,
        dry_run=dry_run,
    )
    if not dry_run and not dispatch_allowed and ok:
        if not any(
            check.label == "Intent 실행 환경"
            for check in risk_report.checks
        ):
            risk_report = PreTradeRiskReport(
                risk_report.checked_at,
                (
                    *risk_report.checks,
                    RiskCheck(
                        "Intent 실행 환경",
                        "fail",
                        dispatch_invariant_reason,
                    ),
                ),
            )
        ok = False
        order_state = "risk_blocked"
        queue_state = "blocked"
        reason = dispatch_invariant_reason
    if not dry_run and dispatch_journal_error:
        risk_report = PreTradeRiskReport(
            risk_report.checked_at,
            (
                *risk_report.checks,
                RiskCheck(
                    "Dispatch Journal",
                    "fail",
                    (
                        "durable-dispatch-journal-unavailable: "
                        f"{dispatch_journal_error}"
                    ),
                ),
            ),
        )
        ok = False
        order_state = "adapter_blocked"
        queue_state = "held"
        reason = "durable-dispatch-journal-unavailable"
    managed_order, oms_created = LIVE_OMS.create(intent, idempotency_key)
    if not oms_created:
        existing = next((item for item in STATE.get("orders", []) if item.get("oms_order_id") == managed_order.order_id), None)
        append_audit("warn", audit_event, f"중복 주문 차단: idempotency_key={idempotency_key}")
        return {"ok": False, "reason": "duplicate-idempotency-key", "order": existing or {}, "duplicate": True, "snapshot": snapshot()}
    DECISION_TRACE_STORE.append(
        trace_id=trace_id,
        stage="BAR_CLOSED",
        decision="EVALUATE",
        input_payload={"barTime": bar_time, "symbol": intent.symbol, "referencePrice": intent.reference_price},
        occurred_at=bar_time,
    )
    DECISION_TRACE_STORE.append(
        trace_id=trace_id,
        stage="SIGNAL_DECIDED",
        decision=intent.side,
        reasons=(intent.reason,),
        input_payload={"strategyId": intent.strategy_id},
        output_payload=runner_report.to_dict() if runner_report is not None else {"intent": intent.side},
        occurred_at=bar_time,
    )
    DECISION_TRACE_STORE.append(
        trace_id=trace_id,
        stage="TARGET_ALLOCATED",
        decision="ALLOCATE",
        output_payload={"quantity": intent.quantity, "notional": intent.notional, "portfolioGate": portfolio_gate},
    )
    if oms_created:
        if ok:
            LIVE_OMS.transition(managed_order.order_id, "RISK_APPROVED", "PreTradeRiskGate passed")
        else:
            LIVE_OMS.transition(managed_order.order_id, "REJECTED", reason)
    order = {
        "time": now_text(),
        "created_at": now_text(),
        "updated_at": now_text(),
        "order_id": next_order_id(order_state, dry_run),
        "oms_order_id": managed_order.order_id,
        "idempotency_key": idempotency_key,
        "idempotency_duplicate": not oms_created,
        "oms_status": managed_order.status,
        "strategy_id": intent.strategy_id,
        "symbol": intent.symbol,
        "asset": intent.asset,
        "side": intent.side,
        "qty": f"{intent.quantity:g}",
        "reference_price": f"{intent.reference_price:g}",
        "notional": f"{intent.notional:,.0f}",
        "state": order_state,
        "queue_state": queue_state,
        "attempts": 1,
        "next_retry_at": future_text(retry_backoff) if order_state in {"risk_blocked", "adapter_blocked"} else "-",
        "broker_order_id": "-",
        "broker_id": broker_id,
        "dry_run": dry_run,
        "mode": intent.mode,
        "canary_scope": canary_scope if canary_scope_required else {},
        "canary_scope_error": canary_scope_failure_reason,
        "reason": reason,
        "trace_id": trace_id,
        "risk_report": risk_report.to_dict(),
        "portfolio_gate": portfolio_gate if portfolio_gate.get("active") else {},
        "capital_rollout": (
            metadata.get("capital_rollout")
            if isinstance(metadata.get("capital_rollout"), dict)
            else {}
        ),
    }
    if isinstance(metadata.get("portfolio_execution"), dict):
        # Preserve the non-secret sleeve allocation plan in both the durable
        # dispatch journal and recovery journal.  This allows an ACK received
        # immediately before a process crash to be attributed after restart.
        order["portfolio_execution"] = dict(
            metadata["portfolio_execution"]
        )
    if functional_test_execution_requested(intent):
        order.update(
            {
                "execution_purpose": FUNCTIONAL_TEST_EXECUTION_PURPOSE,
                "promotion_eligible": False,
                "functional_test": functional_test_report,
                "functional_test_preflight_refresh": (
                    functional_preflight_refresh_report
                    if claimed_functional_session
                    else {}
                ),
            }
        )
    if runner_report is not None:
        order["runner_report"] = runner_report.to_dict()
    DECISION_TRACE_STORE.append(
        trace_id=trace_id,
        stage="RISK_DECIDED",
        decision="ALLOW" if ok else "BLOCK",
        reasons=(reason,),
        output_payload=risk_report.to_dict(),
    )
    DECISION_TRACE_STORE.append(
        trace_id=trace_id,
        stage="ORDER_CREATED" if ok else "BLOCKED",
        decision=order_state.upper(),
        reasons=(reason,),
        output_payload={"orderId": order["order_id"], "omsOrderId": order["oms_order_id"]},
    )
    if ok and not dry_run:
        ok, reason = dispatch_live_order_with_checkpoint(
            order,
            intent,
            managed_order,
            trace_id=trace_id,
        )
    order["updated_at"] = now_text()
    try:
        PROGRAM_LEDGER.record_order_gate_event(order)
    except (OSError, sqlite3.Error) as exc:
        append_audit(
            "warn",
            "Rollout evidence",
            f"주문 게이트 evidence 저장 실패: {str(exc)[:240]}",
        )
    STATE["orders"].insert(0, order)
    STATE["orders"] = STATE["orders"][:50]
    trace_index = STATE.setdefault("order_trace_index", {})
    if not isinstance(trace_index, dict):
        trace_index = {}
        STATE["order_trace_index"] = trace_index
    trace_context = {"trace_id": trace_id, "strategy_id": intent.strategy_id}
    for identifier in {
        str(order.get("order_id") or ""),
        str(order.get("oms_order_id") or ""),
        str(order.get("broker_order_id") or ""),
        str(order.get("idempotency_key") or ""),
    } - {""}:
        trace_index[identifier] = trace_context
    while len(trace_index) > 5000:
        trace_index.pop(next(iter(trace_index)))
    STATE.setdefault("persisted_idempotency_keys", []).append(idempotency_key)
    STATE["persisted_idempotency_keys"] = list(dict.fromkeys(STATE["persisted_idempotency_keys"]))[-5000:]
    checkpoint = RECOVERY_JOURNAL.save(recovery_state_payload(), reason="after-order", idempotency_keys=[str(item.get("idempotency_key") or "") for item in STATE.get("orders", [])])
    STATE["recovery_status"] = {"verified": True, "safeMode": False, "generation": checkpoint["generation"], "detail": "주문 전후 원자적 체크포인트 저장 완료"}
    append_audit(
        "info" if ok else "danger",
        audit_event,
        order_gate_audit_detail(order, reason, risk_report),
        audit_record=order_gate_audit_record(
            source=audit_event,
            intent=intent,
            order=order,
            risk_report=risk_report,
            runner_report=runner_report,
        ),
    )
    if not dry_run and order.get("broker_id"):
        state_name = str(order.get("state") or "").lower()
        if state_name == "acknowledged":
            queue_live_order_lifecycle_notification(
                order,
                status="acknowledged",
            )
        elif state_name in {"broker_rejected", "adapter_blocked", "unknown"}:
            queue_live_order_lifecycle_notification(
                order,
                status="rejected" if state_name == "broker_rejected" else "error",
                reason=str(order.get("reason") or reason),
                message_final=True,
            )
    return {"ok": ok, "reason": reason, "order": order, "snapshot": snapshot()}


def _functional_test_member(
    strategy: dict[str, Any],
    *,
    strategy_instance_id: str,
    symbol: str,
    market_group: str = "",
) -> dict[str, Any]:
    """Seal one current KIS sleeve and its minimum verification pins."""

    strategy_id = str(strategy.get("strategy_id") or "").strip()
    instance_id = str(strategy_instance_id or "").strip()
    us_live = str(market_group or "").strip().upper() == "US_STOCK"
    route = _functional_test_us_strategy_route(strategy) if us_live else {}
    normalized_symbol = (
        canonical_kis_us_symbol(symbol)
        if us_live
        else canonical_kis_domestic_symbol(symbol)
    )
    reference = verified_strategy_artifact_reference(strategy)
    lifecycle = normalize_lifecycle_status(strategy.get("lifecycle_status"))
    blockers: list[str] = []
    if not strategy_id:
        blockers.append("strategy-id-missing")
    if not instance_id:
        blockers.append("strategy-instance-id-missing")
    if not normalized_symbol:
        blockers.append(
            "kis-us-symbol-required" if us_live else "kis-domestic-symbol-required"
        )
    if us_live and normalized_symbol != str(route.get("symbol") or ""):
        blockers.append("functional-test-us-symbol-route-mismatch")
    if strategy_broker_id(strategy) != "kis":
        blockers.append("kis-broker-route-required")
    if not reference:
        blockers.append("verified-strategy-artifact-reference-required")
    if lifecycle in {"paused", "retired"}:
        blockers.append(f"strategy-lifecycle-{lifecycle}")
    if strategy.get("backtester_verified") is not True:
        blockers.append("backtester-verification-pin-required")
    if strategy.get("paper_trader_verified") is not True:
        blockers.append("paper-functional-verification-pin-required")
    if blockers:
        raise ValueError(
            f"FUNCTIONAL_TEST Strategy sleeve {strategy_id or '-'} 차단: "
            + ", ".join(blockers)
        )
    verification = (
        strategy.get("verification")
        if isinstance(strategy.get("verification"), dict)
        else {}
    )
    result = {
        "strategyId": strategy_id,
        "strategyInstanceId": instance_id,
        "symbol": normalized_symbol,
        "brokerId": "kis",
        "artifactId": str(reference.get("artifactId") or ""),
        "artifactHash": str(reference.get("artifactHash") or "").lower(),
        "artifactContentHash": str(reference.get("contentHash") or "").lower(),
        "lifecycle": lifecycle,
        "backtesterVerified": True,
        "paperTraderVerified": True,
        "minimumVerificationHash": governance_sha256(
            {
                "strategyArtifact": reference,
                "backtester": verification.get("backtester", {}),
                "paperTrader": verification.get("paper_trader", {}),
            }
        ),
    }
    if us_live:
        result.update(
            {
                "marketGroup": "US_STOCK",
                "executionRoute": "KIS_US_LIVE_CONTINUOUS",
                "settlementCurrency": "USD",
                "exchange": "NYSE",
                "timeframe": "5m",
            }
        )
    return result


def _functional_test_runtime_scope(
    *,
    portfolio_id: str,
    strategy_id: str,
    permit: Any,
) -> dict[str, Any]:
    """Resolve current catalog truth for a sealed functional runtime."""

    requested_portfolio = str(portfolio_id or "").strip()
    requested_strategy = str(strategy_id or "").strip()
    binding = permit.binding.snapshot()
    market_group = str(binding.get("marketGroup") or "").strip().upper()
    us_live = market_group == "US_STOCK"
    if str(binding.get("accountId") or "") != kis_functional_test_account_id():
        raise ValueError("FUNCTIONAL_TEST permit account binding이 현재 KIS 계좌와 다릅니다.")
    if us_live and (
        binding.get("portfolioRequired") is True or requested_portfolio
    ):
        raise ValueError("functional-test-us-live-strategy-only")

    portfolios = portfolio_rows()
    strategies = strategy_rows(portfolios)
    portfolio: dict[str, Any] = {}
    members: list[dict[str, Any]] = []
    current_binding: dict[str, Any]
    lead_strategy: dict[str, Any] | None = None
    portfolio_reference: dict[str, str] = {}

    if binding.get("portfolioRequired") is True:
        if not requested_portfolio:
            raise ValueError("Portfolio FUNCTIONAL_TEST에는 portfolio_id가 필요합니다.")
        portfolio = next(
            (
                item
                for item in portfolios
                if str(
                    item.get("id")
                    or item.get("portfolio_id")
                    or (item.get("artifact_reference") or {}).get("artifactId")
                    or ""
                ).strip()
                == requested_portfolio
            ),
            {},
        )
        if not portfolio:
            raise ValueError("현재 Portfolio Artifact를 찾을 수 없습니다.")
        portfolio_reference = verified_portfolio_artifact_reference(portfolio)
        if not portfolio_reference:
            raise ValueError("검증된 Portfolio Artifact reference가 필요합니다.")
        raw_instances = portfolio.get("strategy_instances")
        instances = raw_instances if isinstance(raw_instances, list) else []
        if not instances:
            raise ValueError("Portfolio에 실행 가능한 Strategy Instance가 없습니다.")
        for instance in instances:
            if not isinstance(instance, dict):
                raise ValueError("Portfolio Strategy Instance 형식이 올바르지 않습니다.")
            member_strategy_id = str(
                instance.get("sourceStrategyId")
                or instance.get("strategyId")
                or instance.get("strategy_id")
                or ""
            ).strip()
            member_instance_id = str(
                instance.get("instanceId")
                or instance.get("strategyInstanceId")
                or ""
            ).strip()
            member_symbol = canonical_kis_domestic_symbol(
                instance.get("executionInstrument")
                or instance.get("instrumentId")
                or instance.get("qualifiedSymbol")
                or instance.get("symbol")
                or ""
            )
            source_hash = str(instance.get("sourceArtifactHash") or "").lower()
            candidates = [
                item
                for item in strategies
                if str(item.get("strategy_id") or "") == member_strategy_id
            ]
            if source_hash:
                candidates = [
                    item
                    for item in candidates
                    if str(
                        (item.get("artifact_reference") or {}).get("artifactHash")
                        or item.get("artifact_hash")
                        or ""
                    ).lower()
                    == source_hash
                ]
            member_strategy = candidates[0] if candidates else None
            if member_strategy is None:
                raise ValueError(
                    f"Portfolio sleeve {member_strategy_id or '-'}의 현재 Strategy Artifact가 없습니다."
                )
            member = _functional_test_member(
                member_strategy,
                strategy_instance_id=member_instance_id,
                symbol=member_symbol,
                market_group=market_group,
            )
            members.append(member)
            if member_strategy_id == requested_strategy:
                lead_strategy = member_strategy
        if lead_strategy is None:
            raise ValueError("요청한 lead Strategy가 Portfolio 구성에 없습니다.")
        raw_targets = portfolio.get("target_portfolio")
        targets = raw_targets if isinstance(raw_targets, list) else []
        symbols = {
            canonical_kis_domestic_symbol(
                item.get("executionInstrument")
                or item.get("instrumentId")
                or item.get("qualifiedSymbol")
                or item.get("symbol")
                or ""
            )
            for item in [*instances, *targets]
            if isinstance(item, dict)
        }
        symbols.discard("")
        portfolio_artifact_id = str(
            portfolio_reference.get("artifactId") or requested_portfolio
        )
        portfolio_artifact_hash = str(
            portfolio_reference.get("artifactHash") or ""
        ).lower()
        current_binding = {
            "strategyArtifactId": "",
            "strategyArtifactHash": "",
            "strategyInstanceId": "",
            "portfolioRequired": True,
            "portfolioArtifactId": portfolio_artifact_id,
            "portfolioArtifactHash": portfolio_artifact_hash,
            "portfolioInstanceId": (
                f"functional-portfolio:{portfolio_artifact_id}:"
                f"{portfolio_artifact_hash[:12]}"
            ),
            "accountId": kis_functional_test_account_id(),
            "symbols": sorted(symbols),
        }
    else:
        if requested_portfolio:
            raise ValueError("Standalone FUNCTIONAL_TEST에는 portfolio_id가 없어야 합니다.")
        lead_strategy = next(
            (
                item
                for item in strategies
                if str(item.get("strategy_id") or "") == requested_strategy
            ),
            None,
        )
        if lead_strategy is None:
            raise ValueError("현재 standalone Strategy Artifact를 찾을 수 없습니다.")
        reference = verified_strategy_artifact_reference(lead_strategy)
        strategy_instance_id = str(
            lead_strategy.get("strategy_instance_id")
            or lead_strategy.get("instance_id")
            or f"standalone:{requested_strategy}"
        ).strip()
        route = _functional_test_us_strategy_route(lead_strategy) if us_live else {}
        symbol = (
            canonical_kis_us_symbol(
                lead_strategy.get("execution_instrument")
                or lead_strategy.get("instrument_id")
                or lead_strategy.get("symbol")
                or ""
            )
            if us_live
            else canonical_kis_domestic_symbol(
                lead_strategy.get("execution_instrument")
                or lead_strategy.get("instrument_id")
                or lead_strategy.get("symbol")
                or ""
            )
        )
        members.append(
            _functional_test_member(
                lead_strategy,
                strategy_instance_id=strategy_instance_id,
                symbol=symbol,
                market_group=market_group,
            )
        )
        if us_live:
            current_binding = FunctionalTestBinding(
                strategy_artifact_id=str(reference.get("artifactId") or ""),
                strategy_artifact_hash=str(
                    reference.get("artifactHash") or ""
                ).lower(),
                strategy_instance_id=strategy_instance_id,
                portfolio_required=False,
                portfolio_artifact_id="",
                portfolio_artifact_hash="",
                portfolio_instance_id="",
                account_id=kis_functional_test_account_id(),
                symbols=(symbol,),
                market_group=str(route.get("marketGroup") or ""),
                execution_route=str(route.get("executionRoute") or ""),
                settlement_currency=str(route.get("settlementCurrency") or ""),
                exchanges=tuple(route.get("exchanges") or ()),
                symbol_routes=tuple(route.get("symbolRoutes") or ()),
            ).snapshot()
        else:
            current_binding = {
                "strategyArtifactId": str(reference.get("artifactId") or ""),
                "strategyArtifactHash": str(reference.get("artifactHash") or "").lower(),
                "strategyInstanceId": strategy_instance_id,
                "portfolioRequired": False,
                "portfolioArtifactId": "",
                "portfolioArtifactHash": "",
                "portfolioInstanceId": "",
                "accountId": kis_functional_test_account_id(),
                "symbols": [symbol],
            }

    if current_binding != binding:
        raise ValueError("FUNCTIONAL_TEST permit의 exact Artifact/Instance/계좌/종목 binding이 변경되었습니다.")
    unique_member_keys = {
        (
            str(item.get("strategyId") or ""),
            str(item.get("strategyInstanceId") or ""),
            str(item.get("symbol") or ""),
        )
        for item in members
    }
    if len(unique_member_keys) != len(members):
        raise ValueError("FUNCTIONAL_TEST Portfolio sleeve identity가 중복되었습니다.")
    members = sorted(
        members,
        key=lambda item: (
            str(item.get("strategyId") or ""),
            str(item.get("strategyInstanceId") or ""),
            str(item.get("symbol") or ""),
        ),
    )
    return {
        "leadStrategy": lead_strategy,
        "portfolio": portfolio,
        "portfolioId": requested_portfolio,
        "portfolioArtifact": portfolio_reference,
        "strategyMembers": members,
        "strategyMemberHash": governance_sha256(members),
        "allowedSymbols": sorted(str(item) for item in binding.get("symbols") or []),
        "binding": dict(binding),
        "bindingHash": governance_sha256(binding),
        "accountFingerprint": governance_sha256(
            {"functionalTestAccount": str(binding.get("accountId") or "")}
        ),
        "runtimeDeploymentId": str(
            (lead_strategy or {}).get("deployment_id") or ""
        ),
    }


def _functional_test_manifest_values(
    scope: dict[str, Any],
    permit: Any,
    activation: Any,
    *,
    preflight_ttl_seconds: int,
) -> dict[str, Any]:
    members = [
        dict(item)
        for item in scope.get("strategyMembers", [])
        if isinstance(item, dict)
    ]
    risk_policy_revision = max(
        1,
        int(STATE.get("risk_policy_revision") or 1),
    )
    risk_policy_hash = governance_sha256(
        {
            "settings": STATE.get("risk_settings", {}),
            "policyRevision": risk_policy_revision,
            "functionalCaps": permit.caps.snapshot(),
            "smallLiveProfile": {
                "maximumOrderPct": ENVIRONMENT_PROFILES[
                    "SMALL_LIVE"
                ].maximum_order_pct,
                "maximumStrategyCapitalPct": ENVIRONMENT_PROFILES[
                    "SMALL_LIVE"
                ].maximum_strategy_capital_pct,
                "dailyLossLimitPct": ENVIRONMENT_PROFILES[
                    "SMALL_LIVE"
                ].daily_loss_limit_pct,
                "marketOrdersAllowed": ENVIRONMENT_PROFILES[
                    "SMALL_LIVE"
                ].market_orders_allowed,
            },
        }
    )
    config_revision = max(1, int(STATE.get("config_revision") or 1))
    metadata = {
        "executionPurpose": FUNCTIONAL_TEST_EXECUTION_PURPOSE,
        "evidenceClass": "FUNCTIONAL_TEST_NON_PROMOTION",
        "promotionEligible": False,
        "fullLiveAllowed": False,
        "environment": FUNCTIONAL_TEST_ENVIRONMENT,
        "permitId": permit.permit_id,
        "permitHash": permit.content_hash,
        "permitEndsAt": permit.ends_at.isoformat(),
        "activationTokenId": activation.token_id,
        "activationHash": activation.content_hash,
        "activationExpiresAt": activation.expires_at.isoformat(),
        "bindingHash": str(scope.get("bindingHash") or ""),
        "accountFingerprint": str(scope.get("accountFingerprint") or ""),
        "portfolioId": str(scope.get("portfolioId") or ""),
        "portfolioArtifact": dict(
            scope.get("portfolioArtifact")
            if isinstance(scope.get("portfolioArtifact"), dict)
            else {}
        ),
        "strategyId": str(
            (scope.get("leadStrategy") or {}).get("strategy_id")
            if isinstance(scope.get("leadStrategy"), dict)
            else ""
        ),
        "runtimeDeploymentId": str(scope.get("runtimeDeploymentId") or ""),
        "strategyMembers": members,
        "strategyMemberHash": str(scope.get("strategyMemberHash") or ""),
        "allowedSymbols": list(scope.get("allowedSymbols") or []),
        "minimumVerificationPins": [
            {
                "strategyId": str(item.get("strategyId") or ""),
                "strategyInstanceId": str(item.get("strategyInstanceId") or ""),
                "verificationHash": str(item.get("minimumVerificationHash") or ""),
                "backtesterVerified": True,
                "paperTraderVerified": True,
            }
            for item in members
        ],
        "functionalCaps": permit.caps.snapshot(),
    }
    strategy_artifact_hash = (
        str(members[0].get("artifactHash") or "")
        if not scope.get("portfolioId") and len(members) == 1
        else governance_sha256(
            {
                "portfolioId": str(scope.get("portfolioId") or ""),
                "members": members,
            }
        )
    )
    build_hash = governance_sha256(
        {
            "runtime": "live-trader-functional-runtime-v1",
            "adapterContract": broker_adapter_contract(),
        }
    )
    config_hash = governance_sha256(
        {
            "executionPurpose": FUNCTIONAL_TEST_EXECUTION_PURPOSE,
            "permitHash": permit.content_hash,
            "activationHash": activation.content_hash,
            "bindingHash": scope.get("bindingHash"),
            "strategyMemberHash": scope.get("strategyMemberHash"),
            "allowedSymbols": scope.get("allowedSymbols"),
            "accountFingerprint": scope.get("accountFingerprint"),
            "riskPolicyHash": risk_policy_hash,
            "retryPolicy": STATE.get("retry_policy", {}),
            "checklist": STATE.get("checklist", {}),
            "realOrdersEnabled": real_orders_enabled(),
        }
    )
    return {
        "deployment_id": f"functional-test-{permit.permit_id}",
        "strategy_artifact_hash": strategy_artifact_hash,
        "portfolio_artifact_hash": str(
            (scope.get("portfolioArtifact") or {}).get("artifactHash")
            if isinstance(scope.get("portfolioArtifact"), dict)
            else ""
        ),
        "account_fingerprint": str(scope.get("accountFingerprint") or ""),
        "broker_route": "kis",
        "runtime_version": "live-trader-functional-runtime-v1",
        "build_hash": build_hash,
        "execution_adapter": "kis-signed-functional-test-adapter",
        "execution_adapter_version": "v1",
        "risk_policy_revision": risk_policy_revision,
        "risk_policy_hash": risk_policy_hash,
        "config_revision": config_revision,
        "config_hash": config_hash,
        "preflight_ttl_seconds": preflight_ttl_seconds,
        "metadata": metadata,
    }


def _functional_test_utc_datetime(value: object) -> datetime | None:
    """Parse one governance timestamp without falling back to local time."""

    if isinstance(value, datetime):
        parsed = value
    else:
        text = str(value or "").strip()
        if not text:
            return None
        try:
            parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except ValueError:
            return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _functional_test_age_seconds(
    value: object,
    *,
    now: datetime,
) -> float | None:
    parsed = _functional_test_utc_datetime(value)
    if parsed is None:
        return None
    return max(0.0, (now - parsed).total_seconds())


def _functional_test_preflight_evidence(
    scope: dict[str, Any],
    *,
    permit_id: str,
    allow_equity_scope_create: bool = False,
) -> dict[str, Any]:
    """Collect fresh KIS truth and build immutable preflight evidence."""

    lead_strategy = scope.get("leadStrategy")
    if not isinstance(lead_strategy, dict):
        raise ValueError("FUNCTIONAL_TEST lead Strategy를 봉인할 수 없습니다.")
    reconciliation = refresh_preflight_reconciliation(
        lead_strategy,
        maximum_age_seconds=FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS,
    )
    reconciliation_summary = (
        reconciliation.get("summary")
        if isinstance(reconciliation.get("summary"), dict)
        else {}
    )
    broker_row = next(
        (row for row in broker_readiness() if row.broker_id == "kis"),
        None,
    )
    account = broker_account_risk(
        STATE.get("account_risk")
        if isinstance(STATE.get("account_risk"), dict)
        else {},
        "kis",
        currency="KRW",
        maximum_age_seconds=FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS,
    )
    control = durable_control_snapshot()
    safety_blockers: list[str] = []
    equity_scope: dict[str, Any] = {}
    authority_status: dict[str, Any] = {}
    try:
        authority_status = PROGRAM_LEDGER.functional_test_authority_status(
            permit_id=str(permit_id or ""),
            account_fingerprint=str(scope.get("accountFingerprint") or ""),
        )
        if authority_status.get("closed") is True:
            safety_blockers.append("functional-test-authority-closed")
    except (OSError, sqlite3.Error, TypeError, ValueError):
        safety_blockers.append("functional-test-durable-authority-unavailable")
    try:
        current_equity = safe_float(account.get("current_equity"), -1.0)
        observed_at = str(account.get("observed_at") or "").strip()
        if (
            account.get("known") is not True
            or account.get("fresh") is not True
            or current_equity < 0
            or not observed_at
        ):
            raise ValueError("functional-test-equity-observation-unavailable")
        equity_scope = PROGRAM_LEDGER.observe_functional_test_equity(
            permit_id=str(permit_id or ""),
            account_fingerprint=str(scope.get("accountFingerprint") or ""),
            current_equity=current_equity,
            observed_at=observed_at,
            allow_create=allow_equity_scope_create,
        )
    except (OSError, sqlite3.Error, TypeError, ValueError):
        safety_blockers.append("functional-test-equity-scope-unavailable")
    if broker_row is None or not broker_row.order_ready:
        safety_blockers.append("kis-live-order-adapter-not-ready")
    if reconciliation_summary.get("fresh") is not True:
        safety_blockers.append("kis-broker-reconciliation-not-fresh")
    if reconciliation_summary.get("three_way_verified") is not True:
        safety_blockers.append(
            "kis-broker-event-ledger-reconciliation-blocked"
        )
    if reconciliation.get("errors"):
        safety_blockers.append("kis-broker-reconciliation-errors")
    if account.get("known") is not True or account.get("fresh") is not True:
        safety_blockers.append("kis-account-risk-snapshot-not-fresh")
    if STATE.get("kill_switch"):
        safety_blockers.append("kill-switch-active")
    if control.get("halted") is True:
        safety_blockers.append("durable-risk-halt-active")
    if STATE.get("new_entries_blocked"):
        safety_blockers.append("new-risk-entries-blocked")

    preflight_facts = [
        (
            "functional-authority",
            True,
            "현재 permit과 당일 활성화 토큰을 고정했습니다.",
            {},
        ),
        (
            "functional-target-binding",
            True,
            "현재 Artifact·Instance·계좌 fingerprint·종목 binding이 permit과 일치합니다.",
            {
                "bindingHash": scope.get("bindingHash"),
                "memberHash": scope.get("strategyMemberHash"),
            },
        ),
        (
            "minimum-paper-pins",
            True,
            "모든 sleeve의 Backtester 및 Paper 기능 검증 pin을 확인했습니다.",
            {"members": scope.get("strategyMembers")},
        ),
        (
            "kis-live-adapter",
            "kis-live-order-adapter-not-ready" not in safety_blockers,
            str(
                broker_row.detail
                if broker_row is not None
                else "KIS adapter unavailable"
            ),
            {"orderReady": bool(broker_row and broker_row.order_ready)},
        ),
        (
            "fresh-kis-reconciliation",
            not any(
                blocker in safety_blockers
                for blocker in (
                    "kis-broker-reconciliation-not-fresh",
                    "kis-broker-event-ledger-reconciliation-blocked",
                    "kis-broker-reconciliation-errors",
                )
            ),
            str(reconciliation_summary.get("freshness_detail") or ""),
            {
                "summary": reconciliation_summary,
                "errors": reconciliation.get("errors", []),
            },
        ),
        (
            "fresh-kis-account-risk",
            "kis-account-risk-snapshot-not-fresh" not in safety_blockers,
            "현재 KIS 계좌 risk snapshot freshness를 확인했습니다.",
            {
                "known": account.get("known"),
                "fresh": account.get("fresh"),
                "observedAt": account.get("observed_at"),
            },
        ),
        (
            "durable-permit-equity-scope",
            "functional-test-equity-scope-unavailable"
            not in safety_blockers,
            "permit과 계좌에 고정된 누적 손실 원장을 확인했습니다.",
            {
                "permitId": permit_id,
                "accountFingerprint": scope.get("accountFingerprint"),
                "startingEquity": equity_scope.get("starting_equity"),
                "peakEquity": equity_scope.get("peak_equity"),
                "currentEquity": equity_scope.get("current_equity"),
                "worstDrawdown": equity_scope.get("worst_drawdown"),
                "lastObservedAt": equity_scope.get("last_observed_at"),
            },
        ),
        (
            "durable-functional-authority",
            not any(
                blocker in safety_blockers
                for blocker in (
                    "functional-test-authority-closed",
                    "functional-test-durable-authority-unavailable",
                )
            ),
            "permit별 내구 주문 권한이 열려 있는지 확인했습니다.",
            authority_status,
        ),
        (
            "kill-risk-controls",
            not any(
                blocker in safety_blockers
                for blocker in (
                    "kill-switch-active",
                    "durable-risk-halt-active",
                    "new-risk-entries-blocked",
                )
            ),
            "Kill switch, durable halt, 신규 진입 차단이 모두 해제되어 있습니다.",
            {
                "killSwitch": STATE.get("kill_switch"),
                "durableHalt": control.get("halted"),
                "newEntriesBlocked": STATE.get("new_entries_blocked"),
            },
        ),
    ]
    checks = [
        {
            "checkId": check_id,
            "status": "PASS" if passed else "FAIL",
            "detail": detail,
            "evidenceHash": governance_sha256(evidence),
        }
        for check_id, passed, detail, evidence in preflight_facts
    ]
    return {
        "safetyBlockers": safety_blockers,
        "checks": checks,
        "reconciliation": reconciliation,
        "account": account,
        "equityScope": equity_scope,
        "reconciliationHash": governance_sha256(
            {
                "summary": reconciliation_summary,
                "positions": reconciliation.get("positions", []),
                "accounts": reconciliation.get("accounts", []),
                "errors": reconciliation.get("errors", []),
            }
        ),
        "brokerSnapshotHash": governance_sha256(
            {
                "broker": "kis",
                "accountRisk": {
                    "known": account.get("known"),
                    "fresh": account.get("fresh"),
                    "observedAt": account.get("observed_at"),
                },
                "permitEquity": equity_scope,
                "fetchedAt": (
                    STATE.get("broker_reconciliation", {}).get("fetched_at")
                    if isinstance(STATE.get("broker_reconciliation"), dict)
                    else ""
                ),
            }
        ),
    }


def _create_functional_test_preflight(
    *,
    manifest: Any,
    scope: dict[str, Any],
    permit: Any,
    activation: Any,
    ttl_seconds: int,
    issued_at: datetime | None = None,
    allow_equity_scope_create: bool = False,
) -> tuple[Any, dict[str, Any]]:
    evidence = _functional_test_preflight_evidence(
        scope,
        permit_id=str(permit.permit_id or ""),
        allow_equity_scope_create=allow_equity_scope_create,
    )
    preflight = OPERATIONAL_GOVERNANCE.create_preflight_snapshot(
        deployment_id=manifest.deployment_id,
        deployment_manifest_hash=manifest.manifest_hash,
        checks=evidence["checks"],
        reconciliation_hash=str(evidence["reconciliationHash"]),
        broker_snapshot_hash=str(evidence["brokerSnapshotHash"]),
        ttl_seconds=ttl_seconds,
        issued_at=issued_at,
        metadata={
            "executionPurpose": FUNCTIONAL_TEST_EXECUTION_PURPOSE,
            "promotionEligible": False,
            "permitId": permit.permit_id,
            "permitHash": permit.content_hash,
            "activationTokenId": activation.token_id,
            "activationHash": activation.content_hash,
            "bindingHash": str(scope.get("bindingHash") or ""),
        },
    )
    return preflight, evidence


def refresh_functional_test_runtime_preflight(
    intent: OrderIntent,
    *,
    now: datetime | None = None,
    force: bool = False,
) -> tuple[bool, str, dict[str, Any]]:
    """Renew a running FUNCTIONAL_TEST preflight from fresh KIS truth.

    The runtime session and deployment manifest remain immutable.  A renewal
    creates a new immutable snapshot, then appends a PREFLIGHT_REBOUND event.
    Any stale broker truth, changed authority/scope/seal, or persistence error
    blocks the caller before an order can reach the broker.
    """

    if not functional_test_execution_requested(intent):
        return True, "functional-test-preflight-not-required", {}
    current_time = now or datetime.now(timezone.utc)
    if current_time.tzinfo is None:
        current_time = current_time.replace(tzinfo=timezone.utc)
    else:
        current_time = current_time.astimezone(timezone.utc)
    metadata = intent.metadata if isinstance(intent.metadata, dict) else {}
    session_id = str(
        (STATE.get("active_runtime_session_ids") or {}).get("stock") or ""
    ).strip()
    claimed_session_id = str(
        metadata.get("functional_test_session_id")
        or metadata.get("functionalTestSessionId")
        or ""
    ).strip()
    if not session_id or not claimed_session_id:
        return False, "functional-test-runtime-session-missing", {}
    if not secrets.compare_digest(session_id, claimed_session_id):
        return False, "functional-test-runtime-session-mismatch", {}

    try:
        with FUNCTIONAL_TEST_PREFLIGHT_LOCK:
            session_object = OPERATIONAL_GOVERNANCE.get_runtime_session(
                session_id
            )
            if session_object is None:
                return False, "functional-test-runtime-session-missing", {}
            session = session_object.to_dict()
            if (
                str(session.get("profile") or "") != "stock"
                or str(session.get("mode") or "") != "SMALL_LIVE"
                or str(session.get("lifecycle") or "")
                not in {"RUNNING", "DEGRADED"}
            ):
                return (
                    False,
                    "functional-test-runtime-session-state-invalid",
                    {"session": session},
                )
            session_metadata = (
                session.get("metadata")
                if isinstance(session.get("metadata"), dict)
                else {}
            )
            if (
                str(session_metadata.get("executionPurpose") or "")
                != FUNCTIONAL_TEST_EXECUTION_PURPOSE
                or session_metadata.get("promotionEligible") is not False
                or str(session_metadata.get("evidenceClass") or "")
                != "FUNCTIONAL_TEST_NON_PROMOTION"
            ):
                return False, "functional-test-session-purpose-invalid", {
                    "session": session
                }
            manifest = OPERATIONAL_GOVERNANCE.get_deployment_manifest_by_hash(
                str(session.get("deploymentManifestHash") or "")
            )
            if manifest is None:
                return False, "functional-test-manifest-missing", {
                    "session": session
                }
            manifest_metadata = dict(manifest.metadata)
            if (
                str(manifest_metadata.get("executionPurpose") or "")
                != FUNCTIONAL_TEST_EXECUTION_PURPOSE
                or manifest_metadata.get("promotionEligible") is not False
                or manifest_metadata.get("fullLiveAllowed") is not False
                or str(manifest.broker_route or "").lower() != "kis"
            ):
                return False, "functional-test-manifest-purpose-invalid", {
                    "session": session
                }

            permit, activation = functional_test_active_authority(
                now=current_time
            )
            authority_status = functional_test_durable_authority_status(
                permit
            )
            if authority_status.get("closed") is True:
                return (
                    False,
                    "functional-test-authority-closed",
                    {
                        "session": session,
                        "authorityStatus": authority_status,
                    },
                )
            for key, current_value in (
                ("permitId", permit.permit_id),
                ("permitHash", permit.content_hash),
                ("activationTokenId", activation.token_id),
                ("activationHash", activation.content_hash),
            ):
                if (
                    str(manifest_metadata.get(key) or "")
                    != str(current_value)
                    or str(session_metadata.get(key) or "")
                    != str(current_value)
                ):
                    return (
                        False,
                        "functional-test-session-authority-changed:" + key,
                        {"session": session},
                    )

            portfolio_id = str(
                metadata.get("portfolio_id")
                or metadata.get("portfolioId")
                or ""
            ).strip()
            strategy_id = str(intent.strategy_id or "").strip()
            if (
                portfolio_id
                != str(session_metadata.get("portfolioId") or "").strip()
                or strategy_id
                != str(session_metadata.get("strategyId") or "").strip()
            ):
                return False, "functional-test-runtime-context-changed", {
                    "session": session
                }
            scope = _functional_test_runtime_scope(
                portfolio_id=portfolio_id,
                strategy_id=strategy_id,
                permit=permit,
            )
            current_values = _functional_test_manifest_values(
                scope,
                permit,
                activation,
                preflight_ttl_seconds=manifest.preflight_ttl_seconds,
            )
            mismatches = [
                label
                for label, current_value, sealed_value in (
                    (
                        "binding",
                        scope.get("bindingHash"),
                        manifest_metadata.get("bindingHash"),
                    ),
                    (
                        "session-binding",
                        scope.get("bindingHash"),
                        session_metadata.get("bindingHash"),
                    ),
                    (
                        "members",
                        scope.get("strategyMemberHash"),
                        manifest_metadata.get("strategyMemberHash"),
                    ),
                    (
                        "session-members",
                        scope.get("strategyMemberHash"),
                        session_metadata.get("strategyMemberHash"),
                    ),
                    (
                        "account",
                        scope.get("accountFingerprint"),
                        manifest.account_fingerprint,
                    ),
                    (
                        "session-account",
                        scope.get("accountFingerprint"),
                        session_metadata.get("accountFingerprint"),
                    ),
                    (
                        "strategy",
                        current_values["strategy_artifact_hash"],
                        manifest.strategy_artifact_hash,
                    ),
                    (
                        "portfolio",
                        current_values["portfolio_artifact_hash"],
                        manifest.portfolio_artifact_hash,
                    ),
                    (
                        "build",
                        current_values["build_hash"],
                        manifest.build_hash,
                    ),
                    (
                        "risk",
                        current_values["risk_policy_hash"],
                        manifest.risk_policy_hash,
                    ),
                    (
                        "config",
                        current_values["config_hash"],
                        manifest.config_hash,
                    ),
                )
                if str(current_value or "") != str(sealed_value or "")
            ]
            if sorted(scope.get("allowedSymbols") or []) != sorted(
                manifest_metadata.get("allowedSymbols") or []
            ):
                mismatches.append("symbols")
            if mismatches:
                return (
                    False,
                    "functional-test-runtime-seal-changed:"
                    + ",".join(mismatches),
                    {"session": session},
                )

            validity = OPERATIONAL_GOVERNANCE.preflight_validity(
                str(session.get("preflightSnapshotId") or ""),
                at=current_time,
            )
            preflight_payload = (
                validity.get("snapshot")
                if isinstance(validity.get("snapshot"), dict)
                else {}
            )
            expires_at = _functional_test_utc_datetime(
                preflight_payload.get("expiresAt")
            )
            remaining_preflight = (
                (expires_at - current_time).total_seconds()
                if expires_at is not None
                else -1.0
            )
            reconciliation = (
                STATE.get("broker_reconciliation")
                if isinstance(STATE.get("broker_reconciliation"), dict)
                else {}
            )
            reconciliation_summary = (
                reconciliation.get("summary")
                if isinstance(reconciliation.get("summary"), dict)
                else {}
            )
            reconciliation_age = _functional_test_age_seconds(
                reconciliation.get("fetched_at"),
                now=current_time,
            )
            account = broker_account_risk(
                STATE.get("account_risk")
                if isinstance(STATE.get("account_risk"), dict)
                else {},
                "kis",
                currency="KRW",
                maximum_age_seconds=FUNCTIONAL_TEST_RISK_MAX_AGE_SECONDS,
            )
            account_age = _functional_test_age_seconds(
                account.get("observed_at"),
                now=current_time,
            )
            control = durable_control_snapshot()
            broker_truth_fresh = bool(
                reconciliation_summary.get("fresh") is True
                and reconciliation_summary.get("three_way_verified") is True
                and not reconciliation.get("errors")
                and reconciliation_age is not None
                and reconciliation_age
                <= FUNCTIONAL_TEST_PREFLIGHT_REFRESH_MARGIN_SECONDS
                and account.get("known") is True
                and account.get("fresh") is True
                and account_age is not None
                and account_age
                <= FUNCTIONAL_TEST_PREFLIGHT_REFRESH_MARGIN_SECONDS
                and not STATE.get("kill_switch")
                and control.get("halted") is not True
                and not STATE.get("new_entries_blocked")
            )
            refresh_margin = min(
                FUNCTIONAL_TEST_PREFLIGHT_REFRESH_MARGIN_SECONDS,
                max(5.0, float(manifest.preflight_ttl_seconds) * 0.2),
            )
            if (
                not force
                and validity.get("valid") is True
                and remaining_preflight > refresh_margin
                and broker_truth_fresh
            ):
                return True, "functional-test-preflight-current", {
                    "session": session,
                    "preflight": preflight_payload,
                    "action": "REUSED",
                }

            authority_remaining = int(
                min(permit.ends_at, activation.expires_at).timestamp()
                - current_time.timestamp()
            )
            if authority_remaining < 2:
                return False, "functional-test-authority-expiry-imminent", {
                    "session": session
                }
            ttl_seconds = min(
                int(manifest.preflight_ttl_seconds),
                300,
                authority_remaining,
            )
            preflight, evidence = _create_functional_test_preflight(
                manifest=manifest,
                scope=scope,
                permit=permit,
                activation=activation,
                ttl_seconds=ttl_seconds,
                issued_at=current_time,
            )
            blockers = [
                str(item)
                for item in evidence.get("safetyBlockers", [])
                if str(item)
            ]
            if blockers or preflight.status != "PASS":
                return (
                    False,
                    "functional-test-preflight-refresh-blocked:"
                    + ",".join(blockers or [preflight.status]),
                    {
                        "session": session,
                        "preflight": preflight.to_dict(),
                        "safetyBlockers": blockers,
                    },
                )
            rebound = OPERATIONAL_GOVERNANCE.rebind_runtime_preflight(
                session_id,
                preflight.snapshot_id,
                actor="live_trader.functional_test.preflight_refresh",
                occurred_at=current_time,
            )
            return True, "functional-test-preflight-refreshed", {
                "session": rebound.to_dict(),
                "preflight": preflight.to_dict(),
                "action": "REFRESHED",
            }
    except Exception as exc:
        code = (
            exc.code
            if isinstance(exc, FunctionalTestContractError)
            else type(exc).__name__
        )
        return (
            False,
            f"functional-test-preflight-refresh-error:{code}",
            {},
        )


def _functional_test_execution_poll_fresh(
    *,
    now: datetime | None = None,
) -> tuple[bool, str, dict[str, Any]]:
    current = now or datetime.now()
    if current.tzinfo is not None:
        current = current.astimezone().replace(tzinfo=None)
    event_state = execution_event_snapshot()
    age = seconds_since(event_state.get("last_poll"), current)
    errors = [
        dict(item)
        for item in event_state.get("errors", [])
        if isinstance(item, dict)
        and str(item.get("broker_id") or "").strip().lower()
        in {"", "kis"}
    ]
    order_truth = kis_order_truth_snapshot(now=current)
    fresh = bool(
        age is not None
        and age <= FUNCTIONAL_TEST_EXECUTION_OBSERVATION_MAX_AGE_SECONDS
        and not errors
        and order_truth.get("complete") is True
        and order_truth.get("fresh") is True
        and order_truth.get("absenceIsAuthoritative") is True
    )
    return (
        fresh,
        (
            "functional-test-kis-execution-poll-fresh"
            if fresh
            else "functional-test-kis-execution-poll-stale"
        ),
        {
            "lastPoll": event_state.get("last_poll"),
            "ageSeconds": age,
            "errors": errors,
            "orderTruth": order_truth,
        },
    )


def ensure_functional_test_execution_observation() -> tuple[
    bool,
    str,
    dict[str, Any],
]:
    """Require REST truth while reserving KIS WS for the controller mux."""

    try:
        before = LIVE_EXECUTION_STREAMS.snapshot()
        before_brokers = (
            before.get("brokers")
            if isinstance(before.get("brokers"), dict)
            else {}
        )
        before_kis = (
            before_brokers.get("kis")
            if isinstance(before_brokers.get("kis"), dict)
            else {}
        )
        if before_kis.get("running") is True:
            stopped = LIVE_EXECUTION_STREAMS.stop_brokers(
                ("kis",),
                timeout=25.0,
            )
            stopped_brokers = (
                stopped.get("brokers")
                if isinstance(stopped.get("brokers"), dict)
                else {}
            )
            stopped_kis = (
                stopped_brokers.get("kis")
                if isinstance(stopped_brokers.get("kis"), dict)
                else {}
            )
            if stopped_kis.get("running") is True:
                return (
                    False,
                    "functional-test-separate-kis-private-stream-still-running",
                    {
                        "owned": False,
                        "privateThreadDisabled": False,
                        "privateStream": dict(stopped_kis),
                    },
                )

        poll_fresh, poll_reason, poll_details = (
            _functional_test_execution_poll_fresh()
        )
        poll_result: dict[str, Any] = {}
        if not poll_fresh:
            raw_poll = poll_execution_events(
                "kis",
                force_snapshot=True,
                include_snapshot=False,
            )
            poll_result = (
                dict(raw_poll) if isinstance(raw_poll, dict) else {}
            )
            poll_fresh, poll_reason, poll_details = (
                _functional_test_execution_poll_fresh()
            )
        if poll_fresh:
            return True, poll_reason, {
                "owned": False,
                "reused": False,
                "privateThreadDisabled": True,
                "observationMode": "KIS_MARKET_PRIVATE_SINGLE_SOCKET_MUX",
                "privateStream": {},
                "fallbackPoll": poll_details,
                "pollCoalesced": poll_result.get("coalesced") is True,
            }
        return False, poll_reason, {
            "owned": False,
            "reused": False,
            "privateThreadDisabled": True,
            "privateStream": {},
            "fallbackPoll": poll_details,
        }
    except Exception as exc:
        return (
            False,
            "functional-test-kis-execution-observation-error:"
            + type(exc).__name__,
            {"owned": False},
        )


def ingest_functional_test_kis_private_execution(
    tr_id: str,
    fields: tuple[str, ...],
) -> dict[str, Any]:
    """Fail-closed sink for H0STCNI0 on the controller's single socket."""

    return LIVE_EXECUTION_STREAMS.ingest_kis_domestic_fields(tr_id, fields)


def _functional_test_runtime_guard_intent(
    session_id: str,
) -> OrderIntent:
    session_object = OPERATIONAL_GOVERNANCE.get_runtime_session(session_id)
    if session_object is None:
        raise ValueError("functional runtime session missing")
    session = session_object.to_dict()
    metadata = (
        session.get("metadata")
        if isinstance(session.get("metadata"), dict)
        else {}
    )
    manifest = OPERATIONAL_GOVERNANCE.get_deployment_manifest_by_hash(
        str(session.get("deploymentManifestHash") or "")
    )
    if manifest is None:
        raise ValueError("functional runtime manifest missing")
    manifest_metadata = dict(manifest.metadata)
    members = [
        dict(item)
        for item in manifest_metadata.get("strategyMembers", [])
        if isinstance(item, dict)
    ]
    strategy_id = str(metadata.get("strategyId") or "").strip()
    member = next(
        (
            item
            for item in members
            if str(item.get("strategyId") or "").strip() == strategy_id
        ),
        members[0] if members else {},
    )
    symbol = str(
        member.get("symbol")
        or next(
            iter(manifest_metadata.get("allowedSymbols") or []),
            "",
        )
    ).strip()
    if not strategy_id or not symbol:
        raise ValueError("functional runtime guard scope is incomplete")
    return OrderIntent(
        strategy_id=strategy_id,
        asset="KR_STOCK",
        symbol=symbol,
        side="BUY",
        quantity=1.0,
        reference_price=1.0,
        mode="SMALL_LIVE",
        reason="functional-test-runtime-guard",
        metadata={
            "execution_purpose": FUNCTIONAL_TEST_EXECUTION_PURPOSE,
            "functional_test_environment": FUNCTIONAL_TEST_ENVIRONMENT,
            "environment": FUNCTIONAL_TEST_ENVIRONMENT,
            "broker_id": "kis",
            "portfolio_id": str(metadata.get("portfolioId") or ""),
            "strategy_instance_id": str(
                member.get("strategyInstanceId") or ""
            ),
            "functional_test_session_id": session_id,
        },
    )


def run_functional_test_runtime_guard_cycle(
    session_id: str,
) -> tuple[bool, str, dict[str, Any]]:
    """Poll private execution/account truth, then renew the sealed preflight."""

    if str(
        (STATE.get("active_runtime_session_ids") or {}).get("stock") or ""
    ) != str(session_id or ""):
        return False, "functional-test-runtime-guard-session-inactive", {}
    try:
        poll_result = poll_execution_events(
            "kis",
            force_snapshot=True,
            include_snapshot=False,
        )
        poll_fresh, poll_reason, poll_details = (
            _functional_test_execution_poll_fresh()
        )
        if not poll_fresh:
            return False, poll_reason, {
                "poll": (
                    dict(poll_result)
                    if isinstance(poll_result, dict)
                    else {}
                ),
                "freshness": poll_details,
            }
        intent = _functional_test_runtime_guard_intent(session_id)
        allowed, reason, details = refresh_functional_test_runtime_preflight(
            intent
        )
        return allowed, reason, {
            "poll": {
                "ok": (
                    poll_result.get("ok")
                    if isinstance(poll_result, dict)
                    else False
                ),
                "coalesced": (
                    poll_result.get("coalesced") is True
                    if isinstance(poll_result, dict)
                    else False
                ),
            },
            "freshness": poll_details,
            "preflight": details,
        }
    except Exception as exc:
        return (
            False,
            "functional-test-runtime-guard-error:" + type(exc).__name__,
            {},
        )


def _functional_test_runtime_guard_worker(
    session_id: str,
    stop_event: threading.Event,
    interval_seconds: float,
) -> None:
    previous_reason = ""
    try:
        while not stop_event.wait(max(0.05, float(interval_seconds))):
            allowed, reason, _details = (
                run_functional_test_runtime_guard_cycle(session_id)
            )
            checked_at = datetime.now(timezone.utc).isoformat()
            with FUNCTIONAL_TEST_RUNTIME_GUARD_LOCK:
                if session_id != FUNCTIONAL_TEST_RUNTIME_GUARD_SESSION_ID:
                    break
                FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["lastCheckAt"] = (
                    checked_at
                )
                FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["lastReason"] = reason
                if allowed:
                    FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["lastSuccessAt"] = (
                        checked_at
                    )
                    FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["failureCount"] = 0
                else:
                    FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["failureCount"] = (
                        int(
                            FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS.get(
                                "failureCount", 0
                            )
                        )
                        + 1
                    )
            if not allowed and reason.endswith("session-inactive"):
                break
            if reason != previous_reason:
                append_audit(
                    "info" if allowed else "danger",
                    "FUNCTIONAL_TEST Runtime Guard",
                    (
                        "KIS 체결·계좌 대조 및 preflight 갱신 정상"
                        if allowed
                        else f"신규 주문 차단 상태: {reason}"
                    ),
                )
                previous_reason = reason
    finally:
        owned = False
        with FUNCTIONAL_TEST_RUNTIME_GUARD_LOCK:
            global FUNCTIONAL_TEST_RUNTIME_GUARD_STREAM_OWNED
            if session_id == FUNCTIONAL_TEST_RUNTIME_GUARD_SESSION_ID:
                owned = FUNCTIONAL_TEST_RUNTIME_GUARD_STREAM_OWNED
                FUNCTIONAL_TEST_RUNTIME_GUARD_STREAM_OWNED = False
                FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["running"] = False
                FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS[
                    "kisExecutionStreamOwned"
                ] = False
        if owned:
            try:
                LIVE_EXECUTION_STREAMS.stop_brokers(
                    ("kis",),
                    timeout=25.0,
                )
            except Exception:
                pass


def start_functional_test_runtime_guard(
    session_id: str,
    *,
    execution_stream_owned: bool,
    interval_seconds: float = FUNCTIONAL_TEST_RUNTIME_GUARD_INTERVAL_SECONDS,
) -> dict[str, Any]:
    normalized_session_id = str(session_id or "").strip()
    if not normalized_session_id:
        raise ValueError("functional runtime guard session_id is required")
    stop_functional_test_runtime_guard()
    global FUNCTIONAL_TEST_RUNTIME_GUARD_STOP
    global FUNCTIONAL_TEST_RUNTIME_GUARD_THREAD
    global FUNCTIONAL_TEST_RUNTIME_GUARD_SESSION_ID
    global FUNCTIONAL_TEST_RUNTIME_GUARD_STREAM_OWNED
    with FUNCTIONAL_TEST_RUNTIME_GUARD_LOCK:
        FUNCTIONAL_TEST_RUNTIME_GUARD_STOP = threading.Event()
        FUNCTIONAL_TEST_RUNTIME_GUARD_SESSION_ID = normalized_session_id
        FUNCTIONAL_TEST_RUNTIME_GUARD_STREAM_OWNED = bool(
            execution_stream_owned
        )
        FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS.update(
            {
                "running": True,
                "sessionId": normalized_session_id,
                "lastCheckAt": "",
                "lastSuccessAt": "",
                "lastReason": "waiting-first-cycle",
                "failureCount": 0,
                "kisExecutionStreamOwned": bool(execution_stream_owned),
            }
        )
        thread = threading.Thread(
            target=_functional_test_runtime_guard_worker,
            args=(
                normalized_session_id,
                FUNCTIONAL_TEST_RUNTIME_GUARD_STOP,
                interval_seconds,
            ),
            daemon=True,
            name="functional-test-runtime-guard",
        )
        FUNCTIONAL_TEST_RUNTIME_GUARD_THREAD = thread
        thread.start()
        return dict(FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS)


def stop_functional_test_runtime_guard(
    *,
    timeout: float = 30.0,
) -> dict[str, Any]:
    global FUNCTIONAL_TEST_RUNTIME_GUARD_THREAD
    global FUNCTIONAL_TEST_RUNTIME_GUARD_SESSION_ID
    with FUNCTIONAL_TEST_RUNTIME_GUARD_LOCK:
        thread = FUNCTIONAL_TEST_RUNTIME_GUARD_THREAD
        FUNCTIONAL_TEST_RUNTIME_GUARD_STOP.set()
    if thread is not None and thread is not threading.current_thread():
        thread.join(timeout=max(0.0, timeout))
    with FUNCTIONAL_TEST_RUNTIME_GUARD_LOCK:
        alive = bool(thread and thread.is_alive())
        if not alive:
            FUNCTIONAL_TEST_RUNTIME_GUARD_THREAD = None
            FUNCTIONAL_TEST_RUNTIME_GUARD_SESSION_ID = ""
            FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS["running"] = False
        return {
            **dict(FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS),
            "stopped": not alive,
        }


def functional_test_runtime_guard_snapshot() -> dict[str, Any]:
    with FUNCTIONAL_TEST_RUNTIME_GUARD_LOCK:
        return dict(FUNCTIONAL_TEST_RUNTIME_GUARD_STATUS)


def functional_test_runtime_start_allowed(
    session_id: str,
    *,
    portfolio_id: str,
    strategy_id: str,
) -> tuple[bool, str, dict[str, Any]]:
    """Validate the sealed STARTING session before loading any live engine."""

    normalized_session_id = str(session_id or "").strip()
    if not normalized_session_id:
        return False, "functional-test-start-session-missing", {}
    if str(
        (STATE.get("active_runtime_session_ids") or {}).get("stock") or ""
    ) != normalized_session_id:
        return False, "functional-test-start-session-not-active", {}
    try:
        session_object = OPERATIONAL_GOVERNANCE.get_runtime_session(
            normalized_session_id
        )
        if session_object is None:
            return False, "functional-test-start-session-missing", {}
        session = session_object.to_dict()
        if (
            str(session.get("lifecycle") or "") != "STARTING"
            or str(session.get("profile") or "") != "stock"
            or str(session.get("mode") or "") != "SMALL_LIVE"
        ):
            return False, "functional-test-start-session-state-invalid", {"session": session}
        session_metadata = (
            session.get("metadata")
            if isinstance(session.get("metadata"), dict)
            else {}
        )
        if (
            str(session_metadata.get("executionPurpose") or "")
            != FUNCTIONAL_TEST_EXECUTION_PURPOSE
            or session_metadata.get("promotionEligible") is not False
            or str(session_metadata.get("evidenceClass") or "")
            != "FUNCTIONAL_TEST_NON_PROMOTION"
        ):
            return False, "functional-test-start-purpose-invalid", {"session": session}
        validity = OPERATIONAL_GOVERNANCE.preflight_validity(
            str(session.get("preflightSnapshotId") or "")
        )
        if validity.get("valid") is not True:
            return (
                False,
                "functional-test-start-preflight-invalid:"
                + ",".join(str(item) for item in validity.get("reasons", [])),
                {"session": session, "preflight": validity},
            )
        manifest = OPERATIONAL_GOVERNANCE.get_deployment_manifest_by_hash(
            str(session.get("deploymentManifestHash") or "")
        )
        if manifest is None:
            return False, "functional-test-start-manifest-missing", {"session": session}
        manifest_metadata = dict(manifest.metadata)
        if (
            str(manifest_metadata.get("executionPurpose") or "")
            != FUNCTIONAL_TEST_EXECUTION_PURPOSE
            or manifest_metadata.get("promotionEligible") is not False
        ):
            return False, "functional-test-start-manifest-purpose-invalid", {"session": session}
        permit, activation = functional_test_active_authority()
        authority_status = functional_test_durable_authority_status(permit)
        if authority_status.get("closed") is True:
            return (
                False,
                "functional-test-start-authority-closed",
                {"session": session, "authorityStatus": authority_status},
            )
        for key, value in (
            ("permitId", permit.permit_id),
            ("permitHash", permit.content_hash),
            ("activationTokenId", activation.token_id),
            ("activationHash", activation.content_hash),
        ):
            if (
                str(session_metadata.get(key) or "") != str(value)
                or str(manifest_metadata.get(key) or "") != str(value)
            ):
                return (
                    False,
                    "functional-test-start-authority-changed:" + key,
                    {"session": session},
                )
        scope = _functional_test_runtime_scope(
            portfolio_id=portfolio_id,
            strategy_id=strategy_id,
            permit=permit,
        )
        current_values = _functional_test_manifest_values(
            scope,
            permit,
            activation,
            preflight_ttl_seconds=manifest.preflight_ttl_seconds,
        )
        mismatches = [
            label
            for label, current_value, sealed_value in (
                ("binding", scope.get("bindingHash"), manifest_metadata.get("bindingHash")),
                ("members", scope.get("strategyMemberHash"), manifest_metadata.get("strategyMemberHash")),
                ("account", scope.get("accountFingerprint"), manifest.account_fingerprint),
                ("strategy", current_values["strategy_artifact_hash"], manifest.strategy_artifact_hash),
                ("portfolio", current_values["portfolio_artifact_hash"], manifest.portfolio_artifact_hash),
                ("build", current_values["build_hash"], manifest.build_hash),
                ("risk", current_values["risk_policy_hash"], manifest.risk_policy_hash),
                ("config", current_values["config_hash"], manifest.config_hash),
            )
            if str(current_value or "") != str(sealed_value or "")
        ]
        if mismatches:
            return (
                False,
                "functional-test-start-seal-changed:" + ",".join(mismatches),
                {"session": session},
            )
        return True, "functional-test-start-authorized", {
            "session": session,
            "manifest": manifest.to_dict(),
            "scope": scope,
        }
    except (FunctionalTestContractError, OSError, sqlite3.Error, ValueError) as exc:
        code = exc.code if isinstance(exc, FunctionalTestContractError) else type(exc).__name__
        return False, f"functional-test-start-authorization-error:{code}", {}


def _recover_orphaned_functional_test_runtime_session(
    prior_session: object,
) -> object:
    """Fail-close an unbound non-terminal session after fresh KIS truth.

    A process crash can leave the append-only governance session in an active
    lifecycle even though neither the controller nor the in-memory runtime
    binding survived.  It is unsafe to silently replace that session: a late
    or unknown broker order may still exist.  Recovery therefore keeps new
    entries blocked, forces one non-coalesced KIS snapshot, verifies fresh
    three-way account/position/order truth and zero unresolved functional
    orders, and only then appends the terminal FAILED event.
    """

    session_id = str(getattr(prior_session, "session_id", "") or "").strip()
    lifecycle = str(getattr(prior_session, "lifecycle", "") or "").upper()
    if not session_id or lifecycle not in {
        "PREFLIGHT",
        "STARTING",
        "RUNNING",
        "DEGRADED",
        "DRAINING",
        "STOPPING",
    }:
        raise ValueError("functional-test-orphan-session-scope-invalid")

    initial_assessment = functional_test_authority_mutation_assessment()
    runtime = (
        initial_assessment.get("runtime")
        if isinstance(initial_assessment.get("runtime"), dict)
        else {}
    )
    session = (
        initial_assessment.get("session")
        if isinstance(initial_assessment.get("session"), dict)
        else {}
    )
    bound_session_id = str(session.get("sessionId") or "").strip()
    if runtime.get("active") is True or bound_session_id:
        raise ValueError(
            "functional-test-prior-session-still-bound:"
            + (bound_session_id or str(runtime.get("phase") or "UNKNOWN"))
        )

    entry_block_was_active = bool(STATE.get("new_entries_blocked"))
    STATE["new_entries_blocked"] = True
    try:
        raw_poll = poll_execution_events(
            "kis",
            force_snapshot=True,
            include_snapshot=False,
        )
        poll_result = dict(raw_poll) if isinstance(raw_poll, dict) else {}
    except Exception as exc:
        raise ValueError(
            "functional-test-orphan-recovery-poll-error:"
            + type(exc).__name__
        ) from exc
    if (
        poll_result.get("ok") is not True
        or poll_result.get("coalesced") is True
        or poll_result.get("errors")
    ):
        raise ValueError("functional-test-orphan-recovery-poll-incomplete")
    poll_fresh, poll_reason, poll_details = (
        _functional_test_execution_poll_fresh()
    )
    if not poll_fresh:
        raise ValueError(
            "functional-test-orphan-recovery-execution-poll-stale:"
            + str(poll_reason or "unknown")
        )

    # A broker refresh may normally release its own transient entry block.
    # Reassert this recovery fence until the old session is terminal.
    STATE["new_entries_blocked"] = True
    assessment = functional_test_authority_mutation_assessment(
        require_kis_reconciliation=True,
    )
    broker_reconciliation = (
        STATE.get("broker_reconciliation")
        if isinstance(STATE.get("broker_reconciliation"), dict)
        else {}
    )
    reconciliation_summary = (
        broker_reconciliation.get("summary")
        if isinstance(broker_reconciliation.get("summary"), dict)
        else {}
    )
    recovery_blockers = [
        str(item) for item in assessment.get("blockers", []) if str(item)
    ]
    if assessment.get("kisReconciled") is not True:
        recovery_blockers.append("functional-test-kis-reconciliation-unresolved")
    if int(assessment.get("workingOrderCount") or 0) != 0:
        recovery_blockers.append("functional-test-working-orders-unresolved")
    if reconciliation_summary.get("fresh") is not True:
        recovery_blockers.append("functional-test-kis-reconciliation-not-fresh")
    if reconciliation_summary.get("three_way_verified") is not True:
        recovery_blockers.append("functional-test-kis-three-way-unverified")
    if broker_reconciliation.get("errors"):
        recovery_blockers.append("functional-test-kis-reconciliation-errors")
    if assessment.get("allowed") is not True or recovery_blockers:
        raise ValueError(
            "functional-test-orphan-recovery-unresolved:"
            + ",".join(dict.fromkeys(recovery_blockers or ["assessment-blocked"]))
        )

    try:
        recovered = OPERATIONAL_GOVERNANCE.transition_runtime_session(
            session_id,
            "FAILED",
            actor="live_trader.functional_test.recovery",
            event_type="FUNCTIONAL_TEST_CRASH_RECOVERY_FAILED_CLOSED",
            payload={
                "previousLifecycle": lifecycle,
                "deploymentId": str(
                    getattr(prior_session, "deployment_id", "") or ""
                ),
                "forcedKisPoll": True,
                "executionPollReason": str(poll_reason or ""),
                "executionPoll": dict(poll_details),
                "threeWayVerified": True,
                "unresolvedWorkingOrderCount": 0,
                "reason": "controller-and-runtime-binding-absent-after-restart",
            },
        )
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        raise ValueError(
            "functional-test-orphan-recovery-transition-failed:"
            + type(exc).__name__
        ) from exc

    if (
        not entry_block_was_active
        and not STATE.get("manual_new_entries_blocked")
        and not STATE.get("broker_truth_blocked")
        and not STATE.get("daily_loss_entries_blocked")
        and not STATE.get("kill_switch")
        and not STATE.get("kill_switch_rearm_required")
        and durable_control_snapshot().get("halted") is not True
    ):
        STATE["new_entries_blocked"] = False
    append_audit(
        "warn",
        "FUNCTIONAL_TEST Orphan Recovery",
        (
            f"{session_id} ({lifecycle}) 세션을 fresh KIS 3-way 대조와 "
            "미해결 주문 0건 확인 후 FAILED로 종결했습니다."
        ),
    )
    return recovered


def _prepare_functional_test_runtime_session(
    profile_id: str,
    mode: Mode,
    portfolio_id: str,
    strategy_id: str,
) -> tuple[object, str]:
    """Create a separate, immutable non-promotional live test session."""

    if profile_id != "stock" or mode != "SMALL_LIVE":
        raise ValueError("FUNCTIONAL_TEST requires stock/SMALL_LIVE")
    if STATE.get("operator_confirmed") is not True:
        raise ValueError("FUNCTIONAL_TEST runtime 시작 전 운용자 확인이 필요합니다.")
    if STATE.get("dry_run"):
        raise ValueError("FUNCTIONAL_TEST 실주문 runtime에서는 Dry Run을 해제해야 합니다.")
    if not real_orders_enabled():
        raise ValueError("LIVE_TRADER_ENABLE_REAL_ORDERS=true가 필요합니다.")
    control = durable_control_snapshot()
    if STATE.get("kill_switch") or control.get("halted") is True:
        raise ValueError("Kill/Risk 제어가 활성화되어 FUNCTIONAL_TEST를 시작할 수 없습니다.")
    missing_checklist = [
        item
        for item in checklist_rows()
        if item.get("required") and not item.get("checked")
    ]
    if missing_checklist:
        raise ValueError("필수 Live 안전 체크리스트를 먼저 확인하세요.")

    now = datetime.now(timezone.utc)
    permit, activation = functional_test_active_authority(now=now)
    authority_status = functional_test_durable_authority_status(permit)
    if authority_status.get("closed") is True:
        raise ValueError(
            "FUNCTIONAL_TEST permit의 내구 주문 권한이 이미 종료되었습니다."
        )
    remaining_seconds = int(
        min(permit.ends_at, activation.expires_at).timestamp()
        - now.timestamp()
    )
    if remaining_seconds < 2:
        raise ValueError("FUNCTIONAL_TEST permit/당일 활성화 만료가 임박했습니다.")
    scope = _functional_test_runtime_scope(
        portfolio_id=portfolio_id,
        strategy_id=strategy_id,
        permit=permit,
    )
    lead_strategy = scope.get("leadStrategy")
    if not isinstance(lead_strategy, dict):
        raise ValueError("FUNCTIONAL_TEST lead Strategy를 봉인할 수 없습니다.")

    ttl_seconds = min(300, remaining_seconds)
    values = _functional_test_manifest_values(
        scope,
        permit,
        activation,
        preflight_ttl_seconds=ttl_seconds,
    )
    manifest = OPERATIONAL_GOVERNANCE.create_deployment_manifest(**values)
    prior_session = OPERATIONAL_GOVERNANCE.latest_runtime_session(
        manifest.deployment_id
    )
    if (
        prior_session is not None
        and str(getattr(prior_session, "lifecycle", "") or "").upper()
        in {
            "PREFLIGHT",
            "STARTING",
            "RUNNING",
            "DEGRADED",
            "DRAINING",
            "STOPPING",
        }
    ):
        prior_session = _recover_orphaned_functional_test_runtime_session(
            prior_session
        )
    try:
        prior_reservations = PROGRAM_LEDGER.functional_test_reservation_count(
            str(permit.permit_id or "")
        )
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        raise ValueError(
            "FUNCTIONAL_TEST 누적 손실 원장 사용 이력을 확인할 수 없습니다."
        ) from exc
    allow_equity_scope_create = (
        prior_session is None and prior_reservations == 0
    )
    preflight, evidence = _create_functional_test_preflight(
        manifest=manifest,
        scope=scope,
        permit=permit,
        activation=activation,
        ttl_seconds=ttl_seconds,
        issued_at=now,
        allow_equity_scope_create=allow_equity_scope_create,
    )
    safety_blockers = [
        str(item)
        for item in evidence.get("safetyBlockers", [])
        if str(item)
    ]
    if safety_blockers or preflight.status != "PASS":
        raise ValueError(
            "FUNCTIONAL_TEST fresh preflight 차단: "
            + ", ".join(safety_blockers or [preflight.status])
        )

    session = OPERATIONAL_GOVERNANCE.create_runtime_session(
        deployment_id=manifest.deployment_id,
        deployment_manifest_hash=manifest.manifest_hash,
        profile="stock",
        mode="SMALL_LIVE",
        runtime_instance_id=(
            f"functional-desktop-{os.getpid()}-{secrets.token_hex(8)}"
        ),
        preflight_snapshot_id=preflight.snapshot_id,
        metadata={
            "executionPurpose": FUNCTIONAL_TEST_EXECUTION_PURPOSE,
            "evidenceClass": "FUNCTIONAL_TEST_NON_PROMOTION",
            "promotionEligible": False,
            "permitId": permit.permit_id,
            "permitHash": permit.content_hash,
            "activationTokenId": activation.token_id,
            "activationHash": activation.content_hash,
            "bindingHash": str(scope.get("bindingHash") or ""),
            "accountFingerprint": str(scope.get("accountFingerprint") or ""),
            "portfolioId": str(scope.get("portfolioId") or ""),
            "strategyId": str(lead_strategy.get("strategy_id") or ""),
            "runtimeDeploymentId": str(scope.get("runtimeDeploymentId") or ""),
            "strategyMemberHash": str(scope.get("strategyMemberHash") or ""),
            "allowedSymbols": list(scope.get("allowedSymbols") or []),
        },
    )
    session = OPERATIONAL_GOVERNANCE.transition_runtime_session(
        session.session_id,
        "STARTING",
        actor="live_trader.functional_test",
        event_type="FUNCTIONAL_TEST_RUNTIME_START_REQUESTED",
        payload={
            "profile": "stock",
            "mode": "SMALL_LIVE",
            "promotionEligible": False,
        },
    )
    STATE.setdefault("active_runtime_session_ids", {})["stock"] = (
        session.session_id
    )
    return session, "FUNCTIONAL_TEST 전용 거버넌스 Session을 생성했습니다."


def _prepare_operational_runtime_session(
    profile_id: str,
    mode: Mode,
    portfolio_id: str,
    deployment_id: str = "",
    strategy_id: str = "",
) -> tuple[object | None, str]:
    requested_deployment = str(deployment_id or "").strip()
    requested_strategy = str(strategy_id or "").strip()
    requested_portfolio = str(portfolio_id or "").strip()
    explicit_context = bool(requested_deployment or requested_strategy)
    if mode == "MONITOR" and not explicit_context and not requested_portfolio:
        return None, "명시 Deployment가 없는 안전 관찰 MONITOR 세션입니다."
    strategies = strategy_rows(portfolio_rows())
    strategy = (
        _operational_strategy(
            strategies,
            deployment_id=requested_deployment,
            strategy_id=requested_strategy,
            portfolio_id=requested_portfolio,
        )
        if explicit_context
        else _operational_strategy(
            strategies,
            deployment_id=str(STATE.get("selected_deployment_id") or ""),
            strategy_id=str(STATE.get("selected_strategy_id") or ""),
            portfolio_id=requested_portfolio,
        )
    )
    if strategy is None:
        if mode == "MONITOR" and not explicit_context:
            return None, "MONITOR 세션은 선택 가능한 Deployment 없이 관찰 모드로 시작합니다."
        raise ValueError(
            "요청한 Live Deployment를 선택할 수 없습니다."
            if explicit_context
            else "현재 Live Deployment를 선택할 수 없습니다."
        )
    actual_deployment = str(strategy.get("deployment_id") or "")
    actual_strategy = str(strategy.get("strategy_id") or "")
    actual_portfolio = str(
        (strategy.get("portfolio_gate") or {}).get("portfolioId")
        if isinstance(strategy.get("portfolio_gate"), dict)
        else ""
    )
    context_mismatches = [
        label
        for label, requested, actual in (
            ("deployment", requested_deployment, actual_deployment),
            ("strategy", requested_strategy, actual_strategy),
            ("portfolio", requested_portfolio, actual_portfolio),
        )
        if requested and requested != actual
    ]
    if context_mismatches:
        raise ValueError(
            "요청한 Live 실행 컨텍스트가 Artifact와 일치하지 않습니다: "
            + ", ".join(context_mismatches)
        )
    expected_profile = "stock" if strategy_broker_id(strategy) == "kis" else "crypto"
    if profile_id != expected_profile:
        raise ValueError(
            f"요청 profile {profile_id}이 Deployment broker profile {expected_profile}과 일치하지 않습니다."
        )
    if mode in {"SMALL_LIVE", "FULL_LIVE"}:
        qualification_gate = paper_live_qualification_gate_for_strategy(strategy)
        if (
            qualification_gate.get("required") is not True
            or qualification_gate.get("ready") is not True
        ):
            raise ValueError(
                "Deployment에 고정된 exact Paper Evidence/Final binding을 "
                "검증하기 전에는 Live runtime을 시작할 수 없습니다: "
                + str(qualification_gate.get("detail") or "qualification missing")
            )
    manifest = ensure_operational_deployment_manifest(strategy)
    deployment_binding = (
        dict(manifest.metadata.get("deploymentBinding"))
        if isinstance(manifest.metadata.get("deploymentBinding"), dict)
        else {}
    )
    if mode in {"SMALL_LIVE", "FULL_LIVE"} and not _live_deployment_binding_is_executable(
        deployment_binding,
        mode=mode,
    ):
        raise ValueError(
            "현재 DeploymentStore revision/lifecycle/permission binding을 "
            "정확히 봉인할 수 없어 Live runtime을 차단했습니다."
        )
    paper_bindings = [
        dict(item)
        for item in manifest.metadata.get("paperFinalBindings", [])
        if isinstance(item, dict)
    ]
    if mode in {"SMALL_LIVE", "FULL_LIVE"} and (
        not paper_bindings
        or any(item.get("ready") is not True for item in paper_bindings)
    ):
        raise ValueError(
            "Portfolio의 모든 Strategy Instance에 exact Paper Final binding이 "
            "고정되지 않아 Live runtime을 차단했습니다."
        )
    if mode in {"SMALL_LIVE", "FULL_LIVE"} and manifest.portfolio_artifact_hash:
        manifest_portfolio = (
            manifest.metadata.get("portfolioArtifact")
            if isinstance(manifest.metadata.get("portfolioArtifact"), dict)
            else {}
        )
        if (
            str(manifest_portfolio.get("artifactHash") or "").lower()
            != str(manifest.portfolio_artifact_hash or "").lower()
            or any(
                str(item.get("paperPortfolioArtifactId") or "")
                != str(manifest_portfolio.get("artifactId") or "")
                or str(item.get("paperPortfolioArtifactHash") or "").lower()
                != str(manifest.portfolio_artifact_hash or "").lower()
                for item in paper_bindings
            )
        ):
            raise ValueError(
                "현재 Portfolio Artifact hash가 Live Deployment/Paper final "
                "binding과 일치하지 않습니다."
            )
    latest_preflight = OPERATIONAL_GOVERNANCE.latest_preflight_for_deployment(
        manifest.deployment_id
    )
    preflight_id = latest_preflight.snapshot_id if latest_preflight is not None else ""
    if mode in {"SMALL_LIVE", "FULL_LIVE"}:
        if not real_orders_enabled():
            raise ValueError("LIVE_TRADER_ENABLE_REAL_ORDERS=true가 필요합니다.")
        if not preflight_id:
            raise ValueError("현재 Deployment의 Preflight Snapshot을 먼저 실행하세요.")
        validity = OPERATIONAL_GOVERNANCE.preflight_validity(preflight_id)
        if validity.get("valid") is not True:
            raise ValueError(
                "Preflight Snapshot이 유효하지 않습니다: "
                + ", ".join(str(item) for item in validity.get("reasons", []))
            )
        # Re-resolve from disk after preflight and immediately before creating
        # the runtime session.  A Deployment revision, permission digest,
        # Artifact/Paper pin, or exact Portfolio hash changed during preflight
        # must never inherit the earlier manifest/session authority.
        current_strategy = _operational_strategy(
            strategy_rows(portfolio_rows()),
            deployment_id=actual_deployment,
            strategy_id=actual_strategy,
            portfolio_id=actual_portfolio,
        )
        if current_strategy is None:
            raise ValueError(
                "Preflight 이후 현재 Live Deployment 컨텍스트를 다시 찾을 수 없습니다."
            )
        current_manifest_inputs = _operational_manifest_inputs(
            current_strategy
        )
        if not _operational_manifest_matches_inputs(
            manifest,
            current_manifest_inputs,
        ):
            raise ValueError(
                "Preflight 중 Deployment revision/permission 또는 exact "
                "Artifact/Paper/Portfolio binding이 변경되었습니다."
            )
        strategy = current_strategy
    session = OPERATIONAL_GOVERNANCE.create_runtime_session(
        deployment_id=manifest.deployment_id,
        deployment_manifest_hash=manifest.manifest_hash,
        profile=profile_id,
        mode=mode,
        runtime_instance_id=f"desktop-{os.getpid()}-{secrets.token_hex(8)}",
        preflight_snapshot_id=preflight_id if mode in {"SMALL_LIVE", "FULL_LIVE"} else "",
        metadata={
            "portfolioId": str((strategy.get("portfolio_gate") or {}).get("portfolioId") or ""),
            "strategyId": str(strategy.get("strategy_id") or ""),
            "brokerId": strategy_broker_id(strategy),
            "symbol": str(strategy.get("symbol") or ""),
            "deploymentBinding": deployment_binding,
            "deploymentBindingHash": str(
                deployment_binding.get("bindingHash") or ""
            ),
            "portfolioArtifact": dict(
                manifest.metadata.get("portfolioArtifact")
                if isinstance(manifest.metadata.get("portfolioArtifact"), dict)
                else {}
            ),
        },
    )
    session = OPERATIONAL_GOVERNANCE.transition_runtime_session(
        session.session_id,
        "STARTING",
        actor="live_trader.desktop",
        event_type="RUNTIME_START_REQUESTED",
        payload={"profile": profile_id, "mode": mode},
    )
    STATE["selected_deployment_id"] = manifest.deployment_id
    STATE["selected_strategy_id"] = str(strategy.get("strategy_id") or "")
    STATE.setdefault("active_runtime_session_ids", {})[profile_id] = session.session_id
    return session, "운영 거버넌스 Session을 생성했습니다."


def _finish_operational_runtime_start(session: object | None, ok: bool, reason: str) -> None:
    session_id = str(getattr(session, "session_id", "") or "")
    if not session_id:
        return
    try:
        OPERATIONAL_GOVERNANCE.transition_runtime_session(
            session_id,
            "RUNNING" if ok else "FAILED",
            actor="live_trader.desktop",
            event_type="RUNTIME_STARTED" if ok else "RUNTIME_START_FAILED",
            payload={"detail": str(reason or "")[:500]},
        )
    except (OSError, sqlite3.Error, ValueError):
        STATE["new_entries_blocked"] = True


def _restore_previous_runtime_session_binding(
    profile_id: str,
    failed_session: object | None,
    previous_session_id: str,
) -> None:
    failed_session_id = str(getattr(failed_session, "session_id", "") or "")
    active = STATE.setdefault("active_runtime_session_ids", {})
    if not isinstance(active, dict) or not failed_session_id:
        return
    if str(active.get(profile_id) or "") != failed_session_id:
        return
    if previous_session_id:
        active[profile_id] = previous_session_id
    else:
        active.pop(profile_id, None)


@_serialized_safety_mutation
def start_functional_test_runtime(
    workspace: dict[str, Any],
    *,
    confirmed: bool,
    target_key: str = "",
    safety_confirmation: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Explicitly start the selected, already activated KIS test runtime.

    The readiness workspace remains incapable of submitting an order. This
    bridge selects the exact current candidate and enters the separately
    sealed FUNCTIONAL_TEST SMALL_LIVE runtime. Its permit, activation,
    reconciliation, account, scope, cap, and final broker-side checks remain
    mandatory, and its evidence can never be used for promotion.
    """

    def blocked(reason: str) -> dict[str, Any]:
        return {
            "ok": False,
            "reason": reason,
            "runtimeStarted": False,
            "brokerSubmissionPerformed": False,
            "promotionEligible": False,
            "snapshot": snapshot(),
        }

    if confirmed is not True:
        return blocked("FUNCTIONAL_TEST runtime 시작은 명시 확인이 필요합니다.")
    if STATE.get("operator_confirmed") is not True:
        return blocked("FUNCTIONAL_TEST runtime 시작 전 Live 운용 확인이 필요합니다.")

    # KIS permits only one WebSocket session for the configured app key. The
    # stock controller owns one feed/supervisor lifecycle, so never attempt to
    # replace or overlap it from this explicit bridge.  A STOPPING worker is
    # still an owner until its thread has actually exited.
    runtime_snapshot = LIVE_CONTINUOUS_CONTROLLER.snapshot()
    runtime_profiles = (
        runtime_snapshot.get("profiles")
        if isinstance(runtime_snapshot.get("profiles"), dict)
        else {}
    )
    stock_runtime = (
        runtime_profiles.get("stock")
        if isinstance(runtime_profiles.get("stock"), dict)
        else {}
    )
    stock_phase = str(stock_runtime.get("phase") or "").strip().upper()
    if stock_runtime.get("running") is True or stock_phase in {
        "STARTING",
        "RUNNING",
        "DEGRADED",
        "STOPPING",
    }:
        purpose = str(
            stock_runtime.get("executionPurpose") or "STANDARD"
        ).strip().upper()
        return blocked(
            "기존 stock runtime이 KIS WebSocket을 소유하고 있어 "
            "FUNCTIONAL_TEST 시작을 차단했습니다. 먼저 기존 runtime을 완전히 "
            f"정지하세요. (phase={stock_phase or 'UNKNOWN'}, purpose={purpose})"
        )
    if not isinstance(workspace, dict):
        return blocked("FUNCTIONAL_TEST workspace snapshot이 없습니다.")
    if (
        str(workspace.get("environment") or "").strip().upper()
        != FUNCTIONAL_TEST_ENVIRONMENT
    ):
        return blocked("FUNCTIONAL_TEST workspace 환경이 KIS_LIVE가 아닙니다.")
    current = (
        workspace.get("current")
        if isinstance(workspace.get("current"), dict)
        else {}
    )
    if workspace.get("status") != "ACTIVE" or current.get("ready") is not True:
        blockers = ", ".join(
            str(item) for item in current.get("blockers") or []
        )
        return blocked(
            "FUNCTIONAL_TEST 허가와 오늘의 활성화를 먼저 완료하세요."
            + (f" ({blockers})" if blockers else "")
        )
    selected_key = str(current.get("selectedTargetKey") or "").strip()
    requested_key = str(target_key or "").strip()
    if not selected_key or (requested_key and requested_key != selected_key):
        return blocked("요청한 FUNCTIONAL_TEST target이 현재 활성 허가와 다릅니다.")
    candidates = [
        item
        for item in workspace.get("candidates", [])
        if isinstance(item, dict)
    ]
    candidate = next(
        (item for item in candidates if str(item.get("key") or "") == selected_key),
        None,
    )
    if candidate is None or candidate.get("available") is not True:
        return blocked("현재 활성 FUNCTIONAL_TEST Artifact binding을 찾을 수 없습니다.")
    runtime_strategy_id = str(
        candidate.get("runtimeStrategyId")
        or candidate.get("strategyId")
        or ""
    ).strip()
    if not runtime_strategy_id:
        return blocked("FUNCTIONAL_TEST runtime lead Strategy가 없습니다.")
    portfolio_id = str(candidate.get("portfolioId") or "").strip()
    candidate_binding = (
        candidate.get("binding")
        if isinstance(candidate.get("binding"), dict)
        else {}
    )
    challenge = consume_safety_confirmation(
        "FUNCTIONAL_TEST_START",
        safety_confirmation,
        {"targetKey": requested_key or selected_key},
    )
    if challenge.get("ok") is not True:
        return blocked(
            str(
                challenge.get("reason")
                or "safety-confirmation-required"
            )
        )
    result = start_continuous_runtime(
        "stock",
        "SMALL_LIVE",
        portfolio_id,
        "",
        runtime_strategy_id,
        FUNCTIONAL_TEST_EXECUTION_PURPOSE,
        {
            "functional_test_target_key": selected_key,
            "functional_test_portfolio_only": (
                str(candidate.get("kind") or "").upper() == "PORTFOLIO"
            ),
            "marketGroup": str(candidate_binding.get("marketGroup") or ""),
            "portfolioRequired": bool(
                candidate_binding.get("portfolioRequired") is True
            ),
            "symbols": list(candidate_binding.get("symbols") or []),
            "executionRoute": str(
                candidate_binding.get("executionRoute") or ""
            ),
            "settlementCurrency": str(
                candidate_binding.get("settlementCurrency") or ""
            ),
            "exchanges": list(candidate_binding.get("exchanges") or []),
            "symbolRoutes": list(candidate_binding.get("symbolRoutes") or []),
            "routeScopeHash": str(
                candidate_binding.get("routeScopeHash") or ""
            ),
            "exchange": str(
                (
                    (candidate_binding.get("symbolRoutes") or [{}])[0]
                    if isinstance(candidate_binding.get("symbolRoutes"), list)
                    and candidate_binding.get("symbolRoutes")
                    else {}
                ).get("exchange")
                or ""
            ),
            "promotion_eligible": False,
            "use_as_promotion_evidence": False,
            "full_live_requested": False,
        },
        _functional_test_capability=_FUNCTIONAL_TEST_START_CAPABILITY,
    )
    result["runtimeStarted"] = result.get("ok") is True
    result["brokerSubmissionPerformed"] = False
    result["promotionEligible"] = False
    result["executionPurpose"] = FUNCTIONAL_TEST_EXECUTION_PURPOSE
    result["selectedTargetKey"] = selected_key
    return result


@_serialized_safety_mutation
@_serialized_upbit_order_authority
@_two_phase_kis_route_control("START")
def start_continuous_runtime(
    profile_id: str,
    mode: str,
    portfolio_id: str = "",
    deployment_id: str = "",
    strategy_id: str = "",
    execution_purpose: str = "",
    functional_test_context: dict[str, Any] | None = None,
    *,
    _functional_test_capability: object | None = None,
) -> dict[str, Any]:
    normalized_profile = "stock" if profile_id == "stock" else "crypto"
    normalized_mode = normalize_runtime_mode(mode)
    normalized_purpose = str(execution_purpose or "").strip().upper()
    if _upbit_functional_durable_authority_open():
        return {
            "ok": False,
            "reason": "upbit-functional-session-closes-ordinary-runtime-route",
            "runtimeStarted": False,
            "brokerSubmissionPerformed": False,
            "snapshot": snapshot(),
        }
    if normalized_purpose not in {"", FUNCTIONAL_TEST_EXECUTION_PURPOSE}:
        return {
            "ok": False,
            "reason": f"unsupported execution purpose: {normalized_purpose}",
            "snapshot": snapshot(),
        }
    if (
        normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE
        and _functional_test_capability is not _FUNCTIONAL_TEST_START_CAPABILITY
    ):
        return {
            "ok": False,
            "reason": (
                "FUNCTIONAL_TEST runtime은 전용 2단계 확인 시작 경로에서만 "
                "실행할 수 있습니다."
            ),
            "runtimeStarted": False,
            "brokerSubmissionPerformed": False,
            "snapshot": snapshot(),
        }
    if normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE and (
        normalized_profile != "stock" or normalized_mode != "SMALL_LIVE"
    ):
        return {
            "ok": False,
            "reason": "FUNCTIONAL_TEST requires stock/SMALL_LIVE",
            "snapshot": snapshot(),
        }
    governance_session: object | None = None
    previous_session_id = str(
        (STATE.get("active_runtime_session_ids") or {}).get(normalized_profile)
        or ""
    )
    try:
        if normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE:
            governance_session, _governance_reason = (
                _prepare_functional_test_runtime_session(
                    normalized_profile,
                    normalized_mode,
                    portfolio_id,
                    strategy_id,
                )
            )
        else:
            governance_session, _governance_reason = (
                _prepare_operational_runtime_session(
                    normalized_profile,
                    normalized_mode,
                    portfolio_id,
                    deployment_id,
                    strategy_id,
                )
            )
    except (OSError, sqlite3.Error, ValueError) as exc:
        STATE["new_entries_blocked"] = True
        append_audit(
            "danger",
            "Runtime Session",
            f"{normalized_mode} 시작 차단: {str(exc)[:300]}",
        )
        return {"ok": False, "reason": str(exc), "snapshot": snapshot()}
    functional_execution_observation: dict[str, Any] = {}
    functional_execution_stream_owned = False
    if normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE:
        stop_functional_test_runtime_guard()
        (
            observation_allowed,
            observation_reason,
            functional_execution_observation,
        ) = ensure_functional_test_execution_observation()
        functional_execution_stream_owned = bool(
            functional_execution_observation.get("owned")
        )
        if not observation_allowed:
            _finish_operational_runtime_start(
                governance_session,
                False,
                observation_reason,
            )
            _restore_previous_runtime_session_binding(
                normalized_profile,
                governance_session,
                previous_session_id,
            )
            append_audit(
                "danger",
                "FUNCTIONAL_TEST Runtime Guard",
                f"KIS 체결 관측 시작 차단: {observation_reason}",
            )
            return {
                "ok": False,
                "reason": observation_reason,
                "functional_test_execution_observation": (
                    functional_execution_observation
                ),
                "snapshot": snapshot(),
            }
    session_metadata = (
        dict(getattr(governance_session, "metadata", {}) or {})
        if governance_session is not None
        else {}
    )
    bound_portfolio_id = str(
        session_metadata.get("portfolioId") or portfolio_id or ""
    ).strip()
    bound_strategy_id = str(
        session_metadata.get("strategyId") or strategy_id or ""
    ).strip()
    bound_deployment_id = str(
        (
            session_metadata.get("runtimeDeploymentId")
            if normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE
            else getattr(governance_session, "deployment_id", "")
        )
        or deployment_id
        or ""
    ).strip()
    controller_functional_context = (
        {
            **(
                functional_test_context
                if isinstance(functional_test_context, dict)
                else {}
            ),
            "functional_test_session_id": str(
                getattr(governance_session, "session_id", "") or ""
            ),
            "functional_test_permit_id": str(
                session_metadata.get("permitId") or ""
            ),
            "functional_test_permit_hash": str(
                session_metadata.get("permitHash") or ""
            ),
            "functional_test_account_fingerprint": str(
                session_metadata.get("accountFingerprint") or ""
            ),
            "functional_test_activation_token_id": str(
                session_metadata.get("activationTokenId") or ""
            ),
            "functional_test_activation_hash": str(
                session_metadata.get("activationHash") or ""
            ),
            "promotion_eligible": False,
            "use_as_promotion_evidence": False,
            "full_live_requested": False,
        }
        if normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE
        else functional_test_context
    )
    with RUNTIME_CONTROL_LOCK:
        try:
            start_args = (
                normalized_profile,
                normalized_mode,
                bound_portfolio_id,
                bound_strategy_id,
                bound_deployment_id,
            )
            if normalized_purpose or controller_functional_context is not None:
                result = LIVE_CONTINUOUS_CONTROLLER.start(
                    *start_args,
                    normalized_purpose,
                    controller_functional_context,
                )
            else:
                # Preserve the established controller call contract for every
                # ordinary runtime. FUNCTIONAL_TEST is the only caller that
                # needs the two explicit, non-promotional arguments.
                result = LIVE_CONTINUOUS_CONTROLLER.start(*start_args)
        except Exception as exc:
            if functional_execution_stream_owned:
                LIVE_EXECUTION_STREAMS.stop_brokers(
                    ("kis",),
                    timeout=25.0,
                )
            _finish_operational_runtime_start(governance_session, False, str(exc))
            _restore_previous_runtime_session_binding(
                normalized_profile,
                governance_session,
                previous_session_id,
            )
            raise
        if result.get("ok"):
            with RUNTIME_MODE_LOCK:
                sync_runtime_profile_mode(
                    normalized_profile,
                    normalized_mode,
                    action=f"Continuous runtime {normalized_mode} 동기화",
                )
                result["snapshot"] = snapshot()
        _finish_operational_runtime_start(
            governance_session,
            bool(result.get("ok")),
            str(result.get("reason") or ""),
        )
        if (
            result.get("ok")
            and normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE
            and governance_session is not None
        ):
            result["functional_test_guard"] = (
                start_functional_test_runtime_guard(
                    str(getattr(governance_session, "session_id", "") or ""),
                    execution_stream_owned=functional_execution_stream_owned,
                )
            )
            result["functional_test_execution_observation"] = (
                functional_execution_observation
            )
        if not result.get("ok"):
            if functional_execution_stream_owned:
                LIVE_EXECUTION_STREAMS.stop_brokers(
                    ("kis",),
                    timeout=25.0,
                )
            _restore_previous_runtime_session_binding(
                normalized_profile,
                governance_session,
                previous_session_id,
            )
        if governance_session is not None:
            result["runtime_session_id"] = str(
                getattr(governance_session, "session_id", "")
            )
        result["snapshot"] = snapshot()
        result["execution_purpose"] = normalized_purpose
        result["promotion_eligible"] = (
            False if normalized_purpose == FUNCTIONAL_TEST_EXECUTION_PURPOSE else None
        )
    if bound_portfolio_id and result.get("ok"):
        ArtifactMetadataStore().update(bound_portfolio_id, "portfolio", mark_used=True)
    return result


def validation_small_live_snapshot() -> dict[str, Any]:
    """Read the immutable validation plan without changing live permissions."""

    from .validation_small_live import validation_plan_snapshot

    return validation_plan_snapshot()


def run_validation_small_live_once(
    validation_strategy_instance_id: str,
) -> dict[str, Any]:
    """Evaluate one confirmed bar in MONITOR with no OrderIntent path."""

    from .validation_small_live import (
        evaluate_validation_candidate_once,
    )

    candidate_id = str(validation_strategy_instance_id or "").strip()
    if not candidate_id:
        return {
            "ok": False,
            "reason": "검증 후보 ID가 필요합니다.",
            "validation": validation_small_live_snapshot(),
            "snapshot": snapshot(),
        }
    try:
        result = evaluate_validation_candidate_once(candidate_id)
    except Exception as exc:
        reason = str(exc) or type(exc).__name__
        append_audit(
            "danger",
            "Validation MONITOR",
            f"{candidate_id} 1회 평가 차단: {reason}",
        )
        return {
            "ok": False,
            "reason": reason,
            "validation": validation_small_live_snapshot(),
            "snapshot": snapshot(),
        }
    decision = (
        result.get("decision")
        if isinstance(result.get("decision"), dict)
        else {}
    )
    append_audit(
        "info",
        "Validation MONITOR",
        (
            f"{result.get('symbol')} {result.get('timeframe')} "
            f"{decision.get('signal', 'HOLD')}: "
            f"{decision.get('reason', '평가 완료')} · 주문 경로 없음"
        ),
    )
    return {
        **result,
        "reason": "MONITOR 확정 봉 1회 평가 완료 · 주문 경로 없음",
        "validation": validation_small_live_snapshot(),
        "snapshot": snapshot(),
    }


@_two_phase_kis_route_control("STOP")
def stop_continuous_runtime(profile_id: str = "") -> dict[str, Any]:
    normalized_profile = (
        profile_id if profile_id in {"stock", "crypto"} else ""
    )
    target_profiles = (
        (normalized_profile,)
        if normalized_profile
        else ("stock", "crypto")
    )
    governance_sessions: list[tuple[str, str]] = []
    for target in target_profiles:
        session_id = str(
            (STATE.get("active_runtime_session_ids") or {}).get(target) or ""
        )
        if not session_id:
            continue
        try:
            session = OPERATIONAL_GOVERNANCE.get_runtime_session(session_id)
            if session is not None and session.lifecycle in {"RUNNING", "DEGRADED"}:
                session = OPERATIONAL_GOVERNANCE.transition_runtime_session(
                    session_id,
                    "DRAINING",
                    actor="live_trader.desktop",
                    event_type="RUNTIME_DRAIN_REQUESTED",
                    payload={"profile": target},
                )
            if session is not None and session.lifecycle in {"STARTING", "RUNNING", "DEGRADED", "DRAINING"}:
                OPERATIONAL_GOVERNANCE.transition_runtime_session(
                    session_id,
                    "STOPPING",
                    actor="live_trader.desktop",
                    event_type="RUNTIME_STOP_REQUESTED",
                    payload={"profile": target},
                )
            governance_sessions.append((target, session_id))
        except (OSError, sqlite3.Error, ValueError):
            STATE["new_entries_blocked"] = True
    # Controller.stop() first transitions the engine to MONITOR under
    # RUNTIME_MODE_LOCK, then releases that lock before joining the worker.
    # Holding it here across stop() would deadlock a worker that is flushing a
    # due bar through the supervisor's operation_lock.
    with RUNTIME_CONTROL_LOCK:
        result = LIVE_CONTINUOUS_CONTROLLER.stop(normalized_profile)
        if "stock" in target_profiles:
            result["functional_test_guard"] = (
                stop_functional_test_runtime_guard()
            )
        with RUNTIME_MODE_LOCK:
            for target in target_profiles:
                sync_runtime_profile_mode(
                    target,
                    "MONITOR",
                    action=(
                        "Continuous runtime 정지 동기화"
                        if result.get("ok")
                        else "Continuous runtime 정지 실패 fail-closed MONITOR"
                    ),
                )
        for target, session_id in governance_sessions:
            try:
                session = OPERATIONAL_GOVERNANCE.get_runtime_session(session_id)
                if session is not None and session.lifecycle == "STOPPING":
                    OPERATIONAL_GOVERNANCE.transition_runtime_session(
                        session_id,
                        "STOPPED" if result.get("ok") else "FAILED",
                        actor="live_trader.desktop",
                        event_type="RUNTIME_STOPPED" if result.get("ok") else "RUNTIME_STOP_FAILED",
                        payload={"profile": target, "detail": str(result.get("reason") or "")[:500]},
                    )
                if result.get("ok"):
                    STATE.setdefault("active_runtime_session_ids", {}).pop(target, None)
            except (OSError, sqlite3.Error, ValueError):
                STATE["new_entries_blocked"] = True
        result["snapshot"] = snapshot()
    return result


def stop_functional_test_runtime_safely(
    *,
    permit_id: str,
    account_fingerprint: str,
) -> dict[str, Any]:
    """Close order authority before drain; revoke pointers only afterwards.

    The caller may delete the current permit/activation pointers only when
    this function returns ``ok=True``.  A failed drain or broker
    reconciliation deliberately leaves the immutable documents available for
    recovery while the durable authority-close event blocks late orders.
    """

    normalized_permit = str(permit_id or "").strip()
    normalized_account = str(account_fingerprint or "").strip().lower()
    if not normalized_permit or not normalized_account:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-stop-scope-required",
        }
    before = functional_test_authority_mutation_assessment()
    runtime = before.get("runtime") if isinstance(before.get("runtime"), dict) else {}
    session = before.get("session") if isinstance(before.get("session"), dict) else {}
    execution_purpose = str(runtime.get("executionPurpose") or "").upper()
    session_purpose = str(session.get("executionPurpose") or "").upper()
    functional_runtime = FUNCTIONAL_TEST_EXECUTION_PURPOSE in {
        execution_purpose,
        session_purpose,
    }
    runtime_or_session_active = bool(
        runtime.get("active") is True
        or str(session.get("lifecycle") or "").upper()
        in {"STARTING", "RUNNING", "DEGRADED", "DRAINING", "STOPPING"}
    )
    if runtime_or_session_active and not functional_runtime:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-stop-nonfunctional-stock-runtime-active",
            "assessment": before,
        }
    try:
        with FUNCTIONAL_TEST_AUTHORITY_DISPATCH_LOCK:
            authority = PROGRAM_LEDGER.close_functional_test_authority(
                permit_id=normalized_permit,
                account_fingerprint=normalized_account,
                reason="operator-requested-functional-test-stop",
                occurred_at=datetime.now(timezone.utc).isoformat(),
            )
            STATE["new_entries_blocked"] = True
            STATE["manual_new_entries_blocked"] = True
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-authority-close-failed:"
            + type(exc).__name__,
        }

    # This in-memory block is an additional broad guard.  The permit-scoped
    # ProgramLedger event above is the durable source of truth checked at the
    # final KIS POST boundary and survives process restart.
    runtime_result: dict[str, Any] = {
        "ok": True,
        "reason": "functional-test-runtime-not-running",
    }
    if runtime_or_session_active:
        runtime_result = stop_continuous_runtime("stock")
        if runtime_result.get("ok") is not True:
            return {
                "ok": False,
                "status": "STOP_FAILED",
                "reason": "functional-test-runtime-drain-failed",
                "authority": authority,
                "runtime": runtime_result,
            }

    # A final end seals the complete permit, including days that were already
    # cleanly paused.  Always refresh KIS account/position/order truth before
    # the workspace may revoke its permit pointer; otherwise a night-time
    # final end could skip the last three-way reconciliation merely because
    # no runtime thread or working order is currently visible.
    requires_reconciliation = True
    poll_result: dict[str, Any] = {}
    after = functional_test_authority_mutation_assessment()
    if requires_reconciliation:
        try:
            raw_poll = poll_execution_events(
                "kis",
                force_snapshot=True,
                include_snapshot=False,
            )
            poll_result = dict(raw_poll) if isinstance(raw_poll, dict) else {}
        except Exception as exc:
            return {
                "ok": False,
                "status": "STOP_FAILED",
                "reason": "functional-test-stop-reconciliation-error:"
                + type(exc).__name__,
                "authority": authority,
                "runtime": runtime_result,
            }
        if (
            poll_result.get("ok") is not True
            or poll_result.get("coalesced") is True
            or poll_result.get("errors")
        ):
            return {
                "ok": False,
                "status": "STOP_FAILED",
                "reason": "functional-test-stop-broker-poll-incomplete",
                "authority": authority,
                "runtime": runtime_result,
                "poll": poll_result,
            }
        after = functional_test_authority_mutation_assessment(
            require_kis_reconciliation=True,
        )
        if after.get("allowed") is not True:
            return {
                "ok": False,
                "status": "STOP_FAILED",
                "reason": "functional-test-stop-reconciliation-unresolved:"
                + ",".join(str(item) for item in after.get("blockers", [])),
                "authority": authority,
                "runtime": runtime_result,
                "poll": poll_result,
                "assessment": after,
            }
    return {
        "ok": True,
        "status": "STOPPED",
        "reason": "functional-test-runtime-drained-and-reconciled",
        "authority": authority,
        "runtime": runtime_result,
        "poll": poll_result,
        "assessment": after,
    }


def pause_functional_test_runtime_safely(
    *,
    permit_id: str,
    account_fingerprint: str,
) -> dict[str, Any]:
    """Drain one functional-test day without closing its multi-day permit.

    The caller must revoke ``current-activation.json`` first while holding
    ``FUNCTIONAL_TEST_AUTHORITY_DISPATCH_LOCK``.  That revocable document is
    re-read immediately before every KIS POST, so its absence durably wins a
    race with a late order.  This routine then drains the runtime/session and
    always performs a fresh KIS poll plus reconciliation.  Unlike final stop,
    it never writes an irreversible AUTHORITY_CLOSED event.
    """

    normalized_permit = str(permit_id or "").strip()
    normalized_account = str(account_fingerprint or "").strip().lower()
    if not normalized_permit or not normalized_account:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-pause-scope-required",
        }
    try:
        with FUNCTIONAL_TEST_AUTHORITY_DISPATCH_LOCK:
            if FUNCTIONAL_TEST_CURRENT_ACTIVATION_DOCUMENT.exists():
                return {
                    "ok": False,
                    "status": "STOP_FAILED",
                    "reason": "functional-test-pause-activation-not-revoked",
                }
            authority = PROGRAM_LEDGER.functional_test_authority_status(
                permit_id=normalized_permit,
                account_fingerprint=normalized_account,
            )
            if authority.get("closed") is True:
                return {
                    "ok": False,
                    "status": "STOP_FAILED",
                    "reason": "functional-test-pause-authority-already-closed",
                    "authority": authority,
                }
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-pause-authority-check-failed:"
            + type(exc).__name__,
        }

    before = functional_test_authority_mutation_assessment()
    runtime = (
        before.get("runtime")
        if isinstance(before.get("runtime"), dict)
        else {}
    )
    session = (
        before.get("session")
        if isinstance(before.get("session"), dict)
        else {}
    )
    execution_purpose = str(runtime.get("executionPurpose") or "").upper()
    session_purpose = str(session.get("executionPurpose") or "").upper()
    runtime_or_session_active = bool(
        runtime.get("active") is True
        or str(session.get("lifecycle") or "").upper()
        in {"STARTING", "RUNNING", "DEGRADED", "DRAINING", "STOPPING"}
    )
    functional_runtime = FUNCTIONAL_TEST_EXECUTION_PURPOSE in {
        execution_purpose,
        session_purpose,
    }
    if runtime_or_session_active and not functional_runtime:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-pause-nonfunctional-stock-runtime-active",
            "authority": authority,
            "assessment": before,
        }

    runtime_result: dict[str, Any] = {
        "ok": True,
        "reason": "functional-test-runtime-not-running",
    }
    if runtime_or_session_active:
        runtime_result = stop_continuous_runtime("stock")
        if runtime_result.get("ok") is not True:
            return {
                "ok": False,
                "status": "STOP_FAILED",
                "reason": "functional-test-pause-runtime-drain-failed",
                "authority": authority,
                "runtime": runtime_result,
            }

    try:
        raw_poll = poll_execution_events(
            "kis",
            force_snapshot=True,
            include_snapshot=False,
        )
        poll_result = dict(raw_poll) if isinstance(raw_poll, dict) else {}
    except Exception as exc:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-pause-reconciliation-error:"
            + type(exc).__name__,
            "authority": authority,
            "runtime": runtime_result,
        }
    if (
        poll_result.get("ok") is not True
        or poll_result.get("coalesced") is True
        or poll_result.get("errors")
    ):
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-pause-broker-poll-incomplete",
            "authority": authority,
            "runtime": runtime_result,
            "poll": poll_result,
        }
    after = functional_test_authority_mutation_assessment(
        require_kis_reconciliation=True,
    )
    if after.get("allowed") is not True:
        return {
            "ok": False,
            "status": "STOP_FAILED",
            "reason": "functional-test-pause-reconciliation-unresolved:"
            + ",".join(str(item) for item in after.get("blockers", [])),
            "authority": authority,
            "runtime": runtime_result,
            "poll": poll_result,
            "assessment": after,
        }
    return {
        "ok": True,
        "status": "PAUSED",
        "reason": "functional-test-day-drained-and-reconciled",
        "authority": authority,
        "runtime": runtime_result,
        "poll": poll_result,
        "assessment": after,
    }


def start_execution_streams(broker_id: str = "all") -> dict[str, Any]:
    brokers = (
        "kis",
        "binance",
        "binance-futures",
        "upbit",
    ) if str(broker_id).lower().strip() in {"", "all"} else (
        str(broker_id).lower().strip(),
    )
    result = LIVE_EXECUTION_STREAMS.start(brokers)
    append_audit("info", "체결 스트림", f"실시간 체결 감시 시작: {', '.join(brokers)}")
    return {"ok": True, "reason": "execution streams started", "streams": result, "snapshot": snapshot()}


def stop_execution_streams() -> dict[str, Any]:
    result = LIVE_EXECUTION_STREAMS.stop()
    append_audit("info", "체결 스트림", "실시간 체결 감시 정지")
    return {"ok": True, "reason": "execution streams stopped", "streams": result, "snapshot": snapshot()}


def submit_test_intent() -> dict[str, Any]:
    checks = snapshot()
    intent = default_order_intent(checks, "BUY")
    return submit_order_intent(checks, intent, dry_run=bool(STATE["dry_run"]), audit_event="주문 게이트")


def recovery_state_payload() -> dict[str, Any]:
    return {
        "mode": STATE.get("mode"), "dry_run": STATE.get("dry_run"), "kill_switch": STATE.get("kill_switch"),
        "new_entries_blocked": STATE.get("new_entries_blocked"), "orders": list(STATE.get("orders", [])),
        "order_trace_index": dict(STATE.get("order_trace_index", {})),
        "strategy_runner": dict(STATE.get("strategy_runner", {})),
    }


@_serialized_safety_mutation
@_two_phase_kis_route_control("SETTINGS")
def run_recovery_drill() -> dict[str, Any]:
    checkpoint = RECOVERY_JOURNAL.save(recovery_state_payload(), reason="operator-recovery-drill", idempotency_keys=[str(item.get("idempotency_key") or "") for item in STATE.get("orders", [])])
    loaded = RECOVERY_JOURNAL.load_latest()
    verified = loaded.get("contentHash") == checkpoint.get("contentHash") and loaded.get("state") == checkpoint.get("state")
    idempotency_keys = [str(item.get("idempotency_key") or "") for item in STATE.get("orders", []) if item.get("idempotency_key")]
    reconciliation_status = reconciliation_snapshot().get("summary", {}).get("status")
    broker_reconciled = reconciliation_status == "pass"
    assurance = assess_recovery_drill(
        checkpoint_saved=bool(checkpoint.get("contentHash")),
        checkpoint_hash_verified=verified,
        idempotency_verified=len(idempotency_keys) == len(set(idempotency_keys)),
        broker_reconciled=broker_reconciled,
    )
    STATE["recovery_status"] = {
        "verified": assurance["status"] == "pass", "safeMode": bool(loaded.get("safeMode")) or assurance["safeModeRequired"],
        "generation": int(loaded.get("generation") or 0),
        "detail": "복구·멱등성·브로커 대조 훈련 통과" if assurance["status"] == "pass" else "복구 훈련 미통과: 안전 모드에서 신규 위험 차단",
        "corruptCheckpoints": loaded.get("corruptCheckpoints", []),
        "assurance": assurance,
    }
    if assurance["status"] != "pass":
        STATE["new_entries_blocked"] = True
        STATE["mode"] = "MONITOR"
    append_audit("info" if verified else "danger", "Recovery Drill", STATE["recovery_status"]["detail"])
    return {"ok": assurance["status"] == "pass", "recovery": dict(STATE["recovery_status"]), "snapshot": snapshot()}


def durable_dispatch_orders_for_restore() -> list[dict[str, Any]]:
    try:
        rows = PROGRAM_LEDGER.order_dispatch_rows(5000)
    except (AttributeError, OSError, sqlite3.Error, ValueError):
        return []
    return [
        dict(item)
        for item in rows
        if isinstance(item, dict)
        and str(item.get("order_id") or "")
        and str(item.get("idempotency_key") or "")
    ]


def merge_recovered_orders(
    checkpoint_orders: object,
    dispatch_orders: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    for item in (
        checkpoint_orders
        if isinstance(checkpoint_orders, list)
        else []
    ):
        if not isinstance(item, dict):
            continue
        order_id = str(item.get("order_id") or "")
        if order_id:
            merged[order_id] = dict(item)
    # The SQLite dispatch journal is committed immediately before the broker
    # call and is therefore newer/stronger than a recovery checkpoint.
    for item in dispatch_orders:
        order_id = str(item.get("order_id") or "")
        if order_id:
            merged[order_id] = dict(item)
    return sorted(
        merged.values(),
        key=lambda item: str(
            item.get("updated_at")
            or item.get("created_at")
            or item.get("time")
            or ""
        ),
        reverse=True,
    )[:50]


def restore_runtime_from_checkpoint() -> dict[str, Any]:
    loaded = RECOVERY_JOURNAL.load_latest()
    generation = int(loaded.get("generation") or 0)
    durable_dispatch_orders = durable_dispatch_orders_for_restore()
    durable_idempotency_keys = [
        str(item.get("idempotency_key") or "")
        for item in durable_dispatch_orders
        if str(item.get("idempotency_key") or "")
    ]
    if generation <= 0:
        STATE["orders"] = merge_recovered_orders(
            [],
            durable_dispatch_orders,
        )
        STATE["persisted_idempotency_keys"] = list(
            dict.fromkeys(durable_idempotency_keys)
        )
        STATE["mode"] = "MONITOR"
        STATE["dry_run"] = True
        STATE["new_entries_blocked"] = True
        STATE["recovery_status"] = {
            "verified": False,
            "safeMode": True,
            "generation": 0,
            "detail": "유효한 체크포인트 없음: MONITOR/신규 진입 차단 유지",
            "corruptCheckpoints": loaded.get("corruptCheckpoints", []),
        }
        append_audit("warn", "Startup Recovery", STATE["recovery_status"]["detail"])
        return dict(STATE["recovery_status"])
    recovered = loaded.get("state") if isinstance(loaded.get("state"), dict) else {}
    STATE["orders"] = merge_recovered_orders(
        recovered.get("orders"),
        durable_dispatch_orders,
    )
    STATE["order_trace_index"] = dict(recovered.get("order_trace_index", {})) if isinstance(recovered.get("order_trace_index"), dict) else {}
    if isinstance(recovered.get("strategy_runner"), dict):
        STATE["strategy_runner"].update(recovered["strategy_runner"])
    STATE["persisted_idempotency_keys"] = list(
        dict.fromkeys(
            [
                *[
                    str(item)
                    for item in loaded.get("idempotencyKeys", [])
                    if str(item)
                ],
                *durable_idempotency_keys,
            ]
        )
    )
    STATE["mode"] = "MONITOR"
    STATE["dry_run"] = True
    STATE["new_entries_blocked"] = True
    STATE["recovery_status"] = {
        "verified": not loaded.get("safeMode"), "safeMode": True, "generation": generation,
        "detail": "체크포인트 복구 완료. 브로커 reconciliation 전까지 MONITOR/신규 진입 차단",
        "corruptCheckpoints": loaded.get("corruptCheckpoints", []),
    }
    append_audit("warn", "Startup Recovery", STATE["recovery_status"]["detail"])
    return dict(STATE["recovery_status"])


@_serialized_safety_mutation
@_two_phase_kis_route_control("SETTINGS")
def run_shadow_live(payload: dict[str, Any]) -> dict[str, Any]:
    checks = snapshot()
    intent = default_order_intent(checks, str(payload.get("side") or "BUY"))
    reference = safe_float(payload.get("decision_price"), intent.reference_price)
    virtual_fill = safe_float(payload.get("virtual_fill_price"), reference)
    paper_fill = safe_float(payload.get("paper_fill_price"), 0.0)
    evidence = SHADOW_ENGINE.execute(
        ShadowOrder(
            decision_id=str(payload.get("decision_id") or f"shadow-{len(STATE.get('shadow_evidence', [])) + 1}"),
            strategy_id=intent.strategy_id,
            instrument_id=str((intent.metadata or {}).get("instrument_id") or intent.symbol),
            side=intent.side, quantity=intent.quantity, decision_price=reference, virtual_fill_price=virtual_fill,
            expected_cost_bps=safe_float(payload.get("expected_cost_bps"), safe_float((intent.metadata or {}).get("expected_cost_bps"), 0.0)),
            latency_ms=int(safe_float(payload.get("latency_ms"), 0)),
        ), paper_fill_price=paper_fill or None,
    )
    STATE.setdefault("shadow_evidence", []).insert(0, evidence)
    STATE["shadow_evidence"] = STATE["shadow_evidence"][:100]
    append_audit("info", "Shadow Live", f"브로커 전송 없이 가상 체결 기록: {evidence['contentHash'][:12]}")
    return {"ok": True, "evidence": evidence, "snapshot": snapshot()}


def runtime_operational_readiness(strategies: list[dict[str, Any]], portfolios: list[dict[str, Any]]) -> dict[str, Any]:
    bundles = [item.get("operational_readiness_bundle") for item in portfolios if isinstance(item.get("operational_readiness_bundle"), dict) and item.get("operational_readiness_bundle")]
    if not bundles:
        return {"schemaVersion": "operational-readiness-v1", "score": 0, "status": "NOT_REQUIRED", "liveEligible": False, "components": []}
    base = bundles[0]
    source = base.get("operationalReadiness") if isinstance(base.get("operationalReadiness"), dict) else {}
    components = source.get("components") if isinstance(source.get("components"), list) else []
    paper_ready = any((item.get("paper_portfolio_evidence_gate") or {}).get("ready") is True for item in strategies)
    execution_component = next((item for item in components if isinstance(item, dict) and item.get("id") == "executionQuality"), {})
    execution_ok = bool(execution_component.get("passed") or safe_float(execution_component.get("awarded"), 0) > 0 or STATE.get("shadow_evidence"))
    capacity_ok = all(
        not (item.get("advanced_operations") or {}).get("capacity")
        or all(entry.get("allowed") is True for entry in (item.get("advanced_operations") or {}).get("capacity", []) if isinstance(entry, dict))
        for item in portfolios
    )
    return operational_readiness({
        "dataIntegrity": next((component.get("passed") for component in components if isinstance(component, dict) and component.get("id") == "dataIntegrity"), False),
        "artifactReproducibility": bool(base.get("contentHash")), "paperObservation": paper_ready,
        "executionQuality": execution_ok, "capacityHeadroom": capacity_ok,
        "recoveryVerified": STATE.get("recovery_status", {}).get("verified") is True and STATE.get("recovery_status", {}).get("safeMode") is False,
        "policyReplayPassed": bool(STATE.get("policy_replays")),
        "operatorDrill": bool(STATE.get("preflight_last_run")) and all(STATE.get("checklist", {}).values()),
    })


@_serialized_safety_mutation
@_two_phase_kis_route_control("SETTINGS")
def run_policy_replay(payload: dict[str, Any]) -> dict[str, Any]:
    checks = snapshot()
    intent = default_order_intent(checks, str(payload.get("side") or "BUY"))
    intent = replace(
        intent,
        quantity=max(0.0, safe_float(payload.get("quantity"), intent.quantity)),
        reference_price=max(0.0, safe_float(payload.get("referencePrice"), intent.reference_price)),
        metadata={
            **intent.metadata,
            "event_id": str(payload.get("eventId") or "live-policy-replay"),
            "current_weight": safe_float(payload.get("currentWeight"), 0.0),
            "portfolio_equity": safe_float(payload.get("portfolioEquity"), float(STATE["risk_settings"]["strategy_capital_limit_krw"])),
            "expected_alpha_bps": safe_float(payload.get("expectedAlphaBps"), 10.0),
            "expected_cost_bps": safe_float(payload.get("expectedCostBps"), 5.0),
        },
    )
    alternative = payload.get("alternative") if isinstance(payload.get("alternative"), dict) else {}
    bundle = policy_replay_for_intent(checks, intent, alternative)
    STATE.setdefault("policy_replays", [])
    STATE["policy_replays"].insert(0, bundle)
    STATE["policy_replays"] = STATE["policy_replays"][:20]
    append_audit("info", "정책 Replay", f"결정 변경 {bundle['changedDecisionCount']} / {bundle['eventCount']}")
    return {"ok": True, "bundle": bundle, "snapshot": checks}


def run_strategy_cycle(profile_id: str) -> dict[str, Any]:
    checks = snapshot()
    normalized_profile = "stock" if profile_id == "stock" else "crypto"
    strategy_executions = strategy_executions_for_profile(checks, normalized_profile)
    if not strategy_executions:
        reason = f"{normalized_profile} 프로필에 live_small_eligible/live_eligible 전략이 없습니다."
        STATE["strategy_runner"].update({
            "last_run": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "last_market_verified": False,
            "last_profile": normalized_profile,
            "last_strategy": "-",
            "last_signal": "-",
            "last_action": reason,
        })
        append_audit("warn", "전략 Runner", reason)
        return {"ok": False, "reason": reason, "snapshot": snapshot()}

    if len(strategy_executions) > 1:
        return run_multi_strategy_cycle(checks, normalized_profile, strategy_executions)

    execution = strategy_executions[0][1]

    STATE["strategy_runner"].update({
        "last_run": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "last_market_event_at": execution.market_data.occurred_at,
        "last_market_received_at": execution.market_data.received_at,
        "last_market_timeframe": str(strategy_executions[0][0].get("timeframe") or ""),
        "last_market_verified": execution.metadata.get("market_data_verified") is True,
        "last_profile": normalized_profile,
        "last_strategy": execution.artifact_id,
        "last_signal": execution.signal or "-",
        "last_action": execution.reason,
    })
    if execution.intent is None:
        append_audit("info", "전략 Runner", f"{execution.artifact_id}: {execution.reason}")
        return {"ok": True, "reason": execution.reason, "runner_report": execution.to_dict(), "snapshot": snapshot()}

    result = submit_order_intent(
        checks,
        execution.intent,
        dry_run=bool(STATE["dry_run"]),
        audit_event="전략 Runner",
        runner_report=execution,
    )
    STATE["strategy_runner"]["last_action"] = f"{execution.signal} -> {result['reason']}"
    result["runner_report"] = execution.to_dict()
    return result


def run_multi_strategy_cycle(checks: dict[str, Any], profile_id: str, strategy_executions: list[tuple[dict[str, Any], StrategyExecutionResult]]) -> dict[str, Any]:
    observed_at = datetime.now(timezone.utc).isoformat()
    signals: list[SleeveSignal] = []
    policies: dict[str, InstrumentTradePolicy] = {}
    broker_by_instrument: dict[str, str] = {}
    execution_by_instance: dict[str, tuple[dict[str, Any], StrategyExecutionResult]] = {}
    for index, (strategy, execution) in enumerate(strategy_executions):
        gate = strategy.get("portfolio_gate") if isinstance(strategy.get("portfolio_gate"), dict) else {}
        instance = gate.get("instance") if isinstance(gate.get("instance"), dict) else {}
        instance_id = str(instance.get("instanceId") or f"{strategy.get('strategy_id', 'strategy')}:{index}")
        instrument_id = str(strategy.get("instrument_id") or strategy.get("symbol") or instance_id)
        allocation = safe_float(gate.get("policyTargetWeight"), safe_float(gate.get("targetWeight"), 1 / max(1, len(strategy_executions))))
        signals.append(SleeveSignal(
            strategy_instance_id=instance_id,
            strategy_id=str(strategy.get("strategy_id") or execution.artifact_id),
            deployment_id=str(strategy.get("deployment_id") or ""),
            instrument_id=instrument_id,
            symbol=str(strategy.get("symbol") or "UNKNOWN"),
            signal=str(execution.signal or "HOLD"),
            occurred_at=observed_at,
            reference_price=max(0.0, strategy_float(strategy, "reference_price", "last_price", default=0.0)),
            allocation_weight=max(0.0, allocation),
            confidence=safe_float(strategy.get("score"), 100.0) / 100 if str(strategy.get("score") or "").replace(".", "", 1).isdigit() else 1.0,
            reason=execution.reason,
        ))
        policies[instrument_id] = InstrumentTradePolicy(
            instrument_id=instrument_id,
            asset_class=str(strategy.get("asset") or "UNKNOWN"),
            market_type=str(strategy.get("market_type") or "spot"),
            allow_short=strategy.get("allow_short") is True,
            maximum_absolute_weight=min(1.0, max(0.0, safe_float(gate.get("maxSymbolWeightPct"), 100.0) / 100)),
        )
        broker_by_instrument[instrument_id] = strategy_broker_id(strategy)
        execution_by_instance[instance_id] = (strategy, execution)

    current_sleeves = {str(key): safe_float(value, 0.0) for key, value in STATE.get("strategy_sleeves", {}).items()}
    current_weights: dict[str, float] = {}
    current_quantities: dict[str, float] = {}
    for signal in signals:
        current_weights[signal.instrument_id] = current_weights.get(signal.instrument_id, 0.0) + current_sleeves.get(signal.strategy_instance_id, 0.0)
        current_quantities.setdefault(
            signal.instrument_id,
            broker_position_quantity(
                signal.symbol,
                broker_by_instrument.get(signal.instrument_id, ""),
            ),
        )
    portfolio_equity = max(float(STATE["risk_settings"]["strategy_capital_limit_krw"]), 1.0)
    plans = LIVE_MULTI_COORDINATOR.coordinate(
        signals, policies=policies, current_sleeve_weights=current_sleeves,
        current_net_weights=current_weights, current_net_quantities=current_quantities,
        portfolio_equity=portfolio_equity,
    )
    order_results: list[dict[str, Any]] = []
    for plan in plans:
        if plan.blocked or plan.side == "HOLD" or plan.quantity <= 0:
            continue
        preferred_signal = next((signal for signal in signals if signal.instrument_id == plan.instrument_id and signal.signal.upper() == plan.side), None)
        lead_signal = preferred_signal or next(signal for signal in signals if signal.instrument_id == plan.instrument_id)
        strategy, execution = execution_by_instance[lead_signal.strategy_instance_id]
        source_intent = execution.intent or default_order_intent(checks, plan.side)
        contributing_strategies = [
            execution_by_instance[instance_id][0]
            for instance_id in plan.sleeve_targets
            if instance_id in execution_by_instance
        ]
        futures_policy = (
            _intersect_futures_execution_policies(
                [
                    dict(
                        item.get("futures_execution_policy")
                        if isinstance(
                            item.get("futures_execution_policy"),
                            dict,
                        )
                        else futures_execution_policy_from_artifact(item)
                    )
                    for item in contributing_strategies
                ]
            )
            if strategy_broker_id(strategy) == "binance-futures"
            else {}
        )
        futures_metadata = (
            {
                "futures_execution_policy": futures_policy,
                "futures_policy_valid": futures_policy.get("valid") is True,
                "futures_policy_blockers": list(
                    futures_policy.get("blockers") or []
                ),
                "max_leverage": safe_float(
                    futures_policy.get("maxLeverageMultiplier"),
                    1.0,
                ),
                "required_margin_type": str(
                    futures_policy.get("marginMode") or "ISOLATED"
                ),
                "per_trade_risk_pct": safe_float(
                    futures_policy.get("perTradeRiskPercent"),
                    0.5,
                ),
                "max_notional_pct": safe_float(
                    futures_policy.get("maxNotionalPercent"),
                    10.0,
                ),
            }
            if futures_policy
            else {}
        )
        intent = replace(
            source_intent,
            strategy_id=str(strategy.get("strategy_id") or execution.artifact_id),
            side=plan.side,
            quantity=plan.quantity,
            reference_price=lead_signal.reference_price,
            metadata={
                **(source_intent.metadata if isinstance(source_intent.metadata, dict) else {}),
                "multi_strategy": True,
                "strategy_instance_id": lead_signal.strategy_instance_id,
                "strategy_instance_ids": list(plan.sleeve_targets),
                "contributing_strategy_ids": [
                    str(item.get("strategy_id") or "")
                    for item in contributing_strategies
                    if str(item.get("strategy_id") or "")
                ],
                "sleeve_targets": plan.sleeve_targets,
                "target_revision": plan.target_revision,
                "instrument_id": plan.instrument_id,
                "current_weight": plan.current_weight,
                "portfolio_equity": portfolio_equity,
                "expected_alpha_bps": 10.0,
                "expected_cost_bps": 5.0,
                "risk_reducing": abs(plan.target_weight) < abs(plan.current_weight),
                "shortable": plan.shortable,
                **futures_metadata,
            },
            reason=f"multi-strategy net target: {len(plan.sleeve_targets)} sleeves",
        )
        result = submit_order_intent(checks, intent, dry_run=bool(STATE["dry_run"]), audit_event="Multi-Strategy Runner", runner_report=execution)
        result["coordinated_plan"] = plan.to_dict()
        order_results.append(result)
        if result.get("ok"):
            STATE.setdefault("strategy_sleeves", {}).update(plan.sleeve_targets)
    STATE["strategy_runner"].update({
        "last_run": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "last_profile": profile_id,
        "last_market_event_at": max(
            (
                str(execution.market_data.occurred_at or "")
                for _, execution in strategy_executions
            ),
            default="",
        ),
        "last_market_received_at": max(
            (
                str(execution.market_data.received_at or "")
                for _, execution in strategy_executions
            ),
            default="",
        ),
        "last_market_timeframe": str(strategy_executions[0][0].get("timeframe") or ""),
        "last_market_verified": all(
            execution.metadata.get("market_data_verified") is True
            for _, execution in strategy_executions
        ),
        "last_strategy": f"{len(strategy_executions)} sleeves", "last_signal": "NET",
        "last_action": f"{len(plans)} instrument targets · {len(order_results)} net orders",
    })
    append_audit("info", "Multi-Strategy Runner", f"{len(strategy_executions)}개 Sleeve → {len(plans)}개 종목 목표 → {len(order_results)}개 순주문")
    return {
        "ok": all(item.get("ok") for item in order_results) if order_results else True,
        "reason": f"multi-strategy coordinated: {len(strategy_executions)} sleeves, {len(order_results)} net orders",
        "runner_reports": [execution.to_dict() for _, execution in strategy_executions],
        "plans": [plan.to_dict() for plan in plans],
        "orders": order_results,
        "snapshot": snapshot(),
    }


def broker_position_quantity(
    symbol: str,
    broker_id: str = "",
    position_side: str = "",
) -> float:
    positions = STATE.get("broker_reconciliation", {}).get("positions", [])
    normalized_symbol = (
        str(symbol or "")
        .upper()
        .removesuffix(".PERP")
        .replace("-", "")
    )
    normalized_broker = str(broker_id or "").strip().lower()
    aliases = {normalized_symbol}
    for quote_currency in ("USDT", "USDC", "BUSD", "BTC", "ETH"):
        if normalized_symbol.endswith(quote_currency) and len(normalized_symbol) > len(quote_currency):
            aliases.add(normalized_symbol[: -len(quote_currency)])
            break
    matching_positions = [
        item
        for item in positions
        if isinstance(item, dict)
        and (
            not normalized_broker
            or str(item.get("broker_id") or "").strip().lower()
            == normalized_broker
        )
        and (
            str(item.get("symbol") or "")
            .upper()
            .removesuffix(".PERP")
            .replace("-", "")
            in aliases
        )
    ]
    if normalized_broker == "binance-futures":
        requested_side = str(position_side or "").strip().upper()
        if requested_side in {"LONG", "SHORT", "BOTH"}:
            exact = [
                item
                for item in matching_positions
                if normalized_reconciliation_position_side(
                    item,
                    source="broker",
                )
                == requested_side
            ]
            if exact:
                matching_positions = exact
            else:
                one_way = [
                    item
                    for item in matching_positions
                    if normalized_reconciliation_position_side(
                        item,
                        source="broker",
                    )
                    == "BOTH"
                ]
                matching_positions = one_way
        else:
            active_sides = {
                normalized_reconciliation_position_side(
                    item,
                    source="broker",
                )
                for item in matching_positions
                if abs(
                    safe_float(
                        item.get("quantity"),
                        safe_float(
                            item.get("qty"),
                            safe_float(item.get("broker_qty"), 0.0),
                        ),
                    )
                )
                > 1e-12
            }
            if len(active_sides) > 1:
                raise RuntimeError(
                    "dual-side-position-ambiguous:"
                    f"{normalized_symbol}:{','.join(sorted(active_sides))}"
                )
    return sum(
        safe_float(
            item.get("quantity"),
            safe_float(item.get("qty"), safe_float(item.get("broker_qty"), 0.0)),
        )
        for item in matching_positions
    )


def find_order(order_id: str) -> dict[str, Any] | None:
    return next((order for order in STATE["orders"] if order.get("order_id") == order_id), None)


def retry_order(order_id: str) -> dict[str, Any]:
    order = find_order(order_id)
    if not order:
        return {"ok": False, "reason": "order not found", "snapshot": snapshot()}
    reason = (
        "기존 주문은 자동 재제출하지 않습니다. 다음 확정봉에서 새 주문 "
        "intent·trace·멱등성 키를 생성해 전체 주문 게이트를 다시 통과해야 합니다."
    )
    append_audit(
        "warn",
        "주문 재시도 차단",
        f"{order_id}: {reason}",
    )
    return {
        "ok": False,
        "reason": reason,
        "requires_new_confirmed_bar_intent": True,
        "snapshot": snapshot(),
    }


def _cancel_order_after_kis_route_selection(
    order_id: str,
    *,
    _official_kis_truth: dict[str, Any] | None = None,
    _kill_cleanup: bool = False,
) -> dict[str, Any]:
    order = find_order(order_id)
    if not order:
        return {"ok": False, "reason": "order not found", "snapshot": snapshot()}
    if order.get("state") == "canceled":
        return {"ok": True, "reason": "order already canceled", "snapshot": snapshot()}
    if str(order.get("state") or "").lower() == "filled":
        return {"ok": False, "reason": "filled order cannot be canceled", "snapshot": snapshot()}
    if order.get("cancel_request_id"):
        pending = str(order.get("state") or "").lower() == "cancel_pending"
        return {
            "ok": pending,
            "reason": (
                "cancel request already submitted; broker reconciliation pending"
                if pending
                else "cancel result remains unknown; broker reconciliation required"
            ),
            "cancel_request_id": str(order.get("cancel_request_id")),
            "reconciliation_required": True,
            "snapshot": snapshot(),
        }
    broker_order_id = str(order.get("broker_order_id") or "").strip()
    submitted_to_broker = (
        not bool(order.get("dry_run"))
        and broker_order_id not in {"", "-"}
        and str(order.get("queue_state") or "").lower() in {"submitted", "sent", "partially_filled"}
    )
    if submitted_to_broker:
        broker_request = order.get("broker_request") if isinstance(order.get("broker_request"), dict) else {}
        broker_response = order.get("broker_response") if isinstance(order.get("broker_response"), dict) else {}
        response_payload = broker_response.get("json") if isinstance(broker_response.get("json"), dict) else {}
        output = response_payload.get("output") if isinstance(response_payload.get("output"), dict) else {}
        broker_id = str(order.get("broker_id") or broker_request.get("broker_id") or broker_id_from_symbol(str(order.get("symbol") or ""), str(order.get("asset") or ""))).lower()
        if broker_id == "kis":
            refresh = (
                {
                    "ok": True,
                    "truth": dict(_official_kis_truth),
                    "reason": "prevalidated-kill-order-truth",
                }
                if isinstance(_official_kis_truth, dict)
                else refresh_kis_order_truth_for_kill_switch()
            )
            truth = (
                dict(refresh.get("truth"))
                if isinstance(refresh.get("truth"), dict)
                else {}
            )
            identity_allowed, identity_reason = (
                _kis_cancel_identity_is_authoritative(order, truth)
            )
        else:
            identity_allowed, identity_reason = True, ""
        if broker_id == "kis" and not identity_allowed:
            order.update(
                {
                    "queue_state": "reconcile_required",
                    "reason": identity_reason,
                    "updated_at": now_text(),
                }
            )
            append_audit(
                "danger",
                "KIS 주문 취소 차단",
                (
                    f"{order_id} · fresh official truth에서 현재의 유일한 "
                    "date·organization·ODNO working identity를 확정하지 못해 "
                    "broker cancel POST를 전송하지 않았습니다."
                ),
            )
            return {
                "ok": False,
                "reason": identity_reason,
                "reconciliation_required": True,
                "snapshot": snapshot(),
            }
        cancel_request_id = "cancel-" + hashlib.sha256(
            "|".join(
                (
                    order_id,
                    str(order.get("idempotency_key") or ""),
                    broker_id,
                    broker_order_id,
                )
            ).encode("utf-8")
        ).hexdigest()[:24]
        order.update(
            {
                "cancel_request_id": cancel_request_id,
                "cancel_requested_at": datetime.now(timezone.utc).isoformat(),
                "state": "cancel_pending",
                "queue_state": "reconcile_required",
                "reason": "broker-cancel-request-prepared",
                "next_retry_at": "-",
                "updated_at": now_text(),
            }
        )
        oms_order_id = str(order.get("oms_order_id") or "")
        managed = LIVE_OMS.orders.get(oms_order_id)
        if managed is not None:
            if managed.status == "FILLED":
                order.update({"state": "filled", "queue_state": "completed", "reason": "broker-filled"})
                return {"ok": False, "reason": "filled order cannot be canceled", "snapshot": snapshot()}
            if managed.status in {"ACKNOWLEDGED", "PARTIALLY_FILLED"}:
                try:
                    managed = LIVE_OMS.transition(
                        oms_order_id,
                        "CANCEL_PENDING",
                        "broker cancel request prepared",
                        {"cancelRequestId": cancel_request_id},
                    )
                except ValueError as exc:
                    order["reconciliation_warning"] = str(exc)
            order["oms_status"] = managed.status
        if order.get("idempotency_key"):
            try:
                cancel_checkpoint_saved = PROGRAM_LEDGER.update_order_dispatch(order)
            except (OSError, sqlite3.Error, ValueError):
                cancel_checkpoint_saved = False
            if not cancel_checkpoint_saved:
                order.update(
                    {
                        "state": "unknown_cancel_result",
                        "reason": "cancel-request-checkpoint-failed",
                    }
                )
                STATE["new_entries_blocked"] = True
                append_audit("error", "주문 취소 실패", f"{order_id} · 취소 요청 checkpoint 저장 실패")
                return {"ok": False, "reason": "cancel-request-checkpoint-failed", "snapshot": snapshot()}
        kis_kill_intent: dict[str, Any] | None = None
        kis_kill_revision = 0
        try:
            with SAFETY_CONFIRMATION_MUTATION_LOCK:
                with _ordinary_upbit_final_mutation_boundary(
                    broker_id
                ) as emergency:
                    if broker_id == "kis" and _kill_cleanup:
                        # Route -> emergency is already held.  Token issuance,
                        # exact wire sealing, durable reservation, socket and
                        # revocation therefore form one uninterrupted KIS
                        # mutation critical section.
                        with kis_authenticated_mutation_preflight(
                            mode="KILL_PREPARE"
                        ):
                            token = issue_kis_access_token()
                            prepared_cancel = build_kis_cancel_order_request(
                                {
                                    "broker_order_id": broker_order_id,
                                    "symbol": str(
                                        order.get("symbol")
                                        or broker_request.get("symbol")
                                        or ""
                                    ),
                                    "asset": str(
                                        order.get("asset")
                                        or broker_request.get("asset")
                                        or ""
                                    ),
                                    "quantity": order.get("qty")
                                    or broker_request.get("quantity")
                                    or 0,
                                    "exchange": str(
                                        broker_request.get("exchange") or ""
                                    ),
                                    "organization_no": str(
                                        order.get("organization_no")
                                        or output.get("KRX_FWDG_ORD_ORGNO")
                                        or output.get("KRX_FWDG_ORD_ORG_NO")
                                        or ""
                                    ),
                                },
                                access_token=token,
                            )
                            kis_kill_intent = (
                                build_kis_mutation_authority_intent(
                                    prepared_cancel,
                                    operation="KILL_ORDINARY_CANCEL",
                                    claim_id=(
                                        "kis-kill-cancel-"
                                        + secrets.token_hex(16)
                                    ),
                                    owned_order_key={
                                        "orderDate": str(
                                            order.get("order_date") or ""
                                        ),
                                        "organizationNo": str(
                                            order.get("organization_no")
                                            or output.get(
                                                "KRX_FWDG_ORD_ORGNO"
                                            )
                                            or output.get(
                                                "KRX_FWDG_ORD_ORG_NO"
                                            )
                                            or ""
                                        ),
                                        "orderNo": broker_order_id,
                                    },
                                )
                            )
                    if broker_id == "kis" and kis_kill_intent is not None:
                        reservation = _reserve_kis_kill_cancel_authority(
                            kis_kill_intent
                        )
                        kis_kill_revision = int(
                            reservation["killRevision"]
                        )
                    try:
                        if (
                            emergency.get("active") is True
                            and not (
                                broker_id == "kis"
                                and kis_kill_intent is not None
                                and kis_kill_revision > 0
                            )
                        ):
                            raise RuntimeError(
                                "emergency-stop-latch-broker-cancel-forbidden"
                            )
                        if broker_id == "upbit" and not real_orders_enabled():
                            raise RuntimeError(
                                "ordinary-upbit-cancel-real-orders-disabled"
                            )
                        cancel_response = LiveBrokerRouter().cancel_order(
                            broker_id,
                            broker_order_id,
                            symbol=str(order.get("symbol") or broker_request.get("symbol") or ""),
                            asset=str(order.get("asset") or broker_request.get("asset") or ""),
                            quantity=order.get("qty") or broker_request.get("quantity") or 0,
                            exchange=str(broker_request.get("exchange") or ""),
                            organization_no=str(
                                order.get("organization_no")
                                or output.get("KRX_FWDG_ORD_ORGNO")
                                or output.get("KRX_FWDG_ORD_ORG_NO")
                                or ""
                            ),
                            order_date=str(order.get("order_date") or ""),
                            **(
                                {
                                    "_kis_kill_authority_intent": kis_kill_intent,
                                    "_kis_kill_cancel_expected_revision": (
                                        kis_kill_revision
                                    ),
                                }
                                if kis_kill_intent is not None
                                else {}
                            ),
                        )
                    finally:
                        if kis_kill_intent is not None and kis_kill_revision:
                            # Re-enter the same RLock before releasing the
                            # outer route+emergency boundary.  No settings,
                            # STOP, Kill, ordinary, or functional mutation can
                            # cross between the exact socket outcome and grant
                            # revocation.
                            _revoke_kis_kill_cancel_authority(
                                expected_revision=kis_kill_revision,
                                expected_intent=kis_kill_intent,
                            )
                            kis_kill_revision = 0
        except Exception as exc:
            reason = f"브로커 주문 취소 결과 불명: {type(exc).__name__}: {exc}"
            order.update(
                {
                    "state": "unknown_cancel_result",
                    "queue_state": "reconcile_required",
                    "reason": "broker-cancel-outcome-unknown",
                    "cancel_error_type": type(exc).__name__,
                    "updated_at": now_text(),
                }
            )
            if managed is not None and managed.status == "CANCEL_PENDING":
                try:
                    managed = LIVE_OMS.mark_unknown(oms_order_id, "broker cancel outcome unknown")
                    order["oms_status"] = managed.status
                except ValueError as transition_error:
                    order["reconciliation_warning"] = str(transition_error)
            if order.get("idempotency_key"):
                try:
                    PROGRAM_LEDGER.update_order_dispatch(order)
                except (OSError, sqlite3.Error, ValueError):
                    pass
            append_audit("error", "주문 취소 실패", f"{order_id} · {reason}")
            return {"ok": False, "reason": reason, "snapshot": snapshot()}
        if cancel_response.get("ok") is not True:
            reason = str(cancel_response.get("text") or cancel_response.get("status") or "broker cancel rejected")
            order.update(
                {
                    "state": "unknown_cancel_result",
                    "queue_state": "reconcile_required",
                    "reason": "broker-cancel-not-confirmed",
                    "broker_cancel_response": redact_sensitive_payload(cancel_response),
                    "updated_at": now_text(),
                }
            )
            if managed is not None and managed.status == "CANCEL_PENDING":
                try:
                    managed = LIVE_OMS.mark_unknown(oms_order_id, "broker cancel not confirmed")
                    order["oms_status"] = managed.status
                except ValueError as transition_error:
                    order["reconciliation_warning"] = str(transition_error)
            if order.get("idempotency_key"):
                try:
                    PROGRAM_LEDGER.update_order_dispatch(order)
                except (OSError, sqlite3.Error, ValueError):
                    pass
            append_audit("error", "주문 취소 실패", f"{order_id} · {reason}")
            return {"ok": False, "reason": reason, "snapshot": snapshot()}
        order.update(
            {
                "broker_cancel_response": redact_sensitive_payload(cancel_response),
                "cancel_acknowledged_at": datetime.now(timezone.utc).isoformat(),
                "state": "cancel_pending",
                "queue_state": "reconcile_required",
                "reason": "broker-cancel-request-acknowledged",
                "updated_at": now_text(),
            }
        )
        if order.get("idempotency_key"):
            try:
                PROGRAM_LEDGER.update_order_dispatch(order)
            except (OSError, sqlite3.Error, ValueError):
                order["state"] = "unknown_cancel_result"
                order["reason"] = "cancel-ack-checkpoint-failed"
                STATE["new_entries_blocked"] = True
                return {"ok": False, "reason": "cancel-ack-checkpoint-failed", "snapshot": snapshot()}
        append_audit("warn", "주문 취소", f"{order_id} 브로커 취소 요청 접수 · 상태/체결 대조 대기")
        queue_live_order_lifecycle_notification(
            order,
            status="cancel_pending",
            reason=str(order["reason"]),
            message_final=False,
        )
        return {
            "ok": True,
            "reason": "cancel request acknowledged; reconciliation pending",
            "cancel_request_id": cancel_request_id,
            "reconciliation_required": True,
            "snapshot": snapshot(),
        }
    order["state"] = "canceled"
    order["queue_state"] = "canceled"
    order["updated_at"] = now_text()
    order["next_retry_at"] = "-"
    order["reason"] = "브로커 주문과 로컬 큐를 취소했습니다." if submitted_to_broker else "운용자 요청으로 주문 큐 항목을 취소했습니다."
    append_audit("warn", "주문 취소", f"{order_id} {'브로커 주문 및 ' if submitted_to_broker else ''}주문 큐 항목을 취소했습니다.")
    if submitted_to_broker:
        queue_live_order_lifecycle_notification(
            order,
            status="cancelled",
            reason=str(order["reason"]),
            message_final=True,
        )
    return {"ok": True, "reason": "order canceled", "snapshot": snapshot()}


def cancel_order(
    order_id: str,
    *,
    _official_kis_truth: dict[str, Any] | None = None,
    _kill_cleanup: bool = False,
) -> dict[str, Any]:
    """Cancel one order with a truth-to-socket fence for every KIS route."""

    order = find_order(order_id)
    if order is None:
        return {"ok": False, "reason": "order not found", "snapshot": snapshot()}
    broker_request = (
        order.get("broker_request")
        if isinstance(order.get("broker_request"), dict)
        else {}
    )
    broker_id = str(
        order.get("broker_id")
        or broker_request.get("broker_id")
        or broker_id_from_symbol(
            str(order.get("symbol") or ""),
            str(order.get("asset") or ""),
        )
    ).strip().lower()
    if broker_id != "kis":
        return _cancel_order_after_kis_route_selection(
            order_id,
            _official_kis_truth=_official_kis_truth,
            _kill_cleanup=_kill_cleanup,
        )

    with _kis_manual_cancel_preparation() as finish:
        official_truth = _official_kis_truth
        if not isinstance(official_truth, dict):
            refresh = refresh_kis_order_truth_for_kill_switch()
            official_truth = (
                dict(refresh.get("truth"))
                if isinstance(refresh.get("truth"), dict)
                else {}
            )
        return finish(
            lambda: _cancel_order_after_kis_route_selection(
                order_id,
                _official_kis_truth=official_truth,
                _kill_cleanup=_kill_cleanup,
            )
        )


def paper_candidate_evidence_inbox() -> dict[str, Any]:
    """Read published Evidence without runtime or account observation hooks."""
    from .paper_candidate_inbox import list_paper_candidates
    return list_paper_candidates()
